{
  "name": "express-pg-users-api",
  "version": "1.0.0",
  "description": "Express API with PostgreSQL connection pooling and parameterised queries",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "node --watch app.js",
    "test": "node --experimental-vm-modules node_modules/.bin/jest --runInBand"
  },
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "pg": "^8.12.0"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  }
}

/**
 * db.js — PostgreSQL connection pool
 *
 * Creates a single shared pg.Pool instance for the entire process.
 * All query modules import this pool so Node.js module caching ensures
 * only one pool is ever created, regardless of how many files require it.
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials are ever hard-coded. Copy .env.example → .env and fill in
 * your own values before starting the server.
 *
 * Pool tuning knobs (all overridable via env):
 *   DB_POOL_MAX        – maximum number of clients kept alive  (default 10)
 *   DB_POOL_MIN        – minimum number of idle clients        (default 2)
 *   DB_IDLE_TIMEOUT_MS – ms before an idle client is closed    (default 30 000)
 *   DB_CONN_TIMEOUT_MS – ms to wait for an available client    (default 5 000)
 *   DB_STATEMENT_TIMEOUT_MS – per-query hard deadline          (default 10 000)
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool construction
// ---------------------------------------------------------------------------

const pool = new Pool({
  // connectionString covers host/port/db/user/password in one env var.
  // pg also supports individual PG* vars (PGHOST, PGUSER, …) as fallback.
  connectionString: process.env.DATABASE_URL,

  // TLS: require SSL in production; allow self-signed certs only in dev.
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : process.env.DB_SSL === 'true'
      ? { rejectUnauthorized: false }
      : false,

  // Pool sizing
  max:     parseInt(process.env.DB_POOL_MAX ?? '10', 10),
  min:     parseInt(process.env.DB_POOL_MIN ?? '2',  10),

  // How long (ms) a client may sit idle before being evicted
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),

  // How long (ms) to wait for a free client before throwing
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT_MS ?? '5000', 10),

  // Server-side statement timeout — last line of defence against runaway queries
  statement_timeout: parseInt(process.env.DB_STATEMENT_TIMEOUT_MS ?? '10000', 10),
});

// ---------------------------------------------------------------------------
// Pool-level event logging
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  console.info(`[db] new client connected (total: ${pool.totalCount})`);
  // Enforce application_name so queries are identifiable in pg_stat_activity
  client.query("SET application_name = 'express-users-api'").catch(() => {});
});

pool.on('acquire', () => {
  console.debug(`[db] client acquired (idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`);
});

pool.on('remove', () => {
  console.info(`[db] client removed (total: ${pool.totalCount})`);
});

pool.on('error', (err, client) => {
  // An idle client threw an unexpected error (e.g. server closed connection).
  // Log and continue — the pool will create a replacement client automatically.
  console.error('[db] unexpected error on idle client:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool cleanly.  Wire this up to SIGTERM / SIGINT in your entry
 * point so in-flight queries can finish before the process exits.
 */
async function closePool() {
  console.info('[db] draining connection pool…');
  await pool.end();
  console.info('[db] pool closed');
}

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Every public function:
 *   1. Validates & sanitises its inputs BEFORE they touch SQL.
 *   2. Uses pg's $1 / $2 … placeholder syntax — values are NEVER
 *      interpolated into the query string, so SQL injection is impossible
 *      at the driver level.
 *   3. Records wall-clock timing around every pool.query() call and emits
 *      a structured log line so slow queries are visible in production.
 *   4. Throws typed QueryError instances so callers can distinguish
 *      validation failures (400) from DB errors (500).
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Constants & limits
// ---------------------------------------------------------------------------

/** Hard ceiling on the number of rows a single call may return. */
const MAX_LIMIT = 100;

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

/** Maximum length of a full-text search term (after trimming). */
const MAX_QUERY_LENGTH = 200;

// ---------------------------------------------------------------------------
// Typed error class
// ---------------------------------------------------------------------------

/**
 * QueryError extends the built-in Error with an HTTP-friendly `statusCode`
 * and an optional `field` name so the route handler can build a structured
 * 4xx response without extra conditional logic.
 */
class QueryError extends Error {
  /**
   * @param {string}  message    Human-readable description.
   * @param {number}  statusCode Suggested HTTP status (400, 404, 422 …).
   * @param {string} [field]     The input field that caused the problem.
   */
  constructor(message, statusCode = 400, field = null) {
    super(message);
    this.name       = 'QueryError';
    this.statusCode = statusCode;
    this.field      = field;
  }
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Thin wrapper around pool.query() that:
 *   • measures wall-clock execution time
 *   • emits a structured [query] log line with duration, row count, and
 *     the first 120 chars of the SQL text (never the bound values)
 *   • re-throws DB errors with a sanitised message (no internal details
 *     leak to the caller)
 *
 * @param {string}   sql    Parameterised SQL string.
 * @param {any[]}   [params=[]]  Bound parameter values.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(sql, params = []) {
  const start   = process.hrtime.bigint();
  const preview = sql.replace(/\s+/g, ' ').trim().slice(0, 120);

  try {
    const result  = await pool.query(sql, params);
    const elapsed = Number(process.hrtime.bigint() - start) / 1e6; // → ms

    console.info(
      `[query] ok | ${elapsed.toFixed(2)} ms | rows=${result.rowCount} | sql="${preview}"`
    );

    return result;
  } catch (err) {
    const elapsed = Number(process.hrtime.bigint() - start) / 1e6;

    console.error(
      `[query] error | ${elapsed.toFixed(2)} ms | code=${err.code} | sql="${preview}" | msg=${err.message}`
    );

    // Re-throw a sanitised error so stack traces / internal SQL never reach
    // an HTTP response body.
    const wrapped = new QueryError('Database query failed', 500);
    wrapped.cause = err; // preserve for internal logging / APM
    throw wrapped;
  }
}

/**
 * Parse and clamp an integer that will be used as a SQL LIMIT value.
 *
 * @param {any}    raw          Value from user input.
 * @param {number} defaultValue Fallback when raw is undefined / null.
 * @param {number} max          Absolute ceiling.
 * @returns {number}
 * @throws {QueryError} if the value is present but not a positive integer.
 */
function parseLimit(raw, defaultValue = DEFAULT_LIMIT, max = MAX_LIMIT) {
  if (raw === undefined || raw === null || raw === '') return defaultValue;

  const n = Number(raw);

  if (!Number.isInteger(n) || n < 1) {
    throw new QueryError(
      `"limit" must be a positive integer (got ${JSON.stringify(raw)})`,
      400,
      'limit',
    );
  }

  return Math.min(n, max);
}

/**
 * Parse and validate a non-negative integer that will be used as a SQL
 * OFFSET value.
 *
 * @param {any} raw  Value from user input.
 * @returns {number}
 * @throws {QueryError} if the value is present but not a valid offset.
 */
function parseOffset(raw) {
  if (raw === undefined || raw === null || raw === '') return 0;

  const n = Number(raw);

  if (!Number.isInteger(n) || n < 0) {
    throw new QueryError(
      `"offset" must be a non-negative integer (got ${JSON.stringify(raw)})`,
      400,
      'offset',
    );
  }

  return n;
}

/**
 * Validate and normalise a numeric user ID.
 *
 * @param {any} raw  Value from route params.
 * @returns {number}
 * @throws {QueryError} on invalid input.
 */
function parseId(raw) {
  const n = Number(raw);

  if (!Number.isInteger(n) || n < 1) {
    throw new QueryError(
      `User ID must be a positive integer (got ${JSON.stringify(raw)})`,
      400,
      'id',
    );
  }

  return n;
}

/**
 * Validate and normalise a free-text search term.
 *
 * Rules:
 *   • Must be a non-empty string after trimming.
 *   • Maximum length is MAX_QUERY_LENGTH characters.
 *   • No structural mutations — the value is passed to pg as a bound
 *     parameter, so special chars cannot affect query structure.
 *
 * @param {any} raw  Value from query string.
 * @returns {string} Trimmed search term.
 * @throws {QueryError} on invalid input.
 */
function parseSearchQuery(raw) {
  if (typeof raw !== 'string' || raw.trim() === '') {
    throw new QueryError('"query" must be a non-empty string', 400, 'query');
  }

  const trimmed = raw.trim();

  if (trimmed.length > MAX_QUERY_LENGTH) {
    throw new QueryError(
      `"query" must not exceed ${MAX_QUERY_LENGTH} characters`,
      400,
      'query',
    );
  }

  return trimmed;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by primary key.
 *
 * SQL injection prevention
 * ─────────────────────────
 * `id` is validated as a positive integer by parseId(), then passed as the
 * bound value $1. The query string is a static literal — no user-controlled
 * text ever enters it.
 *
 * @param   {number|string} id  The user's primary key.
 * @returns {Promise<object|null>}  The user row, or null if not found.
 * @throws  {QueryError}
 */
async function getUserById(id) {
  const safeId = parseId(id);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await timedQuery(sql, [safeId]);

  return result.rows[0] ?? null;
}

/**
 * Return a paginated list of all users, ordered by creation date descending.
 *
 * SQL injection prevention
 * ─────────────────────────
 * Both `limit` and `offset` are validated as non-negative integers, then
 * passed as bound values $1 / $2.  PostgreSQL does not allow parameter
 * placeholders in ORDER BY direction literals, but since the direction is
 * a hard-coded constant in this file it is safe regardless.
 *
 * @param   {number|string} [limit]   Max rows per page (1–100, default 20).
 * @param   {number|string} [offset]  Zero-based row offset (default 0).
 * @returns {Promise<{users: object[], total: number, limit: number, offset: number}>}
 * @throws  {QueryError}
 */
async function getAllUsers(limit, offset) {
  const safeLimit  = parseLimit(limit);
  const safeOffset = parseOffset(offset);

  // COUNT(*) is fetched in the same round-trip via a window function so the
  // UI can render pagination controls without an extra query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY created_at DESC, id DESC
    LIMIT  $1
    OFFSET $2
  `;

  const result = await timedQuery(sql, [safeLimit, safeOffset]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  // Strip the window-function column from every row before returning
  const users = result.rows.map(({ total_count, ...user }) => user);

  return {
    users,
    total,
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * Full-text search across users' name and email columns.
 *
 * The search term is wrapped in `%…%` wildcards for a LIKE/ILIKE scan.
 * This approach works correctly for moderate data sets; for larger tables
 * swap the WHERE clause for a tsvector GIN index.
 *
 * SQL injection prevention
 * ─────────────────────────
 * The term is validated by parseSearchQuery(), then passed as the bound
 * value $3.  LIKE special characters (`%`, `_`, `\`) are escaped before
 * building the pattern so a user cannot craft a term that changes the
 * selectivity or meaning of the LIKE expression. The pattern is then still
 * passed as a bound value — it never enters the query string.
 *
 * @param   {string}        query   Free-text search term.
 * @param   {number|string} [limit]  Max rows (1–100, default 20).
 * @param   {number|string} [offset] Zero-based row offset (default 0).
 * @returns {Promise<{users: object[], total: number, limit: number, offset: number, query: string}>}
 * @throws  {QueryError}
 */
async function searchUsers(query, limit, offset) {
  const safeQuery  = parseSearchQuery(query);
  const safeLimit  = parseLimit(limit);
  const safeOffset = parseOffset(offset);

  // Escape LIKE metacharacters so the user's literal text is matched.
  // This prevents e.g. the search term "100%" from matching everything.
  const escapedTerm = safeQuery
    .replace(/\\/g, '\\\\') // backslash first to avoid double-escaping
    .replace(/%/g, '\\%')
    .replace(/_/g, '\\_');

  const likePattern = `%${escapedTerm}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1 ESCAPE '\\'
      OR email ILIKE $1 ESCAPE '\\'
    ORDER BY
      -- Exact name matches first, then email matches, then the rest
      CASE WHEN LOWER(name)  = LOWER($3) THEN 0
           WHEN LOWER(email) = LOWER($3) THEN 1
           ELSE 2
      END,
      name ASC,
      id   ASC
    LIMIT  $2
    OFFSET $4
  `;
  // $1 = likePattern  $2 = safeLimit  $3 = safeQuery (for exact-match sort)
  //                                    $4 = safeOffset

  const result = await timedQuery(sql, [likePattern, safeLimit, safeQuery, safeOffset]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  const users = result.rows.map(({ total_count, ...user }) => user);

  return {
    users,
    total,
    limit:  safeLimit,
    offset: safeOffset,
    query:  safeQuery,
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryError,          // exported so route handlers can instanceof-check
  // Expose test helpers (used by unit tests to replace timedQuery)
  _internal: { parseId, parseLimit, parseOffset, parseSearchQuery, timedQuery },
};

/**
 * app.js — Express application wired to the PostgreSQL query layer
 *
 * /users endpoints
 * ────────────────
 *   GET /users              → getAllUsers(limit, offset)
 *   GET /users/search       → searchUsers(query, limit, offset)
 *   GET /users/:id          → getUserById(id)
 *
 * Error handling guarantees that QueryError validation failures become 4xx
 * responses and unexpected errors become 500s — without any internal detail
 * (SQL text, stack traces, pg error codes) leaking to the client.
 */

'use strict';

// Load environment variables from .env before anything else so that db.js
// can read DATABASE_URL when it constructs the pool.
require('dotenv').config();

const express  = require('express');
const { getUserById, getAllUsers, searchUsers, QueryError } = require('./queries');
const { closePool } = require('./db');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Request-level logging middleware
// ---------------------------------------------------------------------------

app.use((req, _res, next) => {
  req._startedAt = process.hrtime.bigint();
  console.info(`[http] --> ${req.method} ${req.originalUrl}`);
  next();
});

// ---------------------------------------------------------------------------
// Health check (no DB dependency)
// ---------------------------------------------------------------------------

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// /users routes
// ---------------------------------------------------------------------------

/**
 * GET /users
 *
 * Query params:
 *   limit  {number}  Rows per page, 1–100 (default 20)
 *   offset {number}  Zero-based offset   (default 0)
 *
 * Response 200:
 *   {
 *     "users":  [...],
 *     "total":  <total matching rows>,
 *     "limit":  <effective limit>,
 *     "offset": <effective offset>
 *   }
 */
app.get('/users', async (req, res, next) => {
  try {
    const { limit, offset } = req.query;
    const data = await getAllUsers(limit, offset);
    res.json(data);
  } catch (err) {
    next(err);
  }
});

/**
 * GET /users/search
 *
 * Must be registered BEFORE /users/:id so Express does not try to coerce
 * the literal string "search" into a numeric ID.
 *
 * Query params:
 *   query  {string}  Required. Free-text search term.
 *   limit  {number}  Rows per page, 1–100 (default 20)
 *   offset {number}  Zero-based offset   (default 0)
 *
 * Response 200:
 *   {
 *     "users":  [...],
 *     "total":  <total matching rows>,
 *     "limit":  <effective limit>,
 *     "offset": <effective offset>,
 *     "query":  "<normalised search term>"
 *   }
 */
app.get('/users/search', async (req, res, next) => {
  try {
    const { query, limit, offset } = req.query;
    const data = await searchUsers(query, limit, offset);
    res.json(data);
  } catch (err) {
    next(err);
  }
});

/**
 * GET /users/:id
 *
 * Path params:
 *   id  {number}  Positive integer primary key.
 *
 * Response 200: user object
 * Response 404: { "error": "User not found" }
 */
app.get('/users/:id', async (req, res, next) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// Centralised error handler
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  const elapsed = req._startedAt
    ? (Number(process.hrtime.bigint() - req._startedAt) / 1e6).toFixed(2)
    : '?';

  if (err instanceof QueryError) {
    const status = err.statusCode >= 400 && err.statusCode < 500 ? err.statusCode : 500;

    if (status < 500) {
      // Validation / not-found errors: safe to surface the message
      console.warn(`[http] <-- ${req.method} ${req.originalUrl} | ${status} | ${elapsed} ms | ${err.message}`);
      const body = { error: err.message };
      if (err.field) body.field = err.field;
      return res.status(status).json(body);
    }
  }

  // Unexpected / server-side errors: log internally, return generic message
  console.error(
    `[http] <-- ${req.method} ${req.originalUrl} | 500 | ${elapsed} ms | ${err.stack ?? err.message}`
  );
  res.status(500).json({ error: 'An unexpected error occurred' });
});

// ---------------------------------------------------------------------------
// Response logging (success paths)
// ---------------------------------------------------------------------------

// Patch res.json so every successful response gets a log line with timing.
// This runs after the route handler sets the status code.
const originalJson = app.response.json;
app.response.json = function loggedJson(body) {
  const req     = this.req;
  const status  = this.statusCode;
  const elapsed = req._startedAt
    ? (Number(process.hrtime.bigint() - req._startedAt) / 1e6).toFixed(2)
    : '?';

  // Only log non-error responses here; errors are logged in the handler above.
  if (status < 400) {
    console.info(`[http] <-- ${req.method} ${req.originalUrl} | ${status} | ${elapsed} ms`);
  }

  return originalJson.call(this, body);
};

// ---------------------------------------------------------------------------
// Server startup & graceful shutdown
// ---------------------------------------------------------------------------

const PORT = parseInt(process.env.PORT ?? '3000', 10);

let server;

// Guard against auto-starting when this file is require()'d by tests
if (require.main === module) {
  server = app.listen(PORT, () => {
    console.info(`[app] server listening on port ${PORT} (NODE_ENV=${process.env.NODE_ENV ?? 'development'})`);
  });

  // Graceful shutdown: finish in-flight requests, drain the DB pool
  const shutdown = async (signal) => {
    console.info(`[app] received ${signal} — shutting down…`);

    server.close(async () => {
      try {
        await closePool();
        console.info('[app] shutdown complete');
        process.exit(0);
      } catch (err) {
        console.error('[app] error during shutdown:', err.message);
        process.exit(1);
      }
    });

    // Force-kill if shutdown takes too long
    setTimeout(() => {
      console.error('[app] shutdown timed out — forcing exit');
      process.exit(1);
    }, 10_000).unref();
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT',  () => shutdown('SIGINT'));
}

module.exports = app;

/**
 * queries.test.js — unit tests for queries.js
 *
 * Strategy
 * ────────
 * The pool is mocked at the module level so tests never need a real
 * PostgreSQL server.  We inject a fake pool via jest.mock() and control
 * what pool.query() returns in each test.
 *
 * What is tested
 * ──────────────
 *  • Input validation (boundary values, type errors, missing fields)
 *  • Correct SQL parameter binding (no user input ever in the SQL string)
 *  • Pagination envelope shape
 *  • LIKE metacharacter escaping in searchUsers
 *  • Query timing log output (console.info spy)
 *  • Error propagation and sanitisation (QueryError vs raw DB errors)
 *  • SQL injection attempts are neutralised by parameterisation
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the db module so no real pool is created
// ---------------------------------------------------------------------------

// We capture the mock query function so individual tests can configure it.
const mockQuery = jest.fn();

jest.mock('./db', () => ({
  pool:      { query: mockQuery },
  closePool: jest.fn().mockResolvedValue(undefined),
}));

// Now require the module under test (after the mock is registered)
const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryError,
  _internal: { parseId, parseLimit, parseOffset, parseSearchQuery },
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Build a fake pg QueryResult. */
function fakeResult(rows = [], extra = {}) {
  return {
    rows,
    rowCount: rows.length,
    ...extra,
  };
}

/** Build a fake user row as the DB would return it. */
function fakeUserRow(overrides = {}) {
  return {
    id:          1,
    name:        'Alice',
    email:       'alice@example.com',
    created_at:  new Date('2024-01-01T00:00:00Z'),
    updated_at:  new Date('2024-01-01T00:00:00Z'),
    total_count: '1',   // pg returns COUNT as a string
    ...overrides,
  };
}

// ---------------------------------------------------------------------------
// Setup / teardown
// ---------------------------------------------------------------------------

beforeEach(() => {
  jest.clearAllMocks();
  // Silence console output during tests unless a specific test overrides this
  jest.spyOn(console, 'info').mockImplementation(() => {});
  jest.spyOn(console, 'warn').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
  jest.spyOn(console, 'debug').mockImplementation(() => {});
});

afterEach(() => {
  jest.restoreAllMocks();
});

// ===========================================================================
// parseId
// ===========================================================================

describe('parseId()', () => {
  test.each([
    [1, 1],
    ['1', 1],
    ['999', 999],
    [Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER],
  ])('parses valid id %p → %p', (input, expected) => {
    expect(parseId(input)).toBe(expected);
  });

  test.each([
    [0],
    [-1],
    [1.5],
    ['abc'],
    [''],
    [null],
    [undefined],
    ['1; DROP TABLE users--'],
    ["1' OR '1'='1"],
  ])('throws QueryError for invalid id %p', (input) => {
    expect(() => parseId(input)).toThrow(QueryError);
