    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('alice', 10, 0);

    const [sql, params] = mockQuery.mock.calls[0];

    // $1 is the LIKE pattern
    expect(params[0]).toBe('%alice%');
    // The raw term also appears as $3 for the exact-match sort expression
    expect(params[2]).toBe('alice');
    // The SQL string must use placeholders, not the literal term
    expect(sql).not.toContain('alice');
    expect(sql).toContain('$1');
  });

