    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('100%');

    const [, params] = mockQuery.mock.calls[0];
    // % in the term must be escaped so it matches literally
    expect(params[0]).toBe('%100\\%%');
  });

  test('escapes LIKE metacharacter _ in search term', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('user_name');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%user\\_name%');
  });

  test('escapes backslash in search term', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    await searchUsers('path\\to');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%path\\\\to%');
  });

  test('SQL injection via query string is bound, not interpolated', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    // Classic injection attempt passed as the search term
    const malicious = "'; DROP TABLE users; --";
    await searchUsers(malicious);

    const [sql, params] = mockQuery.mock.calls[0];

    // Injection payload must appear ONLY as a bound value, never in the SQL
    expect(sql).not.toContain('DROP');
    expect(sql).not.toContain(malicious);
    expect(params[0]).toContain('DROP'); // the value is there, but safely bound
  });

  test('throws QueryError for missing query param', async () => {
    await expect(searchUsers('')).rejects.toThrow(QueryError);
    await expect(searchUsers(null)).rejects.toThrow(QueryError);
    await expect(searchUsers(undefined)).rejects.toThrow(QueryError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryError for query exceeding max length', async () => {
    await expect(searchUsers('x'.repeat(201))).rejects.toThrow(QueryError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryError on invalid limit', async () => {
    await expect(searchUsers('alice', -1)).rejects.toThrow(QueryError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('returns total=0 and empty users[] when no rows match', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const result = await searchUsers('zzznomatch');

    expect(result.total).toBe(0);
    expect(result.users).toEqual([]);
  });

  test('trims whitespace from the search term', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));

    const result = await searchUsers('  alice  ');

    expect(result.query).toBe('alice');
    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%alice%');
  });
});

