/**
 * run_tests.js — Self-contained test runner (no dependencies required).
 *
 * Exercises all query functions and validators with the pg pool mocked
 * via a module-registry patch.  Prints PASS / FAIL per test and exits
 * with a non-zero code if any assertion fails.
 */

'use strict';

// ---------------------------------------------------------------------------
// Minimal assertion + test harness
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (!condition) throw new Error(`Assertion failed: ${message}`);
}

function assertEqual(a, b, msg) {
  if (a !== b) throw new Error(`${msg ?? 'assertEqual'}: expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
}

function assertThrows(fn, match, msg) {
  try {
    fn();
    throw new Error(`${msg ?? 'assertThrows'}: expected throw, but function returned`);
  } catch (err) {
    if (err.message.startsWith(msg ?? 'assertThrows')) throw err;
    if (match && !err.message.includes(match)) {
      throw new Error(`${msg}: expected error matching "${match}", got "${err.message}"`);
    }
  }
}

async function assertRejects(fn, match, msg) {
  try {
    await fn();
    throw new Error(`${msg ?? 'assertRejects'}: expected rejection, but resolved`);
  } catch (err) {
    if (err.message.startsWith(msg ?? 'assertRejects')) throw err;
    if (match && !err.message.match(new RegExp(match, 'i'))) {
      throw new Error(`${msg}: expected error matching "${match}", got "${err.message}"`);
    }
  }
}

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ ${name}`);
    console.error(`    → ${err.message}`);
    failed++;
  }
}

function describe(name, fn) {
  console.log(`\n${name}`);
  return fn();
}

// ---------------------------------------------------------------------------
// Mock the pg pool before requiring queries.js
// ---------------------------------------------------------------------------

let mockRows  = [];
let mockShouldFail = false;
let lastSql   = null;
let lastParams = null;

// Inject a fake 'db' module into the require cache so queries.js picks it up
const Module = require('module');
const fakeDb = {
  pool: {
    query: async (sql, params) => {
      lastSql    = sql;
      lastParams = params;
      if (mockShouldFail) throw new Error('simulated db error');
      return { rows: mockRows, rowCount: mockRows.length };
    },
  },
  closePool: async () => {},
};

// Resolve the absolute path queries.js would use when it calls require('./db')
const path    = require('path');
const dbPath  = path.resolve(__dirname, 'db.js');
require.cache[dbPath] = {
  id:       dbPath,
  filename: dbPath,
  loaded:   true,
  exports:  fakeDb,
};

// Silence console output from the module under test
const _info  = console.info;
const _error = console.error;
const _debug = console.debug;
console.info  = () => {};
console.error = () => {};
console.debug = () => {};

const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryError,
  _internal: { parseId, parseLimit, parseOffset, parseSearchQuery },
} = require('./queries');

console.info  = _info;
console.error = _error;
console.debug = _debug;

// Helper to build fake rows
function fakeUserRow(overrides = {}) {
  return {
    id: 1, name: 'Alice', email: 'alice@example.com',
    created_at: new Date(), updated_at: new Date(),
    total_count: '1',
    ...overrides,
  };
}

function resetMock() {
  mockRows       = [];
  mockShouldFail = false;
  lastSql        = null;
  lastParams     = null;
  console.info   = () => {};
  console.error  = () => {};
  console.debug  = () => {};
}

