      assertEqual(result.users.length, 0);
    });
  });

  // ─── QueryError class ─────────────────────────────────────────────────────
  await describe('QueryError class', async () => {
    await test('is instance of Error', () => {
      assert(new QueryError('oops') instanceof Error);
    });
    await test('carries statusCode and field', () => {
      const e = new QueryError('bad', 422, 'email');
      assertEqual(e.statusCode, 422);
      assertEqual(e.field, 'email');
      assertEqual(e.name, 'QueryError');
    });
    await test('defaults statusCode=400, field=null', () => {
      const e = new QueryError('x');
      assertEqual(e.statusCode, 400);
      assertEqual(e.field, null);
    });
  });

  // ─── Summary ──────────────────────────────────────────────────────────────
  console.log(`\n${'─'.repeat(50)}`);
  console.log(`Tests: ${passed + failed}  |  Passed: ${passed}  |  Failed: ${failed}`);

  if (failed > 0) {
    console.error(`\n${failed} test(s) failed.`);
    process.exit(1);
  } else {
    console.log('\nAll tests passed ✓');
    process.exit(0);
  }
})();

