/**
 * db.js — PostgreSQL connection pool
 *
 * A single Pool instance is created once and re-used for the entire
 * process lifetime.  Every caller that does `require('./db')` receives
 * the same pool object (Node's module-cache guarantee).
 *
 * Configuration is read exclusively from environment variables so that
 * no credentials ever appear in source code.  See .env.example for the
 * full list of supported variables.
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
// All values fall back to pg's own defaults when the env-var is absent, so
// the only hard requirement is DATABASE_URL (or the individual PG* vars).
// ---------------------------------------------------------------------------

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Individual overrides (ignored when DATABASE_URL already contains them)
  host:     process.env.PGHOST,
  port:     process.env.PGPORT     ? Number(process.env.PGPORT)     : undefined,
  database: process.env.PGDATABASE,
  user:     process.env.PGUSER,
  password: process.env.PGPASSWORD,

  // Connection-pool sizing
  // Keep enough connections for typical API concurrency without exhausting
  // the database's max_connections limit.
  max:              Number(process.env.DB_POOL_MAX)              || 10,
  min:              Number(process.env.DB_POOL_MIN)              || 2,
  idleTimeoutMillis:Number(process.env.DB_IDLE_TIMEOUT_MS)       || 30_000,
  connectionTimeoutMillis: Number(process.env.DB_CONN_TIMEOUT_MS) || 5_000,

  // Re-use TLS settings from the connection string when present; allow an
  // explicit opt-out for local development only.
  ssl: process.env.DB_SSL === 'false' ? false : { rejectUnauthorized: true },
});

// ---------------------------------------------------------------------------
// Pool-level event hooks
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  console.info('[db] New client connected to pool '
    + `(total=${pool.totalCount}, idle=${pool.idleCount}, waiting=${pool.waitingCount})`);

  // Set a session-level statement timeout so runaway queries are killed
  // automatically.  Uses a conservative 30-second ceiling; tune via env var.
  const stmtTimeout = process.env.DB_STATEMENT_TIMEOUT_MS || 30_000;
  client.query(`SET statement_timeout = ${Number(stmtTimeout)}`).catch((err) => {
    console.warn('[db] Could not set statement_timeout:', err.message);
  });
});

pool.on('acquire', () => {
  console.debug('[db] Client acquired from pool '
    + `(idle=${pool.idleCount}, waiting=${pool.waitingCount})`);
});

pool.on('remove', () => {
  console.info('[db] Client removed from pool '
    + `(total=${pool.totalCount})`);
});

pool.on('error', (err) => {
  // Unexpected errors on idle clients (e.g. server-side TCP RST).
  // Log and continue — the pool will replace the broken client automatically.
  console.error('[db] Unexpected error on idle pool client:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool cleanly.  Call this in your SIGTERM / SIGINT handler so
 * in-flight queries are allowed to finish before the process exits.
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  console.info('[db] Draining connection pool…');
  await pool.end();
  console.info('[db] Pool closed.');
}

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users resource
 *
 * Design goals
 * ─────────────
 * 1. SQL injection prevention — every piece of caller-supplied data is
 *    passed as a bind parameter ($1, $2, …), never interpolated into the
 *    SQL string.  Integer inputs are additionally coerced and range-checked
 *    before they reach the driver.
 *
 * 2. Connection pooling — all queries go through the shared Pool exported
 *    by db.js.  No individual Client is checked out here; pool.query()
 *    borrows a client, executes the query, and returns it automatically.
 *
 * 3. Query timing — every public function records a high-resolution start
 *    time and logs the elapsed duration after the query resolves or rejects.
 *
 * 4. Input validation — inputs are sanitised before they are handed to pg.
 *    A dedicated ValidationError subclass lets callers distinguish "bad
 *    request" errors from genuine database errors.
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Constants & limits
// ---------------------------------------------------------------------------

const DEFAULTS = {
  LIMIT:      20,
  MAX_LIMIT:  100,
  OFFSET:     0,
  MAX_OFFSET: 1_000_000,      // sanity ceiling; tune to your dataset size
  MAX_SEARCH_LEN: 200,        // prevent absurdly long LIKE patterns
};

// ---------------------------------------------------------------------------
// Custom error classes
// ---------------------------------------------------------------------------

/**
 * Thrown when caller-supplied input fails validation.
 * HTTP layer should map this to a 400 response.
 */
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name  = 'ValidationError';
    this.statusCode = 400;
  }
}

/**
 * Thrown when a requested resource does not exist.
 * HTTP layer should map this to a 404 response.
 */
class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name  = 'NotFoundError';
    this.statusCode = 404;
  }
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Returns a high-resolution timestamp in milliseconds.
 * @returns {number}
 */
function now() {
  const [s, ns] = process.hrtime();
  return s * 1_000 + ns / 1_000_000;
}

/**
 * Logs a completed query with its timing.
 *
 * @param {string} fnName   - Name of the calling query function.
 * @param {string} sql      - The SQL template that was executed.
 * @param {unknown[]} params - Bind parameters (values are shown for debugging).
 * @param {number} startMs  - Value returned by now() before the query ran.
 * @param {'ok'|'error'} status
 */
function logQueryTiming(fnName, sql, params, startMs, status = 'ok') {
  const elapsed = (now() - startMs).toFixed(3);
  const paramSummary = JSON.stringify(params);

  // Collapse whitespace in the SQL string for more-readable single-line logs.
  const compactSql = sql.replace(/\s+/g, ' ').trim();

  console.info(
    `[queries] ${fnName} | status=${status} | duration=${elapsed}ms`
    + ` | params=${paramSummary} | sql="${compactSql}"`
  );
}

/**
 * Parses and validates an integer parameter.
 *
 * @param {unknown} value     - Raw value from the caller.
 * @param {string}  name      - Parameter name (used in error messages).
 * @param {number}  min       - Inclusive lower bound.
 * @param {number}  max       - Inclusive upper bound.
 * @param {number}  fallback  - Value used when `value` is null / undefined.
 * @returns {number}
 */
function parseIntParam(value, name, min, max, fallback) {
  if (value === null || value === undefined || value === '') {
    return fallback;
  }

  // Accept both numeric and string representations.
  const n = Number(value);

  if (!Number.isInteger(n)) {
    throw new ValidationError(`"${name}" must be an integer, got: ${JSON.stringify(value)}`);
  }
  if (n < min || n > max) {
    throw new ValidationError(`"${name}" must be between ${min} and ${max}, got: ${n}`);
  }

  return n;
}

/**
 * Validates and sanitises a free-text search string.
 *
 * We do NOT escape LIKE wildcards here because we want callers to be able
 * to pass them deliberately (e.g. "ali%" to prefix-search).  The value is
 * passed as a bind parameter, so no SQL injection is possible regardless
 * of its content.
 *
 * @param {unknown} value - Raw search string.
 * @returns {string}
 */
function parseSearchQuery(value) {
  if (value === null || value === undefined || value === '') {
    throw new ValidationError('"query" must be a non-empty string');
  }

  if (typeof value !== 'string') {
    throw new ValidationError(`"query" must be a string, got: ${typeof value}`);
  }

  const trimmed = value.trim();
  if (trimmed.length === 0) {
    throw new ValidationError('"query" must not be blank');
  }

  if (trimmed.length > DEFAULTS.MAX_SEARCH_LEN) {
    throw new ValidationError(
      `"query" must be at most ${DEFAULTS.MAX_SEARCH_LEN} characters`
    );
  }

  return trimmed;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetches a single user row by primary key.
 *
 * SQL injection prevention
 * ─────────────────────────
 * `id` is coerced to a JavaScript integer by parseIntParam() before being
 * passed as the $1 bind parameter.  The SQL string is a compile-time
 * constant — no user data is ever concatenated into it.
 *
 * @param {number|string} id - The user's numeric primary key.
 * @returns {Promise<object>} The user row.
 * @throws {ValidationError} When `id` is not a positive integer.
 * @throws {NotFoundError}   When no user with that id exists.
 */
async function getUserById(id) {
  const validId = parseIntParam(id, 'id', 1, Number.MAX_SAFE_INTEGER, null);

  if (validId === null) {
    throw new ValidationError('"id" is required');
  }

  // -------------------------------------------------------------------------
  // NOTE: The SQL string is a static template.  $1 is a PostgreSQL positional
  // bind parameter — the pg driver sends the value out-of-band in the
  // parameterised query protocol, so it is impossible for the value to alter
  // the SQL structure regardless of what it contains.
  // -------------------------------------------------------------------------
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
  `;

  const params = [validId];
  const start  = now();

  try {
    const result = await pool.query(sql, params);
    logQueryTiming('getUserById', sql, params, start, 'ok');

    if (result.rows.length === 0) {
      throw new NotFoundError(`User with id ${validId} not found`);
    }

    return result.rows[0];
  } catch (err) {
    if (err instanceof NotFoundError) throw err; // re-throw — not a db error

    logQueryTiming('getUserById', sql, params, start, 'error');
    throw err;
  }
}

/**
 * Returns a paginated list of all users, ordered by id ascending.
 *
 * SQL injection prevention
 * ─────────────────────────
 * `limit` and `offset` are integer-coerced by parseIntParam() and then
 * passed as $1 / $2 bind parameters.  PostgreSQL's parameterised query
 * protocol enforces that bind parameters can only supply *values*, never
 * SQL keywords or identifiers — LIMIT / OFFSET injection is therefore
 * structurally impossible.
 *
 * @param {number|string} [limit=20]  - Maximum rows to return (1–100).
 * @param {number|string} [offset=0] - Number of rows to skip (≥ 0).
 * @returns {Promise<{ rows: object[], total: number, limit: number, offset: number }>}
 * @throws {ValidationError} When limit or offset fail validation.
 */
async function getAllUsers(limit, offset) {
  const validLimit  = parseIntParam(limit,  'limit',  1, DEFAULTS.MAX_LIMIT,  DEFAULTS.LIMIT);
  const validOffset = parseIntParam(offset, 'offset', 0, DEFAULTS.MAX_OFFSET, DEFAULTS.OFFSET);

  // Two queries in one round-trip via a single SQL statement:
  //   • The main SELECT returns the requested page.
  //   • COUNT(*) OVER () returns the total number of matching rows without a
  //     separate query, which avoids a race condition between two round-trips.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const params = [validLimit, validOffset];
  const start  = now();

  try {
    const result = await pool.query(sql, params);
    logQueryTiming('getAllUsers', sql, params, start, 'ok');

    // pg returns COUNT(*) as a string; coerce it.
    const total = result.rows.length > 0 ? Number(result.rows[0].total_count) : 0;

    // Strip the synthetic total_count column from every row before returning.
    const rows = result.rows.map(({ total_count, ...rest }) => rest);

    return { rows, total, limit: validLimit, offset: validOffset };
  } catch (err) {
    logQueryTiming('getAllUsers', sql, params, start, 'error');
    throw err;
  }
}

/**
 * Full-text search across users' name and email columns.
 *
 * SQL injection prevention
 * ─────────────────────────
 * The search term is passed as bind parameter $1.  The ILIKE pattern is
 * constructed *inside* PostgreSQL by the `'%' || $1 || '%'` expression —
 * the concatenation happens server-side on the already-bound value, so the
 * driver still sends the raw string out-of-band.  No user input is ever
 * interpolated into the SQL string on the Node.js side.
 *
 * Any LIKE metacharacter inside the search string ('_', '%', '\') is treated
 * literally from a SQL-injection perspective (it cannot escape the parameter
 * context), though it will affect pattern matching semantics.  If you need
 * strict literal matching, add `ESCAPE '\'` and escape the metacharacters in
 * parseSearchQuery() before calling this function.
 *
 * @param {string}        query         - The search term (1–200 chars).
 * @param {number|string} [limit=20]   - Maximum rows to return (1–100).
 * @param {number|string} [offset=0]  - Number of rows to skip (≥ 0).
 * @returns {Promise<{ rows: object[], total: number, limit: number, offset: number, query: string }>}
 * @throws {ValidationError} When query / limit / offset fail validation.
 */
async function searchUsers(query, limit, offset) {
  const validQuery  = parseSearchQuery(query);
  const validLimit  = parseIntParam(limit,  'limit',  1, DEFAULTS.MAX_LIMIT,  DEFAULTS.LIMIT);
  const validOffset = parseIntParam(offset, 'offset', 0, DEFAULTS.MAX_OFFSET, DEFAULTS.OFFSET);

  // The search term is wrapped in wildcards entirely within the SQL
  // expression using string concatenation — this keeps user data fully
  // within the parameterised value channel.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    WHERE
      name  ILIKE '%' || $1 || '%'
      OR
      email ILIKE '%' || $1 || '%'
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const params = [validQuery, validLimit, validOffset];
  const start  = now();

  try {
    const result = await pool.query(sql, params);
    logQueryTiming('searchUsers', sql, params, start, 'ok');

    const total = result.rows.length > 0 ? Number(result.rows[0].total_count) : 0;
    const rows  = result.rows.map(({ total_count, ...rest }) => rest);

    return { rows, total, limit: validLimit, offset: validOffset, query: validQuery };
  } catch (err) {
    logQueryTiming('searchUsers', sql, params, start, 'error');
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export error classes so HTTP handlers can do `instanceof` checks.
  ValidationError,
  NotFoundError,
  // Export DEFAULTS so tests and documentation can reference them.
  DEFAULTS,
};

/**
 * app.js — Express application
 *
 * Wires the /users query layer (queries.js) to the HTTP surface.
 * The pool is initialised lazily on first request; a SIGTERM handler
 * drains it cleanly before the process exits.
 */

'use strict';

require('dotenv').config();

const express = require('express');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,
  NotFoundError,
} = require('./queries');
const { closePool } = require('./db');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler and forwards any thrown error to next(),
 * which hands it to the centralised error-handler middleware below.
 *
 * @param {Function} fn - Async (req, res, next) handler.
 * @returns {Function}
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health — liveness probe (no DB call)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users
// Returns a paginated list of all users.
//
// Query parameters
// ────────────────
//   limit  {integer, 1–100, default 20}  — page size
//   offset {integer, 0–1000000, default 0} — rows to skip
//
// Example
//   GET /users?limit=10&offset=20
// ---------------------------------------------------------------------------
app.get('/users', asyncHandler(async (req, res) => {
  const { limit, offset } = req.query;
  const result = await getAllUsers(limit, offset);

  res.json({
    data:   result.rows,
    meta: {
      total:  result.total,
      limit:  result.limit,
      offset: result.offset,
    },
  });
}));

// ---------------------------------------------------------------------------
// GET /users/search
// Searches users by name or email (case-insensitive substring match).
//
// Query parameters
// ────────────────
//   q      {string, 1–200 chars}          — search term (required)
//   limit  {integer, 1–100, default 20}   — page size
//   offset {integer, 0–1000000, default 0} — rows to skip
//
// Example
//   GET /users/search?q=alice&limit=5
//
// NOTE: This route is declared BEFORE /users/:id so that the literal path
//       segment "search" is not mistakenly parsed as a numeric id.
// ---------------------------------------------------------------------------
app.get('/users/search', asyncHandler(async (req, res) => {
  const { q, limit, offset } = req.query;
  const result = await searchUsers(q, limit, offset);

  res.json({
    data:  result.rows,
    meta: {
      total:  result.total,
      limit:  result.limit,
      offset: result.offset,
      query:  result.query,
    },
  });
}));

// ---------------------------------------------------------------------------
// GET /users/:id
// Returns a single user by numeric primary key.
//
// Path parameters
// ────────────────
//   id {positive integer} — user's primary key
//
// Example
//   GET /users/42
// ---------------------------------------------------------------------------
app.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await getUserById(req.params.id);
  res.json({ data: user });
}));

// ---------------------------------------------------------------------------
// Centralised error handler
// ---------------------------------------------------------------------------
// Must be defined after all routes (Express identifies error middleware by
// its 4-argument signature).
// ---------------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Determine HTTP status code from the error type.
  const statusCode = err.statusCode
    || (err instanceof ValidationError ? 400 : null)
    || (err instanceof NotFoundError   ? 404 : null)
    || 500;

  // Log the full stack for server errors; only the message for client errors.
  if (statusCode >= 500) {
    console.error('[app] Unhandled error:', err);
  } else {
    console.warn(`[app] Client error (${statusCode}):`, err.message);
  }

  // Never expose internal error details (stack traces, query text, etc.)
  // to the caller for 5xx responses.
  res.status(statusCode).json({
    error: {
      message: statusCode < 500 ? err.message : 'Internal server error',
      ...(statusCode < 500 && { type: err.name }),
    },
  });
});

// ---------------------------------------------------------------------------
// Server startup & graceful shutdown
// ---------------------------------------------------------------------------

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`[app] Server running on port ${PORT}`);
});

// Allow tests / callers to await the server being ready.
server.on('error', (err) => {
  console.error('[app] Server error:', err);
  process.exit(1);
});

/**
 * Graceful shutdown: stop accepting new connections, wait for in-flight
 * requests to finish, then drain the DB pool.
 */
function gracefulShutdown(signal) {
  console.info(`[app] Received ${signal} — shutting down gracefully…`);

  server.close(async () => {
    console.info('[app] HTTP server closed.');
    await closePool();
    process.exit(0);
  });

  // Hard-kill if graceful shutdown takes too long.
  setTimeout(() => {
    console.error('[app] Graceful shutdown timed out — forcing exit.');
    process.exit(1);
  }, 15_000).unref();
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT',  () => gracefulShutdown('SIGINT'));

module.exports = app;

/**
 * queries.test.js — Unit tests for the queries.js module
 *
 * The pg Pool is mocked so that no real database is needed.
 * Tests verify:
 *   - correct SQL and bind parameters for each query function
 *   - input validation (ValidationError) for all three functions
 *   - NotFoundError when getUserById receives 0 rows
 *   - pagination metadata is correctly assembled
 *   - total_count is stripped from returned rows
 *   - query timing logs fire (console.info spy)
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the db module BEFORE requiring queries.js so the Pool reference
// inside queries.js is replaced with our controllable mock.
// ---------------------------------------------------------------------------
const mockQuery = jest.fn();
jest.mock('./db', () => ({
  pool:      { query: mockQuery },
  closePool: jest.fn(),
}));

const {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,
  NotFoundError,
  DEFAULTS,
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Builds a fake pg result with total_count attached to each row. */
function makeRows(rows, total) {
  return {
    rows: rows.map((r) => ({ ...r, total_count: String(total) })),
  };
}

// ---------------------------------------------------------------------------
// Setup / teardown
// ---------------------------------------------------------------------------

beforeEach(() => {
  jest.clearAllMocks();
  jest.spyOn(console, 'info').mockImplementation(() => {});
  jest.spyOn(console, 'warn').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => {
  jest.restoreAllMocks();
});

// ===========================================================================
// getUserById
// ===========================================================================

describe('getUserById', () => {
  const ALICE = { id: 1, name: 'Alice', email: 'alice@example.com',
                  created_at: new Date(), updated_at: new Date() };

  test('resolves with the first row when the user exists', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [ALICE] });

    const result = await getUserById(1);

    expect(result).toEqual(ALICE);
  });

  test('passes id as a bind parameter — not interpolated into SQL', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [ALICE] });

    await getUserById('7');

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([7]);                   // coerced to integer
    expect(sql).not.toContain('7');                // NOT in the SQL string
    expect(sql).toContain('$1');                   // positional parameter
  });

  test('throws NotFoundError when no rows returned', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [] });

    await expect(getUserById(99)).rejects.toThrow(NotFoundError);
    await expect(getUserById(99)).rejects.toMatchObject({ statusCode: 404 });
  });

  test('throws ValidationError for non-integer id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for zero id', async () => {
    await expect(getUserById(0)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for negative id', async () => {
    await expect(getUserById(-5)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError when id is missing', async () => {
    await expect(getUserById(null)).rejects.toThrow(ValidationError);
    await expect(getUserById(undefined)).rejects.toThrow(ValidationError);
  });

  test('logs query timing on success', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [ALICE] });
    await getUserById(1);
    expect(console.info).toHaveBeenCalledWith(
      expect.stringContaining('getUserById')
    );
    expect(console.info).toHaveBeenCalledWith(
      expect.stringContaining('status=ok')
    );
  });

  test('logs query timing on db error', async () => {
    mockQuery.mockRejectedValueOnce(new Error('connection refused'));
    await expect(getUserById(1)).rejects.toThrow('connection refused');
    expect(console.info).toHaveBeenCalledWith(
      expect.stringContaining('status=error')
    );
  });

  test('SQL injection attempt is neutralised by parameterisation', async () => {
    // The value "1 OR 1=1" is not an integer, so parseIntParam rejects it
    // before it ever reaches the pool.
    await expect(getUserById('1 OR 1=1')).rejects.toThrow(ValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

// ===========================================================================
// getAllUsers
// ===========================================================================

describe('getAllUsers', () => {
  const USERS = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date(), updated_at: new Date() },
  ];

  test('returns rows, total, limit, offset', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(USERS, 42));

    const result = await getAllUsers(10, 20);

    expect(result.rows).toHaveLength(2);
    expect(result.total).toBe(42);
    expect(result.limit).toBe(10);
    expect(result.offset).toBe(20);
  });

  test('strips total_count from returned rows', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(USERS, 2));

    const result = await getAllUsers();
    result.rows.forEach((row) => {
      expect(row).not.toHaveProperty('total_count');
    });
  });

  test('uses default limit and offset when not supplied', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(USERS, 2));

    const result = await getAllUsers();

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe(DEFAULTS.LIMIT);
    expect(params[1]).toBe(DEFAULTS.OFFSET);
    expect(result.limit).toBe(DEFAULTS.LIMIT);
    expect(result.offset).toBe(DEFAULTS.OFFSET);
  });

  test('passes limit and offset as bind parameters', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(USERS, 2));

    await getAllUsers('15', '30');

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([15, 30]);
    expect(sql).toContain('$1');
    expect(sql).toContain('$2');
    expect(sql).not.toContain('15');
    expect(sql).not.toContain('30');
  });

  test('returns total=0 when result set is empty', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [] });

    const result = await getAllUsers();
    expect(result.total).toBe(0);
    expect(result.rows).toHaveLength(0);
  });

  test('throws ValidationError when limit exceeds MAX_LIMIT', async () => {
    await expect(getAllUsers(DEFAULTS.MAX_LIMIT + 1)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for limit=0', async () => {
    await expect(getAllUsers(0)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for negative offset', async () => {
    await expect(getAllUsers(10, -1)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for non-integer limit', async () => {
    await expect(getAllUsers('abc')).rejects.toThrow(ValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('logs query timing', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(USERS, 2));
    await getAllUsers();
    expect(console.info).toHaveBeenCalledWith(
      expect.stringContaining('getAllUsers')
    );
  });
});

// ===========================================================================
// searchUsers
// ===========================================================================

describe('searchUsers', () => {
  const MATCHES = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() },
  ];

  test('returns matching rows with metadata', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(MATCHES, 1));

    const result = await searchUsers('alice');

    expect(result.rows).toHaveLength(1);
    expect(result.total).toBe(1);
    expect(result.query).toBe('alice');
  });

  test('passes search term as first bind parameter', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(MATCHES, 1));

    await searchUsers('alice', 5, 0);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('alice');   // term is params[0]
    expect(params[1]).toBe(5);          // limit is params[1]
    expect(params[2]).toBe(0);          // offset is params[2]

    // The raw search term must NOT appear in the SQL string.
    expect(sql).not.toContain('alice');
    expect(sql).toContain('$1');
  });

  test('LIKE wildcards are built inside SQL, not in Node', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(MATCHES, 1));

    await searchUsers('alice');

    const [sql] = mockQuery.mock.calls[0];
    // The || concatenation approach keeps wildcards on the DB side.
    expect(sql).toMatch(/ILIKE\s+'%'\s*\|\|\s*\$1\s*\|\|\s*'%'/);
  });

  test('trims whitespace from search term', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(MATCHES, 1));

    await searchUsers('  alice  ');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('alice');
  });

  test('strips total_count from returned rows', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(MATCHES, 1));

    const result = await searchUsers('alice');
    result.rows.forEach((row) => expect(row).not.toHaveProperty('total_count'));
  });

  test('returns empty rows and total=0 when no match', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [] });

    const result = await searchUsers('zzznomatch');
    expect(result.rows).toHaveLength(0);
    expect(result.total).toBe(0);
  });

  test('throws ValidationError for missing query', async () => {
    await expect(searchUsers()).rejects.toThrow(ValidationError);
    await expect(searchUsers(null)).rejects.toThrow(ValidationError);
    await expect(searchUsers('')).rejects.toThrow(ValidationError);
    await expect(searchUsers('   ')).rejects.toThrow(ValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws ValidationError when query exceeds max length', async () => {
    const tooLong = 'a'.repeat(DEFAULTS.MAX_SEARCH_LEN + 1);
    await expect(searchUsers(tooLong)).rejects.toThrow(ValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
