    // The attacker value is a string, so it passes type validation but is
    // sent as a plain bind parameter value — it cannot alter SQL structure.
    mockQuery.mockResolvedValueOnce({ rows: [] });

    await searchUsers("' OR '1'='1");

    const [sql, params] = mockQuery.mock.calls[0];
    // The injected string is in params, not in the SQL text.
    expect(params[0]).toBe("' OR '1'='1");
    expect(sql).not.toContain("' OR '1'='1");
  });

  test('logs query timing on success', async () => {
    mockQuery.mockResolvedValueOnce(makeRows(MATCHES, 1));
    await searchUsers('alice');
    expect(console.info).toHaveBeenCalledWith(
      expect.stringContaining('searchUsers')
    );
    expect(console.info).toHaveBeenCalledWith(
      expect.stringContaining('status=ok')
    );
  });

  test('logs query timing on db error', async () => {
    mockQuery.mockRejectedValueOnce(new Error('timeout'));
    await expect(searchUsers('alice')).rejects.toThrow('timeout');
    expect(console.info).toHaveBeenCalledWith(
      expect.stringContaining('status=error')
    );
  });
});

