    "dev": "node --watch app.js",
    "test": "node --test tests/queries.test.js"
  },
  "keywords": [],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "pg": "^8.12.0"
  }
}

/**
 * db.js — PostgreSQL connection pool
 *
 * A single Pool instance is created once at module load time and shared
 * across the whole process (connection pooling). All query functions in
 * queries.js borrow a client from this pool for the duration of one query
 * and immediately return it, so the pool stays healthy under load.
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials ever appear in source code.
 */

'use strict';

const { Pool } = require('pg');

// ─── Pool configuration ──────────────────────────────────────────────────────
// All values come from environment variables. DATABASE_URL is the only
// required one; the rest have safe defaults that suit most deployments.

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Maximum number of clients kept open in the pool.
  // Tune this to match your Postgres max_connections setting minus headroom
  // for other tools (migrations, psql sessions, etc.).
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // How long (ms) a client may sit idle before being closed and removed.
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT_MS ?? '30000', 10),

  // How long (ms) to wait for a free client before throwing an error.
  connectionTimeoutMillis: parseInt(
    process.env.DB_POOL_CONNECTION_TIMEOUT_MS ?? '2000',
    10,
  ),

  // Reject connections whose TLS certificate cannot be verified when the
  // database URL contains sslmode=require (recommended for production).
  ssl: process.env.DATABASE_URL?.includes('sslmode=require')
    ? { rejectUnauthorized: true }
    : undefined,
});

// ─── Pool-level event handlers ───────────────────────────────────────────────

pool.on('connect', (client) => {
  console.log('[db] new client connected to pool');

  // Enforce a statement-level timeout on every connection so that a runaway
  // query cannot hold a client indefinitely.
  client.query('SET statement_timeout = 30000').catch((err) => {
    console.error('[db] failed to set statement_timeout:', err.message);
  });
});

pool.on('acquire', () => {
  console.log(
    `[db] client acquired — pool size: ${pool.totalCount} total, ` +
    `${pool.idleCount} idle, ${pool.waitingCount} waiting`,
  );
});

pool.on('remove', () => {
  console.log('[db] client removed from pool');
});

pool.on('error', (err) => {
  // An idle client in the pool encountered an unexpected error (e.g. the
  // database server closed the connection). Log it so operators notice.
  console.error('[db] unexpected pool error:', err.message);
});

// ─── Graceful shutdown ───────────────────────────────────────────────────────

/**
 * Drain and close all pool clients cleanly.
 * Call this on SIGTERM / SIGINT so in-flight queries finish before the process
 * exits, and Postgres does not see abrupt disconnections.
 */
async function closePool() {
  console.log('[db] closing connection pool…');
  await pool.end();
  console.log('[db] pool closed');
}

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * ─────────────────
 * 1. SQL injection prevention
 *    Every piece of user-supplied data is passed as a *parameter* ($1, $2, …)
 *    rather than interpolated into the SQL string. The pg driver sends
 *    parameters to Postgres over the wire separately from the query text so
 *    Postgres never parses them as SQL — this is the gold-standard defence
 *    against injection, stronger than any escaping heuristic.
 *
 * 2. Input validation before the query is sent
 *    Parameters are validated and coerced at the top of each function so that
 *    bad input is rejected with a clear error before a pool client is even
 *    acquired. This keeps error messages developer-friendly and prevents
 *    unexpected type coercions inside Postgres.
 *
 * 3. Connection pooling
 *    All functions call pool.query() which borrows a client for the duration
 *    of one round-trip and returns it automatically. No manual client.release()
 *    is needed (and therefore cannot be forgotten).
 *
 * 4. Query timing logs
 *    Every function records wall-clock time around the pool.query() call and
 *    emits a structured log line so slow queries are immediately visible in
 *    application logs or a log aggregation tool.
 *
 * 5. Safe column allow-list for search
 *    searchUsers() accepts an optional `searchField` that restricts which
 *    column is searched. Because column names cannot be parameterised in
 *    Postgres, the value is validated against a hard-coded allow-list before
 *    being embedded in the SQL string.
 */

'use strict';

require('dotenv').config();
const { pool } = require('./db');

// ─── Constants ───────────────────────────────────────────────────────────────

/** Maximum rows getAllUsers() or searchUsers() will ever return in one call. */
const HARD_LIMIT = 1000;

/** Default page size when the caller does not supply a limit. */
const DEFAULT_LIMIT = 20;

/** Columns that searchUsers() is permitted to search against. */
const SEARCHABLE_FIELDS = new Set(['name', 'email', 'username']);

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Emit a structured query-timing log line.
 *
 * @param {string} fnName   - Name of the calling query function.
 * @param {string} sql      - The SQL string that was executed (no parameters).
 * @param {unknown[]} params - Bound parameters (logged for debugging).
 * @param {number} startMs  - Value of Date.now() before pool.query() was called.
 * @param {number} rowCount - Number of rows returned / affected.
 */
function logQueryTiming(fnName, sql, params, startMs, rowCount) {
  const durationMs = Date.now() - startMs;
  // Flatten the SQL to a single line for log readability.
  const flatSql = sql.replace(/\s+/g, ' ').trim();
  console.log(
    `[query] fn=${fnName} duration=${durationMs}ms rows=${rowCount} ` +
    `params=${JSON.stringify(params)} sql="${flatSql}"`,
  );
}

/**
 * Parse and clamp an integer, throwing a RangeError when the value is outside
 * the given bounds.
 *
 * @param {unknown} value         - Raw value to coerce.
 * @param {string}  name          - Parameter name (used in the error message).
 * @param {number}  min           - Inclusive lower bound.
 * @param {number}  max           - Inclusive upper bound.
 * @param {number}  [defaultVal]  - Returned when value is null / undefined.
 * @returns {number}
 */
function parseIntParam(value, name, min, max, defaultVal) {
  if (value === null || value === undefined || value === '') {
    if (defaultVal !== undefined) return defaultVal;
    throw new RangeError(`${name} is required`);
  }
  const n = Number(value);
  if (!Number.isInteger(n)) {
    throw new TypeError(`${name} must be an integer, got: ${JSON.stringify(value)}`);
  }
  if (n < min || n > max) {
    throw new RangeError(`${name} must be between ${min} and ${max}, got: ${n}`);
  }
  return n;
}

// ─── Query functions ──────────────────────────────────────────────────────────

/**
 * Fetch a single user row by its primary-key ID.
 *
 * SQL injection prevention
 * ────────────────────────
 * `id` is cast to a JavaScript integer before use and passed as $1 so Postgres
 * receives it as an integer literal, never as SQL text.
 *
 * @param {number|string} id - The user's numeric primary key.
 * @returns {Promise<object|null>} The user row, or null if not found.
 *
 * @example
 * const user = await getUserById(42);
 * // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: Date }
 */
async function getUserById(id) {
  // ── Validate ──────────────────────────────────────────────────────────────
  // Integers only; no strings, floats, objects, or SQL fragments.
  const safeId = parseIntParam(id, 'id', 1, Number.MAX_SAFE_INTEGER);

  // ── Build query ───────────────────────────────────────────────────────────
  // $1 is the *only* place user input touches the query, and it is a bound
  // parameter — Postgres will never interpret it as SQL.
  const sql = `
    SELECT
      id,
      name,
      email,
      username,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;
  const params = [safeId];

  // ── Execute ───────────────────────────────────────────────────────────────
  const startMs = Date.now();
  const { rows, rowCount } = await pool.query(sql, params);
  logQueryTiming('getUserById', sql, params, startMs, rowCount);

  return rows[0] ?? null;
}

/**
 * Fetch a paginated list of all users, ordered by creation date (newest first).
 *
 * SQL injection prevention
 * ────────────────────────
 * Both `limit` and `offset` are coerced to integers and passed as $1 / $2.
 * An integer parameter cannot carry SQL syntax, so pagination values supplied
 * by a caller (e.g. from query-string parameters) cannot alter query structure.
 *
 * @param {number} [limit=20]  - Rows per page (1–1000).
 * @param {number} [offset=0]  - Zero-based row offset.
 * @returns {Promise<{ users: object[], total: number }>}
 *   `users`  — the page of user rows.
 *   `total`  — full count of users in the table (for building pagination UI).
 *
 * @example
 * const { users, total } = await getAllUsers(10, 20);
 * // Page 3 of 10-per-page results; total is the full table count.
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = 0) {
  // ── Validate ──────────────────────────────────────────────────────────────
  const safeLimit  = parseIntParam(limit,  'limit',  1, HARD_LIMIT,        DEFAULT_LIMIT);
  const safeOffset = parseIntParam(offset, 'offset', 0, Number.MAX_SAFE_INTEGER, 0);

  // ── Build query ───────────────────────────────────────────────────────────
  // Two separate queries in a single round-trip via Promise.all for efficiency:
  //   1. The data page.
  //   2. The total row count (for pagination metadata).
  const dataSql = `
    SELECT
      id,
      name,
      email,
      username,
      created_at,
      updated_at
    FROM users
    ORDER BY created_at DESC, id DESC
    LIMIT $1
    OFFSET $2
  `;
  const countSql = `SELECT COUNT(*)::integer AS total FROM users`;

  const dataParams = [safeLimit, safeOffset];

  // ── Execute ───────────────────────────────────────────────────────────────
  const startMs = Date.now();
  const [dataResult, countResult] = await Promise.all([
    pool.query(dataSql, dataParams),
    pool.query(countSql),
  ]);
  // Log timing once, covering both queries (they ran in parallel).
  logQueryTiming('getAllUsers', dataSql, dataParams, startMs, dataResult.rowCount);

  return {
    users: dataResult.rows,
    total: countResult.rows[0].total,
  };
}

/**
 * Full-text search across user records using a case-insensitive ILIKE pattern.
 *
 * SQL injection prevention — two layers
 * ──────────────────────────────────────
 * Layer 1 — column name allow-list
 *   `searchField` (the column to search) is validated against SEARCHABLE_FIELDS
 *   before being embedded in the SQL string. Column identifiers cannot be
 *   parameterised in Postgres, so the allow-list is the correct control here.
 *   Any value not in the set throws immediately, before a pool client is acquired.
 *
 * Layer 2 — parameterised query value
 *   The search term itself is passed as $1 so that wildcard characters in the
 *   user's search string (%, _, \) match literally rather than acting as SQL
 *   meta-characters. The pg driver handles the escaping automatically.
 *
 * @param {string} query              - The search term (1–200 characters).
 * @param {object} [options]          - Optional modifiers.
 * @param {string} [options.searchField='name'] - Column to search (name | email | username).
 * @param {number} [options.limit=20]           - Rows per page (1–1000).
 * @param {number} [options.offset=0]           - Zero-based row offset.
 * @returns {Promise<{ users: object[], total: number }>}
 *
 * @example
 * const { users, total } = await searchUsers('alice', { searchField: 'name', limit: 5 });
 */
async function searchUsers(query, { searchField = 'name', limit = DEFAULT_LIMIT, offset = 0 } = {}) {
  // ── Validate search term ──────────────────────────────────────────────────
  if (typeof query !== 'string' || query.trim().length === 0) {
    throw new TypeError('query must be a non-empty string');
  }
  if (query.length > 200) {
    throw new RangeError('query must not exceed 200 characters');
  }
  const safeQuery = query.trim();

  // ── Validate column name (allow-list) ─────────────────────────────────────
  // Column names cannot be bound as parameters; we guard against injection by
  // refusing any value not in our explicit allow-list.
  if (!SEARCHABLE_FIELDS.has(searchField)) {
    throw new TypeError(
      `searchField must be one of [${[...SEARCHABLE_FIELDS].join(', ')}], ` +
      `got: ${JSON.stringify(searchField)}`,
    );
  }

  // ── Validate pagination ───────────────────────────────────────────────────
  const safeLimit  = parseIntParam(limit,  'limit',  1, HARD_LIMIT,        DEFAULT_LIMIT);
  const safeOffset = parseIntParam(offset, 'offset', 0, Number.MAX_SAFE_INTEGER, 0);

  // ── Build query ───────────────────────────────────────────────────────────
  // $1  — the ILIKE search pattern  (user data → always a bound parameter)
  // $2  — LIMIT                     (user data → always a bound parameter)
  // $3  — OFFSET                    (user data → always a bound parameter)
  //
  // searchField is from the allow-list above, so embedding it is safe.
  //
  // The search pattern wraps the term in % wildcards so 'alice' matches
  // 'alice@example.com', 'Alice Smith', etc.
  const searchPattern = `%${safeQuery}%`;
  const dataSql = `
    SELECT
      id,
      name,
      email,
      username,
      created_at,
      updated_at
    FROM users
    WHERE ${searchField} ILIKE $1
    ORDER BY created_at DESC, id DESC
    LIMIT $2
    OFFSET $3
  `;
  const countSql = `
    SELECT COUNT(*)::integer AS total
    FROM users
    WHERE ${searchField} ILIKE $1
  `;

  const dataParams  = [searchPattern, safeLimit, safeOffset];
  const countParams = [searchPattern];

  // ── Execute ───────────────────────────────────────────────────────────────
  const startMs = Date.now();
  const [dataResult, countResult] = await Promise.all([
    pool.query(dataSql, dataParams),
    pool.query(countSql, countParams),
  ]);
  logQueryTiming('searchUsers', dataSql, dataParams, startMs, dataResult.rowCount);

  return {
    users: dataResult.rows,
    total: countResult.rows[0].total,
  };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Expose constants so callers can reflect on limits (e.g. for API docs).
  HARD_LIMIT,
  DEFAULT_LIMIT,
  SEARCHABLE_FIELDS,
};

/**
 * app.js — Express application with a PostgreSQL query layer
 *
 * /users endpoints
 * ─────────────────
 *   GET /users                  — paginated list of all users
 *   GET /users/:id              — single user by ID
 *   GET /users/search?q=…       — search users by name, email, or username
 *
 * All database access goes through queries.js which uses:
 *   • Parameterised queries     — SQL injection prevention
 *   • Connection pooling        — via a shared pg.Pool in db.js
 *   • Query timing logs         — emitted by logQueryTiming() in queries.js
 *   • Input validation          — bad params are rejected before hitting the DB
 */

'use strict';

require('dotenv').config();

const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ─── Health check ─────────────────────────────────────────────────────────────

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── /users/search ────────────────────────────────────────────────────────────
// Defined *before* /users/:id so the literal segment "search" is matched first
// and is never mistaken for a numeric ID.

/**
 * GET /users/search?q=alice&field=name&limit=20&offset=0
 *
 * Query parameters
 * ────────────────
 * q       {string}  Required. The search term (1–200 chars).
 * field   {string}  Optional. Column to search: name | email | username. Default: name.
 * limit   {number}  Optional. Page size (1–1000). Default: 20.
 * offset  {number}  Optional. Row offset. Default: 0.
 */
app.get('/users/search', async (req, res) => {
  const { q, field = 'name', limit, offset } = req.query;

  try {
    const { users, total } = await searchUsers(q, {
      searchField: field,
      limit,
      offset,
    });

    res.json({
      data: users,
      meta: {
        total,
        limit:  Number(limit  ?? 20),
        offset: Number(offset ?? 0),
        query:  q,
        field,
      },
    });
  } catch (err) {
    handleQueryError(err, res, 'searchUsers');
  }
});

// ─── /users/:id ───────────────────────────────────────────────────────────────

/**
 * GET /users/:id
 *
 * Path parameters
 * ───────────────
 * id  {integer}  Required. The user's numeric primary key.
 */
app.get('/users/:id', async (req, res) => {
  const { id } = req.params;

  try {
    const user = await getUserById(id);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `No user found with id ${id}`,
      });
    }

    res.json({ data: user });
  } catch (err) {
    handleQueryError(err, res, 'getUserById');
  }
});

// ─── /users ───────────────────────────────────────────────────────────────────

/**
 * GET /users?limit=20&offset=0
 *
 * Query parameters
 * ────────────────
 * limit   {number}  Optional. Page size (1–1000). Default: 20.
 * offset  {number}  Optional. Row offset. Default: 0.
 */
app.get('/users', async (req, res) => {
  const { limit, offset } = req.query;

  try {
    const { users, total } = await getAllUsers(limit, offset);

    res.json({
      data: users,
      meta: {
        total,
        limit:  Number(limit  ?? 20),
        offset: Number(offset ?? 0),
      },
    });
  } catch (err) {
    handleQueryError(err, res, 'getAllUsers');
  }
});

// ─── Error handling helper ────────────────────────────────────────────────────

/**
 * Map query-layer errors to appropriate HTTP responses.
 *
 * TypeError  / RangeError → 400 Bad Request  (caller sent invalid input)
 * Anything else           → 500 Internal Server Error
 *
 * Stack traces are never sent to the client; they are logged server-side only.
 *
 * @param {Error}    err     - The thrown error.
 * @param {Response} res     - Express response object.
 * @param {string}   fnName  - Query function name (for log context).
 */
function handleQueryError(err, res, fnName) {
  if (err instanceof TypeError || err instanceof RangeError) {
    console.warn(`[${fnName}] validation error: ${err.message}`);
    return res.status(400).json({
      error: 'Bad Request',
      message: err.message,
    });
  }

  // Unexpected database or application error — log the full stack, return a
  // generic message so internal details are not leaked to clients.
  console.error(`[${fnName}] unexpected error:`, err);
  return res.status(500).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred. Please try again later.',
  });
}

// ─── Server startup & graceful shutdown ───────────────────────────────────────

const PORT = parseInt(process.env.PORT ?? '3000', 10);
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

/**
 * Graceful shutdown — wait for in-flight requests to finish, then drain the
 * connection pool before the process exits.
 */
async function shutdown(signal) {
  console.log(`\n[app] received ${signal} — shutting down gracefully…`);
  server.close(async () => {
    await closePool();
    console.log('[app] shutdown complete');
    process.exit(0);
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;

/**
 * tests/queries.test.js — Unit tests for queries.js
 *
 * Run with:  node --test tests/queries.test.js
 *
 * The pool is mocked so these tests never need a real database connection.
 * Each test exercises input validation and the correct SQL/parameter shape.
 */

'use strict';

const assert = require('node:assert/strict');
const { describe, it, beforeEach, mock } = require('node:test');

// ─── Mock the pool before requiring queries.js ───────────────────────────────
// We replace db.js's pool.query with a controllable stub so we can:
//   • Verify the exact SQL and parameters each function produces.
//   • Simulate row data without a real Postgres connection.
//   • Keep tests fast and hermetic.

let mockQueryFn;   // set per-test via beforeEach

// Intercept require('pg') before queries.js loads it.
// Node's module cache means the mock must be registered before the first
// require('./queries'), which is why this file mocks db.js directly.
const db = require('../db');
db.pool.query = (...args) => mockQueryFn(...args);

const {
  getUserById,
  getAllUsers,
  searchUsers,
  HARD_LIMIT,
  DEFAULT_LIMIT,
  SEARCHABLE_FIELDS,
} = require('../queries');

// ─── getUserById ─────────────────────────────────────────────────────────────

describe('getUserById', () => {
  beforeEach(() => {
    // Default: return a single user row.
    mockQueryFn = async (_sql, _params) => ({ rows: [{ id: 1, name: 'Alice' }], rowCount: 1 });
  });

  it('passes a numeric $1 parameter', async () => {
    let capturedParams;
    mockQueryFn = async (_sql, params) => {
      capturedParams = params;
      return { rows: [{ id: 42, name: 'Bob' }], rowCount: 1 };
    };
    await getUserById(42);
    assert.deepEqual(capturedParams, [42]);
  });

  it('coerces a numeric string ID to an integer', async () => {
    let capturedParams;
    mockQueryFn = async (_sql, params) => {
      capturedParams = params;
      return { rows: [{ id: 7 }], rowCount: 1 };
    };
    await getUserById('7');
    assert.deepEqual(capturedParams, [7]);
  });

  it('returns null when no row is found', async () => {
    mockQueryFn = async () => ({ rows: [], rowCount: 0 });
    const result = await getUserById(999);
    assert.equal(result, null);
  });

  it('returns the user object when a row is found', async () => {
    const fakeUser = { id: 1, name: 'Alice', email: 'alice@example.com' };
    mockQueryFn = async () => ({ rows: [fakeUser], rowCount: 1 });
    const result = await getUserById(1);
    assert.deepEqual(result, fakeUser);
  });

  it('throws TypeError for a non-integer ID (float)', async () => {
    await assert.rejects(
      () => getUserById(1.5),
      (err) => err instanceof TypeError && /integer/i.test(err.message),
    );
  });

  it('throws TypeError for a non-integer ID (string)', async () => {
    await assert.rejects(
      () => getUserById('not-a-number'),
      (err) => err instanceof TypeError,
    );
  });

  it('throws RangeError for ID < 1', async () => {
    await assert.rejects(
      () => getUserById(0),
      (err) => err instanceof RangeError,
    );
  });

  it('throws RangeError for negative ID', async () => {
    await assert.rejects(
      () => getUserById(-5),
      (err) => err instanceof RangeError,
    );
  });

  it('rejects SQL injection attempt in ID', async () => {
    await assert.rejects(
      () => getUserById("1; DROP TABLE users; --"),
      (err) => err instanceof TypeError || err instanceof RangeError,
    );
  });
});

// ─── getAllUsers ──────────────────────────────────────────────────────────────

describe('getAllUsers', () => {
  const fakeUsers  = [{ id: 1 }, { id: 2 }];
  const fakeCount  = [{ total: 50 }];

  beforeEach(() => {
    // Promise.all fires two queries; return different shapes based on call order.
    let callCount = 0;
    mockQueryFn = async (sql) => {
      callCount++;
      // COUNT query contains "COUNT(*)"
      if (sql.includes('COUNT(*)')) return { rows: fakeCount, rowCount: 1 };
      return { rows: fakeUsers, rowCount: fakeUsers.length };
    };
  });

  it('returns users array and total', async () => {
    const { users, total } = await getAllUsers(10, 0);
    assert.deepEqual(users, fakeUsers);
    assert.equal(total, 50);
  });

  it('uses DEFAULT_LIMIT when called with no arguments', async () => {
    let capturedDataParams;
    let callCount = 0;
    mockQueryFn = async (sql, params) => {
      callCount++;
      if (sql.includes('COUNT(*)')) return { rows: fakeCount, rowCount: 1 };
      capturedDataParams = params;
      return { rows: [], rowCount: 0 };
    };
    await getAllUsers();
    assert.equal(capturedDataParams[0], DEFAULT_LIMIT);
    assert.equal(capturedDataParams[1], 0);
  });

  it('passes limit and offset as parameters', async () => {
    let capturedDataParams;
    mockQueryFn = async (sql, params) => {
      if (sql.includes('COUNT(*)')) return { rows: fakeCount, rowCount: 1 };
      capturedDataParams = params;
      return { rows: [], rowCount: 0 };
    };
    await getAllUsers(50, 100);
    assert.deepEqual(capturedDataParams, [50, 100]);
  });

  it('throws RangeError when limit exceeds HARD_LIMIT', async () => {
    await assert.rejects(
      () => getAllUsers(HARD_LIMIT + 1, 0),
      (err) => err instanceof RangeError,
    );
  });

  it('throws RangeError when limit is 0', async () => {
    await assert.rejects(
      () => getAllUsers(0),
      (err) => err instanceof RangeError,
    );
  });

  it('throws RangeError for negative offset', async () => {
    await assert.rejects(
      () => getAllUsers(10, -1),
      (err) => err instanceof RangeError,
    );
  });

  it('throws TypeError when limit is not an integer', async () => {
    await assert.rejects(
      () => getAllUsers('abc'),
      (err) => err instanceof TypeError,
    );
  });
});

// ─── searchUsers ─────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  const fakeUsers = [{ id: 1, name: 'Alice' }];
  const fakeCount = [{ total: 1 }];

  beforeEach(() => {
    mockQueryFn = async (sql) => {
      if (sql.includes('COUNT(*)')) return { rows: fakeCount, rowCount: 1 };
      return { rows: fakeUsers, rowCount: fakeUsers.length };
    };
  });

  it('returns matching users and total', async () => {
    const { users, total } = await searchUsers('alice');
    assert.deepEqual(users, fakeUsers);
    assert.equal(total, 1);
  });

  it('wraps the search term in % wildcards for ILIKE', async () => {
    let capturedDataParams;
    mockQueryFn = async (sql, params) => {
      if (sql.includes('COUNT(*)')) return { rows: fakeCount, rowCount: 1 };
      capturedDataParams = params;
      return { rows: [], rowCount: 0 };
    };
    await searchUsers('alice');
    assert.equal(capturedDataParams[0], '%alice%');
  });

  it('passes search pattern as $1 (never embedded in SQL string)', async () => {
    let capturedSql = '';
    mockQueryFn = async (sql, params) => {
      capturedSql = sql;
      if (sql.includes('COUNT(*)')) return { rows: fakeCount, rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };
    await searchUsers("'; DROP TABLE users; --");
    // The SQL must contain $1, not the raw injection string.
    assert.ok(capturedSql.includes('$1'), 'SQL should use $1 placeholder');
    assert.ok(!capturedSql.includes('DROP'), 'SQL must not contain injection payload');
  });

  it('defaults to searching the name column', async () => {
    let capturedSql = '';
    mockQueryFn = async (sql) => {
      capturedSql = sql;
      if (sql.includes('COUNT(*)')) return { rows: fakeCount, rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };
    await searchUsers('alice');
    assert.ok(capturedSql.includes('name ILIKE'));
  });

  it('accepts email as searchField', async () => {
    let capturedSql = '';
    mockQueryFn = async (sql) => {
      capturedSql = sql;
      if (sql.includes('COUNT(*)')) return { rows: fakeCount, rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };
    await searchUsers('alice', { searchField: 'email' });
    assert.ok(capturedSql.includes('email ILIKE'));
  });

  it('accepts username as searchField', async () => {
    let capturedSql = '';
    mockQueryFn = async (sql) => {
      capturedSql = sql;
      if (sql.includes('COUNT(*)')) return { rows: fakeCount, rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };
    await searchUsers('alice', { searchField: 'username' });
    assert.ok(capturedSql.includes('username ILIKE'));
  });

  it('throws TypeError for an unknown searchField (allow-list check)', async () => {
    await assert.rejects(
      () => searchUsers('alice', { searchField: 'password_hash' }),
      (err) => err instanceof TypeError && /searchField/i.test(err.message),
    );
  });

  it('rejects SQL injection via searchField', async () => {
    await assert.rejects(
      () => searchUsers('alice', { searchField: "name; DROP TABLE users; --" }),
      (err) => err instanceof TypeError,
    );
  });

  it('rejects SQL injection via searchField (UNION attempt)', async () => {
    await assert.rejects(
      () => searchUsers('x', { searchField: "name UNION SELECT * FROM secrets--" }),
      (err) => err instanceof TypeError,
    );
  });

  it('throws TypeError for empty query string', async () => {
    await assert.rejects(
      () => searchUsers(''),
      (err) => err instanceof TypeError && /non-empty/i.test(err.message),
    );
  });

  it('throws TypeError for non-string query', async () => {
    await assert.rejects(
      () => searchUsers(null),
      (err) => err instanceof TypeError,
    );
  });

  it('throws RangeError for query exceeding 200 characters', async () => {
    await assert.rejects(
      () => searchUsers('a'.repeat(201)),
      (err) => err instanceof RangeError && /200/i.test(err.message),
    );
  });

  it('throws RangeError when limit exceeds HARD_LIMIT', async () => {
    await assert.rejects(
      () => searchUsers('alice', { limit: HARD_LIMIT + 1 }),
      (err) => err instanceof RangeError,
    );
  });

  it('trims whitespace from the search term', async () => {
    let capturedParams;
    mockQueryFn = async (sql, params) => {
      if (sql.includes('COUNT(*)')) return { rows: fakeCount, rowCount: 1 };
      capturedParams = params;
      return { rows: [], rowCount: 0 };
    };
    await searchUsers('  alice  ');
    assert.equal(capturedParams[0], '%alice%');
  });
});

// ─── Exported constants ───────────────────────────────────────────────────────

describe('exported constants', () => {
  it('HARD_LIMIT is a positive integer', () => {
    assert.ok(Number.isInteger(HARD_LIMIT) && HARD_LIMIT > 0);
  });

  it('DEFAULT_LIMIT is <= HARD_LIMIT', () => {
    assert.ok(DEFAULT_LIMIT <= HARD_LIMIT);
  });

  it('SEARCHABLE_FIELDS is a Set containing expected values', () => {
    assert.ok(SEARCHABLE_FIELDS instanceof Set);
    assert.ok(SEARCHABLE_FIELDS.has('name'));
    assert.ok(SEARCHABLE_FIELDS.has('email'));
    assert.ok(SEARCHABLE_FIELDS.has('username'));
  });
});

/**
 * Minimal pg stub for unit tests.
 * Provides just enough of the Pool API that db.js and queries.js load cleanly.
 * The actual pool.query is replaced in tests/queries.test.js before any query
 * function is called.
 */
'use strict';

class Pool {
  constructor(_config) {
    this.totalCount   = 0;
    this.idleCount    = 0;
    this.waitingCount = 0;
    this._listeners   = {};
  }
  on(event, fn)        { (this._listeners[event] = this._listeners[event] || []).push(fn); }
  async query(sql, params) { return { rows: [], rowCount: 0 }; }
  async end()          {}
}

module.exports = { Pool };

/** Minimal dotenv stub for unit tests — no-op config(). */
'use strict';
module.exports = { config: () => {} };

