/**
 * db.js — PostgreSQL connection pool
 *
 * Centralises pool creation so every module shares the same set of
 * connections instead of opening a new one per request.
 *
 * Configuration is read exclusively from environment variables so that
 * credentials are never hard-coded in source.  See .env.example for
 * the full list of supported variables.
 *
 * Usage:
 *   const pool = require('./db');
 *   const { rows } = await pool.query('SELECT NOW()');
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Validate required environment variables at start-up so the process fails
// fast with a clear message rather than crashing on the first DB call.
// ---------------------------------------------------------------------------
const REQUIRED_ENV = ['DB_HOST', 'DB_PORT', 'DB_NAME', 'DB_USER', 'DB_PASSWORD'];

const missing = REQUIRED_ENV.filter((key) => !process.env[key]);
if (missing.length > 0) {
  throw new Error(
    `[db] Missing required environment variables: ${missing.join(', ')}.\n` +
      'Copy .env.example to .env and fill in the values.'
  );
}

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
const poolConfig = {
  host:     process.env.DB_HOST,
  port:     Number(process.env.DB_PORT),
  database: process.env.DB_NAME,
  user:     process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Use SSL in every environment except an explicit local-dev opt-out.
  ssl: process.env.DB_SSL === 'false' ? false : { rejectUnauthorized: true },

  // Pool sizing — tune via environment to suit deployment topology.
  // Defaults are intentionally conservative to avoid exhausting DB connections
  // on small instances.
  max:              Number(process.env.DB_POOL_MAX)            || 10,
  min:              Number(process.env.DB_POOL_MIN)            || 2,
  idleTimeoutMillis: Number(process.env.DB_IDLE_TIMEOUT_MS)   || 30_000,
  connectionTimeoutMillis: Number(process.env.DB_CONN_TIMEOUT_MS) || 5_000,

  // Return connection to pool after each query (default pg behaviour, stated
  // explicitly for clarity).
  allowExitOnIdle: true,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

// Surface connection errors that occur on idle clients so they are not
// silently swallowed (the 'error' event on a Pool is emitted for background
// errors that have no associated query callback).
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client', {
    message: err.message,
    // Avoid logging the full stack in production where it could expose
    // internal paths; a structured message is sufficient for alerting.
    code: err.code,
  });
  // Do NOT call process.exit here — let the application decide how to handle
  // persistent pool errors (e.g. via a health-check endpoint).
});

pool.on('connect', () => {
  console.info('[db] New client connected to the pool');
});

pool.on('remove', () => {
  console.info('[db] Client removed from the pool');
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain all pool connections cleanly.
 * Should be called from SIGTERM / SIGINT handlers in the entry-point.
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  console.info('[db] Closing connection pool…');
  await pool.end();
  console.info('[db] Pool closed.');
}

// Attach to the pool instance for convenience so callers only import one
// object.
pool.close = closePool;

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users resource
 *
 * Design decisions
 * ────────────────
 * 1. SQL injection prevention
 *    Every value that originates from user input is passed as a parameter
 *    ($1, $2 …) and handed to pg's parameterised query interface.  The driver
 *    serialises parameters on the wire using the PostgreSQL extended-query
 *    protocol, which means the server always parses SQL and binds values as
 *    separate steps — interpolated strings can never alter query structure.
 *
 *    Additional hardening:
 *    • Integer IDs are coerced with Number() and validated with Number.isInteger
 *      + range checks before they reach the SQL layer.
 *    • Pagination values (limit/offset) are clamped to safe ranges so a caller
 *      cannot request an arbitrarily large result set.
 *    • The ILIKE search term uses a helper that escapes the LIKE meta-characters
 *      (%, _, \) inside the user-supplied string before it is passed as a
 *      parameter, preventing wildcard abuse while keeping the query parameterised.
 *
 * 2. Connection pooling
 *    All functions receive the shared pool exported by db.js.  They call
 *    pool.query() (not pool.connect()) for simple queries so that the driver
 *    handles checkout/release automatically and keeps the pool healthy.
 *
 * 3. Query timing
 *    Every function wraps its execution in a high-resolution timer
 *    (process.hrtime.bigint) and emits a structured log line on completion —
 *    including success/failure, row count and duration in milliseconds.
 *
 * 4. No business logic
 *    This module is deliberately limited to data access.  Validation of HTTP
 *    parameters (e.g. 400 vs 404 decisions) stays in the route layer.
 */

'use strict';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Maximum rows a single getAllUsers call may return. */
const MAX_LIMIT = 100;

/** Default page size when no limit is supplied. */
const DEFAULT_LIMIT = 20;

/** Maximum length of a search query string. */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Structured query logger.
 *
 * Emits a single JSON-serialisable object so log aggregators (Datadog,
 * CloudWatch, etc.) can parse fields without regex.
 *
 * @param {object} params
 * @param {string}  params.fn        - Name of the calling query function.
 * @param {boolean} params.success   - Whether the query completed without error.
 * @param {number}  params.durationMs - Wall-clock time in milliseconds.
 * @param {number}  [params.rowCount] - Number of rows returned / affected.
 * @param {string}  [params.error]    - Error message on failure (no stack trace
 *                                      to avoid leaking internals to log sinks).
 */
function logQuery({ fn, success, durationMs, rowCount, error }) {
  const entry = {
    layer:      'db',
    fn,
    success,
    durationMs: Number(durationMs.toFixed(3)),
    ...(rowCount !== undefined && { rowCount }),
    ...(error !== undefined    && { error }),
  };

  if (success) {
    console.info('[queries]', JSON.stringify(entry));
  } else {
    console.error('[queries]', JSON.stringify(entry));
  }
}

/**
 * Return elapsed milliseconds since a bigint hrtime start value.
 *
 * @param {bigint} startNs
 * @returns {number}
 */
function elapsedMs(startNs) {
  return Number(process.hrtime.bigint() - startNs) / 1_000_000;
}

/**
 * Escape PostgreSQL LIKE / ILIKE meta-characters inside a user-supplied string.
 *
 * Characters escaped: `%`  `_`  `\`
 *
 * The escaped string is still passed as a query parameter — this step only
 * prevents the user from injecting wildcard patterns, it does not replace
 * parameterisation.
 *
 * @param {string} raw
 * @returns {string}
 */
function escapeLikePattern(raw) {
  // Escape backslash first so that subsequent replacements do not double-escape.
  return raw
    .replace(/\\/g, '\\\\')
    .replace(/%/g,  '\\%')
    .replace(/_/g,  '\\_');
}

/**
 * Validate and coerce a pagination limit value.
 *
 * @param {unknown} raw
 * @returns {number} Safe integer in [1, MAX_LIMIT].
 */
function sanitiseLimit(raw) {
  const n = parseInt(raw, 10);
  if (!Number.isInteger(n) || n < 1) return DEFAULT_LIMIT;
  return Math.min(n, MAX_LIMIT);
}

/**
 * Validate and coerce a pagination offset value.
 *
 * @param {unknown} raw
 * @returns {number} Safe non-negative integer.
 */
function sanitiseOffset(raw) {
  const n = parseInt(raw, 10);
  if (!Number.isInteger(n) || n < 0) return 0;
  return n;
}

// ---------------------------------------------------------------------------
// Query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user row by primary key.
 *
 * @param {object} pool       - pg Pool instance (injected for testability).
 * @param {number|string} id  - User ID from the route parameter.
 * @returns {Promise<object|null>} The user row, or null if not found.
 * @throws {TypeError}  If `id` is not a valid positive integer.
 * @throws {Error}      On database errors.
 *
 * @example
 *   const user = await getUserById(pool, 42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function getUserById(pool, id) {
  const fn = 'getUserById';

  // ── Input validation ──────────────────────────────────────────────────────
  const numericId = Number(id);
  if (!Number.isInteger(numericId) || numericId < 1) {
    throw new TypeError(`[${fn}] id must be a positive integer, received: ${JSON.stringify(id)}`);
  }

  // ── Query ─────────────────────────────────────────────────────────────────
  // $1 is bound by pg's parameterised interface — no string interpolation.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
      AND deleted_at IS NULL
    LIMIT 1
  `;

  const startNs = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, [numericId]);

    logQuery({
      fn,
      success:    true,
      durationMs: elapsedMs(startNs),
      rowCount:   result.rowCount,
    });

    return result.rows[0] ?? null;
  } catch (err) {
    logQuery({
      fn,
      success:    false,
      durationMs: elapsedMs(startNs),
      error:      err.message,
    });
    throw err;
  }
}

/**
 * Fetch a paginated list of all (non-deleted) users, ordered by ID ascending.
 *
 * @param {object}         pool         - pg Pool instance.
 * @param {number|string}  [limit=20]   - Max rows to return (capped at 100).
 * @param {number|string}  [offset=0]   - Row offset for pagination.
 * @returns {Promise<{ rows: object[], total: number }>}
 *   `rows`  — the page of user records.
 *   `total` — total number of non-deleted users (for building pagination metadata).
 * @throws {Error} On database errors.
 *
 * @example
 *   const { rows, total } = await getAllUsers(pool, 10, 20);
 */
async function getAllUsers(pool, limit = DEFAULT_LIMIT, offset = 0) {
  const fn = 'getAllUsers';

  // ── Input sanitisation ────────────────────────────────────────────────────
  const safeLimit  = sanitiseLimit(limit);
  const safeOffset = sanitiseOffset(offset);

  // ── Query ─────────────────────────────────────────────────────────────────
  // A single round-trip returns both the page and the total count via a
  // window function, avoiding a separate COUNT(*) query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE deleted_at IS NULL
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const startNs = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, [safeLimit, safeOffset]);

    logQuery({
      fn,
      success:    true,
      durationMs: elapsedMs(startNs),
      rowCount:   result.rowCount,
    });

    // Extract the total from the first row's window-function column (0 when
    // the table is empty).
    const total = result.rows.length > 0
      ? Number(result.rows[0].total_count)
      : 0;

    // Strip the internal total_count column from each returned row so callers
    // receive a clean user object.
    const rows = result.rows.map(({ total_count, ...user }) => user);

    return { rows, total };
  } catch (err) {
    logQuery({
      fn,
      success:    false,
      durationMs: elapsedMs(startNs),
      error:      err.message,
    });
    throw err;
  }
}

/**
 * Full-text prefix search across users' name and email fields.
 *
 * Matching is case-insensitive (ILIKE) and anchored to the start of each word
 * via a leading-wildcard pattern: `%<escaped_term>%`.
 *
 * @param {object}        pool              - pg Pool instance.
 * @param {string}        query             - Search term (max 200 chars).
 * @param {number|string} [limit=20]        - Max rows to return (capped at 100).
 * @param {number|string} [offset=0]        - Row offset for pagination.
 * @returns {Promise<{ rows: object[], total: number }>}
 * @throws {TypeError}  If `query` is not a non-empty string.
 * @throws {Error}      On database errors.
 *
 * @example
 *   const { rows, total } = await searchUsers(pool, 'alice', 5, 0);
 */
async function searchUsers(pool, query, limit = DEFAULT_LIMIT, offset = 0) {
  const fn = 'searchUsers';

  // ── Input validation ──────────────────────────────────────────────────────
  if (typeof query !== 'string' || query.trim().length === 0) {
    throw new TypeError(`[${fn}] query must be a non-empty string`);
  }

  // Truncate to prevent excessively long patterns (not a security boundary —
  // parameterisation already handles injection — but guards against resource
  // exhaustion from huge ILIKE patterns).
  const trimmed = query.trim().slice(0, MAX_SEARCH_LENGTH);

  const safeLimit  = sanitiseLimit(limit);
  const safeOffset = sanitiseOffset(offset);

  // Escape LIKE metacharacters BEFORE wrapping in wildcards.
  // The escaped value is still passed as a parameter — never interpolated.
  const pattern = `%${escapeLikePattern(trimmed)}%`;

  // ── Query ─────────────────────────────────────────────────────────────────
  // $1 is the ILIKE pattern; $2 and $3 are pagination parameters.
  // Using a single $1 reference in two ILIKE clauses keeps the parameter list
  // minimal — pg allows reuse of the same ordinal.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE deleted_at IS NULL
      AND (
            name  ILIKE $1
         OR email ILIKE $1
      )
    ORDER BY
      -- Exact (case-insensitive) matches first, then alphabetical by name.
      CASE WHEN LOWER(name)  = LOWER($2) THEN 0
           WHEN LOWER(email) = LOWER($2) THEN 0
           ELSE 1
      END,
      name ASC
    LIMIT  $3
    OFFSET $4
  `;

  const startNs = process.hrtime.bigint();

  try {
    // $1 = ILIKE pattern  (e.g. '%alice%')
    // $2 = raw trimmed term for exact-match ranking (LOWER comparison is safe
    //      since it is also parameterised)
    // $3 = LIMIT
    // $4 = OFFSET
    const result = await pool.query(sql, [pattern, trimmed, safeLimit, safeOffset]);

    logQuery({
      fn,
      success:    true,
      durationMs: elapsedMs(startNs),
      rowCount:   result.rowCount,
    });

    const total = result.rows.length > 0
      ? Number(result.rows[0].total_count)
      : 0;

    const rows = result.rows.map(({ total_count, ...user }) => user);

    return { rows, total };
  } catch (err) {
    logQuery({
      fn,
      success:    false,
      durationMs: elapsedMs(startNs),
      error:      err.message,
    });
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Expose internal helpers for unit testing.
  _internal: {
    escapeLikePattern,
    sanitiseLimit,
    sanitiseOffset,
    MAX_LIMIT,
    DEFAULT_LIMIT,
    MAX_SEARCH_LENGTH,
  },
