'use strict';

// Load environment variables from .env (no-op if the file is absent, so
// production environments can rely solely on real env vars).
require('dotenv').config();

const express = require('express');
const pool    = require('./db');
const {
  getUserById,
  getAllUsers,
  searchUsers,
} = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Request-level query timing middleware
//
// Attaches a high-resolution start time to every request so route handlers
// can log end-to-end latency without coupling timing logic to each handler.
// ---------------------------------------------------------------------------
app.use((req, _res, next) => {
  req._startNs = process.hrtime.bigint();
  next();
});

// ---------------------------------------------------------------------------
// Helper: build a structured response-timing log
// ---------------------------------------------------------------------------
function logRequest(req, statusCode, extra = {}) {
  const durationMs = Number(process.hrtime.bigint() - req._startNs) / 1_000_000;
  console.info('[app]', JSON.stringify({
    method:     req.method,
    path:       req.path,
    statusCode,
    durationMs: Number(durationMs.toFixed(3)),
    ...extra,
  }));
}

// ---------------------------------------------------------------------------
// Helper: uniform error response
// ---------------------------------------------------------------------------
function sendError(res, req, statusCode, message, extra = {}) {
  logRequest(req, statusCode, { error: message, ...extra });
  return res.status(statusCode).json({ error: message });
}

// ---------------------------------------------------------------------------
// GET /health
// ---------------------------------------------------------------------------
app.get('/health', async (req, res) => {
  // Perform a lightweight DB round-trip to confirm pool connectivity.
  try {
    await pool.query('SELECT 1');
    const body = { status: 'ok', db: 'reachable', timestamp: new Date().toISOString() };
    logRequest(req, 200);
    return res.json(body);
  } catch (err) {
    // The server is running but the DB is unavailable — return 503 so load
    // balancers can remove the instance from rotation.
    return sendError(res, req, 503, 'Database unreachable');
  }
});

// ---------------------------------------------------------------------------
// GET /users
//
// Returns a paginated list of users.
//
// Query parameters:
//   limit   {number}  Rows per page.  Default 20, max 100.
//   offset  {number}  Row offset.     Default 0.
//   search  {string}  Optional search term (name or email, case-insensitive).
//
// Response:
//   {
//     data: User[],
//     pagination: {
//       total:   number,   // total matching rows across all pages
//       limit:   number,   // effective limit used
//       offset:  number,   // effective offset used
//       hasMore: boolean   // convenience flag
//     }
//   }
// ---------------------------------------------------------------------------
app.get('/users', async (req, res) => {
  const { limit, offset, search } = req.query;

  try {
    let rows, total;

    if (search !== undefined) {
      // ── Searched listing ─────────────────────────────────────────────────
      if (typeof search !== 'string' || search.trim().length === 0) {
        return sendError(res, req, 400, '`search` must be a non-empty string');
      }
      ({ rows, total } = await searchUsers(pool, search, limit, offset));
    } else {
      // ── Full listing (paginated) ──────────────────────────────────────────
      ({ rows, total } = await getAllUsers(pool, limit, offset));
    }

    // Re-read the sanitised values from queries.js defaults for the response
    // metadata.  We import the internal helpers for this so the values are
    // always consistent with what the query actually used.
    const { _internal: { sanitiseLimit, sanitiseOffset } } = require('./queries');
    const effectiveLimit  = sanitiseLimit(limit);
    const effectiveOffset = sanitiseOffset(offset);

    const body = {
      data: rows,
      pagination: {
        total,
        limit:   effectiveLimit,
        offset:  effectiveOffset,
        hasMore: effectiveOffset + effectiveLimit < total,
      },
    };

    logRequest(req, 200, { rowCount: rows.length, total });
    return res.json(body);

  } catch (err) {
    // TypeError from input validation in queries.js → 400
    if (err instanceof TypeError) {
      return sendError(res, req, 400, err.message);
    }
    // Unexpected DB error → 500 (message is safe: pg errors do not include
    // query text or parameter values by default)
    console.error('[app] Unhandled error in GET /users:', err.message);
    return sendError(res, req, 500, 'Internal server error');
  }
});

// ---------------------------------------------------------------------------
// GET /users/:id
//
// Returns a single user by primary key.
//
// Route parameter:
//   id  {positive integer}
//
// Response:
//   User object, or 404 if not found / soft-deleted.
// ---------------------------------------------------------------------------
app.get('/users/:id', async (req, res) => {
  const { id } = req.params;

  try {
    const user = await getUserById(pool, id);

    if (!user) {
      return sendError(res, req, 404, `User with id ${id} not found`);
    }

    logRequest(req, 200);
    return res.json({ data: user });

  } catch (err) {
    if (err instanceof TypeError) {
      return sendError(res, req, 400, err.message);
    }
    console.error('[app] Unhandled error in GET /users/:id:', err.message);
    return sendError(res, req, 500, 'Internal server error');
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown
//
// Drain in-flight requests and the DB pool before the process exits so we
// don't drop connections mid-query during rolling deploys.
// ---------------------------------------------------------------------------
async function shutdown(signal) {
  console.info(`[app] ${signal} received — shutting down gracefully`);
  await pool.close();
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------
const PORT = Number(process.env.PORT) || 3000;

// Only call listen() when this file is the entry point, not when it is
// require()'d by tests (which may want to call listen themselves, or use
// supertest without a bound port).
if (require.main === module) {
  app.listen(PORT, () => {
    console.info(`[app] Server listening on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js internal helpers
 *
 * These tests cover the injection-prevention and sanitisation logic without
 * requiring a live database.  DB-facing functions (getUserById, getAllUsers,
 * searchUsers) are exercised via a mock pool so the full parameter-binding
 * path is verified.
 *
 * Run with:  node queries.test.js
 * (No external test runner required — uses Node's built-in assert module.)
 */

'use strict';

const assert = require('assert/strict');

const {
  getUserById,
  getAllUsers,
  searchUsers,
  _internal: {
    escapeLikePattern,
    sanitiseLimit,
    sanitiseOffset,
    MAX_LIMIT,
    DEFAULT_LIMIT,
  },
} = require('./queries');

