// Minimal mock pool
//
// Captures the SQL and params passed to pool.query() so tests can assert that
// the correct parameterised form was used — without touching a real database.
// ---------------------------------------------------------------------------
function makeMockPool(rows = [], rowCount = null) {
  const calls = [];
  const pool = {
    calls,
    async query(sql, params) {
      calls.push({ sql, params });
      const rc = rowCount !== null ? rowCount : rows.length;
      return { rows, rowCount: rc };
    },
  };
  return pool;
}

// ---------------------------------------------------------------------------
// Test runner helpers
// ---------------------------------------------------------------------------
let passed = 0;
let failed = 0;

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ ${name}`);
    console.error(`    ${err.message}`);
    failed++;
  }
}

// ===========================================================================
// escapeLikePattern
// ===========================================================================
console.log('\nescapeLikePattern');

await test('leaves plain strings untouched', () => {
  assert.equal(escapeLikePattern('alice'), 'alice');
});

await test('escapes % character', () => {
  assert.equal(escapeLikePattern('100%'), '100\\%');
});

await test('escapes _ character', () => {
  assert.equal(escapeLikePattern('a_b'), 'a\\_b');
});

await test('escapes \\ character before % and _', () => {
  assert.equal(escapeLikePattern('a\\%b'), 'a\\\\\\%b');
});

await test('escapes multiple metacharacters', () => {
  assert.equal(escapeLikePattern('%_test_%'), '\\%\\_test\\_\\%');
});

await test('returns empty string unchanged', () => {
  assert.equal(escapeLikePattern(''), '');
});

// ===========================================================================
// sanitiseLimit
// ===========================================================================
console.log('\nsanitiseLimit');

await test('returns DEFAULT_LIMIT for undefined', () => {
  assert.equal(sanitiseLimit(undefined), DEFAULT_LIMIT);
});

await test('returns DEFAULT_LIMIT for zero', () => {
  assert.equal(sanitiseLimit(0), DEFAULT_LIMIT);
});

await test('returns DEFAULT_LIMIT for negative', () => {
  assert.equal(sanitiseLimit(-5), DEFAULT_LIMIT);
});

await test('returns DEFAULT_LIMIT for non-numeric string', () => {
  assert.equal(sanitiseLimit('abc'), DEFAULT_LIMIT);
});

await test('caps at MAX_LIMIT', () => {
  assert.equal(sanitiseLimit(MAX_LIMIT + 999), MAX_LIMIT);
});

await test('accepts valid numeric string', () => {
  assert.equal(sanitiseLimit('10'), 10);
});

await test('accepts valid number', () => {
  assert.equal(sanitiseLimit(50), 50);
});

// ===========================================================================
// sanitiseOffset
// ===========================================================================
console.log('\nsanitiseOffset');

await test('returns 0 for undefined', () => {
  assert.equal(sanitiseOffset(undefined), 0);
});

await test('returns 0 for negative', () => {
  assert.equal(sanitiseOffset(-1), 0);
});

await test('returns 0 for non-numeric string', () => {
  assert.equal(sanitiseOffset('abc'), 0);
});

await test('accepts valid positive offset', () => {
  assert.equal(sanitiseOffset(40), 40);
});

await test('accepts numeric string offset', () => {
  assert.equal(sanitiseOffset('100'), 100);
});

// ===========================================================================
// getUserById
// ===========================================================================
console.log('\ngetUserById');

await test('throws TypeError for non-integer id', async () => {
  const pool = makeMockPool();
  await assert.rejects(() => getUserById(pool, 'abc'), TypeError);
});

await test('throws TypeError for float id', async () => {
  const pool = makeMockPool();
  await assert.rejects(() => getUserById(pool, 1.5), TypeError);
});

await test('throws TypeError for zero id', async () => {
  const pool = makeMockPool();
  await assert.rejects(() => getUserById(pool, 0), TypeError);
});

await test('throws TypeError for negative id', async () => {
  const pool = makeMockPool();
  await assert.rejects(() => getUserById(pool, -3), TypeError);
});

await test('passes id as a numeric parameter (not interpolated)', async () => {
  const fakeUser = { id: 1, name: 'Alice', email: 'alice@example.com',
