  const result = await getUserById(pool, 42);
  assert.equal(result, null);
});

await test('returns the user row when found', async () => {
  const fakeUser = { id: 7, name: 'Bob', email: 'bob@example.com',
                     created_at: new Date(), updated_at: new Date() };
  const pool = makeMockPool([fakeUser]);
  const result = await getUserById(pool, 7);
  assert.deepEqual(result, fakeUser);
});

await test('propagates pool errors', async () => {
  const pool = {
    async query() { throw new Error('connection refused'); },
  };
  await assert.rejects(() => getUserById(pool, 1), /connection refused/);
});

// ===========================================================================
// getAllUsers
// ===========================================================================
console.log('\ngetAllUsers');

await test('uses default limit and offset when none supplied', async () => {
