/**
 * queries.test.js — Unit tests for queries.js internal helpers
 *
 * These tests cover the injection-prevention and sanitisation logic without
 * requiring a live database.  DB-facing functions (getUserById, getAllUsers,
 * searchUsers) are exercised via a mock pool so the full parameter-binding
 * path is verified.
 *
 * Run with:  node queries.test.js
 * (No external test runner required — uses Node's built-in assert module.)
 */

'use strict';

const assert = require('assert/strict');

const {
  getUserById,
  getAllUsers,
  searchUsers,
  _internal: {
    escapeLikePattern,
    sanitiseLimit,
    sanitiseOffset,
    MAX_LIMIT,
    DEFAULT_LIMIT,
  },
} = require('./queries');

// ---------------------------------------------------------------------------
// Minimal mock pool
//
// Captures the SQL and params passed to pool.query() so tests can assert that
// the correct parameterised form was used — without touching a real database.
// ---------------------------------------------------------------------------
function makeMockPool(rows = [], rowCount = null) {
  const calls = [];
  const pool = {
    calls,
    async query(sql, params) {
      calls.push({ sql, params });
      const rc = rowCount !== null ? rowCount : rows.length;
      return { rows, rowCount: rc };
    },
  };
  return pool;
}

// ---------------------------------------------------------------------------
// Test runner helpers
// ---------------------------------------------------------------------------
let passed = 0;
let failed = 0;

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ ${name}`);
    console.error(`    ${err.message}`);
    failed++;
  }
}

// ---------------------------------------------------------------------------
// Main — all test suites wrapped in an async IIFE so top-level await is not
// required (preserving CommonJS compatibility with Node < 22 --input-type).
// ---------------------------------------------------------------------------
(async () => {

// ===========================================================================
// escapeLikePattern
// ===========================================================================
console.log('\nescapeLikePattern');

await test('leaves plain strings untouched', () => {
  assert.equal(escapeLikePattern('alice'), 'alice');
});

await test('escapes % character', () => {
  assert.equal(escapeLikePattern('100%'), '100\\%');
});

await test('escapes _ character', () => {
  assert.equal(escapeLikePattern('a_b'), 'a\\_b');
});

await test('escapes \\ character before % and _', () => {
  assert.equal(escapeLikePattern('a\\%b'), 'a\\\\\\%b');
});

await test('escapes multiple metacharacters', () => {
  assert.equal(escapeLikePattern('%_test_%'), '\\%\\_test\\_\\%');
});

await test('returns empty string unchanged', () => {
  assert.equal(escapeLikePattern(''), '');
});

// ===========================================================================
// sanitiseLimit
// ===========================================================================
console.log('\nsanitiseLimit');

await test('returns DEFAULT_LIMIT for undefined', () => {
  assert.equal(sanitiseLimit(undefined), DEFAULT_LIMIT);
});

await test('returns DEFAULT_LIMIT for zero', () => {
  assert.equal(sanitiseLimit(0), DEFAULT_LIMIT);
});

await test('returns DEFAULT_LIMIT for negative', () => {
  assert.equal(sanitiseLimit(-5), DEFAULT_LIMIT);
});

await test('returns DEFAULT_LIMIT for non-numeric string', () => {
  assert.equal(sanitiseLimit('abc'), DEFAULT_LIMIT);
});

await test('caps at MAX_LIMIT', () => {
  assert.equal(sanitiseLimit(MAX_LIMIT + 999), MAX_LIMIT);
});

await test('accepts valid numeric string', () => {
  assert.equal(sanitiseLimit('10'), 10);
});

await test('accepts valid number', () => {
  assert.equal(sanitiseLimit(50), 50);
});

// ===========================================================================
// sanitiseOffset
// ===========================================================================
console.log('\nsanitiseOffset');

await test('returns 0 for undefined', () => {
  assert.equal(sanitiseOffset(undefined), 0);
});

await test('returns 0 for negative', () => {
  assert.equal(sanitiseOffset(-1), 0);
});

await test('returns 0 for non-numeric string', () => {
  assert.equal(sanitiseOffset('abc'), 0);
});

await test('accepts valid positive offset', () => {
  assert.equal(sanitiseOffset(40), 40);
});

await test('accepts numeric string offset', () => {
  assert.equal(sanitiseOffset('100'), 100);
});

// ===========================================================================
// getUserById
// ===========================================================================
console.log('\ngetUserById');

await test('throws TypeError for non-integer id', async () => {
  const pool = makeMockPool();
  await assert.rejects(() => getUserById(pool, 'abc'), TypeError);
});

await test('throws TypeError for float id', async () => {
  const pool = makeMockPool();
  await assert.rejects(() => getUserById(pool, 1.5), TypeError);
});

await test('throws TypeError for zero id', async () => {
  const pool = makeMockPool();
  await assert.rejects(() => getUserById(pool, 0), TypeError);
});

await test('throws TypeError for negative id', async () => {
  const pool = makeMockPool();
  await assert.rejects(() => getUserById(pool, -3), TypeError);
});

await test('passes id as a numeric parameter (not interpolated)', async () => {
  const fakeUser = { id: 1, name: 'Alice', email: 'alice@example.com',
                     created_at: new Date(), updated_at: new Date() };
  const pool = makeMockPool([fakeUser]);
  await getUserById(pool, '1');
  const { sql, params } = pool.calls[0];
  // The value 1 must appear in the params array, not in the SQL string.
  assert.ok(!sql.includes('1'), 'id must not be interpolated into SQL');
  assert.deepEqual(params, [1]);
});

await test('returns null when user is not found', async () => {
  const pool = makeMockPool([]);       // empty result set
  const result = await getUserById(pool, 42);
  assert.equal(result, null);
});

await test('returns the user row when found', async () => {
  const fakeUser = { id: 7, name: 'Bob', email: 'bob@example.com',
                     created_at: new Date(), updated_at: new Date() };
  const pool = makeMockPool([fakeUser]);
  const result = await getUserById(pool, 7);
  assert.deepEqual(result, fakeUser);
});

await test('propagates pool errors', async () => {
  const pool = {
    async query() { throw new Error('connection refused'); },
  };
  await assert.rejects(() => getUserById(pool, 1), /connection refused/);
});

// ===========================================================================
// getAllUsers
// ===========================================================================
console.log('\ngetAllUsers');

await test('uses default limit and offset when none supplied', async () => {
  const pool = makeMockPool([]);
  await getAllUsers(pool);
  const { params } = pool.calls[0];
  assert.equal(params[0], DEFAULT_LIMIT);
  assert.equal(params[1], 0);
});

await test('caps limit at MAX_LIMIT', async () => {
  const pool = makeMockPool([]);
  await getAllUsers(pool, 9999);
  assert.equal(pool.calls[0].params[0], MAX_LIMIT);
});

await test('returns { rows, total } shape', async () => {
  const fakeRows = [
    { id: 1, name: 'Alice', email: 'a@a.com', created_at: null,
      updated_at: null, total_count: '2' },
    { id: 2, name: 'Bob',   email: 'b@b.com', created_at: null,
      updated_at: null, total_count: '2' },
  ];
  const pool = makeMockPool(fakeRows);
  const { rows, total } = await getAllUsers(pool, 10, 0);
  assert.equal(total, 2);
  assert.equal(rows.length, 2);
  // total_count must be stripped from each row
  assert.ok(!('total_count' in rows[0]), 'total_count should be stripped from rows');
});

await test('returns total 0 for empty result', async () => {
  const pool = makeMockPool([]);
  const { rows, total } = await getAllUsers(pool);
  assert.equal(total, 0);
  assert.equal(rows.length, 0);
});

// ===========================================================================
// searchUsers
// ===========================================================================
console.log('\nsearchUsers');

await test('throws TypeError for empty search string', async () => {
  const pool = makeMockPool();
  await assert.rejects(() => searchUsers(pool, '   '), TypeError);
});

await test('throws TypeError for non-string query', async () => {
  const pool = makeMockPool();
  await assert.rejects(() => searchUsers(pool, 42), TypeError);
});

await test('wraps search term in % wildcards as a parameter', async () => {
  const pool = makeMockPool([]);
  await searchUsers(pool, 'alice');
  const { params } = pool.calls[0];
  // $1 must be the ILIKE pattern
  assert.equal(params[0], '%alice%');
});

await test('escapes LIKE metacharacters in the search pattern', async () => {
  const pool = makeMockPool([]);
  await searchUsers(pool, '50%_off');
  const { params } = pool.calls[0];
  assert.equal(params[0], '%50\\%\\_off%');
});

await test('passes raw trimmed term as second parameter for exact ranking', async () => {
  const pool = makeMockPool([]);
  await searchUsers(pool, '  alice  ');
  const { params } = pool.calls[0];
  assert.equal(params[1], 'alice');     // trimmed but not wrapped in %
});

await test('strips total_count from search result rows', async () => {
  const fakeRows = [
    { id: 3, name: 'Charlie', email: 'c@c.com', created_at: null,
      updated_at: null, total_count: '1' },
  ];
  const pool = makeMockPool(fakeRows);
  const { rows } = await searchUsers(pool, 'charlie');
  assert.ok(!('total_count' in rows[0]));
});

await test('does not interpolate search term into SQL string', async () => {
  const malicious = "' OR '1'='1";
  const pool = makeMockPool([]);
  await searchUsers(pool, malicious);
  const { sql, params } = pool.calls[0];
  assert.ok(!sql.includes(malicious), 'raw input must not appear in SQL text');
  assert.ok(params[0].includes(malicious.replace('%', '\\%')) ||
            params[0].includes(malicious),
            'input should be present only in params');
});

// ===========================================================================
// Summary
// ===========================================================================
console.log(`\n${'─'.repeat(50)}`);
console.log(`Tests: ${passed + failed} total, ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);

})();

