{
  "name": "express-pg-users-api",
  "version": "1.0.0",
  "description": "Express API with PostgreSQL connection pooling, parameterised queries, and query timing",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "node --watch app.js",
    "test": "node --experimental-vm-modules node_modules/.bin/jest --runInBand",
    "test:coverage": "node --experimental-vm-modules node_modules/.bin/jest --runInBand --coverage"
  },
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "pg": "^8.12.0"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  }
}

'use strict';

/**
 * @module db
 * @description Manages a single shared pg.Pool instance for the lifetime of
 * the process.  Every module that needs database access imports this file and
 * calls `getPool()` – they all receive the **same** pool, so connections are
 * reused instead of being opened on every request.
 *
 * Exports
 * -------
 *  getPool()   – returns the live Pool, creating it on first call
 *  closePool() – drains and destroys the pool (useful in tests / shutdown)
 *  query()     – thin wrapper: acquires a client, runs a query, releases it
 */

const { Pool } = require('pg');

// ── Singleton state ───────────────────────────────────────────────────────────
/** @type {import('pg').Pool | null} */
let _pool = null;

// ── Pool factory ──────────────────────────────────────────────────────────────

/**
 * Build pool configuration from environment variables with safe defaults.
 *
 * We intentionally read env vars here (at call time) rather than at module
 * load time so that test suites can override process.env before the pool is
 * first created.
 *
 * @returns {import('pg').PoolConfig}
 */
function buildPoolConfig() {
  const connectionString = process.env.DATABASE_URL;

  if (!connectionString) {
    throw new Error(
      'DATABASE_URL is not set. Add it to your .env file (see .env.example).',
    );
  }

  return {
    connectionString,

    // Maximum number of clients kept alive in the pool.
    max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

    // How long (ms) a client can remain idle before being discarded.
    idleTimeoutMillis: parseInt(
      process.env.DB_POOL_IDLE_TIMEOUT ?? '10000',
      10,
    ),

    // How long (ms) to wait when all pool slots are busy before throwing.
    connectionTimeoutMillis: parseInt(
      process.env.DB_POOL_ACQUIRE_TIMEOUT ?? '30000',
      10,
    ),

    // Per-query statement timeout enforced by PostgreSQL itself (not just the
    // client). The DB will cancel the query and return an error if it exceeds
    // this duration.
    statement_timeout: parseInt(
      process.env.DB_QUERY_TIMEOUT ?? '5000',
      10,
    ),

    // Let node-postgres parse timestamp columns as JS Date objects.
    // (pg defaults to returning them as strings.)
    // types are inherited; we leave pg's defaults intact here.
  };
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Returns the shared Pool instance, creating it the first time it is called.
 *
 * @returns {import('pg').Pool}
 */
function getPool() {
  if (!_pool) {
    const config = buildPoolConfig();

    _pool = new Pool(config);

    // Attach a pool-level error listener so that unexpected idle-client errors
    // (e.g. the DB closing the connection) are logged rather than crashing the
    // process via an unhandled "error" event.
    _pool.on('error', (err, client) => {
      console.error('[db] Unexpected error on idle client', {
        message: err.message,
        // client object exposes the underlying socket but no secrets
      });
    });

    // Optional: log when a new physical connection is established.
    _pool.on('connect', () => {
      console.info('[db] New client connected to the pool');
    });

    // Optional: log when a physical connection is removed from the pool.
    _pool.on('remove', () => {
      console.info('[db] Client removed from the pool');
    });

    console.info('[db] Pool created', {
      max: config.max,
      idleTimeoutMillis: config.idleTimeoutMillis,
      connectionTimeoutMillis: config.connectionTimeoutMillis,
      statement_timeout: config.statement_timeout,
      // Intentionally omitting connectionString to keep credentials out of logs
    });
  }

  return _pool;
}

/**
 * Gracefully closes every client in the pool and sets the singleton to null
 * so that `getPool()` will create a fresh pool if called again.
 *
 * Call this in:
 *  - process SIGTERM / SIGINT handlers
 *  - `afterAll` in test suites that need a clean teardown
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  if (_pool) {
    const closing = _pool;
    _pool = null; // prevent new callers from receiving the draining pool
    await closing.end();
    console.info('[db] Pool closed');
  }
}

module.exports = { getPool, closePool };

'use strict';

/**
 * @module queries
 * @description Parameterised query functions for the /users resource.
 *
 * Security
 * ────────
 * Every value that originates from user input is passed as a **bind
 * parameter** ($1, $2 …) rather than interpolated into the SQL string.
 * node-postgres sends parameter values separately from the query text over the
 * wire, so the database driver – not application code – is responsible for
 * escaping.  This completely prevents first-order SQL injection.
 *
 * Additionally:
 *  • Numeric inputs (id, limit, offset) are coerced and range-checked in JS
 *    before the query is built, so out-of-range or non-numeric values are
 *    rejected with a clear error before touching the database.
 *  • The full-text search term is passed as a bind parameter and matched with
 *    ILIKE using a parameterised pattern; no string concatenation is used.
 *  • The pg `statement_timeout` configured on the pool (see db.js) acts as a
 *    server-side backstop against slow-query attacks.
 *
 * Performance
 * ───────────
 * All queries are timed via `queryWithTiming()` which records wall-clock
 * duration and emits a structured log line.  Slow queries (> SLOW_QUERY_MS)
 * emit an additional warning.
 *
 * Exports
 * ───────
 *  getUserById(id)                  – fetch a single user row
 *  getAllUsers(limit, offset)        – paginated list of all users
 *  searchUsers(searchTerm, limit, offset) – ILIKE search across name / email
 */

const { getPool } = require('./db');

// ── Constants ─────────────────────────────────────────────────────────────────

/** Warn in logs when any single query exceeds this threshold (milliseconds). */
const SLOW_QUERY_MS = 500;

/**
 * Hard upper bound on the number of rows a single request may fetch.
 * Prevents callers from requesting arbitrarily large pages.
 */
const MAX_LIMIT = 100;

/** Default page size when no limit is supplied by the caller. */
const DEFAULT_LIMIT = 20;

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Execute a parameterised query against the shared pool and emit timing logs.
 *
 * The function:
 *  1. Records the start time with `process.hrtime.bigint()` (nanosecond
 *     resolution, not subject to system clock adjustments).
 *  2. Runs the query.
 *  3. Calculates elapsed milliseconds and logs a structured line.
 *  4. Emits an additional WARN log if the query exceeded SLOW_QUERY_MS.
 *  5. Re-throws any error after logging it (with query name, not raw SQL, to
 *     avoid leaking column/table details into error responses).
 *
 * @param {string}  queryName  – human-readable label used in log output
 * @param {string}  sql        – parameterised SQL text
 * @param {unknown[]} params   – bind-parameter values matching $1, $2 …
 * @returns {Promise<import('pg').QueryResult>}
 */
async function queryWithTiming(queryName, sql, params) {
  const pool = getPool();
  const startNs = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, params);

    const elapsedMs = Number(process.hrtime.bigint() - startNs) / 1_000_000;

    const logPayload = {
      query: queryName,
      rowCount: result.rowCount,
      durationMs: parseFloat(elapsedMs.toFixed(3)),
    };

    if (elapsedMs > SLOW_QUERY_MS) {
      console.warn('[db] SLOW QUERY detected', logPayload);
    } else {
      console.info('[db] Query executed', logPayload);
    }

    return result;
  } catch (err) {
    const elapsedMs =
      Number(process.hrtime.bigint() - startNs) / 1_000_000;

    console.error('[db] Query failed', {
      query: queryName,
      durationMs: parseFloat(elapsedMs.toFixed(3)),
      // Log err.message (DB error description) but NOT the full SQL or params
      // to avoid leaking schema details or parameter values in production logs.
      errorMessage: err.message,
      errorCode: err.code, // PostgreSQL error code, e.g. "23505" for unique violation
    });

    throw err; // bubble up so route handlers can decide on HTTP status
  }
}

/**
 * Validate and coerce a raw `id` value to a positive integer.
 *
 * @param {unknown} raw
 * @returns {number}
 * @throws {TypeError} when the value is not a valid positive integer
 */
function parseId(raw) {
  const n = Number(raw);
  if (!Number.isInteger(n) || n < 1) {
    throw new TypeError(
      `Invalid id "${raw}": must be a positive integer.`,
    );
  }
  return n;
}

/**
 * Validate and coerce pagination parameters.
 *
 * @param {unknown} rawLimit
 * @param {unknown} rawOffset
 * @returns {{ limit: number, offset: number }}
 * @throws {RangeError} when values are out of acceptable bounds
 */
function parsePagination(rawLimit, rawOffset) {
  const limit = rawLimit === undefined
    ? DEFAULT_LIMIT
    : parseInt(String(rawLimit), 10);

  const offset = rawOffset === undefined
    ? 0
    : parseInt(String(rawOffset), 10);

  if (!Number.isInteger(limit) || isNaN(limit) || limit < 1) {
    throw new RangeError(
      `Invalid limit "${rawLimit}": must be a positive integer.`,
    );
  }
  if (limit > MAX_LIMIT) {
    throw new RangeError(
      `limit ${limit} exceeds the maximum allowed value of ${MAX_LIMIT}.`,
    );
  }
  if (!Number.isInteger(offset) || isNaN(offset) || offset < 0) {
    throw new RangeError(
      `Invalid offset "${rawOffset}": must be a non-negative integer.`,
    );
  }

  return { limit, offset };
}

/**
 * Validate and sanitise a free-text search term.
 *
 * We do NOT need to escape LIKE wildcards ourselves because the term is
 * passed as a bind parameter and PostgreSQL is responsible for treating it as
 * a literal string inside the ILIKE expression.  We do, however, trim
 * whitespace and enforce a minimum/maximum length to prevent accidental or
 * intentional abuse (e.g. an empty string matching all rows, or an enormous
 * string causing performance issues).
 *
 * @param {unknown} raw
 * @returns {string}  trimmed search term
 * @throws {TypeError | RangeError}
 */
function parseSearchTerm(raw) {
  if (typeof raw !== 'string') {
    throw new TypeError('Search query must be a string.');
  }

  const trimmed = raw.trim();

  if (trimmed.length === 0) {
    throw new RangeError('Search query must not be empty.');
  }
  if (trimmed.length > 200) {
    throw new RangeError(
      'Search query must be 200 characters or fewer.',
    );
  }

  return trimmed;
}

// ── Query functions ───────────────────────────────────────────────────────────

/**
 * Fetch a single user by their primary-key id.
 *
 * SQL (parameterised):
 *   SELECT id, name, email, created_at
 *   FROM   users
 *   WHERE  id = $1
 *
 * @param {number | string} id  – user primary key (will be validated)
 * @returns {Promise<object | null>}  user row, or null if not found
 * @throws {TypeError} for non-integer or negative ids
 */
async function getUserById(id) {
  const safeId = parseId(id);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM
      users
    WHERE
      id = $1
  `;

  const result = await queryWithTiming('getUserById', sql, [safeId]);

  // Return null (not undefined or an empty array) so callers can do a simple
  // `if (!user)` check.
  return result.rows[0] ?? null;
}

/**
 * Fetch a paginated list of all users, ordered by id ascending.
 *
 * SQL (parameterised):
 *   SELECT id, name, email, created_at
 *   FROM   users
 *   ORDER  BY id ASC
 *   LIMIT  $1
 *   OFFSET $2
 *
 * @param {number | string} [limit=20]   – page size (1 – 100)
 * @param {number | string} [offset=0]  – number of rows to skip
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number }>}
 * @throws {RangeError} for out-of-range pagination parameters
 */
async function getAllUsers(limit, offset) {
  const { limit: safeLimit, offset: safeOffset } = parsePagination(
    limit,
    offset,
  );

  // Issue two queries in parallel:
  //  1. The actual page of rows.
  //  2. A COUNT(*) for the total so callers can compute page count.
  const rowsSql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM
      users
    ORDER BY
      id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM   users
  `;

  // Run both queries concurrently – they are independent and share the pool.
  const [rowsResult, countResult] = await Promise.all([
    queryWithTiming('getAllUsers:rows', rowsSql, [safeLimit, safeOffset]),
    queryWithTiming('getAllUsers:count', countSql, []),
  ]);

  return {
    users: rowsResult.rows,
    total: parseInt(countResult.rows[0].total, 10),
    limit: safeLimit,
    offset: safeOffset,
  };
}

/**
 * Search users whose `name` or `email` contains the given term
 * (case-insensitive, partial match).
 *
 * SQL (parameterised):
 *   SELECT id, name, email, created_at
 *   FROM   users
 *   WHERE  name  ILIKE $1
 *      OR  email ILIKE $1
 *   ORDER  BY id ASC
 *   LIMIT  $2
 *   OFFSET $3
 *
 * The ILIKE pattern ('%' || $1 || '%') is constructed in SQL, not in JS,
 * so any wildcard characters in the user-supplied term are treated as
 * literals by the database engine and cannot alter the query structure.
 *
 * @param {string}           searchTerm – free-text search term
 * @param {number | string}  [limit=20]
 * @param {number | string}  [offset=0]
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number, searchTerm: string }>}
 * @throws {TypeError | RangeError} for invalid inputs
 */
async function searchUsers(searchTerm, limit, offset) {
  const safeTerm = parseSearchTerm(searchTerm);
  const { limit: safeLimit, offset: safeOffset } = parsePagination(
    limit,
    offset,
  );

  // Using '%' || $1 || '%' keeps wildcard construction on the DB side.
  // The bind parameter $1 is never concatenated into the SQL string.
  const rowsSql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM
      users
    WHERE
      name  ILIKE '%' || $1 || '%'
      OR email ILIKE '%' || $1 || '%'
    ORDER BY
      id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM   users
    WHERE
      name  ILIKE '%' || $1 || '%'
      OR email ILIKE '%' || $1 || '%'
  `;

  const [rowsResult, countResult] = await Promise.all([
    queryWithTiming('searchUsers:rows', rowsSql, [
      safeTerm,
      safeLimit,
      safeOffset,
    ]),
    queryWithTiming('searchUsers:count', countSql, [safeTerm]),
  ]);

  return {
    users: rowsResult.rows,
    total: parseInt(countResult.rows[0].total, 10),
    limit: safeLimit,
    offset: safeOffset,
    searchTerm: safeTerm,
  };
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export helpers so they can be unit-tested in isolation
  _parseId: parseId,
  _parsePagination: parsePagination,
  _parseSearchTerm: parseSearchTerm,
  // Constants exported for test assertions
  _MAX_LIMIT: MAX_LIMIT,
  _DEFAULT_LIMIT: DEFAULT_LIMIT,
  _SLOW_QUERY_MS: SLOW_QUERY_MS,
};

'use strict';

/**
 * @module app
 * @description Express application.
 *
 * Endpoints
 * ─────────
 *  GET /health              – liveness probe
 *  GET /users               – paginated list  (?limit=&offset=)
 *  GET /users/search        – ILIKE search    (?q=&limit=&offset=)
 *  GET /users/:id           – single user by primary key
 *
 * The file loads environment variables from .env (if present), then wires
 * the Express routes to the parameterised query functions in queries.js.
 * Database connection is established lazily on the first query; the pool is
 * shut down cleanly when the process receives SIGTERM or SIGINT.
 */

// Load .env into process.env before anything else reads environment variables.
// dotenv is a no-op when running in environments that already inject vars
// (e.g. Docker, Kubernetes, CI).
require('dotenv').config();

const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();

// ── Middleware ────────────────────────────────────────────────────────────────

// Parse JSON request bodies.
app.use(express.json());

/**
 * Request logger – emits a structured line for every incoming request so that
 * query timing logs (emitted by queries.js) can be correlated to a specific
 * HTTP request.
 */
app.use((req, _res, next) => {
  console.info('[http] Incoming request', {
    method: req.method,
    path: req.path,
    query: req.query,
    // Deliberately omitting headers/body to avoid logging auth tokens or PII
  });
  next();
});

// ── Routes ────────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Lightweight liveness check.  Does not hit the database.
 */
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users/search?q=<term>&limit=<n>&offset=<n>
 *
 * Must be registered BEFORE /users/:id so that the literal path segment
 * "search" is not mistakenly captured as an `:id` parameter.
 *
 * Query parameters
 *  q       {string}  required – search term (1-200 chars)
 *  limit   {number}  optional – page size, default 20, max 100
 *  offset  {number}  optional – rows to skip, default 0
 *
 * Responses
 *  200 { users, total, limit, offset, searchTerm }
 *  400 { error }  – missing or invalid parameters
 *  500 { error }  – unexpected database error
 */
app.get('/users/search', async (req, res) => {
  const { q, limit, offset } = req.query;

  if (!q) {
    return res
      .status(400)
      .json({ error: 'Missing required query parameter: q' });
  }

  try {
    const data = await searchUsers(q, limit, offset);
    return res.json(data);
  } catch (err) {
    if (err instanceof TypeError || err instanceof RangeError) {
      return res.status(400).json({ error: err.message });
    }
    console.error('[http] Unhandled error in GET /users/search', {
      errorMessage: err.message,
    });
    return res
      .status(500)
      .json({ error: 'An unexpected error occurred. Please try again later.' });
  }
});

/**
 * GET /users?limit=<n>&offset=<n>
 *
 * Returns a paginated list of all users ordered by id ASC.
 *
 * Query parameters
 *  limit   {number}  optional – page size, default 20, max 100
 *  offset  {number}  optional – rows to skip, default 0
 *
 * Responses
 *  200 { users, total, limit, offset }
 *  400 { error }  – invalid pagination parameters
 *  500 { error }
 */
app.get('/users', async (req, res) => {
  const { limit, offset } = req.query;

  try {
    const data = await getAllUsers(limit, offset);
    return res.json(data);
  } catch (err) {
    if (err instanceof TypeError || err instanceof RangeError) {
      return res.status(400).json({ error: err.message });
    }
    console.error('[http] Unhandled error in GET /users', {
      errorMessage: err.message,
    });
    return res
      .status(500)
      .json({ error: 'An unexpected error occurred. Please try again later.' });
  }
});

/**
 * GET /users/:id
 *
 * Returns a single user whose primary key matches `:id`.
 *
 * Path parameters
 *  id  {number}  required – positive integer
 *
 * Responses
 *  200 { id, name, email, created_at }
 *  400 { error }  – id is not a valid positive integer
 *  404 { error }  – no user with that id
 *  500 { error }
 */
app.get('/users/:id', async (req, res) => {
  const { id } = req.params;

  try {
    const user = await getUserById(id);

    if (!user) {
      return res
        .status(404)
        .json({ error: `No user found with id ${id}.` });
    }

    return res.json(user);
  } catch (err) {
    if (err instanceof TypeError || err instanceof RangeError) {
      return res.status(400).json({ error: err.message });
    }
    console.error('[http] Unhandled error in GET /users/:id', {
      id,
      errorMessage: err.message,
    });
    return res
      .status(500)
      .json({ error: 'An unexpected error occurred. Please try again later.' });
  }
});

// ── 404 catch-all ─────────────────────────────────────────────────────────────

app.use((_req, res) => {
  res.status(404).json({ error: 'Route not found.' });
});

// ── Graceful shutdown ─────────────────────────────────────────────────────────

/**
 * Drain the connection pool before the process exits so that in-flight queries
 * are allowed to complete and idle connections are returned to PostgreSQL.
 *
 * @param {string} signal
 */
async function shutdown(signal) {
  console.info(`[app] Received ${signal}. Shutting down gracefully …`);
  await closePool();
  console.info('[app] Shutdown complete. Exiting.');
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// ── Server startup ────────────────────────────────────────────────────────────

const PORT = parseInt(process.env.PORT ?? '3000', 10);

// Only start listening when this file is executed directly (not when it is
// require()'d by tests).
if (require.main === module) {
  app.listen(PORT, () => {
    console.info(`[app] Server running on port ${PORT}`);
  });
}

module.exports = app;

