/**
 * @file queries.test.js
 * @description Unit tests for queries.js
 *
 * Strategy
 * ────────
 * We isolate queries.js from a real database by providing a Jest mock for the
 * `./db` module.  The mock exposes a `getPool()` that returns a fake pool
 * whose `query` method can be controlled per-test via `mockResolvedValueOnce`
 * and `mockRejectedValueOnce`.
 *
 * This means:
 *  • Tests are fast (no I/O).
 *  • Tests exercise our own validation/transformation logic, not pg internals.
 *  • SQL injection prevention is verified by asserting that the SQL string
 *    never contains user-supplied values and that all user values appear only
 *    in the params array.
 */

// ── Mock db.js ────────────────────────────────────────────────────────────────

// Create a stable fake pool query function we can configure per-test.
const mockQuery = jest.fn();

jest.mock('./db', () => ({
  getPool: () => ({ query: mockQuery }),
  closePool: jest.fn().mockResolvedValue(undefined),
}));

const {
  getUserById,
  getAllUsers,
  searchUsers,
  _parseId,
  _parsePagination,
  _parseSearchTerm,
  _MAX_LIMIT,
  _DEFAULT_LIMIT,
} = require('./queries');

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Build a minimal pg QueryResult stub. */
function makeResult(rows = [], rowCount = null) {
  return { rows, rowCount: rowCount ?? rows.length };
}

/** A fake user row returned by the mock DB. */
const FAKE_USER = {
  id: 1,
  name: 'Alice',
  email: 'alice@example.com',
  created_at: new Date('2024-01-01T00:00:00Z'),
};

// Reset the mock before each test to prevent cross-test pollution.
beforeEach(() => {
  mockQuery.mockReset();
});

