'use strict';

/**
 * @file queries.test.js  (Node built-in test runner — no external deps)
 *
 * Run with:   node --test queries.test.js
 *
 * Uses node:test (Node ≥ 18) and node:assert for assertions, and overrides
 * require() via Module._resolveFilename to inject a mock for ./db so the
 * tests never touch a real database.
 */

const { describe, it, before, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const Module = require('node:module');

// ── Lightweight mock infrastructure ──────────────────────────────────────────
// We intercept require('./db') and return a controlled fake instead.

let mockQueryImpl = null; // set per-test

const fakePool = {
  query: (...args) => {
    if (!mockQueryImpl) throw new Error('mockQueryImpl not set for this test');
    return mockQueryImpl(...args);
  },
};

const fakeDb = {
  getPool: () => fakePool,
  closePool: async () => {},
};

// Track every call to fakePool.query so we can make assertions.
let queryCalls = [];

const wrappedFakePool = {
  query: (...args) => {
    const call = { args };
    queryCalls.push(call);
    const result = fakePool.query(...args);
    call.promise = result;
    return result;
  },
};

const wrappedFakeDb = {
  getPool: () => wrappedFakePool,
  closePool: async () => {},
};

// Intercept require so that queries.js gets our fake db
const originalLoad = Module._load;
Module._load = function (request, parent, isMain) {
  // Resolve relative paths from the parent module's directory
  if (
    (request === './db' || request === '../db') &&
    parent &&
    parent.filename &&
    parent.filename.includes('queries')
  ) {
    return wrappedFakeDb;
  }
  return originalLoad.apply(this, arguments);
};

// Now require queries.js — it will get our fake db
const {
  getUserById,
  getAllUsers,
  searchUsers,
  _parseId,
  _parsePagination,
  _parseSearchTerm,
  _MAX_LIMIT,
  _DEFAULT_LIMIT,
} = require('./queries');

// ── Helpers ───────────────────────────────────────────────────────────────────

function makeResult(rows = []) {
  return { rows, rowCount: rows.length };
}

const FAKE_USER = {
  id: 1,
  name: 'Alice',
  email: 'alice@example.com',
  created_at: new Date('2024-01-01T00:00:00Z'),
};

function resetMocks() {
  queryCalls = [];
  mockQueryImpl = null;
}

/** Set up a sequence of resolved values for successive pool.query() calls. */
function mockQuerySequence(...results) {
  let idx = 0;
  mockQueryImpl = () => {
    if (idx >= results.length) throw new Error('Unexpected extra query call');
    return Promise.resolve(results[idx++]);
  };
}

/** Make the next pool.query() call reject with the given error. */
function mockQueryReject(err) {
  mockQueryImpl = () => Promise.reject(err);
}

// ── Tests ─────────────────────────────────────────────────────────────────────

describe('_parseId', () => {
  it('accepts positive integers', () => {
    assert.equal(_parseId(1), 1);
    assert.equal(_parseId('42'), 42);
    assert.equal(_parseId(999), 999);
  });

  it('rejects zero', () => {
    assert.throws(() => _parseId(0), TypeError);
  });

  it('rejects negative numbers', () => {
    assert.throws(() => _parseId(-1), TypeError);
  });

  it('rejects floats', () => {
    assert.throws(() => _parseId(1.5), TypeError);
  });

  it('rejects non-numeric strings', () => {
    assert.throws(() => _parseId('abc'), TypeError);
    assert.throws(() => _parseId(''), TypeError);
  });

  it('rejects SQL injection strings', () => {
    assert.throws(() => _parseId("1; DROP TABLE users--"), TypeError);
    assert.throws(() => _parseId("1 OR 1=1"), TypeError);
  });

  it('rejects null and undefined', () => {
    assert.throws(() => _parseId(null), TypeError);
    assert.throws(() => _parseId(undefined), TypeError);
  });
});

// ─────────────────────────────────────────────────────────────────────────────

describe('_parsePagination', () => {
  it('returns defaults when both args are undefined', () => {
    assert.deepEqual(_parsePagination(undefined, undefined), {
      limit: _DEFAULT_LIMIT,
      offset: 0,
    });
  });

  it('accepts valid limit and offset', () => {
    assert.deepEqual(_parsePagination(10, 20), { limit: 10, offset: 20 });
    assert.deepEqual(_parsePagination('5', '0'), { limit: 5, offset: 0 });
  });

  it('accepts limit equal to MAX_LIMIT', () => {
    assert.equal(_parsePagination(_MAX_LIMIT, 0).limit, _MAX_LIMIT);
  });

  it('rejects limit greater than MAX_LIMIT', () => {
    assert.throws(() => _parsePagination(_MAX_LIMIT + 1, 0), RangeError);
  });

  it('rejects limit of zero', () => {
    assert.throws(() => _parsePagination(0, 0), RangeError);
  });

  it('rejects negative limit', () => {
    assert.throws(() => _parsePagination(-1, 0), RangeError);
  });

  it('rejects negative offset', () => {
    assert.throws(() => _parsePagination(10, -1), RangeError);
  });

  it('rejects non-numeric strings', () => {
    assert.throws(() => _parsePagination('abc', 0), RangeError);
    assert.throws(() => _parsePagination(10, 'xyz'), RangeError);
  });
});

// ─────────────────────────────────────────────────────────────────────────────

describe('_parseSearchTerm', () => {
  it('accepts a normal string', () => {
    assert.equal(_parseSearchTerm('alice'), 'alice');
  });

  it('trims leading and trailing whitespace', () => {
    assert.equal(_parseSearchTerm('  bob  '), 'bob');
  });

  it('accepts strings with SQL-like characters (safe as bind params)', () => {
    assert.equal(_parseSearchTerm("O'Brien"), "O'Brien");
    assert.equal(_parseSearchTerm('test%user'), 'test%user');
  });

  it('rejects non-strings', () => {
    assert.throws(() => _parseSearchTerm(42), TypeError);
    assert.throws(() => _parseSearchTerm(null), TypeError);
    assert.throws(() => _parseSearchTerm(undefined), TypeError);
  });

  it('rejects empty string', () => {
    assert.throws(() => _parseSearchTerm(''), RangeError);
    assert.throws(() => _parseSearchTerm('   '), RangeError);
  });

  it('rejects strings longer than 200 characters', () => {
    assert.throws(() => _parseSearchTerm('a'.repeat(201)), RangeError);
  });

  it('accepts strings of exactly 200 characters', () => {
    assert.doesNotThrow(() => _parseSearchTerm('a'.repeat(200)));
  });
});

// ─────────────────────────────────────────────────────────────────────────────

describe('getUserById', () => {
  beforeEach(resetMocks);

  it('calls pool.query with parameterised SQL and returns the row', async () => {
    mockQuerySequence(makeResult([FAKE_USER]));

    const user = await getUserById(1);

    assert.deepEqual(user, FAKE_USER);
    assert.equal(queryCalls.length, 1);

    const [sql, params] = queryCalls[0].args;
    assert.deepEqual(params, [1]);
    // User-supplied value must not appear in the SQL string
    assert.doesNotMatch(sql, /\b1\b/);
    assert.ok(sql.includes('$1'), 'SQL must contain $1 placeholder');
  });

  it('returns null when no row is found', async () => {
    mockQuerySequence(makeResult([]));
    assert.equal(await getUserById(99), null);
  });

  it('coerces a string id to an integer', async () => {
    mockQuerySequence(makeResult([FAKE_USER]));
    await getUserById('7');
    const [, params] = queryCalls[0].args;
    assert.deepEqual(params, [7]);
  });

  it('rejects an invalid id without querying the DB', async () => {
    await assert.rejects(() => getUserById('not-an-id'), TypeError);
    assert.equal(queryCalls.length, 0);
  });

  it('rejects SQL injection in id without querying the DB', async () => {
    await assert.rejects(() => getUserById("1; DROP TABLE users--"), TypeError);
    assert.equal(queryCalls.length, 0);
  });

  it('re-throws database errors', async () => {
    mockQueryReject(new Error('connection refused'));
    await assert.rejects(() => getUserById(1), /connection refused/);
  });
});

// ─────────────────────────────────────────────────────────────────────────────

describe('getAllUsers', () => {
  beforeEach(resetMocks);

  it('runs two queries concurrently and returns shaped payload', async () => {
    mockQuerySequence(
      makeResult([FAKE_USER]),
      makeResult([{ total: '42' }]),
    );

    const result = await getAllUsers(10, 0);

    assert.deepEqual(result, {
      users: [FAKE_USER],
      total: 42,
      limit: 10,
      offset: 0,
    });
    assert.equal(queryCalls.length, 2);
  });

  it('applies default limit and offset when omitted', async () => {
    mockQuerySequence(makeResult([]), makeResult([{ total: '0' }]));

    const result = await getAllUsers();

    assert.equal(result.limit, _DEFAULT_LIMIT);
    assert.equal(result.offset, 0);
  });

  it('passes limit and offset as bind params, not in SQL text', async () => {
    mockQuerySequence(makeResult([]), makeResult([{ total: '0' }]));

    await getAllUsers(5, 10);

    const rowsCall = queryCalls.find(({ args: [sql] }) =>
      sql.includes('LIMIT'),
    );
    assert.ok(rowsCall, 'Expected a query containing LIMIT');

    const [sql, params] = rowsCall.args;
    assert.deepEqual(params, [5, 10]);
    assert.doesNotMatch(sql, /\b5\b/);
    assert.doesNotMatch(sql, /\b10\b/);
    assert.ok(sql.includes('$1'));
    assert.ok(sql.includes('$2'));
  });

  it('rejects limit exceeding MAX_LIMIT without querying the DB', async () => {
    await assert.rejects(() => getAllUsers(_MAX_LIMIT + 1, 0), RangeError);
    assert.equal(queryCalls.length, 0);
  });

  it('rejects negative offset without querying the DB', async () => {
    await assert.rejects(() => getAllUsers(10, -5), RangeError);
    assert.equal(queryCalls.length, 0);
  });

  it('total is parsed as a number, not returned as a string', async () => {
    mockQuerySequence(makeResult([]), makeResult([{ total: '123' }]));

    const result = await getAllUsers();

    assert.equal(typeof result.total, 'number');
    assert.equal(result.total, 123);
  });
});

// ─────────────────────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  beforeEach(resetMocks);

  it('runs two queries and returns shaped payload including searchTerm', async () => {
    mockQuerySequence(
      makeResult([FAKE_USER]),
      makeResult([{ total: '1' }]),
    );

    const result = await searchUsers('alice', 10, 0);

    assert.deepEqual(result, {
      users: [FAKE_USER],
      total: 1,
      limit: 10,
      offset: 0,
      searchTerm: 'alice',
    });
    assert.equal(queryCalls.length, 2);
  });

  it('passes search term as a bind parameter — never interpolated into SQL', async () => {
    const injectionAttempt = "'; DROP TABLE users; --";

    mockQuerySequence(makeResult([]), makeResult([{ total: '0' }]));

    await searchUsers(injectionAttempt, 10, 0);

    for (const { args: [sql, params] } of queryCalls) {
      assert.doesNotMatch(sql, new RegExp(injectionAttempt.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')));
      assert.equal(params[0], injectionAttempt);
    }
  });

  it('uses server-side wildcard construction in SQL (no JS concatenation)', async () => {
    mockQuerySequence(makeResult([]), makeResult([{ total: '0' }]));

    await searchUsers('bob', 5, 0);

    const rowsCall = queryCalls.find(({ args: [sql] }) =>
      sql.includes('ILIKE'),
    );
    assert.ok(rowsCall, 'Expected a query containing ILIKE');

    const [sql] = rowsCall.args;
    assert.doesNotMatch(sql, /%bob%/);
    assert.ok(sql.includes("'%' ||"), "SQL must use server-side '%' || $n concatenation");
    assert.ok(sql.includes("|| '%'"));
  });

  it('trims whitespace from the search term before querying', async () => {
    mockQuerySequence(makeResult([]), makeResult([{ total: '0' }]));

    const result = await searchUsers('  carol  ', 5, 0);

    assert.equal(result.searchTerm, 'carol');
    assert.equal(queryCalls[0].args[1][0], 'carol');
  });

  it('rejects empty search term without querying the DB', async () => {
    await assert.rejects(() => searchUsers('', 10, 0), RangeError);
    assert.equal(queryCalls.length, 0);
  });

  it('rejects a search term longer than 200 characters without querying the DB', async () => {
    await assert.rejects(() => searchUsers('x'.repeat(201)), RangeError);
    assert.equal(queryCalls.length, 0);
  });

  it('rejects invalid pagination without querying the DB', async () => {
    await assert.rejects(
      () => searchUsers('alice', _MAX_LIMIT + 1, 0),
      RangeError,
    );
    assert.equal(queryCalls.length, 0);
  });

  it('re-throws database errors', async () => {
    mockQueryReject(new Error('timeout'));
    await assert.rejects(() => searchUsers('alice'), /timeout/);
  });
});

