/**
 * db.js — PostgreSQL connection pool
 *
 * Reads connection config exclusively from environment variables.
 * Never hard-code credentials here; supply them via a .env file
 * (excluded from version control) or your deployment secrets manager.
 *
 * Required env vars:
 *   DB_HOST     – hostname of the PostgreSQL server
 *   DB_PORT     – port (default 5432)
 *   DB_NAME     – database name
 *   DB_USER     – database user
 *   DB_PASSWORD – database password
 *   DB_POOL_MAX – maximum pool size          (default 10)
 *   DB_POOL_MIN – minimum idle connections   (default 2)
 *   DB_IDLE_TIMEOUT_MS – ms before idle conn is released (default 30000)
 *   DB_CONN_TIMEOUT_MS – ms to wait for a free conn      (default 5000)
 *
 * Alternatively set DATABASE_URL to a postgres:// connection string and
 * the pool will parse it automatically.
 */

'use strict';

const { Pool } = require('pg');

// ─── Build pool config ────────────────────────────────────────────────────────

const poolConfig = process.env.DATABASE_URL
  ? {
      connectionString: process.env.DATABASE_URL,
      // Enforce SSL in production unless explicitly disabled
      ssl:
        process.env.NODE_ENV === 'production'
          ? { rejectUnauthorized: true }
          : false,
    }
  : {
      host:     process.env.DB_HOST     || 'localhost',
      port:     parseInt(process.env.DB_PORT || '5432', 10),
      database: process.env.DB_NAME     || 'app',
      user:     process.env.DB_USER     || 'postgres',
      password: process.env.DB_PASSWORD || '',
      ssl:
        process.env.NODE_ENV === 'production'
          ? { rejectUnauthorized: true }
          : false,
    };

// Pool-level tunables
poolConfig.max            = parseInt(process.env.DB_POOL_MAX        || '10',    10);
poolConfig.min            = parseInt(process.env.DB_POOL_MIN        || '2',     10);
poolConfig.idleTimeoutMillis    = parseInt(process.env.DB_IDLE_TIMEOUT_MS || '30000', 10);
poolConfig.connectionTimeoutMillis = parseInt(process.env.DB_CONN_TIMEOUT_MS || '5000',  10);

// ─── Create pool ──────────────────────────────────────────────────────────────

const pool = new Pool(poolConfig);

// Catch idle-connection errors so they don't crash the process
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client', err);
});

// Optional: log when a new physical connection is established
pool.on('connect', () => {
  if (process.env.NODE_ENV !== 'test') {
    console.log('[db] New client connected to pool');
  }
});

// ─── Graceful shutdown ────────────────────────────────────────────────────────

/**
 * Drain all pool connections cleanly.
 * Call this during SIGTERM / SIGINT handling in app.js.
 */
async function closePool() {
  await pool.end();
  console.log('[db] Pool has ended');
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Security guarantees
 * ───────────────────
 * • Every piece of user-supplied data is passed as a query parameter ($1, $2 …),
 *   never interpolated into the SQL string.  PostgreSQL handles escaping at the
 *   protocol level, making string-based SQL injection structurally impossible.
 * • The only dynamic SQL fragment is the ORDER BY column in getAllUsers().
 *   That fragment is validated against an explicit allowlist before use, so it
 *   cannot be influenced by raw user input.
 * • LIMIT and OFFSET are cast to integers with Number() and validated with
 *   Number.isInteger(); non-integer values are rejected before they reach the
 *   driver.
 * • The full-text search in searchUsers() uses the PostgreSQL ILIKE operator
 *   with a parameterised pattern; the wildcard characters are appended in
 *   application code, not concatenated from user input.
 *
 * Query timing
 * ────────────
 * Every exported function wraps its pg call with a high-resolution timer
 * (process.hrtime.bigint) and emits a structured [query] log line that
 * includes the function name, resolved parameters, and wall-clock duration.
 */

'use strict';

const { pool } = require('./db');

// ─── Constants ────────────────────────────────────────────────────────────────

/** Maximum rows that getAllUsers() will ever return in one call. */
const HARD_LIMIT = 1000;

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

/** Default page offset when the caller omits `offset`. */
const DEFAULT_OFFSET = 0;

/**
 * Columns that getAllUsers() will accept for ORDER BY.
 * This allowlist is the only defence needed here because ORDER BY
 * cannot be parameterised at the PostgreSQL protocol level.
 */
const ALLOWED_ORDER_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);
const DEFAULT_ORDER_COLUMN  = 'id';
const ALLOWED_ORDER_DIRS    = new Set(['ASC', 'DESC']);
const DEFAULT_ORDER_DIR     = 'ASC';

// ─── Internal helpers ─────────────────────────────────────────────────────────

/**
 * Thin wrapper around pool.query() that:
 *   1. Acquires a client from the pool (automatically released on completion).
 *   2. Measures wall-clock execution time with nanosecond resolution.
 *   3. Emits a structured log line.
 *   4. Re-throws any database error so callers can handle it.
 *
 * @param {string}   label  – human-readable name used in the log line
 * @param {string}   sql    – parameterised SQL string
 * @param {Array}    params – positional parameter values ($1, $2 …)
 * @returns {import('pg').QueryResult}
 */
async function timedQuery(label, sql, params = []) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, params);
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.log(
      JSON.stringify({
        level:      'info',
        type:       'query',
        fn:         label,
        params:     params,          // parameter VALUES are logged for debugging;
                                     // omit / mask in high-security environments
        rowCount:   result.rowCount,
        durationMs: parseFloat(durationMs.toFixed(3)),
        timestamp:  new Date().toISOString(),
      })
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.error(
      JSON.stringify({
        level:      'error',
        type:       'query',
        fn:         label,
        params:     params,
        durationMs: parseFloat(durationMs.toFixed(3)),
        error:      err.message,
        timestamp:  new Date().toISOString(),
      })
    );

    throw err; // preserve original stack for the caller
  }
}

/**
 * Parse and validate a LIMIT value supplied by the caller.
 * Returns a safe integer between 1 and HARD_LIMIT.
 *
 * @param {*} raw
 * @returns {number}
 */
function parseLimit(raw) {
  const n = raw === undefined || raw === null ? DEFAULT_LIMIT : Number(raw);
  if (!Number.isInteger(n) || n < 1) {
    throw Object.assign(new Error(`limit must be a positive integer, got: ${raw}`), {
      status: 400,
    });
  }
  return Math.min(n, HARD_LIMIT);
}

/**
 * Parse and validate an OFFSET value supplied by the caller.
 * Returns a safe integer ≥ 0.
 *
 * @param {*} raw
 * @returns {number}
 */
function parseOffset(raw) {
  const n = raw === undefined || raw === null ? DEFAULT_OFFSET : Number(raw);
  if (!Number.isInteger(n) || n < 0) {
    throw Object.assign(new Error(`offset must be a non-negative integer, got: ${raw}`), {
      status: 400,
    });
  }
  return n;
}

/**
 * Validate an ORDER BY column name against the allowlist.
 * Falls back to the default column if the supplied value is absent.
 * Throws if a non-allowlisted value is explicitly supplied.
 *
 * @param {*} raw
 * @returns {string}
 */
function parseOrderColumn(raw) {
  if (raw === undefined || raw === null) return DEFAULT_ORDER_COLUMN;
  if (!ALLOWED_ORDER_COLUMNS.has(raw)) {
    throw Object.assign(
      new Error(`orderBy must be one of: ${[...ALLOWED_ORDER_COLUMNS].join(', ')}`),
      { status: 400 }
    );
  }
  return raw; // safe: validated against a hardcoded Set
}

/**
 * Validate an ORDER BY direction against the allowlist.
 *
 * @param {*} raw
 * @returns {'ASC'|'DESC'}
 */
function parseOrderDir(raw) {
  if (raw === undefined || raw === null) return DEFAULT_ORDER_DIR;
  const upper = String(raw).toUpperCase();
  if (!ALLOWED_ORDER_DIRS.has(upper)) {
    throw Object.assign(new Error(`orderDir must be ASC or DESC`), { status: 400 });
  }
  return upper; // safe: validated against a hardcoded Set
}

// ─── Exported query functions ─────────────────────────────────────────────────

/**
 * Fetch a single user by their primary-key ID.
 *
 * SQL injection prevention:
 *   `id` is passed as $1 — a parameterised placeholder.  The value is also
 *   coerced to an integer and rejected if it is not a valid positive integer,
 *   providing a second layer of defence before the query is even built.
 *
 * @param {number|string} id  – user primary key
 * @returns {Object|null}     – user row, or null if not found
 *
 * @example
 *   const user = await getUserById(42);
 */
async function getUserById(id) {
  // Validate: must be a positive integer
  const numericId = Number(id);
  if (!Number.isInteger(numericId) || numericId < 1) {
    throw Object.assign(
      new Error(`id must be a positive integer, got: ${id}`),
      { status: 400 }
    );
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
  `;

  const result = await timedQuery('getUserById', sql, [numericId]);
  return result.rows[0] ?? null;
}

/**
 * Return a paginated list of all users.
 *
 * SQL injection prevention:
 *   • LIMIT  → cast + integer-validated → passed as $1
 *   • OFFSET → cast + integer-validated → passed as $2
 *   • ORDER BY column → validated against ALLOWED_ORDER_COLUMNS Set,
 *     then interpolated as a literal identifier (never from raw user input)
 *   • ORDER BY direction → validated against ALLOWED_ORDER_DIRS Set
 *
 * @param {number} [limit=20]   – rows per page (max 1000)
 * @param {number} [offset=0]   – rows to skip
 * @param {object} [options]
 * @param {string} [options.orderBy='id']   – column to sort by
 * @param {string} [options.orderDir='ASC'] – 'ASC' or 'DESC'
 * @returns {{ rows: Object[], total: number }}
 *
 * @example
 *   const { rows, total } = await getAllUsers(10, 0, { orderBy: 'name' });
 */
async function getAllUsers(limit, offset, options = {}) {
  const safeLimit  = parseLimit(limit);
  const safeOffset = parseOffset(offset);
  const safeCol    = parseOrderColumn(options.orderBy);
  const safeDir    = parseOrderDir(options.orderDir);

  // safeCol and safeDir are NEVER derived from raw user input;
  // they have already passed allowlist validation above.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY ${safeCol} ${safeDir}
    LIMIT  $1
    OFFSET $2
  `;

  const result = await timedQuery('getAllUsers', sql, [safeLimit, safeOffset]);

  return {
    rows:  result.rows.map(({ total_count, ...row }) => row),
    total: result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0,
  };
}

/**
 * Full-text search across user name and email fields.
 *
 * SQL injection prevention:
 *   The search term is passed as parameter $1.  The wildcard characters
 *   ('%' and '_') are added in application code — they are *not* derived
 *   from user input.  This means users cannot craft patterns that change
 *   query semantics, and the pg driver handles any special characters in
 *   the term itself.
 *
 *   Additionally the raw query string is:
 *     • Length-limited to 200 characters.
 *     • Stripped of leading/trailing whitespace.
 *
 * @param {string} query        – search term (matched with ILIKE on name + email)
 * @param {number} [limit=20]   – maximum results to return
 * @param {number} [offset=0]   – pagination offset
 * @returns {{ rows: Object[], total: number }}
 *
 * @example
 *   const { rows } = await searchUsers('alice', 5, 0);
 */
async function searchUsers(query, limit, offset) {
  // ── Input validation ───────────────────────────────────────────────────────

  if (query === undefined || query === null) {
    throw Object.assign(new Error('query parameter is required'), { status: 400 });
  }

  const term = String(query).trim();

  if (term.length === 0) {
    throw Object.assign(new Error('query must not be empty'), { status: 400 });
  }

  if (term.length > 200) {
    throw Object.assign(new Error('query must be 200 characters or fewer'), { status: 400 });
  }

  const safeLimit  = parseLimit(limit);
  const safeOffset = parseOffset(offset);

  // Build the ILIKE pattern in application code.
  // The '%' wildcards are hardcoded here, NOT derived from user input.
  const pattern = `%${term}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY
      -- Exact matches first, then alphabetical
      CASE WHEN LOWER(name)  = LOWER($2) THEN 0
           WHEN LOWER(email) = LOWER($2) THEN 0
           ELSE 1
      END,
      name ASC
    LIMIT  $3
    OFFSET $4
  `;

  // $1 = ILIKE pattern (e.g. '%alice%')
  // $2 = raw term      (e.g. 'alice')   — used only for exact-match ranking
  // $3 = LIMIT
  // $4 = OFFSET
  const result = await timedQuery('searchUsers', sql, [pattern, term, safeLimit, safeOffset]);

  return {
    rows:  result.rows.map(({ total_count, ...row }) => row),
    total: result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0,
  };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
};

'use strict';

const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ─── Health check ─────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─── /users endpoints ─────────────────────────────────────────────────────────

/**
 * GET /users
 *
 * Returns a paginated list of all users.
 *
 * Query params:
 *   limit    {number}  rows per page              (default 20, max 1000)
 *   offset   {number}  rows to skip               (default 0)
 *   orderBy  {string}  column: id|name|email|created_at  (default id)
 *   orderDir {string}  ASC or DESC                (default ASC)
 *   search   {string}  if present, delegates to searchUsers()
 *
 * Examples:
 *   GET /users
 *   GET /users?limit=10&offset=20
 *   GET /users?orderBy=name&orderDir=DESC
 *   GET /users?search=alice
 *   GET /users?search=alice&limit=5
 */
app.get('/users', async (req, res) => {
  try {
    const { limit, offset, orderBy, orderDir, search } = req.query;

    // If a search term is present, delegate to the search path
    if (search !== undefined) {
      const { rows, total } = await searchUsers(search, limit, offset);
      return res.json({
        data: rows,
        pagination: {
          total,
          limit:  rows.length,
          offset: offset !== undefined ? Number(offset) : 0,
          search,
        },
      });
    }

    const { rows, total } = await getAllUsers(limit, offset, { orderBy, orderDir });

    return res.json({
      data: rows,
      pagination: {
        total,
        limit:  rows.length,
        offset: offset !== undefined ? Number(offset) : 0,
      },
    });
  } catch (err) {
    return handleError(res, err);
  }
});

/**
 * GET /users/:id
 *
 * Returns a single user by ID.
 *
 * Params:
 *   id  {number}  user primary key
 *
 * Examples:
 *   GET /users/1
 *   GET /users/42
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `No user with id ${req.params.id}`,
      });
    }

    return res.json({ data: user });
  } catch (err) {
    return handleError(res, err);
  }
});

// ─── Error helper ─────────────────────────────────────────────────────────────

/**
 * Centralised error responder.
 * Validation errors (status 400) are surfaced to the client.
 * All other errors are logged server-side and return a generic 500.
 */
function handleError(res, err) {
  if (err.status === 400) {
    return res.status(400).json({ error: 'Bad Request', message: err.message });
  }
  // Do NOT leak internal error details to the client
  console.error('[app] Internal error:', err);
  return res.status(500).json({ error: 'Internal Server Error' });
}

// ─── Graceful shutdown ────────────────────────────────────────────────────────

async function shutdown(signal) {
  console.log(`[app] ${signal} received — shutting down gracefully`);
  await closePool();
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ─── Start ────────────────────────────────────────────────────────────────────

const PORT = parseInt(process.env.PORT || '3000', 10);

app.listen(PORT, () => {
  console.log(`[app] Server running on port ${PORT}`);
});

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * The pg pool is fully mocked so no real database is needed.
 * Tests cover:
 *   • correct SQL parameterisation (injection prevention)
 *   • input validation and error messages
 *   • timing log output (via console.log spy)
 *   • pagination / search result shaping
 */

'use strict';

// ─── Mock the pool before requiring queries.js ────────────────────────────────

const mockQuery = jest.fn();
jest.mock('./db', () => ({
  pool:      { query: mockQuery },
  closePool: jest.fn(),
}));

const { getUserById, getAllUsers, searchUsers } = require('./queries');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/** Fake user row returned from the pool */
function makeRow(overrides = {}) {
  return {
    id:          1,
    name:        'Alice',
    email:       'alice@example.com',
    created_at:  new Date('2024-01-01').toISOString(),
    updated_at:  new Date('2024-01-02').toISOString(),
    total_count: '50',
    ...overrides,
  };
}

/** Resolve pool.query() with a single row */
function resolveOne(row = makeRow()) {
  mockQuery.mockResolvedValueOnce({ rows: [row], rowCount: 1 });
}

/** Resolve pool.query() with multiple rows */
function resolveMany(rows) {
  mockQuery.mockResolvedValueOnce({ rows, rowCount: rows.length });
}

/** Resolve pool.query() with an empty result set */
function resolveEmpty() {
  mockQuery.mockResolvedValueOnce({ rows: [], rowCount: 0 });
}

beforeEach(() => {
  mockQuery.mockReset();
  jest.spyOn(console, 'log').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => {
  console.log.mockRestore();
  console.error.mockRestore();
});

// ─── getUserById ──────────────────────────────────────────────────────────────

describe('getUserById', () => {
  test('returns user when found', async () => {
    resolveOne();
    const user = await getUserById(1);
    expect(user).toMatchObject({ id: 1, name: 'Alice', email: 'alice@example.com' });
    // total_count should be stripped — it's an internal column
    expect(user.total_count).toBeUndefined();
  });

  test('returns null when user is not found', async () => {
    resolveEmpty();
    const user = await getUserById(999);
    expect(user).toBeNull();
  });

  test('passes id as a parameterised value — not interpolated into SQL', async () => {
    resolveOne();
    await getUserById(42);

    const [sql, params] = mockQuery.mock.calls[0];
    // The SQL string must NOT contain the literal id value
    expect(sql).not.toContain('42');
    // The id must appear as the first positional parameter
    expect(params).toEqual([42]);
    // The placeholder must be present in the SQL
    expect(sql).toContain('$1');
  });

  test('accepts a numeric string id and coerces it', async () => {
    resolveOne();
    await getUserById('7');
    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe(7);
  });

  test('rejects a non-integer id with status 400', async () => {
    await expect(getUserById('abc')).rejects.toMatchObject({
      status:  400,
      message: expect.stringContaining('positive integer'),
    });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a negative id with status 400', async () => {
    await expect(getUserById(-1)).rejects.toMatchObject({ status: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects zero as id with status 400', async () => {
    await expect(getUserById(0)).rejects.toMatchObject({ status: 400 });
  });

  test('rejects a SQL injection attempt in id', async () => {
    await expect(getUserById('1; DROP TABLE users--')).rejects.toMatchObject({
      status: 400,
    });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('emits a structured timing log on success', async () => {
    resolveOne();
    await getUserById(1);

    const logArg = JSON.parse(console.log.mock.calls[0][0]);
    expect(logArg).toMatchObject({
      level:    'info',
      type:     'query',
      fn:       'getUserById',
      params:   [1],
    });
    expect(typeof logArg.durationMs).toBe('number');
    expect(logArg.durationMs).toBeGreaterThanOrEqual(0);
  });

  test('emits an error log and re-throws on db failure', async () => {
    mockQuery.mockRejectedValueOnce(new Error('connection lost'));
    await expect(getUserById(1)).rejects.toThrow('connection lost');

    const errArg = JSON.parse(console.error.mock.calls[0][0]);
    expect(errArg).toMatchObject({ level: 'error', fn: 'getUserById' });
  });
});

// ─── getAllUsers ──────────────────────────────────────────────────────────────

describe('getAllUsers', () => {
  test('returns rows and total count', async () => {
    const rows = [makeRow({ id: 1 }), makeRow({ id: 2, name: 'Bob', email: 'bob@example.com' })];
    resolveMany(rows);
    const result = await getAllUsers();
    expect(result.total).toBe(50);
    expect(result.rows).toHaveLength(2);
    expect(result.rows[0].total_count).toBeUndefined();
  });

  test('returns empty result when table is empty', async () => {
    resolveEmpty();
    const result = await getAllUsers();
    expect(result.rows).toHaveLength(0);
    expect(result.total).toBe(0);
  });

  test('passes limit and offset as parameterised values', async () => {
    resolveMany([makeRow()]);
    await getAllUsers(10, 20);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([10, 20]);
    expect(sql).toContain('$1');
    expect(sql).toContain('$2');
    expect(sql).not.toMatch(/LIMIT\s+10/i);
    expect(sql).not.toMatch(/OFFSET\s+20/i);
  });

  test('applies default limit and offset when omitted', async () => {
    resolveMany([makeRow()]);
    await getAllUsers();
    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe(20);  // DEFAULT_LIMIT
    expect(params[1]).toBe(0);   // DEFAULT_OFFSET
  });

  test('caps limit at HARD_LIMIT (1000)', async () => {
    resolveMany([makeRow()]);
    await getAllUsers(9999);
    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe(1000);
  });

  test('accepts valid orderBy column', async () => {
    resolveMany([makeRow()]);
    await getAllUsers(10, 0, { orderBy: 'name', orderDir: 'DESC' });
    const [sql] = mockQuery.mock.calls[0];
    expect(sql).toContain('name DESC');
  });

  test('rejects disallowed orderBy column with status 400', async () => {
    await expect(
      getAllUsers(10, 0, { orderBy: 'password' })
    ).rejects.toMatchObject({ status: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects SQL injection in orderBy with status 400', async () => {
    await expect(
      getAllUsers(10, 0, { orderBy: 'id; DROP TABLE users--' })
    ).rejects.toMatchObject({ status: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects invalid orderDir with status 400', async () => {
    await expect(
      getAllUsers(10, 0, { orderDir: 'SIDEWAYS' })
    ).rejects.toMatchObject({ status: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects non-integer limit with status 400', async () => {
    await expect(getAllUsers('ten')).rejects.toMatchObject({ status: 400 });
  });

  test('rejects negative offset with status 400', async () => {
    await expect(getAllUsers(10, -5)).rejects.toMatchObject({ status: 400 });
  });

  test('rejects float limit with status 400', async () => {
    await expect(getAllUsers(10.5)).rejects.toMatchObject({ status: 400 });
  });

  test('emits a structured timing log on success', async () => {
    resolveMany([makeRow()]);
    await getAllUsers(5, 0);

    const logArg = JSON.parse(console.log.mock.calls[0][0]);
    expect(logArg).toMatchObject({
      level:  'info',
      type:   'query',
      fn:     'getAllUsers',
      params: [5, 0],
    });
    expect(typeof logArg.durationMs).toBe('number');
  });
});

// ─── searchUsers ─────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  test('returns matched rows and total count', async () => {
    resolveMany([makeRow()]);
    const result = await searchUsers('alice');
    expect(result.rows).toHaveLength(1);
    expect(result.total).toBe(50);
    expect(result.rows[0].total_count).toBeUndefined();
  });

  test('returns empty result when no matches', async () => {
    resolveEmpty();
    const result = await searchUsers('zzznomatch');
    expect(result.rows).toHaveLength(0);
    expect(result.total).toBe(0);
  });

  test('wraps the term in % wildcards for ILIKE — not from user input', async () => {
    resolveMany([makeRow()]);
    await searchUsers('alice');

    const [sql, params] = mockQuery.mock.calls[0];
    // $1 must be the %…% pattern
    expect(params[0]).toBe('%alice%');
    // $2 must be the raw term for exact-match ranking
    expect(params[1]).toBe('alice');
    // SQL must use parameterised placeholders, not the literal string
    expect(sql).not.toContain('alice');
    expect(sql).toContain('$1');
    expect(sql).toContain('$2');
  });

  test('passes limit and offset as parameterised values', async () => {
    resolveMany([makeRow()]);
    await searchUsers('bob', 5, 10);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params[2]).toBe(5);
    expect(params[3]).toBe(10);
    expect(sql).toContain('$3');
    expect(sql).toContain('$4');
  });

  test('a term containing SQL meta-characters is safely parameterised', async () => {
    // These characters are dangerous in string interpolation but safe as params
    resolveMany([makeRow()]);
    await searchUsers("' OR '1'='1");

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe("%' OR '1'='1%");  // passed as a value, never executed as SQL
    expect(params[1]).toBe("' OR '1'='1");
  });

  test('a term containing a semicolon is safely parameterised', async () => {
    resolveMany([makeRow()]);
    await searchUsers('alice; DROP TABLE users--');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%alice; DROP TABLE users--%');
  });

  test('a term containing UNION injection is safely parameterised', async () => {
    resolveMany([makeRow()]);
    await searchUsers('x UNION SELECT password FROM users--');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%x UNION SELECT password FROM users--%');
  });

  test('rejects undefined query with status 400', async () => {
    await expect(searchUsers(undefined)).rejects.toMatchObject({ status: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects empty string with status 400', async () => {
    await expect(searchUsers('')).rejects.toMatchObject({ status: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects whitespace-only string with status 400', async () => {
    await expect(searchUsers('   ')).rejects.toMatchObject({ status: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a term longer than 200 characters with status 400', async () => {
    await expect(searchUsers('a'.repeat(201))).rejects.toMatchObject({
      status:  400,
      message: expect.stringContaining('200'),
    });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('accepts a term of exactly 200 characters', async () => {
    resolveEmpty();
    await expect(searchUsers('a'.repeat(200))).resolves.toBeDefined();
  });

  test('rejects invalid limit with status 400', async () => {
    await expect(searchUsers('alice', 'bad')).rejects.toMatchObject({ status: 400 });
  });

  test('trims leading/trailing whitespace from search term', async () => {
    resolveMany([makeRow()]);
    await searchUsers('  alice  ');
    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%alice%');
    expect(params[1]).toBe('alice');
  });

  test('emits a structured timing log on success', async () => {
    resolveMany([makeRow()]);
    await searchUsers('alice', 10, 0);

    const logArg = JSON.parse(console.log.mock.calls[0][0]);
    expect(logArg).toMatchObject({
      level: 'info',
      type:  'query',
      fn:    'searchUsers',
    });
    expect(logArg.params[0]).toBe('%alice%');
    expect(typeof logArg.durationMs).toBe('number');
  });
});

