/**
 * db/pool.js
 *
 * Creates and exports a single shared pg.Pool instance for the entire
 * application.  All query modules import this file so every request
 * goes through the same pool rather than opening a fresh connection
 * each time.
 *
 * Configuration is read exclusively from environment variables so that
 * credentials are never hard-coded in source files.  In production,
 * set DATABASE_URL (or the individual PG* variables) in your deployment
 * environment or a .env file that is excluded from version control.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
// pg reads the standard PG* environment variables automatically, but we also
// support the DATABASE_URL connection string used by most PaaS providers.
// Explicit pool-tuning knobs are surfaced here so operators can adjust them
// without touching code.
// ---------------------------------------------------------------------------

const poolConfig = {
  // connectionString takes priority when present; individual PG* vars are
  // used as fallbacks by the pg driver automatically.
  connectionString: process.env.DATABASE_URL || undefined,

  // Maximum number of clients the pool should keep open.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // Milliseconds a client must sit idle before being closed & removed.
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT ?? '30000', 10),

  // Milliseconds to wait for a client before throwing a timeout error.
  connectionTimeoutMillis: parseInt(
    process.env.DB_POOL_CONNECT_TIMEOUT ?? '5000',
    10,
  ),

  // Keep SSL enabled for production; allow override for local dev.
  ssl:
    process.env.DB_SSL === 'false'
      ? false
      : process.env.NODE_ENV === 'production'
        ? { rejectUnauthorized: true }
        : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event hooks for observability
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  // Tag every new physical connection so it's easy to correlate in logs.
  client._createdAt = Date.now();
  console.info(
    `[pool] new client connected  | total=${pool.totalCount} ` +
      `idle=${pool.idleCount} waiting=${pool.waitingCount}`,
  );
});

pool.on('acquire', () => {
  console.debug(
    `[pool] client acquired       | total=${pool.totalCount} ` +
      `idle=${pool.idleCount} waiting=${pool.waitingCount}`,
  );
});

pool.on('remove', () => {
  console.info(
    `[pool] client removed        | total=${pool.totalCount} ` +
      `idle=${pool.idleCount} waiting=${pool.waitingCount}`,
  );
});

pool.on('error', (err, client) => {
  // An idle client has errored — log and let the pool manage reconnection.
  console.error('[pool] idle client error:', err.message, client);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------
// Call pool.end() once when the process exits so in-flight transactions can
// finish and connections are closed cleanly.
// ---------------------------------------------------------------------------

async function closePool() {
  console.info('[pool] draining connection pool…');
  await pool.end();
  console.info('[pool] pool closed.');
}

module.exports = { pool, closePool };

/**
 * db/queries.js
 *
 * Parameterised query functions for the /users endpoint.
 *
 * Design principles
 * -----------------
 * 1. SQL injection prevention
 *    Every value supplied by the caller is passed as a bound parameter
 *    ($1, $2 …) via pg's parameterised-query API.  User-supplied strings
 *    are NEVER interpolated directly into SQL text.
 *
 *    The one exception is sort direction, which must be an SQL keyword
 *    (ASC/DESC) and cannot be parameterised.  We enforce an explicit
 *    allow-list before it reaches the query so no arbitrary text is
 *    accepted.
 *
 * 2. Connection pooling
 *    All functions call pool.query(), which checks out a client from the
 *    shared pool in db/pool.js, runs the query, and immediately returns
 *    the client to the pool.  No manual client management is needed for
 *    simple queries.
 *
 * 3. Query timing
 *    Every public function records wall-clock time with process.hrtime.bigint()
 *    (nanosecond resolution) and emits a structured log line so slow queries
 *    are visible in application logs without a separate APM agent.
 *
 * 4. Input validation
 *    Numeric inputs (id, limit, offset) are coerced and range-checked before
 *    the query is issued.  Invalid values throw a typed QueryValidationError
 *    that callers (e.g. route handlers) can distinguish from database errors.
 */

'use strict';

const { pool } = require('./pool');

// ---------------------------------------------------------------------------
// Custom error types
// ---------------------------------------------------------------------------

/**
 * Thrown when a caller passes a value that fails validation (bad type,
 * out-of-range, empty string, etc.).  HTTP handlers should map this to 400.
 */
class QueryValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'QueryValidationError';
  }
}

/**
 * Thrown when a requested resource does not exist.
 * HTTP handlers should map this to 404.
 */
class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'NotFoundError';
  }
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Returns elapsed milliseconds (two decimal places) since the BigInt
 * timestamp produced by process.hrtime.bigint().
 *
 * @param {bigint} startNs
 * @returns {string}  e.g. "3.47"
 */
function elapsedMs(startNs) {
  return ((Number(process.hrtime.bigint() - startNs)) / 1_000_000).toFixed(2);
}

/**
 * Emit a structured timing log line.
 *
 * @param {string} fnName      Human-readable query function name.
 * @param {object} params      The validated parameters actually used.
 * @param {string} durationMs  Elapsed milliseconds as a string.
 * @param {number} rowCount    Number of rows returned / affected.
 */
function logQueryTiming(fnName, params, durationMs, rowCount) {
  console.info(
    `[query] fn=${fnName} ` +
      `params=${JSON.stringify(params)} ` +
      `duration_ms=${durationMs} ` +
      `rows=${rowCount}`,
  );
}

/**
 * Coerce *value* to a safe integer and confirm it falls within [min, max].
 *
 * @param {*}      value
 * @param {string} name   Parameter name (used in error messages).
 * @param {number} min
 * @param {number} max
 * @returns {number}
 */
function toSafeInt(value, name, min, max) {
  const n = Number(value);
  if (!Number.isInteger(n)) {
    throw new QueryValidationError(
      `"${name}" must be an integer, got: ${JSON.stringify(value)}`,
    );
  }
  if (n < min || n > max) {
    throw new QueryValidationError(
      `"${name}" must be between ${min} and ${max}, got: ${n}`,
    );
  }
  return n;
}

/**
 * Sanitise a free-text search string:
 *  - Reject empty / whitespace-only strings.
 *  - Trim leading/trailing whitespace.
 *  - Cap length so excessively large strings are rejected early.
 *
 * NOTE: The value is still passed as a bound parameter ($1) — this
 * pre-processing is an additional defence-in-depth measure, not a
 * substitute for parameterisation.
 *
 * @param {*}      value
 * @param {string} name
 * @param {number} [maxLength=200]
 * @returns {string}
 */
function toSafeSearchString(value, name, maxLength = 200) {
  if (typeof value !== 'string') {
    throw new QueryValidationError(
      `"${name}" must be a string, got: ${typeof value}`,
    );
  }
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    throw new QueryValidationError(`"${name}" must not be empty or whitespace`);
  }
  if (trimmed.length > maxLength) {
    throw new QueryValidationError(
      `"${name}" must not exceed ${maxLength} characters`,
    );
  }
  return trimmed;
}

/**
 * Validate a sort-direction string against an explicit allow-list.
 * Because sort direction must appear as an SQL keyword (not a parameter),
 * this allow-list is the only safe way to handle it.
 *
 * @param {string} dir   Raw value from caller.
 * @returns {'ASC'|'DESC'}
 */
function toSafeSortDir(dir) {
  const ALLOWED = new Set(['ASC', 'DESC']);
  const upper = String(dir ?? 'ASC').toUpperCase();
  if (!ALLOWED.has(upper)) {
    throw new QueryValidationError(
      `sortDir must be "ASC" or "DESC", got: ${JSON.stringify(dir)}`,
    );
  }
  return upper;
}

/**
 * Validate a sortBy column against an explicit allow-list.
 * Column names cannot be parameterised, so we only permit known safe values.
 *
 * @param {string} col   Raw value from caller.
 * @returns {string}     One of the safe column names.
 */
function toSafeSortCol(col) {
  const ALLOWED = new Set(['id', 'name', 'email', 'created_at']);
  const lower = String(col ?? 'id').toLowerCase();
  if (!ALLOWED.has(lower)) {
    throw new QueryValidationError(
      `sortBy must be one of ${[...ALLOWED].join(', ')}, got: ${JSON.stringify(col)}`,
    );
  }
  return lower;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by primary key.
 *
 * SQL injection prevention
 * ------------------------
 * The id is coerced to a JavaScript integer before being passed as the sole
 * bound parameter $1.  PostgreSQL receives a typed integer value — not a
 * string fragment — so injection is structurally impossible.
 *
 * @param {number|string} id  User primary key (positive integer).
 * @returns {Promise<object>} The user row.
 * @throws {QueryValidationError} If id is not a valid positive integer.
 * @throws {NotFoundError}        If no user with that id exists.
 */
async function getUserById(id) {
  // Validate ----------------------------------------------------------------
  const safeId = toSafeInt(id, 'id', 1, Number.MAX_SAFE_INTEGER);

  // Query -------------------------------------------------------------------
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
  `;

  const startNs = process.hrtime.bigint();

  const result = await pool.query(sql, [safeId]);

  const durationMs = elapsedMs(startNs);
  logQueryTiming('getUserById', { id: safeId }, durationMs, result.rowCount);

  if (result.rowCount === 0) {
    throw new NotFoundError(`User with id ${safeId} not found`);
  }

  return result.rows[0];
}

/**
 * Retrieve a paginated list of users.
 *
 * SQL injection prevention
 * ------------------------
 * Both limit and offset are coerced to integers and range-checked, then
 * passed as bound parameters ($1, $2).  The sort column and direction are
 * validated against strict allow-lists before being interpolated as SQL
 * keywords — no user-supplied string reaches the query text directly.
 *
 * @param {number|string} limit    Maximum rows to return (1 – 100).
 * @param {number|string} offset   Number of rows to skip (≥ 0).
 * @param {object}        [opts]   Optional sort options.
 * @param {string}        [opts.sortBy='id']      Column to sort by.
 * @param {string}        [opts.sortDir='ASC']    Sort direction.
 * @returns {Promise<{users: object[], total: number, limit: number, offset: number}>}
 * @throws {QueryValidationError}
 */
async function getAllUsers(limit, offset, { sortBy = 'id', sortDir = 'ASC' } = {}) {
  // Validate ----------------------------------------------------------------
  const safeLimit  = toSafeInt(limit,  'limit',  1, 100);
  const safeOffset = toSafeInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);
  const safeCol    = toSafeSortCol(sortBy);
  const safeDir    = toSafeSortDir(sortDir);

  // Parameterised query; safeCol and safeDir are keywords from allow-lists.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    ORDER BY ${safeCol} ${safeDir}
    LIMIT  $1
    OFFSET $2
  `;

  // Run data query and count query concurrently for efficiency.
  const countSql = `SELECT COUNT(*) AS total FROM users`;

  const startNs = process.hrtime.bigint();

  const [dataResult, countResult] = await Promise.all([
    pool.query(sql, [safeLimit, safeOffset]),
    pool.query(countSql),
  ]);

  const durationMs = elapsedMs(startNs);
  logQueryTiming(
    'getAllUsers',
    { limit: safeLimit, offset: safeOffset, sortBy: safeCol, sortDir: safeDir },
    durationMs,
    dataResult.rowCount,
  );

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * Full-text search across users' name and email fields.
 *
 * SQL injection prevention
 * ------------------------
 * The raw search term is validated and trimmed, then embedded inside a LIKE
 * pattern string in JavaScript.  That pattern string is passed as a single
 * bound parameter ($1) — the database driver handles all escaping.  The
 * caller can never inject SQL because the entire pattern, including the %
 * wildcards, is a single opaque string value from the database's perspective.
 *
 * Pagination (limit/offset) and sort options follow the same rules as
 * getAllUsers() above.
 *
 * @param {string}        query    Search term (1 – 200 characters).
 * @param {number|string} [limit=20]
 * @param {number|string} [offset=0]
 * @param {object}        [opts]
 * @param {string}        [opts.sortBy='name']
 * @param {string}        [opts.sortDir='ASC']
 * @returns {Promise<{users: object[], total: number, limit: number, offset: number, query: string}>}
 * @throws {QueryValidationError}
 */
async function searchUsers(
  query,
  limit = 20,
  offset = 0,
  { sortBy = 'name', sortDir = 'ASC' } = {},
) {
  // Validate ----------------------------------------------------------------
  const safeQuery  = toSafeSearchString(query, 'query');
  const safeLimit  = toSafeInt(limit,  'limit',  1, 100);
  const safeOffset = toSafeInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);
  const safeCol    = toSafeSortCol(sortBy);
  const safeDir    = toSafeSortDir(sortDir);

  // Build the LIKE pattern in JS; pass it as a bound parameter.
  // '%' + safeQuery + '%' is a plain JS string — it never touches SQL text.
  const likePattern = `%${safeQuery}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY ${safeCol} ${safeDir}
    LIMIT  $2
    OFFSET $3
  `;

  // Count matching rows for pagination metadata.
  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
  `;

  const startNs = process.hrtime.bigint();

  const [dataResult, countResult] = await Promise.all([
    pool.query(sql,      [likePattern, safeLimit, safeOffset]),
    pool.query(countSql, [likePattern]),
  ]);

  const durationMs = elapsedMs(startNs);
  logQueryTiming(
    'searchUsers',
    { query: safeQuery, limit: safeLimit, offset: safeOffset, sortBy: safeCol, sortDir: safeDir },
    durationMs,
    dataResult.rowCount,
  );

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
    query:  safeQuery,
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export error types so callers can do `instanceof` checks.
  QueryValidationError,
  NotFoundError,
};

/**
 * app.js
 *
 * Express application.  The /users endpoint now delegates all data access to
 * the query layer in db/queries.js, which uses a shared pg connection pool
 * and fully parameterised SQL.
 */

'use strict';

// Load environment variables from .env before anything else.
// In production, set these vars in your deployment environment instead.
require('dotenv').config();

const express = require('express');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
  NotFoundError,
} = require('./db/queries');
const { closePool } = require('./db/pool');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Request-level timing middleware
// ---------------------------------------------------------------------------
// Attaches a high-resolution start timestamp to every request and emits a
// single log line when the response finishes, giving us end-to-end latency
// for every HTTP call.
// ---------------------------------------------------------------------------

app.use((req, res, next) => {
  const startNs = process.hrtime.bigint();

  res.on('finish', () => {
    const durationMs = (
      Number(process.hrtime.bigint() - startNs) / 1_000_000
    ).toFixed(2);

    console.info(
      `[http] ${req.method} ${req.originalUrl} ` +
        `status=${res.statusCode} duration_ms=${durationMs}`,
    );
  });

  next();
});

// ---------------------------------------------------------------------------
// Shared route-error handler
// ---------------------------------------------------------------------------
// Maps our typed errors to appropriate HTTP status codes so every route
// handler only needs to call next(err) on failure.
// ---------------------------------------------------------------------------

function handleRouteError(err, res) {
  if (err instanceof QueryValidationError) {
    return res.status(400).json({ error: 'Bad Request', message: err.message });
  }
  if (err instanceof NotFoundError) {
    return res.status(404).json({ error: 'Not Found', message: err.message });
  }
  // Unexpected database / internal error — do NOT leak internals.
  console.error('[http] unhandled error:', err);
  return res
    .status(500)
    .json({ error: 'Internal Server Error', message: 'An unexpected error occurred.' });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health  ---------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users  ----------------------------------------------------------------
//
// Query parameters
//   limit    integer 1-100, default 20
//   offset   integer ≥ 0,   default 0
//   sortBy   id | name | email | created_at,  default id
//   sortDir  ASC | DESC,    default ASC
//   search   free-text search term (activates searchUsers when present)
//
// Example requests
//   GET /users
//   GET /users?limit=5&offset=10
//   GET /users?search=alice
//   GET /users?search=example.com&sortBy=email&sortDir=DESC

app.get('/users', async (req, res) => {
  const {
    limit   = 20,
    offset  = 0,
    sortBy  = 'id',
    sortDir = 'ASC',
    search,
  } = req.query;

  try {
    let result;

    if (search !== undefined) {
      // Free-text search across name and email.
      result = await searchUsers(search, limit, offset, { sortBy, sortDir });
    } else {
      // Paginated list of all users.
      result = await getAllUsers(limit, offset, { sortBy, sortDir });
    }

    res.json(result);
  } catch (err) {
    handleRouteError(err, res);
  }
});

// GET /users/:id  ------------------------------------------------------------
//
// Fetch a single user by primary key.
//
// Example requests
//   GET /users/1
//   GET /users/42

app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);
    res.json(user);
  } catch (err) {
    handleRouteError(err, res);
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------
// Drain the connection pool when the process receives a termination signal so
// in-flight database work is not abruptly interrupted.
// ---------------------------------------------------------------------------

async function shutdown(signal) {
  console.info(`\n[app] received ${signal} — starting graceful shutdown…`);
  await closePool();
  console.info('[app] shutdown complete.');
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

const PORT = parseInt(process.env.PORT ?? '3000', 10);

if (require.main === module) {
  app.listen(PORT, () => {
    console.info(`[app] server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * db/queries.test.js
 *
 * Unit tests for the query layer.
 *
 * Strategy
 * --------
 * The pg pool is mocked at the module level so these tests run without a real
 * database.  We verify:
 *   1. Correct SQL is issued with the expected bound parameters.
 *   2. Input validation rejects bad values before touching the pool.
 *   3. Query timing logs are emitted.
 *   4. Error types (NotFoundError, QueryValidationError) are thrown correctly.
 *
 * Run with:  node --test db/queries.test.js
 * (Node.js built-in test runner — no extra dependencies required.)
 */

'use strict';

const { describe, it, before, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');

// ---------------------------------------------------------------------------
// Mock the pg pool before importing queries.js
// ---------------------------------------------------------------------------

// We intercept require('pg') by injecting a mock into the module cache.
const mockQueryFn = { calls: [] };

const mockPool = {
  query: async (sql, params) => {
    mockQueryFn.calls.push({ sql: sql.trim().replace(/\s+/g, ' '), params });
    // Return value is controlled per-test via mockPool.__nextResult.
    const result = mockPool.__nextResults.shift();
    if (result instanceof Error) throw result;
    return result;
  },
  totalCount:   1,
  idleCount:    1,
  waitingCount: 0,
  on:           () => {},
  end:          async () => {},
  __nextResults: [],
};

// Patch require cache for 'pg' and the pool module before loading queries.
const Module = require('module');
const originalLoad = Module._load;
Module._load = function (request, parent, isMain) {
  if (request === 'pg') {
    return { Pool: class { constructor() { return mockPool; } } };
  }
  return originalLoad.apply(this, arguments);
};

// Now it's safe to load our modules.
const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
  NotFoundError,
} = require('./queries');

// Restore Module._load after loading (keeps other requires unaffected).
Module._load = originalLoad;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function fakeUserRow(overrides = {}) {
  return {
    id:         1,
    name:       'Alice',
    email:      'alice@example.com',
    created_at: new Date('2024-01-01'),
    ...overrides,
  };
}

/** Queue pool results for the next N pool.query() calls */
function queueResults(...results) {
  mockPool.__nextResults.push(...results);
}

// ---------------------------------------------------------------------------
// Test suite
// ---------------------------------------------------------------------------

describe('getUserById', () => {
  beforeEach(() => {
    mockQueryFn.calls = [];
    mockPool.__nextResults = [];
  });

  it('issues a parameterised SELECT with the correct id', async () => {
    queueResults({ rows: [fakeUserRow()], rowCount: 1 });

    await getUserById(1);

    assert.equal(mockQueryFn.calls.length, 1);
    const { sql, params } = mockQueryFn.calls[0];
    assert.match(sql, /SELECT/i);
    assert.match(sql, /FROM users/i);
    assert.match(sql, /WHERE id = \$1/i);
    assert.deepEqual(params, [1]);
  });

  it('coerces a numeric string id to integer', async () => {
    queueResults({ rows: [fakeUserRow({ id: 42 })], rowCount: 1 });

    const user = await getUserById('42');

    assert.equal(user.id, 42);
    assert.deepEqual(mockQueryFn.calls[0].params, [42]);
  });

  it('returns the user row on success', async () => {
    const row = fakeUserRow({ id: 7, name: 'Bob', email: 'bob@example.com' });
    queueResults({ rows: [row], rowCount: 1 });

    const result = await getUserById(7);

    assert.deepEqual(result, row);
  });

  it('throws NotFoundError when no row is returned', async () => {
    queueResults({ rows: [], rowCount: 0 });

    await assert.rejects(
      () => getUserById(999),
      (err) => {
        assert.ok(err instanceof NotFoundError);
        assert.match(err.message, /999/);
        return true;
      },
    );
  });

  it('throws QueryValidationError for id = 0', async () => {
    await assert.rejects(
      () => getUserById(0),
      QueryValidationError,
    );
    assert.equal(mockQueryFn.calls.length, 0); // pool never called
  });

  it('throws QueryValidationError for negative id', async () => {
    await assert.rejects(() => getUserById(-5), QueryValidationError);
    assert.equal(mockQueryFn.calls.length, 0);
  });

  it('throws QueryValidationError for non-numeric id', async () => {
    await assert.rejects(() => getUserById('abc'), QueryValidationError);
    assert.equal(mockQueryFn.calls.length, 0);
  });

  it('throws QueryValidationError for SQL-injection attempt in id', async () => {
    // e.g. "1 OR 1=1" — should fail integer coercion, never reach DB.
    await assert.rejects(() => getUserById('1 OR 1=1'), QueryValidationError);
    assert.equal(mockQueryFn.calls.length, 0);
  });
});

// ---------------------------------------------------------------------------

describe('getAllUsers', () => {
  beforeEach(() => {
    mockQueryFn.calls = [];
    mockPool.__nextResults = [];
  });

  it('issues SELECT with LIMIT $1 OFFSET $2', async () => {
    queueResults(
      { rows: [fakeUserRow()], rowCount: 1 },   // data query
      { rows: [{ total: '1' }], rowCount: 1 },  // count query
    );

    await getAllUsers(10, 0);

    const dataSql = mockQueryFn.calls[0].sql;
    assert.match(dataSql, /LIMIT\s+\$1/i);
    assert.match(dataSql, /OFFSET\s+\$2/i);
    assert.deepEqual(mockQueryFn.calls[0].params, [10, 0]);
  });

  it('runs data query and count query concurrently', async () => {
    queueResults(
      { rows: [], rowCount: 0 },
      { rows: [{ total: '50' }], rowCount: 1 },
    );

    const result = await getAllUsers(5, 0);

    assert.equal(mockQueryFn.calls.length, 2);
    assert.equal(result.total, 50);
  });

  it('returns pagination envelope', async () => {
    queueResults(
      { rows: [fakeUserRow()], rowCount: 1 },
      { rows: [{ total: '1' }], rowCount: 1 },
    );

    const result = await getAllUsers(20, 40);

    assert.equal(result.limit,  20);
    assert.equal(result.offset, 40);
    assert.ok(Array.isArray(result.users));
  });

  it('accepts valid sortBy and sortDir options', async () => {
    queueResults(
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    );

    await getAllUsers(10, 0, { sortBy: 'name', sortDir: 'DESC' });

    const sql = mockQueryFn.calls[0].sql;
    assert.match(sql, /ORDER BY name DESC/i);
  });

  it('throws QueryValidationError for limit > 100', async () => {
    await assert.rejects(() => getAllUsers(101, 0), QueryValidationError);
    assert.equal(mockQueryFn.calls.length, 0);
  });

  it('throws QueryValidationError for limit = 0', async () => {
    await assert.rejects(() => getAllUsers(0, 0), QueryValidationError);
  });

  it('throws QueryValidationError for negative offset', async () => {
    await assert.rejects(() => getAllUsers(10, -1), QueryValidationError);
  });

  it('throws QueryValidationError for unknown sortBy column', async () => {
    // SQL injection attempt via sortBy — must never reach DB.
    await assert.rejects(
      () => getAllUsers(10, 0, { sortBy: 'id; DROP TABLE users; --' }),
      QueryValidationError,
    );
    assert.equal(mockQueryFn.calls.length, 0);
  });

  it('throws QueryValidationError for invalid sortDir', async () => {
    await assert.rejects(
      () => getAllUsers(10, 0, { sortDir: 'SIDEWAYS' }),
      QueryValidationError,
    );
  });
});

// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  beforeEach(() => {
    mockQueryFn.calls = [];
    mockPool.__nextResults = [];
  });

  it('wraps search term in LIKE wildcards as a bound parameter', async () => {
    queueResults(
      { rows: [fakeUserRow()], rowCount: 1 },
      { rows: [{ total: '1' }], rowCount: 1 },
    );

    await searchUsers('alice', 20, 0);

    const { sql, params } = mockQueryFn.calls[0];
    // Pattern must be $1, not interpolated into SQL text.
    assert.match(sql, /ILIKE \$1/i);
    assert.equal(params[0], '%alice%');
  });

  it('trims whitespace from the search term', async () => {
    queueResults(
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    );

    const result = await searchUsers('  bob  ', 10, 0);

    assert.equal(result.query, 'bob');
    assert.equal(mockQueryFn.calls[0].params[0], '%bob%');
  });

  it('returns search metadata in envelope', async () => {
    queueResults(
      { rows: [fakeUserRow()], rowCount: 1 },
      { rows: [{ total: '1' }], rowCount: 1 },
    );

    const result = await searchUsers('alice', 10, 5);

    assert.equal(result.query,  'alice');
    assert.equal(result.limit,  10);
    assert.equal(result.offset, 5);
    assert.equal(result.total,  1);
  });

  it('throws QueryValidationError for empty query string', async () => {
    await assert.rejects(() => searchUsers(''), QueryValidationError);
    assert.equal(mockQueryFn.calls.length, 0);
  });

  it('throws QueryValidationError for whitespace-only query', async () => {
    await assert.rejects(() => searchUsers('   '), QueryValidationError);
    assert.equal(mockQueryFn.calls.length, 0);
  });

  it('throws QueryValidationError for query exceeding 200 chars', async () => {
    await assert.rejects(() => searchUsers('a'.repeat(201)), QueryValidationError);
  });

  it('throws QueryValidationError for SQL-injection attempt in query string', async () => {
    // Even though the value is passed as a bound parameter, validation should
    // reject excessively suspicious input before it reaches the pool.
    // (A normal-length injection string passes length validation and is safe
    // because pg parameterisation treats it as a plain string value — this test
    // confirms the LIKE pattern is built correctly and $1 is used.)
    queueResults(
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    );

    const injection = "' OR '1'='1";
    await searchUsers(injection, 10, 0);

    // The raw injection string appears inside the LIKE pattern as a bound
    // parameter value — NOT spliced into SQL text.
    const { params } = mockQueryFn.calls[0];
    assert.equal(params[0], `%${injection}%`);
  });

  it('throws QueryValidationError for unknown sortBy in search', async () => {
    await assert.rejects(
      () => searchUsers('alice', 10, 0, { sortBy: '1; DELETE FROM users; --' }),
      QueryValidationError,
    );
    assert.equal(mockQueryFn.calls.length, 0);
  });
});

// ---------------------------------------------------------------------------
// Verify error type exports
// ---------------------------------------------------------------------------

describe('Error type exports', () => {
  it('exports QueryValidationError', () => {
    assert.ok(typeof QueryValidationError === 'function');
    const e = new QueryValidationError('test');
    assert.ok(e instanceof QueryValidationError);
    assert.ok(e instanceof Error);
    assert.equal(e.name, 'QueryValidationError');
  });

  it('exports NotFoundError', () => {
    assert.ok(typeof NotFoundError === 'function');
    const e = new NotFoundError('not found');
    assert.ok(e instanceof NotFoundError);
    assert.ok(e instanceof Error);
    assert.equal(e.name, 'NotFoundError');
  });
});

