/**
 * db.js — PostgreSQL connection pool singleton
 *
 * Exports a single `pg.Pool` instance that is shared across the entire
 * application.  All query functions in queries.js borrow a connection from
 * this pool and return it automatically when the query resolves/rejects.
 *
 * Configuration is driven entirely by environment variables so that no
 * credentials are ever hard-coded in source.  Set the variables in a
 * .env file (development) or in your deployment environment (production).
 *
 * Required environment variables:
 *   DB_HOST      – database host          (default: localhost)
 *   DB_PORT      – database port          (default: 5432)
 *   DB_NAME      – database name          (default: app)
 *   DB_USER      – database user          (default: postgres)
 *   DB_PASSWORD  – database password      (required, no default)
 *   DB_SSL       – enable TLS             (default: false)
 *
 * Optional pool-tuning variables:
 *   DB_POOL_MAX          – max connections in pool          (default: 10)
 *   DB_POOL_IDLE_TIMEOUT – ms before idle client is closed  (default: 30000)
 *   DB_POOL_CONN_TIMEOUT – ms to wait for a free client     (default: 5000)
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration — values come exclusively from the environment.
// ---------------------------------------------------------------------------
const poolConfig = {
  host:     process.env.DB_HOST     || 'localhost',
  port:     parseInt(process.env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME     || 'app',
  user:     process.env.DB_USER     || 'postgres',
  password: process.env.DB_PASSWORD,           // no fallback — must be set

  // Pool sizing
  max:              parseInt(process.env.DB_POOL_MAX          || '10',    10),
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT || '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN_TIMEOUT || '5000', 10),

  // TLS: enable in production by setting DB_SSL=true
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event handlers
// ---------------------------------------------------------------------------

// Emitted whenever a new client is created and added to the pool.
pool.on('connect', (client) => {
  console.log(`[db] New client connected (total pool size: ${pool.totalCount})`);

  // Set a statement timeout on every new connection so runaway queries
  // cannot hold a connection indefinitely.
  const stmtTimeout = parseInt(process.env.DB_STMT_TIMEOUT_MS || '10000', 10);
  client.query(`SET statement_timeout = ${stmtTimeout}`).catch((err) => {
    console.error('[db] Failed to set statement_timeout on new client:', err.message);
  });
});

// Emitted when a client is returned to the pool after a query.
pool.on('acquire', () => {
  console.log(
    `[db] Client acquired from pool ` +
    `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount}, total: ${pool.totalCount})`
  );
});

// Emitted when a client is removed from the pool.
pool.on('remove', () => {
  console.log(`[db] Client removed from pool (remaining: ${pool.totalCount})`);
});

// Surface unexpected errors from idle clients (e.g. server-side disconnects)
// so they don't silently crash the process.
pool.on('error', (err) => {
  console.error('[db] Unexpected error on idle pool client:', err.message);
  // Do NOT exit the process here — the pool will automatically replace
  // the faulty client on the next acquire.
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool and close all connections.
 * Called by the shutdown hook in app.js.
 */
async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] All connections closed.');
}

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Every public function in this module:
 *   1. Accepts only typed/validated inputs — raw strings from request objects
 *      are NEVER interpolated into SQL.  All user-supplied values are passed
 *      as positional parameters ($1, $2, …) so the pg driver sends them to
 *      PostgreSQL as separate bind parameters, making SQL injection
 *      structurally impossible.
 *   2. Validates and coerces inputs before touching the database so that
 *      malformed values are rejected at the application layer, not by
 *      Postgres error messages (which could leak schema information).
 *   3. Logs query timing with [query] prefixed messages so slow queries
 *      are immediately visible in your log aggregator.
 *   4. Borrows a connection from the shared pool and returns it in a
 *      finally block, even when the query throws.
 *
 * Exported functions
 * ──────────────────
 *   getUserById(id)                 → single user row | null
 *   getAllUsers(limit, offset)      → { rows, total }
 *   searchUsers(query, limit, offset) → { rows, total }
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Parse and validate a positive integer.
 * Returns the integer, or throws a ValidationError when the value is invalid.
 *
 * @param {*}      value    – raw value (typically from req.query / req.params)
 * @param {string} name     – field name, used in error messages
 * @param {number} min      – inclusive lower bound
 * @param {number} max      – inclusive upper bound
 * @returns {number}
 */
function parsePositiveInt(value, name, min = 1, max = Number.MAX_SAFE_INTEGER) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < min || n > max) {
    throw new ValidationError(
      `"${name}" must be an integer between ${min} and ${max}, received: ${JSON.stringify(value)}`
    );
  }
  return n;
}

/**
 * Sanitise a free-text search string:
 *   • Strips leading/trailing whitespace.
 *   • Enforces a maximum length to avoid enormous LIKE patterns.
 *   • Escapes the PostgreSQL LIKE metacharacters (%, _) so a user typing
 *     "100%" does not accidentally become a wildcard pattern.
 *
 * The escaped value is still sent as a bind parameter — this escaping is an
 * additional defence-in-depth measure, not a substitute for parameterisation.
 *
 * @param {string} raw – user-supplied search term
 * @returns {string}   – safe value to embed inside a LIKE pattern
 */
function sanitiseSearchTerm(raw) {
  if (typeof raw !== 'string') {
    throw new ValidationError('"query" must be a string');
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new ValidationError('"query" must not be empty');
  }
  const MAX_SEARCH_LENGTH = 200;
  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new ValidationError(
      `"query" must be ${MAX_SEARCH_LENGTH} characters or fewer`
    );
  }
  // Escape LIKE metacharacters so the input is treated as a literal string.
  return trimmed.replace(/([\\%_])/g, '\\$1');
}

/**
 * Emit a structured timing log line.
 *
 * @param {string} fnName   – name of the calling query function
 * @param {string} sql      – the SQL template (no bind values)
 * @param {number} startMs  – value from Date.now() before the query
 * @param {number} rowCount – number of rows returned / affected
 */
function logTiming(fnName, sql, startMs, rowCount) {
  const elapsed = Date.now() - startMs;
  const level   = elapsed > 500 ? 'SLOW' : 'OK';          // flag slow queries
  // Log the SQL template, not the bind values, to avoid leaking PII in logs.
  console.log(
    `[query] fn=${fnName} status=${level} duration=${elapsed}ms ` +
    `rows=${rowCount} sql="${sql.replace(/\s+/g, ' ').trim()}"`
  );
}

// ---------------------------------------------------------------------------
// Custom error class (lets app.js distinguish validation from DB errors)
// ---------------------------------------------------------------------------

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

// ---------------------------------------------------------------------------
// Query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by primary-key ID.
 *
 * @param {number|string} id – user ID (will be validated as a positive integer)
 * @returns {Promise<Object|null>} user row, or null when not found
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function getUserById(id) {
  // --- Input validation ---------------------------------------------------
  const safeId = parsePositiveInt(id, 'id', 1);

  // --- SQL (parameterised) ------------------------------------------------
  // $1 is the bind slot for safeId.  PostgreSQL will never interpret it as
  // SQL syntax regardless of its content.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
      AND deleted_at IS NULL
  `;

  const startMs = Date.now();
  let   client;

  try {
    client = await pool.connect();
    const result = await client.query(sql, [safeId]);
    logTiming('getUserById', sql, startMs, result.rowCount);
    return result.rows[0] ?? null;          // null = not found
  } catch (err) {
    logTiming('getUserById', sql, startMs, 0);
    throw enrichDbError(err, 'getUserById');
  } finally {
    if (client) client.release();           // always return the connection
  }
}

/**
 * Retrieve a paginated list of all active users.
 *
 * @param {number|string} limit  – rows per page  (1–100, default 20)
 * @param {number|string} offset – rows to skip   (≥0,    default 0)
 * @returns {Promise<{ rows: Object[], total: number }>}
 *
 * @example
 *   const { rows, total } = await getAllUsers(20, 0);
 */
async function getAllUsers(limit = 20, offset = 0) {
  // --- Input validation ---------------------------------------------------
  const safeLimit  = parsePositiveInt(limit,  'limit',  1, 100);
  const safeOffset = parsePositiveInt(offset, 'offset', 0);

  // --- SQL (parameterised) ------------------------------------------------
