    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE deleted_at IS NULL
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

