      )
    ORDER BY
      -- Exact matches first, then prefix matches, then substring matches
      CASE
        WHEN name  ILIKE $2 THEN 0
        WHEN email ILIKE $2 THEN 0
        WHEN name  ILIKE $3 THEN 1
        WHEN email ILIKE $3 THEN 1
        ELSE 2
      END ASC,
      id ASC
    LIMIT  $4
    OFFSET $5
  `;

  // $1 = '%term%'  (substring match used in WHERE + ORDER BY fallback)
  // $2 = 'term'    (exact match for ORDER BY rank 0)
  // $3 = 'term%'   (prefix match for ORDER BY rank 1)
  // $4 = limit
  // $5 = offset
  const exactPattern  = safeTerm;
  const prefixPattern = `${safeTerm}%`;

  const startMs = Date.now();
  let   client;

  try {
    client = await pool.connect();
    const result = await client.query(sql, [
      likePattern,
      exactPattern,
      prefixPattern,
      safeLimit,
      safeOffset,
    ]);
    logTiming('searchUsers', sql, startMs, result.rowCount);

    const total = result.rows.length > 0
      ? parseInt(result.rows[0].total_count, 10)
      : 0;
    const rows  = result.rows.map(({ total_count, ...rest }) => rest);

    return { rows, total };
  } catch (err) {
    logTiming('searchUsers', sql, startMs, 0);
    throw enrichDbError(err, 'searchUsers');
  } finally {
    if (client) client.release();
  }
}

// ---------------------------------------------------------------------------
// Error enrichment — wraps low-level pg errors with context, and deliberately
// strips Postgres error detail/hint fields that may contain sensitive data
// before the error propagates to the HTTP layer.
// ---------------------------------------------------------------------------

/**
 * @param {Error}  err    – original error from pg
 * @param {string} source – name of the calling query function
 * @returns {Error}
 */
function enrichDbError(err, source) {
  // Re-throw validation errors unchanged — they already carry a 400 status.
  if (err instanceof ValidationError) return err;

  const safe = new Error(`Database error in ${source}`);
  safe.name       = 'DatabaseError';
  safe.statusCode = 503;
  // Preserve the pg error code (e.g. '23505' = unique_violation) for the
  // caller to inspect, but omit the raw message which may contain table/column
  // names or data values.
  safe.pgCode     = err.code;
  // Attach the original only in non-production for debugging.
  if (process.env.NODE_ENV !== 'production') {
    safe.cause = err;
  }
  return safe;
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,   // exported so app.js can use instanceof checks
};

/**
 * app.js — Express application with PostgreSQL-backed /users endpoint
 *
 * Endpoints
 * ─────────
 *   GET /health              – liveness probe
 *   GET /users               – paginated user list
 *   GET /users?search=<term> – full-text search over name / email
 *   GET /users/:id           – fetch a single user by ID
 *
 * All database access goes through queries.js, which uses a shared pg
 * connection pool (db.js) and fully-parameterised SQL.
 */

'use strict';

require('dotenv').config();

const express    = require('express');
const { closePool }          = require('./db');
const { getUserById, getAllUsers, searchUsers, ValidationError } = require('./queries');

const app  = express();
const PORT = parseInt(process.env.PORT || '3000', 10);

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------

app.use(express.json());

// Request-level timing log — records method, path, status and wall-clock time
// for every request so slow endpoints are easy to spot.
app.use((req, _res, next) => {
  req._startMs = Date.now();
  _res.on('finish', () => {
    const elapsed = Date.now() - req._startMs;
    console.log(
      `[http] ${req.method} ${req.originalUrl} → ${_res.statusCode} (${elapsed}ms)`
    );
  });
  next();
});

// ---------------------------------------------------------------------------
// Route helpers
// ---------------------------------------------------------------------------

/**
 * Centralised error → HTTP response mapper.
 * Keeps route handlers free of repetitive if/else chains.
 *
 * @param {Error}    err – any error thrown by a query function
 * @param {Response} res – Express response object
 */
function handleError(err, res) {
  if (err instanceof ValidationError) {
    return res.status(400).json({ error: err.message });
  }
  if (err.name === 'DatabaseError') {
    // Never expose internal DB details to the client.
    return res.status(503).json({ error: 'Service temporarily unavailable' });
  }
  console.error('[app] Unhandled error:', err);
  return res.status(500).json({ error: 'Internal server error' });
}

/**
 * Parse the `limit` and `offset` query-string parameters, falling back to
 * sensible defaults.  The actual range-checking is done inside the query
 * functions themselves — these are just coercion helpers.
 *
 * @param {Request} req
 * @returns {{ limit: number, offset: number }}
 */
function parsePagination(req) {
  return {
    limit:  req.query.limit  !== undefined ? Number(req.query.limit)  : 20,
    offset: req.query.offset !== undefined ? Number(req.query.offset) : 0,
  };
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// ── GET /health ─────────────────────────────────────────────────────────────
app.get('/health', (_req, res) => {
  res.json({
    status:    'ok',
    timestamp: new Date().toISOString(),
    pool: {
      // Expose pool stats so infrastructure health checks can detect
      // connection exhaustion without querying the DB.
      total:   require('./db').pool.totalCount,
      idle:    require('./db').pool.idleCount,
      waiting: require('./db').pool.waitingCount,
    },
  });
});

// ── GET /users  &  GET /users?search=<term> ─────────────────────────────────
//
// Query-string parameters:
//   search  – free-text term; activates searchUsers() instead of getAllUsers()
//   limit   – rows per page (integer, 1–100, default 20)
//   offset  – rows to skip (integer, ≥0, default 0)
//
app.get('/users', async (req, res) => {
  const { limit, offset } = parsePagination(req);

  try {
    if (req.query.search !== undefined) {
      // ── Search branch ────────────────────────────────────────────────────
      const { rows, total } = await searchUsers(req.query.search, limit, offset);
      return res.json({
        data:       rows,
        pagination: { limit, offset, total },
      });
    }

    // ── List branch ──────────────────────────────────────────────────────
    const { rows, total } = await getAllUsers(limit, offset);
    return res.json({
      data:       rows,
      pagination: { limit, offset, total },
    });
  } catch (err) {
    return handleError(err, res);
  }
});

// ── GET /users/:id ───────────────────────────────────────────────────────────
//
// Path parameter:
//   :id – numeric user ID (must be a positive integer)
//
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    return res.json({ data: user });
  } catch (err) {
    return handleError(err, res);
  }
});

// ---------------------------------------------------------------------------
// 404 catch-all (must come after all routes)
// ---------------------------------------------------------------------------

app.use((_req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

// Only start listening when this file is the entry-point, not when it is
// required by tests — keeps the test suite clean.
if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });

  // ── Graceful shutdown ───────────────────────────────────────────────────
  // On SIGTERM / SIGINT:
  //   1. Stop accepting new connections.
  //   2. Wait for in-flight requests to complete (5 s timeout).
  //   3. Drain the connection pool.
  //   4. Exit cleanly.
  const shutdown = (signal) => {
    console.log(`[app] Received ${signal} — shutting down…`);

    server.close(async () => {
      try {
        await closePool();
        console.log('[app] Shutdown complete.');
        process.exit(0);
      } catch (err) {
        console.error('[app] Error during shutdown:', err.message);
        process.exit(1);
      }
    });

    // Force-kill if graceful shutdown takes too long.
    setTimeout(() => {
      console.error('[app] Shutdown timeout — forcing exit.');
      process.exit(1);
    }, 5_000).unref();
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT',  () => shutdown('SIGINT'));
}

module.exports = app;

/**
 * test_queries_logic.js
 *
 * Self-contained tests that mock the `pg` pool and `dotenv` so no real
 * database or npm packages are needed.  Run with:
 *
 *   node test_queries_logic.js
 */

'use strict';

const assert = require('assert');

// ─── 1. Stub out external modules before requiring queries.js ───────────────

// Minimal dotenv stub — config() is a no-op here.
const Module = require('module');
const _origLoad = Module._load.bind(Module);

// Track the query and values received by our mock client.
let lastQuery  = null;
let lastValues = null;
let mockRows   = [];

// Fake pg client
const mockClient = {
  query: async (sql, values) => {
    lastQuery  = sql;
    lastValues = values;
    return { rows: mockRows, rowCount: mockRows.length };
  },
  release: () => {},
};

// Fake pg pool
const mockPool = {
  connect:      async () => mockClient,
  totalCount:   0,
  idleCount:    0,
  waitingCount: 0,
  on:           () => {},
  end:          async () => {},
};

Module._load = (request, parent, isMain) => {
  if (request === 'dotenv')  return { config: () => {} };
  if (request === 'pg')      return { Pool: class { constructor() { return mockPool; } } };
  if (request === './db')    return { pool: mockPool, closePool: async () => {} };
  return _origLoad(request, parent, isMain);
};

const { getUserById, getAllUsers, searchUsers, ValidationError } = require('./queries');

// ─── 2. Test runner ─────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

// ─── 3. getUserById ─────────────────────────────────────────────────────────

console.log('\ngetUserById');

await test('returns a user row when found', async () => {
  mockRows = [{ id: 1, name: 'Alice', email: 'alice@example.com' }];
  const user = await getUserById(1);
  assert.strictEqual(user.id, 1);
  assert.strictEqual(user.name, 'Alice');
});

await test('returns null when no row is found', async () => {
  mockRows = [];
  const user = await getUserById(99);
  assert.strictEqual(user, null);
});

await test('passes id as a bind parameter (not interpolated)', async () => {
  mockRows = [];
  await getUserById(42);
  // The SQL must NOT contain the literal value "42"
  assert.ok(!lastQuery.includes('42'),       'id should not be in SQL string');
  // The bind value array must contain the integer 42
  assert.deepStrictEqual(lastValues, [42],   'id must be in bind values array');
});

await test('rejects id = 0 (below minimum)', async () => {
  await assert.rejects(
    () => getUserById(0),
    (err) => err instanceof ValidationError && err.statusCode === 400
  );
});

await test('rejects negative id', async () => {
  await assert.rejects(
    () => getUserById(-5),
    (err) => err instanceof ValidationError
  );
});

await test('rejects non-numeric id', async () => {
  await assert.rejects(
    () => getUserById('abc'),
    (err) => err instanceof ValidationError
  );
});

await test('rejects SQL injection attempt in id ("1 OR 1=1")', async () => {
  await assert.rejects(
    () => getUserById('1 OR 1=1'),
    (err) => err instanceof ValidationError
  );
});

await test('rejects float id (1.5)', async () => {
  await assert.rejects(
    () => getUserById(1.5),
    (err) => err instanceof ValidationError
  );
});

// ─── 4. getAllUsers ──────────────────────────────────────────────────────────

console.log('\ngetAllUsers');

await test('returns rows and strips total_count from each row', async () => {
  mockRows = [
    { id: 1, name: 'Alice', email: 'a@x.com', total_count: '2' },
    { id: 2, name: 'Bob',   email: 'b@x.com', total_count: '2' },
  ];
  const { rows, total } = await getAllUsers(20, 0);
  assert.strictEqual(total, 2);
  assert.strictEqual(rows.length, 2);
  assert.ok(!('total_count' in rows[0]), 'total_count must not leak into output');
});

await test('total is 0 when no rows are returned', async () => {
  mockRows = [];
  const { rows, total } = await getAllUsers(20, 0);
  assert.strictEqual(total, 0);
  assert.deepStrictEqual(rows, []);
});

await test('passes limit and offset as bind parameters', async () => {
  mockRows = [];
  await getAllUsers(10, 30);
  assert.deepStrictEqual(lastValues, [10, 30]);
  assert.ok(!lastQuery.includes('10'), 'limit should not be in SQL string');
  assert.ok(!lastQuery.includes('30'), 'offset should not be in SQL string');
});

await test('uses default limit=20, offset=0', async () => {
  mockRows = [];
  await getAllUsers();
  assert.deepStrictEqual(lastValues, [20, 0]);
});

await test('rejects limit > 100', async () => {
  await assert.rejects(
    () => getAllUsers(101, 0),
    (err) => err instanceof ValidationError
  );
});

await test('rejects limit = 0', async () => {
  await assert.rejects(
    () => getAllUsers(0, 0),
    (err) => err instanceof ValidationError
  );
});

await test('rejects negative offset', async () => {
  await assert.rejects(
    () => getAllUsers(20, -1),
    (err) => err instanceof ValidationError
  );
});

await test('rejects non-numeric limit', async () => {
  await assert.rejects(
    () => getAllUsers('many', 0),
    (err) => err instanceof ValidationError
  );
});

// ─── 5. searchUsers ─────────────────────────────────────────────────────────

console.log('\nsearchUsers');

await test('passes LIKE pattern as bind parameter', async () => {
  mockRows = [];
  await searchUsers('alice', 20, 0);
  // $1 must be the substring LIKE pattern
  assert.strictEqual(lastValues[0], '%alice%');
  // $2 must be the exact-match pattern
  assert.strictEqual(lastValues[1], 'alice');
  // $3 must be the prefix pattern
  assert.strictEqual(lastValues[2], 'alice%');
  // $4 and $5 are limit / offset
  assert.strictEqual(lastValues[3], 20);
  assert.strictEqual(lastValues[4], 0);
});

await test('the search term is NOT interpolated into the SQL string', async () => {
  mockRows = [];
  await searchUsers('alice', 20, 0);
  assert.ok(!lastQuery.includes('alice'), 'search term must not appear in SQL');
});

await test('escapes LIKE metacharacter % in search term', async () => {
  mockRows = [];
  await searchUsers('100%', 10, 0);
  // The % inside the term must be escaped; the outer % wildcards are added
  // by the application.
  assert.ok(
    lastValues[0].includes('100\\%'),
    `Expected escaped LIKE pattern, got: ${lastValues[0]}`
  );
});

await test('escapes LIKE metacharacter _ in search term', async () => {
  mockRows = [];
  await searchUsers('user_name', 10, 0);
  assert.ok(
    lastValues[0].includes('user\\_name'),
    `Expected escaped LIKE pattern, got: ${lastValues[0]}`
  );
});

await test('escapes LIKE metacharacter backslash in search term', async () => {
  mockRows = [];
  await searchUsers('C:\\path', 10, 0);
  assert.ok(
    lastValues[0].includes('C:\\\\path'),
    `Expected escaped backslash, got: ${lastValues[0]}`
  );
});

await test('rejects empty search term', async () => {
  await assert.rejects(
    () => searchUsers('', 20, 0),
    (err) => err instanceof ValidationError
  );
});

await test('rejects whitespace-only search term', async () => {
  await assert.rejects(
    () => searchUsers('   ', 20, 0),
    (err) => err instanceof ValidationError
  );
});

await test('rejects search term longer than 200 chars', async () => {
  await assert.rejects(
    () => searchUsers('a'.repeat(201), 20, 0),
    (err) => err instanceof ValidationError
  );
});

await test('rejects non-string search term (number)', async () => {
  await assert.rejects(
    () => searchUsers(42, 20, 0),
    (err) => err instanceof ValidationError
  );
});

await test('classic SQL injection attempt is rejected as non-integer id', async () => {
  // Classic attack: "1; DROP TABLE users--"
  await assert.rejects(
    () => getUserById("1; DROP TABLE users--"),
    (err) => err instanceof ValidationError
  );
});

await test('strips total_count from searchUsers results', async () => {
  mockRows = [
    { id: 3, name: 'Charlie', email: 'c@x.com', total_count: '1' },
  ];
  const { rows, total } = await searchUsers('charlie', 10, 0);
  assert.strictEqual(total, 1);
  assert.ok(!('total_count' in rows[0]));
});

// ─── 6. Summary ─────────────────────────────────────────────────────────────

console.log(`\n─────────────────────────────`);
console.log(`  ${passed} passed, ${failed} failed`);
console.log(`─────────────────────────────\n`);

if (failed > 0) process.exit(1);

