// ─── 2. Test runner ─────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`       ${err.message}`);
    failed++;
  }
}

async function runAll() {

// ─── 3. getUserById ─────────────────────────────────────────────────────────

console.log('\ngetUserById');

await test('returns a user row when found', async () => {
  mockRows = [{ id: 1, name: 'Alice', email: 'alice@example.com' }];
  const user = await getUserById(1);
  assert.strictEqual(user.id, 1);
  assert.strictEqual(user.name, 'Alice');
});

await test('returns null when no row is found', async () => {
  mockRows = [];
  const user = await getUserById(99);
  assert.strictEqual(user, null);
});

await test('passes id as a bind parameter (not interpolated)', async () => {
  mockRows = [];
  await getUserById(42);
  // The SQL must NOT contain the literal value "42"
  assert.ok(!lastQuery.includes('42'),       'id should not be in SQL string');
  // The bind value array must contain the integer 42
  assert.deepStrictEqual(lastValues, [42],   'id must be in bind values array');
});

await test('rejects id = 0 (below minimum)', async () => {
  await assert.rejects(
    () => getUserById(0),
    (err) => err instanceof ValidationError && err.statusCode === 400
  );
});

await test('rejects negative id', async () => {
  await assert.rejects(
    () => getUserById(-5),
    (err) => err instanceof ValidationError
  );
});

await test('rejects non-numeric id', async () => {
  await assert.rejects(
    () => getUserById('abc'),
    (err) => err instanceof ValidationError
  );
});

await test('rejects SQL injection attempt in id ("1 OR 1=1")', async () => {
  await assert.rejects(
    () => getUserById('1 OR 1=1'),
    (err) => err instanceof ValidationError
  );
});

await test('rejects float id (1.5)', async () => {
  await assert.rejects(
    () => getUserById(1.5),
    (err) => err instanceof ValidationError
  );
});

// ─── 4. getAllUsers ──────────────────────────────────────────────────────────

console.log('\ngetAllUsers');

await test('returns rows and strips total_count from each row', async () => {
  mockRows = [
    { id: 1, name: 'Alice', email: 'a@x.com', total_count: '2' },
    { id: 2, name: 'Bob',   email: 'b@x.com', total_count: '2' },
  ];
  const { rows, total } = await getAllUsers(20, 0);
  assert.strictEqual(total, 2);
  assert.strictEqual(rows.length, 2);
  assert.ok(!('total_count' in rows[0]), 'total_count must not leak into output');
});

await test('total is 0 when no rows are returned', async () => {
  mockRows = [];
  const { rows, total } = await getAllUsers(20, 0);
  assert.strictEqual(total, 0);
  assert.deepStrictEqual(rows, []);
});

await test('passes limit and offset as bind parameters', async () => {
  mockRows = [];
  await getAllUsers(10, 30);
  assert.deepStrictEqual(lastValues, [10, 30]);
  assert.ok(!lastQuery.includes('10'), 'limit should not be in SQL string');
  assert.ok(!lastQuery.includes('30'), 'offset should not be in SQL string');
});

await test('uses default limit=20, offset=0', async () => {
  mockRows = [];
  await getAllUsers();
  assert.deepStrictEqual(lastValues, [20, 0]);
});

await test('rejects limit > 100', async () => {
  await assert.rejects(
    () => getAllUsers(101, 0),
    (err) => err instanceof ValidationError
  );
});

await test('rejects limit = 0', async () => {
  await assert.rejects(
    () => getAllUsers(0, 0),
    (err) => err instanceof ValidationError
  );
});

await test('rejects negative offset', async () => {
  await assert.rejects(
    () => getAllUsers(20, -1),
    (err) => err instanceof ValidationError
  );
});

await test('rejects non-numeric limit', async () => {
  await assert.rejects(
    () => getAllUsers('many', 0),
    (err) => err instanceof ValidationError
  );
});

// ─── 5. searchUsers ─────────────────────────────────────────────────────────

console.log('\nsearchUsers');

await test('passes LIKE pattern as bind parameter', async () => {
  mockRows = [];
  await searchUsers('alice', 20, 0);
  // $1 must be the substring LIKE pattern
  assert.strictEqual(lastValues[0], '%alice%');
  // $2 must be the exact-match pattern
  assert.strictEqual(lastValues[1], 'alice');
  // $3 must be the prefix pattern
  assert.strictEqual(lastValues[2], 'alice%');
  // $4 and $5 are limit / offset
  assert.strictEqual(lastValues[3], 20);
  assert.strictEqual(lastValues[4], 0);
});

await test('the search term is NOT interpolated into the SQL string', async () => {
  mockRows = [];
  await searchUsers('alice', 20, 0);
  assert.ok(!lastQuery.includes('alice'), 'search term must not appear in SQL');
});

await test('escapes LIKE metacharacter % in search term', async () => {
  mockRows = [];
  await searchUsers('100%', 10, 0);
  // The % inside the term must be escaped; the outer % wildcards are added
  // by the application.
  assert.ok(
    lastValues[0].includes('100\\%'),
    `Expected escaped LIKE pattern, got: ${lastValues[0]}`
  );
});

await test('escapes LIKE metacharacter _ in search term', async () => {
  mockRows = [];
  await searchUsers('user_name', 10, 0);
  assert.ok(
    lastValues[0].includes('user\\_name'),
    `Expected escaped LIKE pattern, got: ${lastValues[0]}`
  );
});

await test('escapes LIKE metacharacter backslash in search term', async () => {
  mockRows = [];
  await searchUsers('C:\\path', 10, 0);
  assert.ok(
    lastValues[0].includes('C:\\\\path'),
    `Expected escaped backslash, got: ${lastValues[0]}`
  );
});

await test('rejects empty search term', async () => {
  await assert.rejects(
    () => searchUsers('', 20, 0),
    (err) => err instanceof ValidationError
  );
});

await test('rejects whitespace-only search term', async () => {
  await assert.rejects(
    () => searchUsers('   ', 20, 0),
    (err) => err instanceof ValidationError
  );
});

await test('rejects search term longer than 200 chars', async () => {
  await assert.rejects(
    () => searchUsers('a'.repeat(201), 20, 0),
    (err) => err instanceof ValidationError
  );
});

await test('rejects non-string search term (number)', async () => {
  await assert.rejects(
    () => searchUsers(42, 20, 0),
    (err) => err instanceof ValidationError
  );
});

await test('classic SQL injection attempt is rejected as non-integer id', async () => {
  // Classic attack: "1; DROP TABLE users--"
  await assert.rejects(
    () => getUserById("1; DROP TABLE users--"),
    (err) => err instanceof ValidationError
  );
});

await test('strips total_count from searchUsers results', async () => {
  mockRows = [
    { id: 3, name: 'Charlie', email: 'c@x.com', total_count: '1' },
  ];
  const { rows, total } = await searchUsers('charlie', 10, 0);
  assert.strictEqual(total, 1);
  assert.ok(!('total_count' in rows[0]));
});

// ─── 6. Summary ─────────────────────────────────────────────────────────────

console.log(`\n─────────────────────────────`);
console.log(`  ${passed} passed, ${failed} failed`);
console.log(`─────────────────────────────\n`);

if (failed > 0) process.exit(1);

} // end runAll

runAll();

