/**
 * db.js — PostgreSQL connection pool singleton
 *
 * Exports a single `pg.Pool` instance that is shared across the entire
 * application.  All query functions in queries.js borrow a connection from
 * this pool and return it automatically when the query resolves/rejects.
 *
 * Configuration is driven entirely by environment variables so that no
 * credentials are ever hard-coded in source.  Set the variables in a
 * .env file (development) or in your deployment environment (production).
 *
 * Required environment variables:
 *   DB_HOST      – database host          (default: localhost)
 *   DB_PORT      – database port          (default: 5432)
 *   DB_NAME      – database name          (default: app)
 *   DB_USER      – database user          (default: postgres)
 *   DB_PASSWORD  – database password      (required, no default)
 *   DB_SSL       – enable TLS             (default: false)
 *
 * Optional pool-tuning variables:
 *   DB_POOL_MAX          – max connections in pool          (default: 10)
 *   DB_POOL_IDLE_TIMEOUT – ms before idle client is closed  (default: 30000)
 *   DB_POOL_CONN_TIMEOUT – ms to wait for a free client     (default: 5000)
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration — values come exclusively from the environment.
// ---------------------------------------------------------------------------
const poolConfig = {
  host:     process.env.DB_HOST     || 'localhost',
  port:     parseInt(process.env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME     || 'app',
  user:     process.env.DB_USER     || 'postgres',
  password: process.env.DB_PASSWORD,           // no fallback — must be set

  // Pool sizing
  max:              parseInt(process.env.DB_POOL_MAX          || '10',    10),
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT || '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN_TIMEOUT || '5000', 10),

  // TLS: enable in production by setting DB_SSL=true
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event handlers
// ---------------------------------------------------------------------------

// Emitted whenever a new client is created and added to the pool.
pool.on('connect', (client) => {
  console.log(`[db] New client connected (total pool size: ${pool.totalCount})`);

  // Set a statement timeout on every new connection so runaway queries
  // cannot hold a connection indefinitely.
  const stmtTimeout = parseInt(process.env.DB_STMT_TIMEOUT_MS || '10000', 10);
  client.query(`SET statement_timeout = ${stmtTimeout}`).catch((err) => {
    console.error('[db] Failed to set statement_timeout on new client:', err.message);
  });
});

// Emitted when a client is returned to the pool after a query.
pool.on('acquire', () => {
  console.log(
    `[db] Client acquired from pool ` +
    `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount}, total: ${pool.totalCount})`
  );
});

// Emitted when a client is removed from the pool.
pool.on('remove', () => {
  console.log(`[db] Client removed from pool (remaining: ${pool.totalCount})`);
});

// Surface unexpected errors from idle clients (e.g. server-side disconnects)
// so they don't silently crash the process.
pool.on('error', (err) => {
  console.error('[db] Unexpected error on idle pool client:', err.message);
  // Do NOT exit the process here — the pool will automatically replace
  // the faulty client on the next acquire.
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool and close all connections.
 * Called by the shutdown hook in app.js.
 */
async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] All connections closed.');
}

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Every public function in this module:
 *   1. Accepts only typed/validated inputs — raw strings from request objects
 *      are NEVER interpolated into SQL.  All user-supplied values are passed
 *      as positional parameters ($1, $2, …) so the pg driver sends them to
 *      PostgreSQL as separate bind parameters, making SQL injection
 *      structurally impossible.
 *   2. Validates and coerces inputs before touching the database so that
 *      malformed values are rejected at the application layer, not by
 *      Postgres error messages (which could leak schema information).
 *   3. Logs query timing with [query] prefixed messages so slow queries
 *      are immediately visible in your log aggregator.
 *   4. Borrows a connection from the shared pool and returns it in a
 *      finally block, even when the query throws.
