 * additional defence-in-depth measure, not a substitute for parameterisation.
 *
 * @param {string} raw – user-supplied search term
 * @returns {string}   – safe value to embed inside a LIKE pattern
 */
function sanitiseSearchTerm(raw) {
  if (typeof raw !== 'string') {
    throw new ValidationError('"query" must be a string');
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new ValidationError('"query" must not be empty');
