  // ── Happy path ──────────────────────────────────────────────────────────────

  test('returns rows array and total count', async () => {
    pool.query.mockResolvedValueOnce(makeResult([ALICE, BOB]));
    const { rows, total } = await getAllUsers();
    expect(rows).toHaveLength(2);
    expect(total).toBe(2);
    // total_count should be stripped from each row
    rows.forEach((r) => expect(r).not.toHaveProperty('total_count'));
  });

  test('returns empty rows and zero total when table is empty', async () => {
    pool.query.mockResolvedValueOnce({ rows: [], rowCount: 0 });
    const { rows, total } = await getAllUsers();
    expect(rows).toHaveLength(0);
    expect(total).toBe(0);
  });

  // ── Pagination ──────────────────────────────────────────────────────────────

  test('passes limit and offset as positional parameters', async () => {
    pool.query.mockResolvedValueOnce(makeResult([CAROL]));
    await getAllUsers(5, 10);

    const call = pool.query.mock.calls[0][0];
    expect(call.text).toContain('$1');
    expect(call.text).toContain('$2');
    expect(call.values).toEqual([5, 10]);
  });

  test('uses default limit=20 and offset=0 when not provided', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await getAllUsers();
    expect(pool.query.mock.calls[0][0].values).toEqual([20, 0]);
  });

  test('accepts string numbers from query params', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await getAllUsers('50', '100');
    expect(pool.query.mock.calls[0][0].values).toEqual([50, 100]);
  });

  // ── Limit cap ───────────────────────────────────────────────────────────────

  test('rejects limit > 200', async () => {
    await expect(getAllUsers(201)).rejects.toThrow(RangeError);
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('allows limit = 200 (boundary)', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await expect(getAllUsers(200)).resolves.toBeDefined();
  });

  // ── Input validation ────────────────────────────────────────────────────────

  test('rejects negative limit', async () => {
    await expect(getAllUsers(-1)).rejects.toThrow(RangeError);
  });

  test('rejects float offset', async () => {
    await expect(getAllUsers(10, 1.5)).rejects.toThrow(RangeError);
  });

  test('rejects non-numeric limit', async () => {
    await expect(getAllUsers('abc')).rejects.toThrow(RangeError);
  });

  // ── Timing log ─────────────────────────────────────────────────────────────

  test('emits timing log containing function name', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await getAllUsers();
    expect(consoleSpy).toHaveBeenCalledWith(expect.stringContaining('getAllUsers'));
  });
});

// ═════════════════════════════════════════════════════════════════════════════
// searchUsers
// ═════════════════════════════════════════════════════════════════════════════

describe('searchUsers', () => {
  // ── Happy path ──────────────────────────────────────────────────────────────

  test('returns matching rows and total', async () => {
    pool.query.mockResolvedValueOnce(makeResult([ALICE]));
    const { rows, total } = await searchUsers('alice');
    expect(rows).toHaveLength(1);
    expect(total).toBe(1);
  });

  // ── SQL parameterisation ────────────────────────────────────────────────────

  test('wraps search term in % wildcards and passes as $1', async () => {
    pool.query.mockResolvedValueOnce(makeResult([ALICE]));
    await searchUsers('alice');

    const call = pool.query.mock.calls[0][0];
    expect(call.values[0]).toBe('%alice%');
    // The SQL text must NOT contain the literal search string.
    expect(call.text).not.toContain('alice');
    expect(call.text).toContain('$1');
  });

  test('passes limit as $2 and offset as $3', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await searchUsers('bob', 10, 5);
    expect(pool.query.mock.calls[0][0].values).toEqual(['%bob%', 10, 5]);
  });

  test('uses default limit=20 and offset=0', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await searchUsers('carol');
    expect(pool.query.mock.calls[0][0].values).toEqual(['%carol%', 20, 0]);
  });

  test('strips leading/trailing whitespace from search term', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await searchUsers('  alice  ');
    expect(pool.query.mock.calls[0][0].values[0]).toBe('%alice%');
  });

  // ── Input validation ────────────────────────────────────────────────────────

  test('throws TypeError when query is undefined', async () => {
    await expect(searchUsers(undefined)).rejects.toThrow(TypeError);
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws TypeError when query is null', async () => {
    await expect(searchUsers(null)).rejects.toThrow(TypeError);
  });

  test('throws RangeError when query is blank', async () => {
    await expect(searchUsers('   ')).rejects.toThrow(RangeError);
  });

  test('throws RangeError when query exceeds 200 characters', async () => {
    await expect(searchUsers('a'.repeat(201))).rejects.toThrow(RangeError);
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('accepts query of exactly 200 characters', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await expect(searchUsers('a'.repeat(200))).resolves.toBeDefined();
  });

  test('rejects limit > 200', async () => {
    await expect(searchUsers('alice', 999)).rejects.toThrow(RangeError);
  });

  test('rejects negative offset', async () => {
    await expect(searchUsers('alice', 10, -1)).rejects.toThrow(RangeError);
  });

  // ── SQL injection attempts ──────────────────────────────────────────────────

  test('injection: LIKE wildcard abuse — passes literal chars as data', async () => {
    // A malicious user providing extra LIKE wildcards: "%_%" cannot escape
    // the ILIKE pattern because the entire value is a parameter.
    pool.query.mockResolvedValueOnce(makeResult([]));
    await searchUsers('%_%');
    // The value passed must be the raw string wrapped in our %…% wildcards.
    expect(pool.query.mock.calls[0][0].values[0]).toBe('%%_%%');
    // The SQL text itself still only has $1 — no injection.
    expect(pool.query.mock.calls[0][0].text).toContain('$1');
  });

  test("injection: single-quote escape attempt ' OR '1'='1", async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await searchUsers("' OR '1'='1");
    // Value travels as a parameter — the quotes are never executed as SQL.
    expect(pool.query.mock.calls[0][0].values[0]).toBe("%' OR '1'='1%");
  });

  test('injection: comment terminator -- in search term', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await searchUsers('admin--');
    expect(pool.query.mock.calls[0][0].values[0]).toBe('%admin--%');
  });

  test('injection: UNION SELECT payload in search term', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await searchUsers('x UNION SELECT * FROM users--');
    // The whole string is a parameter value, not SQL.
    const passedValue = pool.query.mock.calls[0][0].values[0];
    expect(passedValue).toBe('%x UNION SELECT * FROM users--%');
  });

  test('injection: semicolon stacked query in search term', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await searchUsers('x; DROP TABLE users;--');
    expect(pool.query.mock.calls[0][0].values[0]).toBe('%x; DROP TABLE users;--%');
  });

  // ── Timing log ─────────────────────────────────────────────────────────────

  test('emits timing log containing function name', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));
    await searchUsers('test');
    expect(consoleSpy).toHaveBeenCalledWith(expect.stringContaining('searchUsers'));
  });

  test('emits ERROR log and re-throws on DB failure', async () => {
    pool.query.mockRejectedValueOnce(new Error('timeout'));
    await expect(searchUsers('error')).rejects.toThrow('timeout');
    expect(errorSpy).toHaveBeenCalledWith(expect.stringContaining('ERROR'));
  });
});

// ═════════════════════════════════════════════════════════════════════════════
// timedQuery — slow-query WARN path (indirect, via getAllUsers)
// ═════════════════════════════════════════════════════════════════════════════

describe('timedQuery slow-query WARN', () => {
  test('logs WARN and threshold when query exceeds 500 ms', async () => {
    // Simulate a slow query by making hrtime return a large delta.
    const originalHrtime = process.hrtime.bigint;
    let call = 0;
    jest.spyOn(process.hrtime, 'bigint').mockImplementation(() => {
      // First call (start): 0 ns; second call (end): 600 ms in nanoseconds.
      return call++ === 0 ? 0n : 600_000_000n;
    });

    pool.query.mockResolvedValueOnce(makeResult([]));
    await getAllUsers();

    expect(consoleSpy).toHaveBeenCalledWith(expect.stringContaining('WARN'));
    expect(consoleSpy).toHaveBeenCalledWith(expect.stringContaining('slow query'));

    process.hrtime.bigint.mockRestore();
  });
});

