// Manually replicate what Jest does: replace require('./db') with the mock,
// then load queries.js and exercise the validation layer — no pg needed.

const Module = require('module');
const origLoad = Module._load;

// ── Intercept require('./db') ──────────────────────────────────────────────
const mockPool = {
  query:        async () => ({ rows: [], rowCount: 0 }),
  totalCount:   1, idleCount: 1, waitingCount: 0,
  on:           () => {},
  end:          async () => {},
};
Module._load = function(req, parent, isMain) {
  if (req === './db') return mockPool;
  return origLoad.apply(this, arguments);
};

const { getUserById, getAllUsers, searchUsers } = require('./queries');

async function run() {
  let pass = 0, fail = 0;

  async function expect(label, fn, shouldThrow) {
    try {
      await fn();
      if (shouldThrow) { console.error('FAIL (expected throw):', label); fail++; }
      else             { console.log('PASS:', label); pass++; }
    } catch (e) {
      if (shouldThrow) { console.log('PASS (threw as expected):', label); pass++; }
      else             { console.error('FAIL (unexpected throw):', label, e.message); fail++; }
    }
  }

  // getUserById validation
  await expect('getUserById(1) — valid',          () => getUserById(1),          false);
  await expect('getUserById(-1) — neg',           () => getUserById(-1),         true);
  await expect('getUserById(1.5) — float',        () => getUserById(1.5),        true);
  await expect('getUserById(\"1 OR 1=1\") — sqli', () => getUserById('1 OR 1=1'), true);
  await expect('getUserById(undefined)',           () => getUserById(undefined),  true);

  // getAllUsers validation
  mockPool.query = async () => ({ rows: [], rowCount: 0 });
  await expect('getAllUsers() — defaults',   () => getAllUsers(),       false);
  await expect('getAllUsers(201) — over cap', () => getAllUsers(201),    true);
  await expect('getAllUsers(-1) — neg',       () => getAllUsers(-1),     true);
  await expect('getAllUsers(\"abc\") — NaN',  () => getAllUsers('abc'),  true);

  // searchUsers validation
  mockPool.query = async () => ({ rows: [], rowCount: 0 });
  await expect('searchUsers(\"alice\") — valid',  () => searchUsers('alice'),          false);
  await expect('searchUsers(undefined)',           () => searchUsers(undefined),        true);
  await expect('searchUsers(\"\") — blank',        () => searchUsers(''),              true);
  await expect('searchUsers(201 chars) — toolong', () => searchUsers('a'.repeat(201)), true);
  await expect('searchUsers limit > 200',          () => searchUsers('x', 999),        true);

  console.log(\`\nResults: \${pass} passed, \${fail} failed\`);
  process.exitCode = fail > 0 ? 1 : 0;
}

run();
