/**
 * db.js — PostgreSQL connection pool
 *
 * A single Pool instance is created once and reused across the entire
 * process lifetime.  Importing this module from multiple files is safe
 * because Node's module cache means the Pool constructor runs only once.
 *
 * Configuration is read exclusively from environment variables so that
 * no credentials ever appear in source code.
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ── Pool configuration ────────────────────────────────────────────────────────
// All values come from environment variables with safe, conservative defaults.
const poolConfig = {
  connectionString: process.env.DATABASE_URL,

  // Maximum number of clients kept alive in the pool.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // How long (ms) an idle client is allowed to sit in the pool before being
  // closed and removed.
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT_MS ?? '30000', 10),

  // How long (ms) to wait for a client to become available before throwing.
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONNECTION_TIMEOUT_MS ?? '2000', 10),

  // Reject self-signed certificates in production; allow them in development.
  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : process.env.DATABASE_URL?.includes('localhost') ||
        process.env.DATABASE_URL?.includes('127.0.0.1')
      ? false
      : { rejectUnauthorized: false },
};

const pool = new Pool(poolConfig);

// ── Pool-level event handlers ─────────────────────────────────────────────────

/** Log whenever a fresh TCP connection is established. */
pool.on('connect', (client) => {
  console.log(
    `[db] New client connected — pool total: ${pool.totalCount}, ` +
      `idle: ${pool.idleCount}, waiting: ${pool.waitingCount}`
  );
});

/** Surface unexpected errors on idle clients so they never go unhandled. */
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT exit the process here; the pool will discard the broken client
  // and create a fresh one on the next request.
});

// ── Graceful shutdown ─────────────────────────────────────────────────────────

/**
 * Drain the pool when the process exits cleanly (e.g. SIGTERM from a
 * container orchestrator).  This lets in-flight queries finish and avoids
 * "connection terminated unexpectedly" errors in PostgreSQL logs.
 */
async function shutdownPool() {
  try {
    await pool.end();
    console.log('[db] Pool drained — all clients closed.');
  } catch (err) {
    console.error('[db] Error while draining pool:', err.message);
  }
}

process.once('SIGTERM', shutdownPool);
process.once('SIGINT', shutdownPool);

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles applied here:
 *
 *  1. SQL injection prevention
 *     Every piece of user-supplied data travels through the `$N` placeholder
 *     mechanism provided by node-postgres.  The driver sends the query text
 *     and the values array to PostgreSQL as *separate protocol messages*, so
 *     the database engine itself performs escaping — no manual sanitisation
 *     is needed or trusted.
 *
 *  2. Input validation
 *     Parameters are validated and coerced to their expected types *before*
 *     they reach the query builder, so the SQL layer never receives
 *     surprising values (e.g. NaN, negative limits, etc.).
 *
 *  3. Connection pooling
 *     All functions use `pool.query()` which checks out a client, runs the
 *     query, then immediately returns the client to the pool — perfect for
 *     short-lived, single-statement operations.
 *
 *  4. Query timing
 *     Every query is wrapped in a `withTiming()` helper that records wall-
 *     clock duration and emits a structured log line.  Slow queries (over
 *     SLOW_QUERY_THRESHOLD_MS) are flagged with a WARN level so they can be
 *     caught in log-alerting pipelines.
 *
 *  5. Minimal privilege
 *     The queries only SELECT — they never mutate data, so even if a bug
 *     existed in the parameter binding the worst an attacker could read is
 *     user rows (scope limited by the DB role's GRANT).
 */

'use strict';

const pool = require('./db');

// ── Constants ─────────────────────────────────────────────────────────────────

/** Queries slower than this threshold emit a WARN log line. */
const SLOW_QUERY_THRESHOLD_MS = 500;

/** Hard upper bound on the `limit` parameter to prevent accidental full dumps. */
const MAX_LIMIT = 200;

/** Default page size when no limit is provided. */
const DEFAULT_LIMIT = 20;

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Wraps a `pool.query()` call with structured timing logs.
 *
 * @param {string}   label   - Human-readable name shown in logs.
 * @param {string}   text    - Parameterised SQL string.
 * @param {Array}    values  - Positional parameter values ($1, $2 …).
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(label, text, values) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query({ text, values });
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    const level = durationMs > SLOW_QUERY_THRESHOLD_MS ? 'WARN' : 'INFO';

    console.log(
      `[query][${level}] ${label} — ` +
        `rows=${result.rowCount} ` +
        `duration=${durationMs.toFixed(2)}ms` +
        (level === 'WARN' ? ` ⚠ slow query threshold=${SLOW_QUERY_THRESHOLD_MS}ms` : '')
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.error(
      `[query][ERROR] ${label} — ` +
        `duration=${durationMs.toFixed(2)}ms ` +
        `error="${err.message}"`
    );
    throw err; // re-throw so the caller / route handler can respond with 500
  }
}

/**
 * Validates and coerces a value to a positive integer.
 *
 * @param {*}      value    - Raw input (may be a string from query params).
 * @param {string} name     - Parameter name used in error messages.
 * @param {number} fallback - Value to use when `value` is undefined / null.
 * @param {number} [max]    - Optional upper bound (inclusive).
 * @returns {number}
 */
function toPositiveInt(value, name, fallback, max) {
  if (value === undefined || value === null || value === '') return fallback;

  const n = Number(value);

  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError(`"${name}" must be a non-negative integer, got: ${value}`);
  }

  if (max !== undefined && n > max) {
    throw new RangeError(`"${name}" must be ≤ ${max}, got: ${n}`);
  }

  return n;
}

/**
 * Validates and trims a free-text search query.
 *
 * @param {*}      value - Raw input from the request.
 * @param {string} name  - Parameter name used in error messages.
 * @returns {string}
 */
function toSafeSearchString(value, name) {
  if (value === undefined || value === null) {
    throw new TypeError(`"${name}" is required`);
  }

  const s = String(value).trim();

  if (s.length === 0) {
    throw new RangeError(`"${name}" must not be blank`);
  }

  if (s.length > 200) {
    throw new RangeError(`"${name}" must be 200 characters or fewer`);
  }

  return s;
}

// ── Query functions ───────────────────────────────────────────────────────────

/**
 * Fetches a single user row by its primary key.
 *
 * SQL injection safety: `id` is passed as the `$1` positional parameter.
 * node-postgres sends it in a separate binary protocol message, so it is
 * *never* interpolated into the query string.
 *
 * @param {number|string} id - The user's numeric primary key.
 * @returns {Promise<Object|null>} The user row, or `null` if not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: … }
 */
async function getUserById(id) {
  // Coerce & validate — rejects NaN, floats, negative numbers, strings, etc.
  const safeId = toPositiveInt(id, 'id', undefined, Number.MAX_SAFE_INTEGER);

  if (safeId === undefined) {
    throw new TypeError('"id" is required');
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users ordered by creation date (newest
 * first).
 *
 * SQL injection safety: both `limit` and `offset` are integer-validated
 * before being passed as `$1` / `$2` positional parameters.  PostgreSQL
 * only accepts numeric literals in those positions, so no string escaping
 * is necessary or possible.
 *
 * @param {number|string} [limit=20]  - Page size (1–200, default 20).
 * @param {number|string} [offset=0]  - Number of rows to skip (default 0).
 * @returns {Promise<{ rows: Object[], total: number }>}
 *
 * @example
 *   const { rows, total } = await getAllUsers(10, 20);
 */
async function getAllUsers(limit, offset) {
  const safeLimit  = toPositiveInt(limit,  'limit',  DEFAULT_LIMIT, MAX_LIMIT);
  const safeOffset = toPositiveInt(offset, 'offset', 0);

  // A single round-trip returns both the page and the total count using a
  // window function, avoiding a second COUNT(*) query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY created_at DESC, id DESC
    LIMIT  $1
    OFFSET $2
  `;

  const result = await timedQuery('getAllUsers', sql, [safeLimit, safeOffset]);

  return {
    rows:  result.rows.map(({ total_count, ...rest }) => rest),
    total: result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0,
  };
}

/**
 * Full-text search across the `name` and `email` columns using a
 * case-insensitive ILIKE pattern.
 *
 * SQL injection safety: the raw `query` string is passed as `$1`.
 * The `%` wildcards are added *here in JavaScript* — not by the user —
 * and the whole value travels as a parameter, never concatenated into
 * the SQL text.  PostgreSQL treats it as a plain string value, not SQL.
 *
 * @param {string}        query        - Search term (1–200 chars).
 * @param {number|string} [limit=20]   - Page size (1–200, default 20).
 * @param {number|string} [offset=0]   - Rows to skip (default 0).
 * @returns {Promise<{ rows: Object[], total: number }>}
 *
 * @example
 *   const { rows, total } = await searchUsers('alice');
 */
async function searchUsers(query, limit, offset) {
  const safeQuery  = toSafeSearchString(query, 'query');
  const safeLimit  = toPositiveInt(limit,  'limit',  DEFAULT_LIMIT, MAX_LIMIT);
  const safeOffset = toPositiveInt(offset, 'offset', 0);

  // Wrap the sanitised search term in SQL wildcards here — NOT in the SQL
  // string itself — so the user can never inject a rogue LIKE pattern.
  const likePattern = `%${safeQuery}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY created_at DESC, id DESC
    LIMIT  $2
    OFFSET $3
  `;

  const result = await timedQuery('searchUsers', sql, [likePattern, safeLimit, safeOffset]);

  return {
    rows:  result.rows.map(({ total_count, ...rest }) => rest),
    total: result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0,
  };
}

// ── Exports ───────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Expose pool for use in graceful-shutdown / health-check helpers.
  pool,
};

/**
 * app.js — Express application
 *
 * /users routes are backed by the parameterised query layer in queries.js.
 * All database interaction goes through the connection pool defined in db.js.
 */

'use strict';

require('dotenv').config();
const express = require('express');
const { getUserById, getAllUsers, searchUsers, pool } = require('./queries');

const app = express();
app.use(express.json());

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Wraps an async route handler so unhandled promise rejections are forwarded
 * to Express's error middleware rather than crashing the process.
 *
 * @param {Function} fn - Async (req, res, next) handler.
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ── Routes ────────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Liveness probe: also reports pool statistics so orchestrators can spot
 * connection exhaustion before it affects end-users.
 */
app.get('/health', asyncHandler(async (req, res) => {
  // Attempt a lightweight round-trip to confirm the DB is reachable.
  let dbStatus = 'ok';
  try {
    await pool.query('SELECT 1');
  } catch (err) {
    dbStatus = `error: ${err.message}`;
  }

  res.json({
    status:    'ok',
    timestamp: new Date().toISOString(),
    db: {
      status:        dbStatus,
      totalClients:  pool.totalCount,
      idleClients:   pool.idleCount,
      waitingQueue:  pool.waitingCount,
    },
  });
}));

/**
 * GET /users
 * Returns a paginated list of users.
 *
 * Query parameters:
 *   ?limit=20     Page size (default 20, max 200)
 *   ?offset=0     Rows to skip  (default 0)
 *   ?search=alice Free-text search across name and email
 *
