/**
 * db.js — PostgreSQL connection pool
 *
 * Reads connection config exclusively from environment variables so that no
 * credentials ever appear in source code.  A single Pool instance is exported
 * and reused across the entire process lifetime.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
// All values come from environment variables.  Provide safe defaults only for
// non-sensitive tunables (pool sizes, timeouts).  The actual DB credentials
// MUST be set in the environment — the process exits if they are missing.
// ---------------------------------------------------------------------------

const REQUIRED_ENV = ['PGHOST', 'PGPORT', 'PGDATABASE', 'PGUSER', 'PGPASSWORD'];

const missing = REQUIRED_ENV.filter((key) => !process.env[key]);
if (missing.length > 0) {
  console.error(
    `[db] Missing required environment variables: ${missing.join(', ')}. ` +
      'Set them before starting the server.',
  );
  // In production-style code we exit early rather than silently connecting to
  // the wrong (or no) database.
  process.exit(1);
}

const pool = new Pool({
  host:     process.env.PGHOST,
  port:     Number(process.env.PGPORT),
  database: process.env.PGDATABASE,
  user:     process.env.PGUSER,
  password: process.env.PGPASSWORD,

  // ── Pool tunables (safe to expose; no credentials) ──────────────────────
  // Maximum number of clients the pool will hold.
  max: Number(process.env.PG_POOL_MAX ?? 10),

  // Milliseconds a client must sit idle before being released.
  idleTimeoutMillis: Number(process.env.PG_IDLE_TIMEOUT_MS ?? 30_000),

  // Milliseconds to wait for a client before throwing an acquisition error.
  connectionTimeoutMillis: Number(process.env.PG_CONN_TIMEOUT_MS ?? 5_000),

  // Use SSL in production unless explicitly disabled.
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
});

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  console.log(`[db] New client connected (total: ${pool.totalCount})`);
  // Enforce a statement timeout per connection so runaway queries cannot lock
  // the database indefinitely.
  const stmtTimeout = process.env.PG_STATEMENT_TIMEOUT_MS ?? 10_000;
  client.query(`SET statement_timeout = ${Number(stmtTimeout)}`).catch((err) => {
    console.error('[db] Failed to set statement_timeout:', err.message);
  });
});

pool.on('acquire', () => {
  console.log(
    `[db] Client acquired from pool ` +
      `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`,
  );
});

pool.on('remove', () => {
  console.log(`[db] Client removed from pool (total: ${pool.totalCount})`);
});

pool.on('error', (err) => {
  // Idle clients that encounter unexpected errors are surfaced here.
  console.error('[db] Unexpected pool error:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------

async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] Pool closed.');
}

process.on('SIGINT',  () => closePool().then(() => process.exit(0)));
process.on('SIGTERM', () => closePool().then(() => process.exit(0)));

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * ─────────────────
 * 1. SQL injection prevention
 *    Every user-supplied value is passed as a *parameter* ($1, $2 …) and
 *    never interpolated into the query string.  The pg driver sends parameters
 *    to PostgreSQL over the wire separately from the SQL text, so the database
 *    server itself handles escaping — no manual sanitisation is needed or
 *    relied upon.
 *
 * 2. Input validation & type coercion
 *    Parameters are validated and coerced to their expected types before being
 *    handed to the driver.  Invalid values throw a typed QueryValidationError
 *    that the route layer can translate into a 400 response.
 *
 * 3. Query timing
 *    Every query is wrapped in a timer that emits structured log lines so
 *    slow queries are immediately visible in logs / APM tools.
 *
 * 4. Connection pooling
 *    All queries are executed through the shared Pool defined in db.js; no
 *    single-client connections are used, ensuring efficient resource reuse.
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Hard ceiling on the number of rows that can be requested in one call. */
const MAX_LIMIT = 100;

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

/** Default starting offset when the caller omits `offset`. */
const DEFAULT_OFFSET = 0;

/** Minimum length for a search query string. */
const MIN_SEARCH_LENGTH = 1;

/** Maximum length for a search query string. */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Custom error type
// ---------------------------------------------------------------------------

/**
 * Thrown when a caller supplies a value that fails validation.
 * The route layer maps this to HTTP 400.
 */
class QueryValidationError extends Error {
  /**
   * @param {string} field   - Name of the invalid parameter.
   * @param {string} message - Human-readable explanation.
   */
  constructor(field, message) {
    super(message);
    this.name  = 'QueryValidationError';
    this.field = field;
  }
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Runs a parameterised query against the shared pool, logging its duration.
 *
 * @param {string}   label      - Short human-readable name shown in logs.
 * @param {string}   sql        - The SQL text with $1 … $n placeholders.
 * @param {any[]}    params     - Positional parameter values.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(label, sql, params) {
  const start = process.hrtime.bigint();

  console.log(`[query:${label}] Executing with ${params.length} parameter(s)`);

  try {
    const result = await pool.query(sql, params);

    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.log(
      `[query:${label}] OK — ${result.rowCount} row(s) returned in ${durationMs.toFixed(2)} ms`,
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.error(
      `[query:${label}] ERROR after ${durationMs.toFixed(2)} ms — ${err.message}`,
    );

    throw err; // re-throw; callers decide how to handle DB errors
  }
}

/**
 * Validates and coerces `value` to a safe integer within [min, max].
 *
 * @param {any}    value - Raw value from caller.
 * @param {string} field - Parameter name (used in error messages).
 * @param {number} min   - Inclusive lower bound.
 * @param {number} max   - Inclusive upper bound.
 * @returns {number}
 */
function toSafeInt(value, field, min, max) {
  const n = Number(value);

  if (!Number.isInteger(n)) {
    throw new QueryValidationError(field, `"${field}" must be an integer, got: ${value}`);
  }
  if (n < min || n > max) {
    throw new QueryValidationError(
      field,
      `"${field}" must be between ${min} and ${max}, got: ${n}`,
    );
  }

  return n;
}

/**
 * Validates a search query string: strips leading/trailing whitespace,
 * enforces length bounds, and rejects strings that consist entirely of
 * wildcard characters (which would match every row and defeat pagination).
 *
 * @param {any} value - Raw value from caller.
 * @returns {string}  - Trimmed, validated string.
 */
function toSafeSearchString(value) {
  if (typeof value !== 'string') {
    throw new QueryValidationError('query', '"query" must be a string');
  }

  const trimmed = value.trim();

  if (trimmed.length < MIN_SEARCH_LENGTH) {
    throw new QueryValidationError(
      'query',
      `"query" must be at least ${MIN_SEARCH_LENGTH} character(s) after trimming`,
    );
  }
  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new QueryValidationError(
      'query',
      `"query" must be at most ${MAX_SEARCH_LENGTH} characters`,
    );
  }
  if (/^[%_\s]+$/.test(trimmed)) {
    throw new QueryValidationError(
      'query',
      '"query" must contain at least one non-wildcard character',
    );
  }

  return trimmed;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by their primary-key ID.
 *
 * SQL injection prevention:
 *   `id` is coerced to a JavaScript integer before being passed as parameter
 *   $1.  PostgreSQL never interpolates it into the query string.
 *
 * @param {number|string} id - The user's numeric ID.
 * @returns {Promise<object|null>} The user row, or null if not found.
 *
 * @throws {QueryValidationError} When `id` is not a positive integer.
 * @throws {Error}                On unexpected database errors.
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 *   res.json(user);
 */
async function getUserById(id) {
  // Coerce & validate — rejects strings like "1; DROP TABLE users"
  const safeId = toSafeInt(id, 'id', 1, Number.MAX_SAFE_INTEGER);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);

  return result.rows[0] ?? null;
}

/**
 * Retrieve a paginated list of all users.
 *
 * SQL injection prevention:
 *   Both `limit` and `offset` are coerced to integers and passed as $1 / $2.
 *   PostgreSQL's LIMIT and OFFSET clauses accept numeric parameters safely.
 *
 * @param {number} [limit=20]  - Maximum rows to return (1–100).
 * @param {number} [offset=0]  - Zero-based row offset for pagination.
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number }>}
 *
 * @throws {QueryValidationError} When `limit` or `offset` are out of range.
 *
 * @example
 *   // GET /users?limit=10&offset=20
 *   const page = await getAllUsers(10, 20);
 *   res.json(page);
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = DEFAULT_OFFSET) {
  const safeLimit  = toSafeInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = toSafeInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // Run the data query and the count query concurrently for efficiency.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('getAllUsers:data',  dataSql,  [safeLimit, safeOffset]),
    timedQuery('getAllUsers:count', countSql, []),
  ]);

  return {
    users:  dataResult.rows,
    total:  Number(countResult.rows[0].total),
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * Search users by a partial match on `name` or `email`.
 *
 * SQL injection prevention:
 *   The search term is passed as parameter $1 inside a pg_ilike expression.
 *   The `%` wildcards are appended *in JavaScript* before being handed to the
 *   driver as a parameter value — they are never concatenated into the SQL
 *   text itself.  Any `%` or `_` characters already present in the caller's
 *   string are escaped so they are treated as literals, not SQL wildcards.
 *
 * @param {string} query         - The search term (1–200 characters).
 * @param {number} [limit=20]    - Maximum rows to return (1–100).
 * @param {number} [offset=0]    - Zero-based row offset for pagination.
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number, query: string }>}
 *
 * @throws {QueryValidationError} When any parameter fails validation.
 *
 * @example
 *   // GET /users/search?q=alice&limit=5
 *   const results = await searchUsers('alice', 5, 0);
 *   res.json(results);
 */
async function searchUsers(query, limit = DEFAULT_LIMIT, offset = DEFAULT_OFFSET) {
  const safeQuery  = toSafeSearchString(query);
  const safeLimit  = toSafeInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = toSafeInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // Escape any literal `%` or `_` in the caller's string so they match
  // exactly those characters rather than acting as LIKE wildcards.
  const escapedQuery = safeQuery.replace(/[%_\\]/g, '\\$&');
  const likePattern  = `%${escapedQuery}%`;

  // $1 = likePattern, $2 = safeLimit, $3 = safeOffset
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('searchUsers:data',  dataSql,  [likePattern, safeLimit, safeOffset]),
    timedQuery('searchUsers:count', countSql, [likePattern]),
  ]);

  return {
    users:  dataResult.rows,
    total:  Number(countResult.rows[0].total),
    limit:  safeLimit,
    offset: safeOffset,
    query:  safeQuery,
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
  // Expose constants so callers (tests, docs) can reference them.
  MAX_LIMIT,
  DEFAULT_LIMIT,
  DEFAULT_OFFSET,
};

/**
 * app.js — Express application
 *
 * /users endpoints are now backed by parameterised PostgreSQL queries
 * defined in queries.js, executed through a connection pool in db.js.
 */

'use strict';

// Load environment variables from a .env file when present (dev / CI).
// In production, variables are injected directly into the process environment.
require('dotenv').config();

const express = require('express');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
  MAX_LIMIT,
  DEFAULT_LIMIT,
  DEFAULT_OFFSET,
} = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Centralised error handler for route callbacks.
 *
 * Maps QueryValidationError → 400, everything else → 500 so that internal
 * database details are never leaked to the client.
 *
 * @param {Error}    err  - The thrown error.
 * @param {string}   label - Short context label for server-side logs.
 * @param {import('express').Response} res
 */
function handleRouteError(err, label, res) {
  if (err instanceof QueryValidationError) {
    return res.status(400).json({
      error: 'Invalid request parameter',
      field: err.field,
      detail: err.message,
    });
  }

  // Unexpected / database errors: log the real message server-side but return
  // a generic 500 to the client so internal details are not exposed.
  console.error(`[${label}] Unexpected error:`, err.message);
  return res.status(500).json({ error: 'Internal server error' });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/** GET /health — liveness check; no DB dependency */
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── GET /users ──────────────────────────────────────────────────────────────
/**
 * List users with optional pagination.
 *
 * Query params:
 *   limit  {number}  Rows per page (1–100, default 20)
 *   offset {number}  Row offset    (≥0,    default 0)
 *
 * Responds 200 { users, total, limit, offset }
 *          400 on invalid parameters
 *          500 on database errors
 */
app.get('/users', async (req, res) => {
  const limit  = req.query.limit  ?? DEFAULT_LIMIT;
  const offset = req.query.offset ?? DEFAULT_OFFSET;

  try {
    const result = await getAllUsers(limit, offset);
    return res.json(result);
  } catch (err) {
    return handleRouteError(err, 'GET /users', res);
  }
});

// ── GET /users/search ───────────────────────────────────────────────────────
/**
 * Search users by name or email (case-insensitive partial match).
 *
 * Query params:
 *   q      {string}  Search term (required, 1–200 chars)
 *   limit  {number}  Rows per page (1–100, default 20)
 *   offset {number}  Row offset    (≥0,    default 0)
 *
 * Responds 200 { users, total, limit, offset, query }
 *          400 on missing or invalid parameters
 *          500 on database errors
 *
 * NOTE: this route must be registered *before* /users/:id so that
 *       the literal path segment "search" is not mistaken for an id.
 */
app.get('/users/search', async (req, res) => {
  const { q, limit = DEFAULT_LIMIT, offset = DEFAULT_OFFSET } = req.query;

  if (!q || typeof q !== 'string' || q.trim() === '') {
    return res.status(400).json({
      error: 'Invalid request parameter',
      field: 'q',
      detail: 'Query parameter "q" is required',
    });
  }

  try {
    const result = await searchUsers(q, limit, offset);
    return res.json(result);
  } catch (err) {
    return handleRouteError(err, 'GET /users/search', res);
  }
});

// ── GET /users/:id ──────────────────────────────────────────────────────────
/**
 * Fetch a single user by numeric ID.
 *
 * Path param:
 *   id {number}  Positive integer user ID
 *
 * Responds 200 { id, name, email, created_at, updated_at }
 *          400 on non-integer id
 *          404 when no user exists with that id
 *          500 on database errors
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found', id: req.params.id });
    }

    return res.json(user);
  } catch (err) {
    return handleRouteError(err, 'GET /users/:id', res);
  }
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

const PORT = Number(process.env.PORT ?? 3000);

// Only start listening when this file is the entry point, not when it is
// imported by tests (which import the module directly).
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * The pool is mocked so no real database connection is needed.
 * Tests cover:
 *   • Happy-path behaviour for each query function
 *   • Input validation / QueryValidationError cases
 *   • SQL injection attempts (verify they are rejected before touching the DB)
 *   • Parameterisation (verify the SQL text never contains the raw value)
 *   • Query timing log output
 *   • Pagination metadata
 *
 * Run with:  node --test queries.test.js   (Node ≥ 18 built-in test runner)
 */

'use strict';

const { test, describe, beforeEach, mock } = require('node:test');
const assert = require('node:assert/strict');

// ---------------------------------------------------------------------------
// Mock the pool BEFORE requiring queries.js so the module picks up the mock.
// ---------------------------------------------------------------------------

// We build a small fake pool whose `query` method we can control per-test.
const fakePool = {
  query: async () => { throw new Error('pool.query not configured for this test'); },
  totalCount: 1,
  idleCount: 1,
  waitingCount: 0,
  on: () => {},
  end: async () => {},
};

// Intercept require('pg') so Pool returns our fakePool.
// Node's module cache means we patch before the first require of queries.js.
const Module = require('node:module');
const _originalLoad = Module._load.bind(Module);

Module._load = function (request, parent, isMain) {
  if (request === 'pg') {
    return {
      Pool: class MockPool {
        constructor() { return fakePool; }
      },
    };
  }
  return _originalLoad(request, parent, isMain);
};

// Also stub dotenv and db.js so the env-variable guard in db.js is bypassed.
Module._load = (function (original) {
  return function (request, parent, isMain) {
    if (request === 'dotenv')  return { config: () => {} };
    if (request === './db')    return { pool: fakePool, closePool: async () => {} };
    if (request === 'pg')      return { Pool: class { constructor() { return fakePool; } } };
    return original(request, parent, isMain);
  };
})(Module._load);

// Now it is safe to load the module under test.
const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
  MAX_LIMIT,
  DEFAULT_LIMIT,
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Configure fakePool.query to respond to sequential calls with the provided
 * result objects.
 *
 * @param {...object} results
 */
function setPoolResults(...results) {
  const queue = [...results];
  fakePool.query = async (_sql, _params) => {
    if (queue.length === 0) throw new Error('Unexpected extra pool.query call');
    return queue.shift();
  };
}

/**
 * Configure fakePool.query to capture every call and return a fixed result.
 *
 * @param {object}   result  - The QueryResult to return.
 * @returns {{ calls: Array<{sql:string, params:any[]}> }}
 */
function capturePoolCalls(result) {
  const calls = [];
  fakePool.query = async (sql, params) => {
    calls.push({ sql, params });
    return result;
  };
  return { calls };
}

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------

describe('getUserById', () => {

  test('returns a user when the pool resolves with one row', async () => {
    const mockUser = { id: 1, name: 'Alice', email: 'alice@example.com' };
    setPoolResults({ rows: [mockUser], rowCount: 1 });

    const user = await getUserById(1);
    assert.deepEqual(user, mockUser);
  });

  test('returns null when no row is found', async () => {
    setPoolResults({ rows: [], rowCount: 0 });
    const user = await getUserById(999);
    assert.equal(user, null);
  });

  test('passes id as a parameterised value, not in SQL text', async () => {
    const { calls } = capturePoolCalls({ rows: [], rowCount: 0 });
    await getUserById(42).catch(() => {});
    const { sql, params } = calls[0];
    assert.ok(!sql.includes('42'), 'id must not appear in SQL text');
    assert.deepEqual(params, [42]);
  });

  // ── Validation ────────────────────────────────────────────────────────────

  test('throws QueryValidationError for a non-numeric id', async () => {
    await assert.rejects(
      () => getUserById('abc'),
      (err) => {
        assert.ok(err instanceof QueryValidationError);
        assert.equal(err.field, 'id');
        return true;
      },
    );
  });

  test('throws QueryValidationError for id = 0 (below minimum)', async () => {
    await assert.rejects(() => getUserById(0), QueryValidationError);
  });

  test('throws QueryValidationError for a negative id', async () => {
    await assert.rejects(() => getUserById(-5), QueryValidationError);
  });

  test('throws QueryValidationError for a float id', async () => {
    await assert.rejects(() => getUserById(1.5), QueryValidationError);
  });

  // ── SQL injection attempts ────────────────────────────────────────────────

  test('rejects classic SQL injection string as id', async () => {
    await assert.rejects(
      () => getUserById("1; DROP TABLE users; --"),
      QueryValidationError,
    );
  });

  test('rejects UNION-based injection attempt as id', async () => {
    await assert.rejects(
      () => getUserById("1 UNION SELECT * FROM secrets"),
      QueryValidationError,
    );
  });

  test('rejects boolean injection attempt as id', async () => {
    await assert.rejects(
      () => getUserById("1 OR 1=1"),
      QueryValidationError,
    );
  });

});

// ---------------------------------------------------------------------------
// getAllUsers
// ---------------------------------------------------------------------------

describe('getAllUsers', () => {

  const makeListResult = (n = 2) => ({
    rows: Array.from({ length: n }, (_, i) => ({
      id: i + 1, name: `User ${i + 1}`, email: `u${i + 1}@example.com`,
    })),
    rowCount: n,
  });

  test('returns paginated result with total count', async () => {
    setPoolResults(makeListResult(2), { rows: [{ total: '50' }], rowCount: 1 });

    const result = await getAllUsers(10, 0);
    assert.equal(result.total, 50);
    assert.equal(result.limit, 10);
    assert.equal(result.offset, 0);
    assert.equal(result.users.length, 2);
  });

  test('uses DEFAULT_LIMIT when no arguments are given', async () => {
    const { calls } = capturePoolCalls({ rows: [], rowCount: 0 });
    // Two queries run (data + count); count returns no `total` key — that is
    // fine for this test, which only inspects the params.
    fakePool.query = async (sql, params) => {
      calls.push({ sql, params });
      if (sql.includes('COUNT')) return { rows: [{ total: '0' }], rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };

    await getAllUsers();
    // The data query should have DEFAULT_LIMIT as its first parameter.
    const dataCall = calls.find((c) => !c.sql.includes('COUNT'));
    assert.equal(dataCall.params[0], DEFAULT_LIMIT);
  });

  test('passes limit and offset as parameters, not in SQL text', async () => {
    const callLog = [];
    fakePool.query = async (sql, params) => {
      callLog.push({ sql, params });
      if (sql.includes('COUNT')) return { rows: [{ total: '0' }], rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };

    await getAllUsers(7, 14);
    const dataCall = callLog.find((c) => !c.sql.includes('COUNT'));
    assert.ok(!dataCall.sql.includes('7'),  'limit must not appear in SQL text');
    assert.ok(!dataCall.sql.includes('14'), 'offset must not appear in SQL text');
    assert.deepEqual(dataCall.params, [7, 14]);
  });

  // ── Validation ────────────────────────────────────────────────────────────

  test('throws QueryValidationError when limit exceeds MAX_LIMIT', async () => {
    await assert.rejects(
      () => getAllUsers(MAX_LIMIT + 1, 0),
      (err) => err instanceof QueryValidationError && err.field === 'limit',
    );
  });

  test('throws QueryValidationError when limit is 0', async () => {
    await assert.rejects(() => getAllUsers(0, 0), QueryValidationError);
  });

  test('throws QueryValidationError when offset is negative', async () => {
    await assert.rejects(() => getAllUsers(10, -1), QueryValidationError);
  });

  test('throws QueryValidationError for non-integer limit', async () => {
    await assert.rejects(() => getAllUsers('ten', 0), QueryValidationError);
  });

  test('throws QueryValidationError for float offset', async () => {
    await assert.rejects(() => getAllUsers(10, 2.5), QueryValidationError);
  });

  // ── SQL injection attempts ────────────────────────────────────────────────

  test('rejects injection attempt in limit', async () => {
    await assert.rejects(
      () => getAllUsers('10; DROP TABLE users; --', 0),
      QueryValidationError,
    );
  });

  test('rejects injection attempt in offset', async () => {
    await assert.rejects(
      () => getAllUsers(10, '0 UNION SELECT password FROM users'),
      QueryValidationError,
    );
  });

});

// ---------------------------------------------------------------------------
// searchUsers
// ---------------------------------------------------------------------------

describe('searchUsers', () => {

  const makeSearchResult = (n = 1) => ({
    rows: Array.from({ length: n }, (_, i) => ({
      id: i + 1, name: `Alice ${i}`, email: `alice${i}@example.com`,
    })),
    rowCount: n,
  });

  function poolReturnsSearch(dataRows = 1, total = 1) {
    fakePool.query = async (sql, params) => {
      if (sql.includes('COUNT')) return { rows: [{ total: String(total) }], rowCount: 1 };
      return makeSearchResult(dataRows);
    };
  }

  test('returns matching users and metadata', async () => {
    poolReturnsSearch(2, 2);
    const result = await searchUsers('alice', 10, 0);
    assert.equal(result.users.length, 2);
    assert.equal(result.total, 2);
    assert.equal(result.query, 'alice');
    assert.equal(result.limit, 10);
    assert.equal(result.offset, 0);
  });

  test('wraps the search term in % wildcards as a parameter value', async () => {
    const callLog = [];
    fakePool.query = async (sql, params) => {
      callLog.push({ sql, params });
      if (sql.includes('COUNT')) return { rows: [{ total: '0' }], rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };

    await searchUsers('bob');
    const dataCall = callLog.find((c) => !c.sql.includes('COUNT'));
    // The wildcard pattern must be a parameter value, not in the SQL text.
    assert.equal(dataCall.params[0], '%bob%');
    assert.ok(!dataCall.sql.includes('bob'), 'search term must not appear in SQL text');
  });

  test('escapes literal % in search term before building LIKE pattern', async () => {
    const callLog = [];
    fakePool.query = async (sql, params) => {
      callLog.push({ sql, params });
      if (sql.includes('COUNT')) return { rows: [{ total: '0' }], rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };

    await searchUsers('50%off');
    const dataCall = callLog.find((c) => !c.sql.includes('COUNT'));
    // The bare % must be escaped to \% so it is not treated as a SQL wildcard.
    assert.equal(dataCall.params[0], '%50\\%off%');
  });

  test('escapes literal _ in search term', async () => {
    const callLog = [];
    fakePool.query = async (sql, params) => {
      callLog.push({ sql, params });
      if (sql.includes('COUNT')) return { rows: [{ total: '0' }], rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };

    await searchUsers('hello_world');
    const dataCall = callLog.find((c) => !c.sql.includes('COUNT'));
    assert.equal(dataCall.params[0], '%hello\\_world%');
  });

  test('trims whitespace from the search query', async () => {
    poolReturnsSearch();
    const result = await searchUsers('  alice  ');
    assert.equal(result.query, 'alice');
  });

  // ── Validation ────────────────────────────────────────────────────────────

  test('throws QueryValidationError for an empty string query', async () => {
    await assert.rejects(() => searchUsers(''), QueryValidationError);
  });

  test('throws QueryValidationError for a whitespace-only query', async () => {
    await assert.rejects(() => searchUsers('   '), QueryValidationError);
  });

  test('throws QueryValidationError for a wildcards-only query', async () => {
    await assert.rejects(() => searchUsers('%%__'), QueryValidationError);
  });

  test('throws QueryValidationError for non-string query', async () => {
    await assert.rejects(() => searchUsers(42), QueryValidationError);
  });

  test('throws QueryValidationError when query exceeds max length', async () => {
    await assert.rejects(() => searchUsers('a'.repeat(201)), QueryValidationError);
  });

  test('throws QueryValidationError when limit exceeds MAX_LIMIT', async () => {
    await assert.rejects(
      () => searchUsers('alice', MAX_LIMIT + 1),
      (err) => err instanceof QueryValidationError && err.field === 'limit',
    );
  });

  // ── SQL injection attempts ────────────────────────────────────────────────

  test('rejects SQL injection in search term: quote-based', async () => {
    // A string with only quotes is valid text, so it should reach the DB —
    // but it must be passed as a parameter value, not spliced into the SQL.
    const callLog = [];
    fakePool.query = async (sql, params) => {
      callLog.push({ sql, params });
      if (sql.includes('COUNT')) return { rows: [{ total: '0' }], rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };

    const payload = "' OR '1'='1";
    await searchUsers(payload);
    // The raw payload must NEVER appear inside the SQL text.
    for (const { sql } of callLog) {
      assert.ok(
        !sql.includes("'"),
        'SQL injection payload must not be interpolated into SQL text',
      );
    }
    // It must appear only in the params array (wrapped in wildcards, escaped).
    const dataCall = callLog.find((c) => !c.sql.includes('COUNT'));
    assert.ok(dataCall.params[0].includes("' OR '1'='1"));
  });

  test('rejects SQL injection in search term: comment-based', async () => {
    const callLog = [];
    fakePool.query = async (sql, params) => {
      callLog.push({ sql, params });
      if (sql.includes('COUNT')) return { rows: [{ total: '0' }], rowCount: 1 };
      return { rows: [], rowCount: 0 };
    };

    await searchUsers("admin'--");
    for (const { sql } of callLog) {
      assert.ok(!sql.includes('--'), 'SQL comment must not be in SQL text');
    }
  });

  test('rejects wildcard-only injection designed to dump all rows', async () => {
    await assert.rejects(() => searchUsers('%'), QueryValidationError);
    await assert.rejects(() => searchUsers('_'), QueryValidationError);
    await assert.rejects(() => searchUsers('%%%%'), QueryValidationError);
  });

});

