/**
 * Runs a parameterised query against the shared pool, logging its duration.
 *
 * @param {string}   label      - Short human-readable name shown in logs.
 * @param {string}   sql        - The SQL text with $1 … $n placeholders.
 * @param {any[]}    params     - Positional parameter values.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(label, sql, params) {
  const start = process.hrtime.bigint();

  console.log(`[query:${label}] Executing with ${params.length} parameter(s)`);

  try {
    const result = await pool.query(sql, params);

    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.log(
      `[query:${label}] OK — ${result.rowCount} row(s) returned in ${durationMs.toFixed(2)} ms`,
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.error(
      `[query:${label}] ERROR after ${durationMs.toFixed(2)} ms — ${err.message}`,
    );

    throw err; // re-throw; callers decide how to handle DB errors
  }
}

/**
 * Validates and coerces `value` to a safe integer within [min, max].
 *
 * @param {any}    value - Raw value from caller.
 * @param {string} field - Parameter name (used in error messages).
 * @param {number} min   - Inclusive lower bound.
 * @param {number} max   - Inclusive upper bound.
 * @returns {number}
 */
function toSafeInt(value, field, min, max) {
  const n = Number(value);

  if (!Number.isInteger(n)) {
    throw new QueryValidationError(field, `"${field}" must be an integer, got: ${value}`);
  }
  if (n < min || n > max) {
    throw new QueryValidationError(
      field,
      `"${field}" must be between ${min} and ${max}, got: ${n}`,
    );
  }

  return n;
}

/**
 * Validates a search query string: strips leading/trailing whitespace,
 * enforces length bounds, and rejects strings that consist entirely of
 * wildcard characters (which would match every row and defeat pagination).
 *
 * @param {any} value - Raw value from caller.
 * @returns {string}  - Trimmed, validated string.
 */
function toSafeSearchString(value) {
  if (typeof value !== 'string') {
    throw new QueryValidationError('query', '"query" must be a string');
  }

  const trimmed = value.trim();

  if (trimmed.length < MIN_SEARCH_LENGTH) {
    throw new QueryValidationError(
      'query',
      `"query" must be at least ${MIN_SEARCH_LENGTH} character(s) after trimming`,
    );
  }
  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new QueryValidationError(
      'query',
      `"query" must be at most ${MAX_SEARCH_LENGTH} characters`,
    );
  }
  if (/^[%_\s]+$/.test(trimmed)) {
    throw new QueryValidationError(
      'query',
      '"query" must contain at least one non-wildcard character',
    );
  }

  return trimmed;
}

