async function getUserById(id) {
  // Coerce & validate — rejects strings like "1; DROP TABLE users"
  const safeId = toSafeInt(id, 'id', 1, Number.MAX_SAFE_INTEGER);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);

  return result.rows[0] ?? null;
}

