/**
 * logger.js
 *
 * Centralised Winston logger shared across the application.
 * - Console transport:  human-readable coloured output in development,
 *                       plain JSON in production.
 * - All query timing and error events are logged through this module so
 *   there is one consistent format and one place to add file / cloud
 *   transports later.
 *
 * Usage
 *   const logger = require('./logger');
 *   logger.info('message', { meta: 'data' });
 *   logger.error('something broke', { err });
 */

'use strict';

const { createLogger, format, transports } = require('winston');

const { combine, timestamp, printf, colorize, errors } = format;

const isDevelopment = process.env.NODE_ENV !== 'production';

// ── Human-readable line format used in development ─────────────────────────
const devFormat = combine(
  colorize({ all: true }),
  timestamp({ format: 'HH:mm:ss.SSS' }),
  errors({ stack: true }),
  printf(({ timestamp, level, message, stack, ...meta }) => {
    const metaStr = Object.keys(meta).length ? ` ${JSON.stringify(meta)}` : '';
    return stack
      ? `${timestamp} [${level}] ${message}\n${stack}${metaStr}`
      : `${timestamp} [${level}] ${message}${metaStr}`;
  }),
);

// ── Structured JSON format used in production ───────────────────────────────
const prodFormat = combine(
  timestamp(),
  errors({ stack: true }),
  format.json(),
);

const logger = createLogger({
  level: process.env.LOG_LEVEL || (isDevelopment ? 'debug' : 'info'),
  format: isDevelopment ? devFormat : prodFormat,
  transports: [new transports.Console()],
  // Do not exit on handled exceptions – let the app decide.
  exitOnError: false,
});

module.exports = logger;

/**
 * db.js
 *
 * PostgreSQL connection pool singleton.
 *
 * Why a singleton pool?
 *  - node-postgres (pg) Pool manages a fixed set of long-lived TCP connections
 *    to the database.  Creating a new Pool per request would exhaust both file
 *    descriptors and DB server connection slots almost immediately under load.
 *  - Exporting a single shared instance means every module that calls
 *    require('./db') gets the same pool, so the limit configured here is a
 *    true global cap.
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials are ever hard-coded in source.  The expected variables are:
 *
 *   DATABASE_URL   – full connection string  (takes priority when present)
 *   PGHOST         – hostname / IP
 *   PGPORT         – port (default 5432)
 *   PGDATABASE     – database name
 *   PGUSER         – role name
 *   PGPASSWORD     – password
 *   DB_POOL_MAX    – maximum pool size       (default 10)
 *   DB_POOL_MIN    – minimum pool size       (default 2)
 *   DB_IDLE_MS     – idle timeout in ms      (default 30 000)
 *   DB_CONNECT_MS  – connection timeout in ms (default 5 000)
 *
 * The module also instruments the pool with event listeners so that every
 * connection-lifecycle event is written to the shared logger.
 */

'use strict';

require('dotenv').config();

const { Pool } = require('pg');
const logger   = require('./logger');

// ── Pool configuration ──────────────────────────────────────────────────────

const poolConfig = {
  // If DATABASE_URL is provided pg will parse host/port/user/password/database
  // from it automatically.  Individual PG* vars serve as the fallback.
  connectionString: process.env.DATABASE_URL || undefined,

  // Individual overrides (ignored when connectionString supplies the same info
  // via the pg driver's own precedence rules).
  host:     process.env.PGHOST     || 'localhost',
  port:     parseInt(process.env.PGPORT || '5432', 10),
  database: process.env.PGDATABASE || 'postgres',
  user:     process.env.PGUSER,
  password: process.env.PGPASSWORD,

  // Pool sizing
  max:             parseInt(process.env.DB_POOL_MAX   || '10',    10),
  min:             parseInt(process.env.DB_POOL_MIN   || '2',     10),
  idleTimeoutMillis:    parseInt(process.env.DB_IDLE_MS     || '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECT_MS || '5000',  10),

  // Always use SSL in production unless explicitly disabled.
  ssl: process.env.NODE_ENV === 'production' && process.env.DB_SSL !== 'false'
    ? { rejectUnauthorized: true }
    : false,
};

// ── Create the shared pool ──────────────────────────────────────────────────

const pool = new Pool(poolConfig);

// ── Pool event instrumentation ──────────────────────────────────────────────

pool.on('connect', (client) => {
  logger.debug('db.pool: new client connected', {
    totalCount: pool.totalCount,
    idleCount:  pool.idleCount,
    waitingCount: pool.waitingCount,
  });
});

pool.on('acquire', (client) => {
  logger.debug('db.pool: client acquired from pool', {
    totalCount:   pool.totalCount,
    idleCount:    pool.idleCount,
    waitingCount: pool.waitingCount,
  });
});

pool.on('remove', (client) => {
  logger.debug('db.pool: client removed from pool', {
    totalCount:   pool.totalCount,
    idleCount:    pool.idleCount,
    waitingCount: pool.waitingCount,
  });
});

pool.on('error', (err, client) => {
  // An idle client has encountered an error — log and continue.
  // The pool will automatically discard the broken client.
  logger.error('db.pool: idle client error', {
    message: err.message,
    code:    err.code,
  });
});

// ── Pool stats helper ───────────────────────────────────────────────────────

/**
 * Returns a plain object describing the current pool state.
 * Useful for the /health endpoint.
 *
 * @returns {{ totalCount: number, idleCount: number, waitingCount: number }}
 */
pool.stats = () => ({
  totalCount:   pool.totalCount,
  idleCount:    pool.idleCount,
  waitingCount: pool.waitingCount,
});

module.exports = pool;

/**
 * queries.js
 *
 * Parameterised query functions for the /users resource.
 *
 * ┌─────────────────────────────────────────────────────────────────────────┐
 * │  SQL-injection prevention strategy                                      │
 * │                                                                         │
 * │  Every value supplied by a caller is passed exclusively through the     │
 * │  `values` array of a parameterised query ($1, $2 … placeholders).       │
 * │  PostgreSQL's wire protocol sends parameters separately from the SQL    │
 * │  text; the server NEVER concatenates them.  This is the strongest       │
 * │  possible defence — even a value that contains single quotes, comment   │
 * │  sequences, or UNION clauses cannot alter the query's parse tree.       │
 * │                                                                         │
 * │  Additional hardening applied here:                                     │
 * │  • Numeric inputs (id, limit, offset) are coerced to integers and       │
 * │    validated before the query is sent — malformed values are rejected   │
 * │    with a typed error before any DB round-trip occurs.                  │
 * │  • The `searchUsers` query wraps the search term in ILIKE with a        │
 * │    parameterised placeholder; wildcard characters (%, _) that the       │
 * │    caller embeds are treated as literals because they are passed as a   │
 * │    bound value, not interpolated into SQL text.  We additionally        │
 * │    escape them so that they behave as literal text in the LIKE pattern  │
 * │    rather than acting as wildcards — preserving the principle of least  │
 * │    surprise.                                                             │
 * │  • Column/table names are NEVER derived from user input.                │
 * └─────────────────────────────────────────────────────────────────────────┘
 *
 * ┌─────────────────────────────────────────────────────────────────────────┐
 * │  Query timing                                                           │
 * │                                                                         │
 * │  Every public function measures wall-clock duration with                │
 * │  process.hrtime.bigint() (nanosecond resolution) and emits a           │
 * │  structured log entry that includes:                                    │
 * │    fn       – name of the query function                                │
 * │    durationMs – elapsed time in milliseconds (2 decimal places)        │
 * │    rowCount – number of rows returned / affected                        │
 * │    params   – sanitised parameter list (safe to log)                   │
 * └─────────────────────────────────────────────────────────────────────────┘
 *
 * Exported API
 *   getUserById(id)                    → Promise<User | null>
 *   getAllUsers(limit, offset)         → Promise<{ users: User[], total: number }>
 *   searchUsers(query, limit, offset) → Promise<{ users: User[], total: number }>
 */

'use strict';

const pool   = require('./db');
const logger = require('./logger');

// ── Constants ───────────────────────────────────────────────────────────────

/** Maximum rows that may be requested in a single page. */
const MAX_LIMIT = 100;

/** Default page size when the caller does not specify one. */
const DEFAULT_LIMIT = 20;

// ── Internal helpers ─────────────────────────────────────────────────────────

/**
 * Executes a parameterised query against the shared pool, measures its
 * duration, and emits a structured timing log entry.
 *
 * All queries flow through this function so timing and logging are consistent
 * across the module.
 *
 * @param {string}   fnName  - Name of the calling function (for log context).
 * @param {string}   text    - SQL statement with $n placeholders.
 * @param {unknown[]} values - Bound parameter values (never interpolated).
 * @returns {Promise<import('pg').QueryResult>}
 * @throws {QueryError} on database errors.
 */
async function runQuery(fnName, text, values) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query({ text, values });

    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    logger.info('db.query: success', {
      fn:         fnName,
      durationMs: parseFloat(durationMs.toFixed(2)),
      rowCount:   result.rowCount,
      // Log the values so timing logs are useful for debugging, but never
      // log raw passwords or secrets — only the values this module controls.
      params:     values,
    });

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    logger.error('db.query: error', {
      fn:         fnName,
      durationMs: parseFloat(durationMs.toFixed(2)),
      message:    err.message,
      code:       err.code,        // PostgreSQL error code, e.g. '42P01'
      params:     values,
    });

    // Re-throw a sanitised error so route handlers do not leak raw pg messages
    // (which can contain table/column names) to HTTP clients.
    const queryErr    = new Error(`Database error in ${fnName}`);
    queryErr.code     = err.code;
    queryErr.original = err;
    throw queryErr;
  }
}

/**
 * Coerces `value` to a safe integer and validates it against an inclusive
 * range.  Throws a ValidationError if the value cannot be used.
 *
 * @param {unknown} value
 * @param {string}  name   - Field name used in the error message.
 * @param {number}  min
 * @param {number}  max
 * @returns {number}
 */
function toSafeInt(value, name, min, max) {
  const n = Number(value);

  if (!Number.isInteger(n)) {
    const err = new Error(`${name} must be an integer, got: ${value}`);
    err.type  = 'ValidationError';
    throw err;
  }
  if (n < min || n > max) {
    const err = new Error(`${name} must be between ${min} and ${max}, got: ${n}`);
    err.type  = 'ValidationError';
    throw err;
  }

  return n;
}

/**
 * Escapes LIKE metacharacters (%, _) and the escape character itself (\) in
 * a search term so they are treated as literals within an ILIKE pattern.
 *
 * The function returns a string suitable for use inside a LIKE value bound
 * through a parameterised placeholder — the escaping is purely semantic
 * (LIKE syntax), not SQL injection protection (which is already handled by
 * the parameterised query mechanism).
 *
 * @param {string} raw
 * @returns {string}
 */
function escapeLikeWildcards(raw) {
  // Escape backslash first so subsequent replacements are not double-escaped.
  return raw
    .replace(/\\/g, '\\\\')
    .replace(/%/g,  '\\%')
    .replace(/_/g,  '\\_');
}

/**
 * Validates that a raw search term is a non-empty string within a reasonable
 * length limit, then returns the escaped version ready for ILIKE.
 *
 * @param {unknown} raw
 * @returns {string}
 */
function toSafeSearchTerm(raw) {
  if (typeof raw !== 'string' || raw.trim() === '') {
    const err = new Error('search query must be a non-empty string');
    err.type  = 'ValidationError';
    throw err;
  }
  if (raw.length > 200) {
    const err = new Error('search query must not exceed 200 characters');
    err.type  = 'ValidationError';
    throw err;
  }

  return escapeLikeWildcards(raw.trim());
}

// ── Public query functions ───────────────────────────────────────────────────

/**
 * Fetches a single user by their primary-key ID.
 *
 * The `id` value is validated as a positive integer before the query is sent.
 * It is always passed as a bound parameter ($1), never interpolated into the
 * SQL string.
 *
 * @param {number|string} id - The user's numeric ID.
 * @returns {Promise<Object|null>} The user row, or null if not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'Not found' });
 */
async function getUserById(id) {
  const safeId = toSafeInt(id, 'id', 1, Number.MAX_SAFE_INTEGER);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await runQuery('getUserById', sql, [safeId]);

  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users along with the total count (useful
 * for building pagination UIs without a second query).
 *
 * Both `limit` and `offset` are validated integers, and `limit` is capped at
 * MAX_LIMIT to prevent runaway queries.  They are passed as bound parameters
 * ($1 and $2) — never interpolated.
 *
 * A single query using a window function is used so that count and rows are
 * fetched in one round-trip.
 *
 * @param {number} [limit=20]  - Rows per page.  Capped at MAX_LIMIT (100).
 * @param {number} [offset=0] - Zero-based row offset.
 * @returns {Promise<{ users: Object[], total: number }>}
 *
 * @example
 *   const { users, total } = await getAllUsers(10, 0);
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = 0) {
  const safeLimit  = toSafeInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = toSafeInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // COUNT(*) OVER () is evaluated once per result set by the planner and
  // avoids a second round-trip.  It is equivalent to a subquery count but
  // cleaner and typically no slower on indexed tables.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const result = await runQuery('getAllUsers', sql, [safeLimit, safeOffset]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  // Strip the internal total_count column from the returned user objects.
  const users = result.rows.map(({ total_count, ...user }) => user);

  return { users, total };
}

/**
 * Full-text–style search across user name and email using a case-insensitive
 * LIKE pattern.
 *
 * Defence in depth:
 *  1. The search term length is validated before the query is built.
 *  2. LIKE metacharacters (%, _) are escaped so the term cannot be crafted to
 *     perform a full-table wildcard scan via a trivially broad pattern.
 *  3. The escaped term is still passed as a bound parameter ($1) — it is
 *     never concatenated into the SQL string.
 *
 * @param {string} query           - The search string (max 200 characters).
 * @param {number} [limit=20]      - Rows per page.  Capped at MAX_LIMIT.
 * @param {number} [offset=0]      - Zero-based row offset.
 * @returns {Promise<{ users: Object[], total: number }>}
 *
 * @example
 *   const { users, total } = await searchUsers('alice', 10, 0);
 */
async function searchUsers(query, limit = DEFAULT_LIMIT, offset = 0) {
  const safeTerm   = toSafeSearchTerm(query);
  const safeLimit  = toSafeInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = toSafeInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // The pattern is assembled in JS and sent as a single bound value.
  // PostgreSQL receives e.g.  '%alice%'  as opaque text data — the LIKE
  // operator is already in the SQL text, so there is no injection risk.
  const pattern = `%${safeTerm}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const result = await runQuery('searchUsers', sql, [pattern, safeLimit, safeOffset]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  const users = result.rows.map(({ total_count, ...user }) => user);

  return { users, total };
}

// ── Module exports ───────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Expose constants so tests and route handlers can reference them without
  // magic numbers.
  MAX_LIMIT,
  DEFAULT_LIMIT,
};

/**
 * app.js
 *
 * Express application.
 *
 * Changes from the original:
 *  - /health now reports database pool stats so operators can see connection
 *    pressure at a glance without additional tooling.
 *  - /users now supports three modes driven by query parameters:
 *      GET /users              → paginated list   (getAllUsers)
 *      GET /users?search=…     → filtered list    (searchUsers)
 *      GET /users/:id          → single user      (getUserById)
 *    All database access is through queries.js parameterised functions;
 *    no SQL is constructed in this file.
 *  - Structured error responses distinguish validation errors (400) from
 *    not-found (404) and unexpected server errors (500).  Raw error messages
 *    from the database are never forwarded to the HTTP client.
 */

'use strict';

require('dotenv').config();

const express = require('express');
const logger  = require('./logger');
const pool    = require('./db');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  MAX_LIMIT,
  DEFAULT_LIMIT,
} = require('./queries');

const app = express();
app.use(express.json());

// ── Request logging middleware ───────────────────────────────────────────────

app.use((req, _res, next) => {
  logger.debug('http: incoming request', {
    method: req.method,
    path:   req.path,
    query:  req.query,
    ip:     req.ip,
  });
  next();
});

// ── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 *
 * Liveness + pool stats.  Returns 200 when the process is healthy.
 * The db sub-object lets load balancers and dashboards see pool pressure
 * without requiring direct DB access.
 */
app.get('/health', (_req, res) => {
  res.json({
    status:    'ok',
    timestamp: new Date().toISOString(),
    db:        pool.stats(),
  });
});

/**
 * GET /users
 *
 * Returns a paginated list of all users.
 *
 * Query parameters
 *   limit   {integer}  Rows per page.  1 – MAX_LIMIT.  Default: DEFAULT_LIMIT.
 *   offset  {integer}  Zero-based row offset.           Default: 0.
 *   search  {string}   When present, filters by name / email (ILIKE).
 *
 * Response 200
 *   {
 *     "data":   [ { id, name, email, created_at, updated_at }, … ],
 *     "total":  <integer>,   // unfiltered / filtered count
 *     "limit":  <integer>,
 *     "offset": <integer>
 *   }
 *
 * Response 400  – invalid limit / offset / search parameters
 * Response 500  – unexpected database error
 */
app.get('/users', async (req, res) => {
  const rawLimit  = req.query.limit  ?? DEFAULT_LIMIT;
  const rawOffset = req.query.offset ?? 0;
  const rawSearch = req.query.search;

  try {
    const limit  = parseInt(rawLimit,  10);
    const offset = parseInt(rawOffset, 10);

    let users, total;

    if (rawSearch !== undefined) {
      // search mode — delegates to searchUsers()
      ({ users, total } = await searchUsers(rawSearch, limit, offset));
    } else {
      // list mode — delegates to getAllUsers()
      ({ users, total } = await getAllUsers(limit, offset));
    }

    return res.json({ data: users, total, limit, offset });

  } catch (err) {
    if (err.type === 'ValidationError') {
      return res.status(400).json({
        error: 'Invalid query parameters',
        detail: err.message,
      });
    }
    // Unexpected DB error — already logged inside runQuery(); send a generic
    // message so internal details are not leaked to the client.
    logger.error('route /users: unhandled error', { message: err.message });
    return res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * GET /users/:id
 *
 * Returns a single user by numeric ID.
 *
 * Response 200  – user object
 * Response 400  – id is not a valid positive integer
 * Response 404  – no user with that id
 * Response 500  – unexpected database error
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({
        error:  'Not found',
        detail: `No user with id ${req.params.id}`,
      });
    }

    return res.json({ data: user });

  } catch (err) {
    if (err.type === 'ValidationError') {
      return res.status(400).json({
        error:  'Invalid user id',
        detail: err.message,
      });
    }
    logger.error('route /users/:id: unhandled error', { message: err.message });
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// ── 404 catch-all ────────────────────────────────────────────────────────────

app.use((_req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// ── Start server (only when run directly, not during tests) ──────────────────

if (require.main === module) {
  const PORT = parseInt(process.env.PORT || '3000', 10);
  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js
 *
 * Unit tests for every public function in queries.js.
 *
 * Strategy
 * ────────
 * The pg pool is mocked at the module level so no real database is required.
 * Each test configures pool.query to return a controlled result or throw a
 * controlled error, then asserts on:
 *   • the SQL text sent to the driver                (correct query shape)
 *   • the values array sent to the driver            (parameterisation)
 *   • the value returned to the caller               (correct mapping)
 *   • that ValidationErrors are thrown pre-query     (input validation)
 *   • that DB errors are wrapped and re-thrown       (error sanitisation)
 */

'use strict';

// ── Mock pg pool before requiring queries.js ─────────────────────────────────

// We replace the entire db.js module so pool.query is a Jest spy.
jest.mock('./db', () => {
  const mockQuery = jest.fn();
  return {
    query:  mockQuery,
    stats:  jest.fn(() => ({ totalCount: 1, idleCount: 1, waitingCount: 0 })),
    on:     jest.fn(),  // pool event listeners called in db.js constructor chain
  };
});

// Silence logger output during tests so jest output stays clean.
jest.mock('./logger', () => ({
  debug: jest.fn(),
  info:  jest.fn(),
  error: jest.fn(),
}));

const pool = require('./db');

const {
  getUserById,
  getAllUsers,
  searchUsers,
  MAX_LIMIT,
  DEFAULT_LIMIT,
} = require('./queries');

// ── Helpers ──────────────────────────────────────────────────────────────────

/** Builds the mock return value that pool.query resolves with. */
function makeResult(rows) {
  return { rows, rowCount: rows.length };
}

/** A single stub user row as the DB would return it. */
const stubUser = {
  id:         1,
  name:       'Alice',
  email:      'alice@example.com',
  created_at: new Date('2024-01-01'),
  updated_at: new Date('2024-01-01'),
};

// Reset mock state between tests.
beforeEach(() => {
  jest.clearAllMocks();
});

// ════════════════════════════════════════════════════════════════════════════
// getUserById
// ════════════════════════════════════════════════════════════════════════════

describe('getUserById', () => {

  // ── Happy path ─────────────────────────────────────────────────────────────

  test('returns the matching user when found', async () => {
    pool.query.mockResolvedValueOnce(makeResult([stubUser]));

    const user = await getUserById(1);

    expect(user).toEqual(stubUser);
  });

  test('returns null when no row is returned', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    const user = await getUserById(99999);

    expect(user).toBeNull();
  });

  // ── Parameterisation ───────────────────────────────────────────────────────

  test('passes id as a bound parameter, not interpolated in SQL', async () => {
    pool.query.mockResolvedValueOnce(makeResult([stubUser]));

    await getUserById(42);

    const [{ text, values }] = pool.query.mock.calls[0];
    // The id must appear in the values array.
    expect(values).toEqual([42]);
    // The SQL text must use a placeholder, not the literal value.
    expect(text).toContain('$1');
    expect(text).not.toContain('42');
  });

  test('coerces a string id to an integer', async () => {
    pool.query.mockResolvedValueOnce(makeResult([stubUser]));

    await getUserById('7');

    const [{ values }] = pool.query.mock.calls[0];
    expect(values[0]).toBe(7);
  });

  // ── Input validation ───────────────────────────────────────────────────────

  test('throws ValidationError for id = 0', async () => {
    await expect(getUserById(0)).rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws ValidationError for negative id', async () => {
    await expect(getUserById(-1)).rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws ValidationError for a non-numeric string', async () => {
    await expect(getUserById('abc')).rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws ValidationError for a float', async () => {
    await expect(getUserById(1.5)).rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  // ── SQL injection surface area ─────────────────────────────────────────────

  test('rejects SQL-looking id strings before querying', async () => {
    // If this reaches the DB driver the test would fail anyway (non-integer),
    // but we assert no query is sent at all.
    await expect(getUserById("1 OR 1=1")).rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  // ── Error propagation ──────────────────────────────────────────────────────

  test('wraps DB errors and does not leak raw pg messages', async () => {
    pool.query.mockRejectedValueOnce(
      Object.assign(new Error('relation "users" does not exist'), { code: '42P01' }),
    );

    await expect(getUserById(1)).rejects.toMatchObject({
      message: 'Database error in getUserById',
      code:    '42P01',
    });
  });

});

// ════════════════════════════════════════════════════════════════════════════
// getAllUsers
