describe('getAllUsers', () => {

  const stubRows = [
    { ...stubUser, id: 1, total_count: '2' },
    { ...stubUser, id: 2, name: 'Bob', email: 'bob@example.com', total_count: '2' },
  ];

  // ── Happy path ─────────────────────────────────────────────────────────────

  test('returns users array and total', async () => {
    pool.query.mockResolvedValueOnce(makeResult(stubRows));

    const { users, total } = await getAllUsers(10, 0);

    expect(users).toHaveLength(2);
    expect(total).toBe(2);
  });

  test('strips total_count from returned user objects', async () => {
    pool.query.mockResolvedValueOnce(makeResult(stubRows));

    const { users } = await getAllUsers(10, 0);

    users.forEach(u => expect(u).not.toHaveProperty('total_count'));
  });

  test('returns { users: [], total: 0 } when table is empty', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    const { users, total } = await getAllUsers();

    expect(users).toEqual([]);
    expect(total).toBe(0);
  });

  // ── Parameterisation ───────────────────────────────────────────────────────

  test('passes limit and offset as bound parameters', async () => {
    pool.query.mockResolvedValueOnce(makeResult(stubRows));

    await getAllUsers(5, 10);

    const [{ text, values }] = pool.query.mock.calls[0];
    expect(values).toEqual([5, 10]);
    expect(text).toContain('$1');
    expect(text).toContain('$2');
    // Literal numbers must not appear inside the SQL.
    expect(text).not.toMatch(/LIMIT\s+5/);
    expect(text).not.toMatch(/OFFSET\s+10/);
  });

  test('uses DEFAULT_LIMIT when no arguments supplied', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    await getAllUsers();

    const [{ values }] = pool.query.mock.calls[0];
    expect(values[0]).toBe(DEFAULT_LIMIT);
    expect(values[1]).toBe(0);
  });

  // ── Input validation ───────────────────────────────────────────────────────

  test('throws ValidationError when limit exceeds MAX_LIMIT', async () => {
    await expect(getAllUsers(MAX_LIMIT + 1, 0))
      .rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws ValidationError for limit = 0', async () => {
    await expect(getAllUsers(0, 0))
      .rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws ValidationError for negative offset', async () => {
    await expect(getAllUsers(10, -1))
      .rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws ValidationError for float limit', async () => {
    await expect(getAllUsers(2.5, 0))
      .rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws ValidationError for non-numeric limit', async () => {
    await expect(getAllUsers('many', 0))
      .rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  // ── Error propagation ──────────────────────────────────────────────────────

  test('wraps DB errors with sanitised message', async () => {
    pool.query.mockRejectedValueOnce(
      Object.assign(new Error('connection timeout'), { code: 'ETIMEDOUT' }),
    );

    await expect(getAllUsers(10, 0)).rejects.toMatchObject({
      message: 'Database error in getAllUsers',
    });
  });

});

