describe('searchUsers', () => {

  const stubSearchRows = [
    { ...stubUser, total_count: '1' },
  ];

  // ── Happy path ─────────────────────────────────────────────────────────────

  test('returns matching users and total', async () => {
    pool.query.mockResolvedValueOnce(makeResult(stubSearchRows));

    const { users, total } = await searchUsers('alice');

    expect(users).toHaveLength(1);
    expect(total).toBe(1);
  });

  test('strips total_count from returned user objects', async () => {
    pool.query.mockResolvedValueOnce(makeResult(stubSearchRows));

    const { users } = await searchUsers('alice');

    users.forEach(u => expect(u).not.toHaveProperty('total_count'));
  });

  test('returns empty result when no matches', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    const { users, total } = await searchUsers('zzznomatch');

    expect(users).toEqual([]);
    expect(total).toBe(0);
  });

  // ── Parameterisation ───────────────────────────────────────────────────────

  test('wraps search term in % wildcards passed as a bound value', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    await searchUsers('alice', 10, 0);

    const [{ text, values }] = pool.query.mock.calls[0];

    // Pattern must be the first bound value.
    expect(values[0]).toBe('%alice%');
    // SQL text must use ILIKE with a placeholder.
    expect(text).toMatch(/ILIKE\s+\$1/i);
    // The literal term must NOT appear naked in the SQL.
    expect(text).not.toContain("'alice'");
  });

  test('passes limit and offset as separate bound parameters', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    await searchUsers('bob', 5, 20);

    const [{ values }] = pool.query.mock.calls[0];
    expect(values).toEqual(['%bob%', 5, 20]);
  });

  // ── LIKE metacharacter escaping ────────────────────────────────────────────

  test('escapes % in search term so it is not a wildcard', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    await searchUsers('100%', 10, 0);

    const [{ values }] = pool.query.mock.calls[0];
    // The raw % from the search term must be escaped as \% inside the pattern.
    expect(values[0]).toBe('%100\\%%');
  });

  test('escapes _ in search term so it is not a single-char wildcard', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    await searchUsers('user_name', 10, 0);

    const [{ values }] = pool.query.mock.calls[0];
    expect(values[0]).toBe('%user\\_name%');
  });

  test('escapes backslash in search term', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    await searchUsers('a\\b', 10, 0);

    const [{ values }] = pool.query.mock.calls[0];
    expect(values[0]).toBe('%a\\\\b%');
  });

  // ── Input validation ───────────────────────────────────────────────────────

  test('throws ValidationError for empty search string', async () => {
    await expect(searchUsers('')).rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws ValidationError for whitespace-only search string', async () => {
    await expect(searchUsers('   ')).rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws ValidationError for non-string query (number)', async () => {
    await expect(searchUsers(123)).rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('throws ValidationError for search term exceeding 200 characters', async () => {
    const longTerm = 'a'.repeat(201);
    await expect(searchUsers(longTerm)).rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  test('accepts a search term of exactly 200 characters', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    const term = 'a'.repeat(200);
    // Should not throw.
    await expect(searchUsers(term)).resolves.toBeDefined();
  });

  test('throws ValidationError when limit exceeds MAX_LIMIT', async () => {
    await expect(searchUsers('alice', MAX_LIMIT + 1))
      .rejects.toMatchObject({ type: 'ValidationError' });
    expect(pool.query).not.toHaveBeenCalled();
  });

  // ── SQL injection surface area ─────────────────────────────────────────────

  test('passes SQL-like strings as bound data, not SQL', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    const injection = "' OR '1'='1";
    await searchUsers(injection, 10, 0);

    const [{ values }] = pool.query.mock.calls[0];
    // The injection string must be in the values array (bound data).
    expect(values[0]).toContain(injection.trim());
    // The SQL text must not contain the injection fragment.
    expect(pool.query.mock.calls[0][0].text).not.toContain("OR '1'='1");
  });

  test('handles UNION-based injection attempt as literal data', async () => {
    pool.query.mockResolvedValueOnce(makeResult([]));

    await searchUsers("x' UNION SELECT * FROM secrets --", 10, 0);

    const [{ text }] = pool.query.mock.calls[0];
    expect(text).not.toContain('UNION');
    expect(text).not.toContain('secrets');
  });

  // ── Error propagation ──────────────────────────────────────────────────────

  test('wraps DB errors with sanitised message', async () => {
    pool.query.mockRejectedValueOnce(
      Object.assign(new Error('column "emailz" does not exist'), { code: '42703' }),
    );

    await expect(searchUsers('alice')).rejects.toMatchObject({
      message: 'Database error in searchUsers',
      code:    '42703',
    });
  });

});

