/**
 * run_tests.js  –  minimal self-contained test runner (no npm dependencies)
 *
 * Mocks  ./db  and  ./logger  in-process before loading queries.js so every
 * assertion exercises real module logic without a live database.
 *
 * Usage:  node run_tests.js
 */

'use strict';

// ── Minimal mock registry ────────────────────────────────────────────────────
// We patch Module._resolveFilename + Module._cache to intercept specific
// require() calls and return our mocks.

const Module = require('module');

const _origResolve = Module._resolveFilename.bind(Module);

// Fake pool object – tests configure mockQuery as needed.
const mockQuery  = { calls: [], impl: null };
const fakePool   = {
  query:  (...args) => {
    mockQuery.calls.push(args);
    if (mockQuery.impl) return mockQuery.impl(...args);
    return Promise.reject(new Error('mockQuery not configured'));
  },
  stats:  () => ({ totalCount: 1, idleCount: 1, waitingCount: 0 }),
  on:     () => {},
};

const fakeLogger = {
  debug: () => {},
  info:  () => {},
  error: () => {},
};

// Map absolute-like paths back to mock objects.
const MOCKS = {
  './db':     fakePool,
  './logger': fakeLogger,
};

// Intercept require() for our two mocked modules.
Module._resolveFilename = function (request, parent, isMain, options) {
  if (MOCKS[request]) return request;          // return the key as a fake path
  return _origResolve(request, parent, isMain, options);
};

const _origLoad = Module._load.bind(Module);
Module._load = function (request, parent, isMain) {
  if (MOCKS[request]) return MOCKS[request];
  return _origLoad(request, parent, isMain);
};

// ── Now safe to import queries.js ────────────────────────────────────────────

