// ── Tiny test harness ────────────────────────────────────────────────────────

let passed  = 0;
let failed  = 0;
const errors = [];

async function test(name, fn) {
  mockQuery.calls  = [];
  mockQuery.impl   = null;
  try {
    await fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (e) {
    console.log(`  ✗  ${name}`);
    console.log(`       ${e.message}`);
    errors.push({ name, error: e });
    failed++;
  }
}

function expect(actual) {
  return {
    toBe(expected) {
      if (actual !== expected)
        throw new Error(`Expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
    },
    toEqual(expected) {
      const a = JSON.stringify(actual), b = JSON.stringify(expected);
      if (a !== b) throw new Error(`Expected ${b}, got ${a}`);
    },
    toBeNull() {
      if (actual !== null) throw new Error(`Expected null, got ${JSON.stringify(actual)}`);
    },
    toBeDefined() {
      if (actual === undefined) throw new Error('Expected value to be defined');
    },
    toHaveLength(n) {
      if (!actual || actual.length !== n)
        throw new Error(`Expected length ${n}, got ${actual?.length}`);
    },
    toContain(str) {
      if (!actual || !actual.includes(str))
        throw new Error(`Expected "${actual}" to contain "${str}"`);
    },
    not: {
      toHaveProperty(key) {
        if (actual && Object.prototype.hasOwnProperty.call(actual, key))
          throw new Error(`Expected object not to have property "${key}"`);
      },
      toContain(str) {
        if (actual && actual.includes(str))
          throw new Error(`Expected "${actual}" NOT to contain "${str}"`);
      },
      toMatch(re) {
        if (re.test(actual))
          throw new Error(`Expected string NOT to match ${re}`);
      },
    },
    toBeGreaterThan(n) {
      if (!(actual > n)) throw new Error(`Expected ${actual} > ${n}`);
    },
    toBeLessThanOrEqual(n) {
      if (!(actual <= n)) throw new Error(`Expected ${actual} <= ${n}`);
    },
    toMatch(re) {
      if (!re.test(actual)) throw new Error(`Expected "${actual}" to match ${re}`);
    },
    toMatchObject(subset) {
      for (const [k, v] of Object.entries(subset)) {
        if (actual[k] !== v)
          throw new Error(`Expected .${k} = ${JSON.stringify(v)}, got ${JSON.stringify(actual[k])}`);
      }
    },
  };
}

async function expectRejects(promise, subset) {
  try {
    await promise;
    throw new Error('Promise should have rejected but resolved');
  } catch (err) {
    if (err.message === 'Promise should have rejected but resolved') throw err;
    for (const [k, v] of Object.entries(subset)) {
      if (err[k] !== v)
        throw new Error(`Expected error.${k} = ${JSON.stringify(v)}, got ${JSON.stringify(err[k])}`);
    }
  }
}

