//  literal path segment "search" is not misinterpreted as an :id value.

app.get('/users/search', async (req, res) => {
  const { q, limit, offset } = req.query;

  if (!q) {
    return res.status(400).json({
      error: 'Missing required query parameter: q',
    });
  }

  try {
    const data = await searchUsers(q, limit, offset);

    return res.json({
      data: data.rows,
      meta: {
        total:  data.total,
        limit:  data.limit,
        offset: data.offset,
        query:  data.query, // echo the cleaned search term
      },
    });
  } catch (err) {
    return handleError(err, res);
  }
