  });

  test('emits an error log and re-throws on DB failure', async () => {
    const dbError = Object.assign(new Error('connection refused'), { code: '08006' });
    mockQuery.mockRejectedValueOnce(dbError);

    await expect(getUserById(1)).rejects.toThrow('connection refused');

    const logArg = JSON.parse(console.error.mock.calls[0][0]);
    expect(logArg.event).toBe('query_error');
    expect(logArg.errCode).toBe('08006');
  });

  // ── Validation ──────────────────────────────────────────────────────

  test.each([
    ['zero',            0],
    ['negative',       -5],
    ['float',         3.7],
    ['string',      'abc'],
    ['SQL fragment', "1 OR 1=1"],
    ['UNION payload', "1 UNION SELECT * FROM users--"],
    ['undefined',  undefined],
    ['null',           null],
  ])('throws ValidationError for id = %s', async (_label, bad) => {
    await expect(getUserById(bad)).rejects.toMatchObject({
      name:   'ValidationError',
      status: 400,
    });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('coerces a valid numeric string to an integer', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [SAMPLE_USERS[2]], rowCount: 1 });

    const user = await getUserById('3');

    expect(user).toEqual(SAMPLE_USERS[2]);
    expect(mockQuery.mock.calls[0][1]).toEqual([3]);
  });
});

// ─────────────────────────────────────────────────────────────────────
// getAllUsers
// ─────────────────────────────────────────────────────────────────────

describe('getAllUsers', () => {
  test('returns rows stripped of total_count plus pagination meta', async () => {
    mockQuery.mockResolvedValueOnce(makeResult(SAMPLE_USERS, 3));

    const result = await getAllUsers(20, 0);

    expect(result.rows).toHaveLength(3);
    expect(result.rows[0]).not.toHaveProperty('total_count');
    expect(result).toMatchObject({ total: 3, limit: 20, offset: 0 });
  });

  test('applies default limit and offset when not supplied', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    await getAllUsers();

    const [, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([DEFAULT_LIMIT, 0]);
  });

  test('clamps limit to MAX_LIMIT', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    const result = await getAllUsers(9999, 0);

    expect(result.limit).toBe(MAX_LIMIT);
    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe(MAX_LIMIT);
  });

  test('uses $1 and $2 placeholders in SQL', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    await getAllUsers(10, 5);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(sql).toMatch(/LIMIT\s+\$1/i);
    expect(sql).toMatch(/OFFSET\s+\$2/i);
    expect(params).toEqual([10, 5]);
  });

  test('returns total 0 and empty rows when result set is empty', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [], rowCount: 0 });

    const result = await getAllUsers();

    expect(result.rows).toEqual([]);
    expect(result.total).toBe(0);
  });

  test('resets negative offset to 0', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    const result = await getAllUsers(10, -50);

    expect(result.offset).toBe(0);
  });

  test('emits a timing log', async () => {
    mockQuery.mockResolvedValueOnce(makeResult(SAMPLE_USERS.slice(0, 1), 1));

    await getAllUsers(10, 0);

    const logArg = JSON.parse(console.log.mock.calls[0][0]);
    expect(logArg.label).toBe('getAllUsers');
  });
});

// ─────────────────────────────────────────────────────────────────────
// searchUsers
// ─────────────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  test('returns matching rows and meta including the cleaned query term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([SAMPLE_USERS[0]], 1));

    const result = await searchUsers('alice', 10, 0);

    expect(result.rows).toHaveLength(1);
    expect(result.query).toBe('alice');
    expect(result).toMatchObject({ total: 1, limit: 10, offset: 0 });
  });

  test('trims whitespace from the search term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    const result = await searchUsers('  bob  ', 10, 0);

    expect(result.query).toBe('bob');
  });

  test('passes the search pattern as $1 (parameterised, not inline)', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    await searchUsers('alice', 10, 0);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(sql).toMatch(/ILIKE \$1/i);
    // The LIKE pattern must be a value in params, not in the SQL string.
    expect(params[0]).toBe('%alice%');
    expect(sql).not.toContain('alice');
  });

  // ── SQL injection via search query ──────────────────────────────────

  test("escapes '%' so it matches literally, not as a wildcard", async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    await searchUsers('100%', 10, 0);

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%100\\%%');  // escaped inside the pattern
  });

  test("escapes '_' so it matches literally, not as a single-char wildcard", async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    await searchUsers('user_name', 10, 0);

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%user\\_name%');
  });

  test("escapes backslash so it does not break the ESCAPE clause", async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    await searchUsers('C:\\Users', 10, 0);

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toContain('\\\\');
  });

  test.each([
    ["UNION SELECT payload",  "' UNION SELECT * FROM users--"],
    ["DROP TABLE attempt",    "'; DROP TABLE users;--"],
    ["comment injection",     "admin'--"],
    ["stacked query",         "1'; SELECT pg_sleep(5);--"],
    ["OR tautology",          "' OR '1'='1"],
  ])('does not execute injected SQL: %s', async (_label, payload) => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    await searchUsers(payload, 10, 0);

    const [sql, params] = mockQuery.mock.calls[0];

    // The raw payload must never appear in the SQL string itself.
    expect(sql).not.toContain(payload);

    // The driver receives the payload as a parameterised value.
    // Crucially it is wrapped in % delimiters and any metacharacters are
    // escaped — neither the SQL keyword nor the quote characters are
    // interpreted as SQL by the database.
    expect(typeof params[0]).toBe('string');
  });

  // ── Validation ──────────────────────────────────────────────────────

  test('throws ValidationError for empty string', async () => {
    await expect(searchUsers('', 10, 0)).rejects.toMatchObject({
      name: 'ValidationError', status: 400,
    });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws ValidationError for whitespace-only string', async () => {
    await expect(searchUsers('   ', 10, 0)).rejects.toMatchObject({
      name: 'ValidationError', status: 400,
    });
  });

  test('throws ValidationError when query exceeds 200 chars', async () => {
    await expect(searchUsers('a'.repeat(201), 10, 0)).rejects.toMatchObject({
      name: 'ValidationError', status: 400,
    });
  });

  test('throws ValidationError for non-string query', async () => {
    await expect(searchUsers(42, 10, 0)).rejects.toMatchObject({
      name: 'ValidationError', status: 400,
    });
  });

  test('emits a timing log', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([], 0));

    await searchUsers('test', 5, 0);

    const logArg = JSON.parse(console.log.mock.calls[0][0]);
    expect(logArg.label).toBe('searchUsers');
    expect(typeof logArg.durationMs).toBe('number');
  });

  test('propagates DB errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('timeout'));

    await expect(searchUsers('alice', 10, 0)).rejects.toThrow('timeout');
  });
});

// ─────────────────────────────────────────────────────────────────────
// Standalone validator unit tests
// ─────────────────────────────────────────────────────────────────────

describe('_validateId', () => {
  test.each([1, 2, 100, 999999])('accepts positive integer %i', (n) => {
    expect(_validateId(n)).toBe(n);
  });

  test.each([0, -1, 1.5, NaN, '', null, undefined, [], {}])(
    'throws for invalid value %p', (v) => {
      expect(() => _validateId(v)).toThrow();
    }
  );
});

describe('_validatePagination', () => {
  test('returns defaults when both args are undefined', () => {
    expect(_validatePagination(undefined, undefined)).toEqual({
      limit: DEFAULT_LIMIT, offset: 0,
    });
  });

  test('clamps limit above MAX_LIMIT', () => {
    expect(_validatePagination(500, 0).limit).toBe(MAX_LIMIT);
  });

  test('floors floating-point values', () => {
    const { limit, offset } = _validatePagination(9.9, 4.7);
    expect(limit).toBe(9);
    expect(offset).toBe(4);
  });

  test('resets negative offset to 0', () => {
    expect(_validatePagination(10, -1).offset).toBe(0);
  });
});

describe('_validateSearchQuery', () => {
  test('returns trimmed string for valid input', () => {
    expect(_validateSearchQuery('  hello  ')).toBe('hello');
  });

  test('throws for empty string', () => {
    expect(() => _validateSearchQuery('')).toThrow();
  });

  test('throws for non-string', () => {
    expect(() => _validateSearchQuery(123)).toThrow();
  });

  test('throws when length exceeds custom maxLen', () => {
    expect(() => _validateSearchQuery('abcde', 4)).toThrow();
  });
});

