/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single shared `pg` Pool instance so every module in the
 * application reuses the same set of connections rather than opening a
 * new connection on every request.
 *
 * Configuration is read exclusively from environment variables so that
 * credentials never appear in source code.  Copy .env.example to .env
 * and fill in your real values before starting the server.
 *
 * Required env vars:
 *   DB_HOST      – hostname of the PostgreSQL server  (default: localhost)
 *   DB_PORT      – port                               (default: 5432)
 *   DB_NAME      – database name
 *   DB_USER      – login role
 *   DB_PASSWORD  – password for that role
 *   DB_POOL_MAX  – maximum pool size                  (default: 10)
 *   DB_IDLE_MS   – ms before an idle connection is closed (default: 30000)
 *   DB_CONN_MS   – ms before a connection attempt times out (default: 5000)
 *   NODE_ENV     – when set to "test" the pool is NOT created (jest safety)
 */

'use strict';

const { Pool } = require('pg');

// ── Validate required variables at startup so the process fails fast
// instead of producing cryptic runtime errors later. ──────────────────
const REQUIRED_VARS = ['DB_NAME', 'DB_USER', 'DB_PASSWORD'];

if (process.env.NODE_ENV !== 'test') {
  const missing = REQUIRED_VARS.filter((v) => !process.env[v]);
  if (missing.length) {
    throw new Error(
      `[db] Missing required environment variable(s): ${missing.join(', ')}. ` +
        'Copy .env.example to .env and set every value before starting.'
    );
  }
}

// ── Pool configuration ────────────────────────────────────────────────
const poolConfig = {
  host:            process.env.DB_HOST     || 'localhost',
  port:            Number(process.env.DB_PORT) || 5432,
  database:        process.env.DB_NAME,
  user:            process.env.DB_USER,
  password:        process.env.DB_PASSWORD,

  // Maximum number of clients in the pool.  Tune to (db max_connections
  // minus connections reserved for other services) divided by the number
  // of application replicas.
  max:             Number(process.env.DB_POOL_MAX)  || 10,

  // How long (ms) a client may sit idle before it is destroyed.
  idleTimeoutMillis:    Number(process.env.DB_IDLE_MS)  || 30_000,

  // How long (ms) to wait when acquiring a new client from the pool
  // before throwing an error.
  connectionTimeoutMillis: Number(process.env.DB_CONN_MS) || 5_000,

  // Keep SSL available for production/cloud environments.
  // Set DB_SSL=true to enable; leave unset for local development.
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
};

// ── Create the pool (skipped in unit-test environment) ───────────────
let pool;

if (process.env.NODE_ENV === 'test') {
  // Tests inject their own mock via jest.mock('./db') — we export a
  // clearly broken stub so any accidental real usage throws immediately.
  pool = {
    query: () => {
      throw new Error('[db] Real pool must not be called in test environment.');
    },
    end: () => Promise.resolve(),
  };
} else {
  pool = new Pool(poolConfig);

  // Surface idle/background errors that would otherwise be swallowed.
  pool.on('error', (err, client) => {
    console.error('[db] Unexpected error on idle client:', err.message, client);
  });

  // Optional startup connectivity check — logs a warning but does NOT
  // prevent the server from starting; avoids a hard crash when the DB
  // is temporarily unavailable during a rolling deploy.
  pool
    .connect()
    .then((client) => {
      console.log(
        `[db] Pool connected — host=${poolConfig.host} db=${poolConfig.database} ` +
          `max=${poolConfig.max}`
      );
      client.release();
    })
    .catch((err) => {
      console.warn(
        '[db] Initial connectivity check failed (server will still start):', err.message
      );
    });
}

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Every public function in this module:
 *   1. Accepts only typed / validated arguments — raw user input is
 *      NEVER interpolated into SQL strings.
 *   2. Uses the pg driver's built-in parameterised query API ($1, $2 …)
 *      so the database itself handles escaping and prevents SQL injection.
 *   3. Records wall-clock query timing and logs it at DEBUG level so slow
 *      queries are visible without requiring an external APM tool.
 *   4. Validates and sanitises every argument before it reaches the pool
 *      so invalid input produces a clear 4xx error rather than a DB error.
 *
 * Exported functions
 * ──────────────────
 *   getUserById(id)                    → single user row or null
 *   getAllUsers(limit, offset)         → { rows, total, limit, offset }
 *   searchUsers(query, limit, offset)  → { rows, total, limit, offset, query }
 */

'use strict';

const pool = require('./db');

// ── Constants ─────────────────────────────────────────────────────────

/** Hard ceiling on the number of rows returned in a single page. */
const MAX_LIMIT = 100;

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

/** Column allowlist used by searchUsers to restrict full-text search scope. */
const SEARCHABLE_COLUMNS = ['name', 'email'];

// ── Private helpers ───────────────────────────────────────────────────

/**
 * Executes a parameterised SQL query against the shared pool and emits a
 * structured timing log entry on completion (or failure).
 *
 * @param {string}   label      – Human-readable name shown in log output.
 * @param {string}   sql        – Parameterised SQL string (uses $1, $2 …).
 * @param {Array}    params     – Positional parameter values; may be empty.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(label, sql, params = []) {
  const startTime = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, params);

    const durationMs = Number(process.hrtime.bigint() - startTime) / 1e6;

    // Structured log — replace with your preferred logger (pino, winston …)
    // by swapping out these console calls.
    console.log(
      JSON.stringify({
        level:      'debug',
        event:      'query_ok',
        label,
        durationMs: Number(durationMs.toFixed(3)),
        rowCount:   result.rowCount,
        // Never log `params` here — it may contain PII or sensitive data.
      })
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - startTime) / 1e6;

    console.error(
      JSON.stringify({
        level:      'error',
        event:      'query_error',
        label,
        durationMs: Number(durationMs.toFixed(3)),
        errCode:    err.code,     // pg error code, e.g. "42P01"
        errMessage: err.message,
      })
    );

    // Re-throw so the route handler can decide the HTTP status code.
    throw err;
  }
}

/**
 * Validates and coerces a numeric `id` argument.
 * Throws a typed ValidationError for any invalid value so the caller can
 * return HTTP 400 without exposing an internal stack trace.
 *
 * @param {*} id
 * @returns {number} – Safe positive integer.
 */
function validateId(id) {
  const n = Number(id);

  if (!Number.isInteger(n) || n < 1) {
    const err = new Error(`Invalid id "${id}": must be a positive integer.`);
    err.name  = 'ValidationError';
    err.status = 400;
    throw err;
  }

  return n;
}

/**
 * Validates and coerces pagination parameters.
 *
 * @param {*} rawLimit   – Desired page size (coerced to int, clamped to MAX_LIMIT).
 * @param {*} rawOffset  – Zero-based row offset (coerced to non-negative int).
 * @returns {{ limit: number, offset: number }}
 */
function validatePagination(rawLimit, rawOffset) {
  let limit  = rawLimit  === undefined ? DEFAULT_LIMIT : Number(rawLimit);
  let offset = rawOffset === undefined ? 0             : Number(rawOffset);

  if (!Number.isFinite(limit)  || limit  < 1) limit  = DEFAULT_LIMIT;
  if (!Number.isFinite(offset) || offset < 0) offset = 0;

  // Silently clamp rather than reject — avoids breaking existing clients.
  limit = Math.min(Math.floor(limit),  MAX_LIMIT);
  offset = Math.floor(offset);

  return { limit, offset };
}

/**
 * Validates a free-text search term.
 * Rejects empty strings and enforces a maximum length to prevent accidental
 * full-table scans via enormous LIKE patterns.
 *
 * @param {*}      rawQuery  – Raw value from the request (e.g. req.query.q).
 * @param {number} [maxLen]  – Maximum allowed character count (default: 200).
 * @returns {string} – Trimmed, non-empty search term.
 */
function validateSearchQuery(rawQuery, maxLen = 200) {
  if (typeof rawQuery !== 'string') {
    const err = new Error('Search query must be a non-empty string.');
    err.name   = 'ValidationError';
    err.status = 400;
    throw err;
  }

  const trimmed = rawQuery.trim();

  if (trimmed.length === 0) {
    const err = new Error('Search query must not be empty or whitespace.');
    err.name   = 'ValidationError';
    err.status = 400;
    throw err;
  }

  if (trimmed.length > maxLen) {
    const err = new Error(
      `Search query too long: ${trimmed.length} chars (max ${maxLen}).`
    );
    err.name   = 'ValidationError';
    err.status = 400;
    throw err;
