 * app.js — Express application
 *
 * /users endpoint wiring
 * ──────────────────────
 *   GET /users               – paginated list of all users
 *   GET /users/search        – search users by name or email
 *   GET /users/:id           – fetch a single user by id
 *
 * All database access is delegated to queries.js which uses parameterised
 * queries and connection pooling (see db.js).  Input validation happens in
 * queries.js; this file only handles HTTP concerns (status codes, response
 * shape, error translation).
 */

'use strict';

require('dotenv').config(); // load .env before anything else

const express = require('express');
const {
  getUserById,
  getAllUsers,
  searchUsers,
} = require('./queries');

const app = express();

app.use(express.json());

// ── Health ────────────────────────────────────────────────────────────

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── /users — list all (paginated) ─────────────────────────────────────
//
//  Query params:
//    limit  (integer, 1–100, default 20)
//    offset (integer, ≥ 0,   default  0)
//
//  Example: GET /users?limit=10&offset=20

app.get('/users', async (req, res) => {
  try {
    const { limit, offset } = req.query;
    const data = await getAllUsers(limit, offset);

    return res.json({
      data:   data.rows,
      meta: {
        total:  data.total,
        limit:  data.limit,
        offset: data.offset,
      },
    });
  } catch (err) {
    return handleError(err, res);
  }
});

// ── /users/search — free-text search ──────────────────────────────────
//
//  Query params:
//    q      (required string, max 200 chars)
//    limit  (integer, 1–100, default 20)
//    offset (integer, ≥ 0,   default  0)
//
//  Example: GET /users/search?q=alice&limit=5
//
//  NOTE: this route MUST be registered before /users/:id so that the
//  literal path segment "search" is not misinterpreted as an :id value.

app.get('/users/search', async (req, res) => {
  const { q, limit, offset } = req.query;

  if (!q) {
    return res.status(400).json({
      error: 'Missing required query parameter: q',
    });
  }

  try {
    const data = await searchUsers(q, limit, offset);

    return res.json({
      data: data.rows,
      meta: {
        total:  data.total,
        limit:  data.limit,
        offset: data.offset,
        query:  data.query, // echo the cleaned search term
      },
    });
  } catch (err) {
    return handleError(err, res);
  }
});

// ── /users/:id — single user ───────────────────────────────────────────
//
//  Path param:
//    id (positive integer)
//
//  Example: GET /users/42

app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: `User ${req.params.id} not found.` });
    }

    return res.json({ data: user });
  } catch (err) {
    return handleError(err, res);
  }
});

// ── Error helper ───────────────────────────────────────────────────────

/**
 * Translates thrown errors into appropriate HTTP responses.
 * ValidationErrors (thrown by queries.js) become 400; everything else
 * becomes 500 with only a generic message exposed to the client so that
 * internal details are never leaked.
 *
 * @param {Error}                         err
 * @param {import('express').Response}    res
 */
function handleError(err, res) {
  if (err.name === 'ValidationError') {
    return res.status(err.status || 400).json({ error: err.message });
  }

  // Log the full error server-side but return nothing sensitive to the client.
  console.error('[app] Unhandled error:', err);
  return res.status(500).json({ error: 'An internal server error occurred.' });
}

