/**
 * db/pool.js
 *
 * Creates and exports a single shared pg.Pool instance for the entire
 * application.  Every module that needs a database connection imports this
 * file instead of creating its own pool, so the total number of open
 * connections stays inside the configured limit.
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials ever appear in source code.  See .env.example for the full
 * list of supported variables.
 */

'use strict';

const { Pool } = require('pg');
const logger   = require('../logger');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
// pg reads DATABASE_URL automatically when it is set, but we also support
// individual connection variables for environments where a single URL is
// inconvenient (e.g. separate secrets for host / password in some cloud
// secret managers).
// ---------------------------------------------------------------------------

const poolConfig = {
  // If DATABASE_URL is provided it takes precedence over individual fields.
  connectionString: process.env.DATABASE_URL || undefined,

  // Individual connection fields (used when DATABASE_URL is absent).
  host:     process.env.DB_HOST     || 'localhost',
  port:     parseInt(process.env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME     || 'app',
  user:     process.env.DB_USER     || 'postgres',
  password: process.env.DB_PASSWORD || '',

  // Pool sizing.
  // min – connections kept alive even when idle.
  // max – hard ceiling on concurrent connections.
  min: parseInt(process.env.DB_POOL_MIN || '2',  10),
  max: parseInt(process.env.DB_POOL_MAX || '10', 10),

  // How long (ms) a client may sit idle in the pool before being closed.
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT || '30000', 10),

  // How long (ms) to wait for a connection before throwing an error.
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT || '5000', 10),

  // Enable SSL in production unless explicitly disabled.
  ssl: process.env.DB_SSL === 'false'
    ? false
    : process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event handlers
// ---------------------------------------------------------------------------

// Fired whenever a new physical client is created and added to the pool.
pool.on('connect', (client) => {
  logger.debug('pg pool: new client connected', {
    totalCount:   pool.totalCount,
    idleCount:    pool.idleCount,
    waitingCount: pool.waitingCount,
  });

  // Set a statement timeout on every new connection so a runaway query
  // cannot hold a connection open indefinitely.
  const statementTimeout = process.env.DB_STATEMENT_TIMEOUT || '30000'; // ms
  client
    .query(`SET statement_timeout = ${parseInt(statementTimeout, 10)}`)
    .catch((err) => logger.warn('pg pool: could not set statement_timeout', { err }));
});

// Fired when a client is released back to the pool.
pool.on('release', (_err, _client) => {
  logger.debug('pg pool: client released', {
    totalCount:   pool.totalCount,
    idleCount:    pool.idleCount,
    waitingCount: pool.waitingCount,
  });
});

// Fired for unexpected errors on idle clients (e.g. unexpected disconnection).
// Without this handler the error would be an unhandled rejection and crash
// the process.
pool.on('error', (err, _client) => {
  logger.error('pg pool: unexpected error on idle client', { err });
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------
// Drain the pool when the process exits so that open connections are closed
// cleanly rather than being forcibly reset by the server.

async function shutdown() {
  logger.info('pg pool: draining connections…');
  try {
    await pool.end();
    logger.info('pg pool: all connections closed');
  } catch (err) {
    logger.error('pg pool: error during shutdown', { err });
  }
}

process.on('SIGINT',  shutdown);
process.on('SIGTERM', shutdown);

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = pool;

/**
 * logger.js
 *
 * Centralised Winston logger used by every layer of the application.
 * Outputs JSON in production (easy to ingest by log aggregators) and a
 * colourised, human-readable format in development.
 */

'use strict';

const { createLogger, format, transports } = require('winston');

const { combine, timestamp, errors, json, colorize, printf } = format;

const isProduction = process.env.NODE_ENV === 'production';

// Human-readable format for local development.
const devFormat = combine(
  colorize({ all: true }),
  timestamp({ format: 'HH:mm:ss.SSS' }),
  errors({ stack: true }),
  printf(({ level, message, timestamp: ts, stack, ...meta }) => {
    const metaStr = Object.keys(meta).length
      ? '\n  ' + JSON.stringify(meta, null, 2).replace(/\n/g, '\n  ')
      : '';
    return `${ts} [${level}] ${stack || message}${metaStr}`;
  }),
);

// Structured JSON format for production / log pipelines.
const prodFormat = combine(
  timestamp(),
  errors({ stack: true }),
  json(),
);

const logger = createLogger({
  level: process.env.LOG_LEVEL || (isProduction ? 'info' : 'debug'),
  format: isProduction ? prodFormat : devFormat,
  transports: [
    new transports.Console(),
  ],
});

module.exports = logger;

/**
 * db/queries.js
 *
 * Parameterised query functions for the /users endpoint.
 *
 * Design principles applied here
 * ───────────────────────────────
 * 1. SQL injection prevention
 *    Every value that originates from user input is passed as a positional
 *    parameter ($1, $2, …) in a parameterised query.  The pg driver sends
 *    the query text and the parameter array separately over the wire, so the
 *    PostgreSQL server never interpolates user-supplied text into SQL.
 *    Dynamic identifiers (column names used in ORDER BY) are validated against
 *    an explicit allow-list before being embedded in the query string.
 *
 * 2. Connection pooling
 *    All functions receive a `client` argument that defaults to the shared
 *    pool exported by ./pool.js.  When `client` is the pool, pg automatically
 *    checks out an idle connection, runs the query, and returns it.  Callers
 *    that need a transaction pass their own checked-out client instead.
 *
 * 3. Query timing logs
 *    A thin `timedQuery` wrapper measures wall-clock duration for every query
 *    and emits a structured log entry that includes the operation name,
 *    duration in milliseconds, and the number of rows returned.  Slow queries
 *    (exceeding SLOW_QUERY_THRESHOLD_MS) are logged at WARN level.
 *
 * 4. Input validation
 *    Numeric inputs (id, limit, offset) are validated and clamped/rejected
 *    before reaching the database layer.  String inputs are trimmed and
 *    length-bounded.
 */

'use strict';

const pool   = require('./pool');
const logger = require('../logger');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Maximum rows a single getAllUsers call may return. */
const MAX_LIMIT = 100;

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

/** Query duration (ms) above which a WARN log entry is emitted. */
const SLOW_QUERY_THRESHOLD_MS = parseInt(
  process.env.SLOW_QUERY_THRESHOLD_MS || '200',
  10,
);

/**
 * Columns that callers are allowed to sort by.
 * This allow-list is the ONLY safe way to inject dynamic identifiers into
 * SQL; never interpolate raw user input for column or table names.
 */
const ALLOWED_SORT_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);

/**
 * The columns projected in every SELECT so we never accidentally expose
 * password hashes or other sensitive fields added to the table later.
 */
const USER_COLUMNS = 'id, name, email, created_at';

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * timedQuery
 *
 * Runs a parameterised query, records wall-clock duration, and emits a
 * structured log entry.  Returns the full pg QueryResult.
 *
 * @param {string}        operation  - Human-readable label used in log output.
 * @param {pg.Pool|pg.PoolClient} client - Pool or checked-out client.
 * @param {string}        text       - Parameterised SQL string.
 * @param {Array}         [params=[]] - Positional parameter values.
 * @returns {Promise<pg.QueryResult>}
 */
async function timedQuery(operation, client, text, params = []) {
  const start = process.hrtime.bigint();

  let result;
  try {
    result = await client.query(text, params);
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    logger.error('db query error', {
      operation,
      durationMs: +durationMs.toFixed(3),
      sql: redactSql(text),
      error: err.message,
      code:  err.code,
    });

    throw err; // re-throw so callers can handle appropriately
  }

  const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
  const rowCount   = result.rowCount ?? result.rows.length;

  const logPayload = {
    operation,
    durationMs: +durationMs.toFixed(3),
    rowCount,
    sql: redactSql(text),
  };

  if (durationMs > SLOW_QUERY_THRESHOLD_MS) {
    logger.warn('db slow query detected', logPayload);
  } else {
    logger.debug('db query ok', logPayload);
  }

  return result;
}

/**
 * redactSql
 *
 * Strips parameter values from a SQL string before logging so that PII or
 * sensitive literals are never written to log files.  Because we always use
 * parameterised queries the SQL text itself contains only $1, $2 … markers,
 * but this helper is a defence-in-depth measure.
 *
 * @param {string} sql
 * @returns {string}
 */
function redactSql(sql) {
  return sql.replace(/\s+/g, ' ').trim();
}

/**
 * assertPositiveInteger
 *
 * Throws a TypeError if `value` is not a safe positive integer.
 * Used to validate `id`, `limit`, and `offset` before they reach the DB.
 *
 * @param {*}      value - The value to check.
 * @param {string} name  - The parameter name (used in error messages).
 */
function assertPositiveInteger(value, name) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1) {
    throw new TypeError(`${name} must be a positive integer, got: ${JSON.stringify(value)}`);
  }
}

/**
 * assertNonNegativeInteger
 *
 * Like assertPositiveInteger but also accepts 0.  Used for `offset`.
 *
 * @param {*}      value
 * @param {string} name
 */
function assertNonNegativeInteger(value, name) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw new TypeError(`${name} must be a non-negative integer, got: ${JSON.stringify(value)}`);
  }
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * getUserById
 *
 * Fetches a single user row by primary key.
 *
 * SQL injection prevention
 *   `id` is coerced to an integer and validated before being passed as the
 *   sole positional parameter ($1).  Even if a caller somehow passes a
 *   non-numeric value the validation step throws before the query executes.
 *
 * @param {number|string} id      - The user's primary key.
 * @param {pg.Pool|pg.PoolClient} [client=pool] - Optional DB client (for transactions).
 * @returns {Promise<object|null>} The user row, or null when not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function getUserById(id, client = pool) {
  // --- Input validation ---------------------------------------------------
  assertPositiveInteger(id, 'id');
  const safeId = parseInt(id, 10);

  // --- Query --------------------------------------------------------------
  const sql = `
    SELECT ${USER_COLUMNS}
    FROM   users
    WHERE  id = $1
    LIMIT  1
  `;

  const { rows } = await timedQuery('getUserById', client, sql, [safeId]);

  return rows[0] ?? null;
}

/**
 * getAllUsers
 *
 * Returns a paginated list of users plus a total row-count for building
 * pagination metadata in the HTTP response.
 *
 * SQL injection prevention
 *   `limit` and `offset` are validated as non-negative integers and passed as
 *   positional parameters ($1 / $2).  The sort column is matched against
 *   ALLOWED_SORT_COLUMNS before being interpolated into the query string, and
 *   the sort direction is forced to one of exactly two string literals so it
 *   can never carry attacker-controlled text.
 *
 * @param {object} [options={}]
 * @param {number} [options.limit=DEFAULT_LIMIT]  - Rows per page (max MAX_LIMIT).
 * @param {number} [options.offset=0]             - Zero-based row offset.
 * @param {string} [options.sortBy='id']          - Column to sort by.
 * @param {string} [options.sortDir='ASC']        - 'ASC' or 'DESC'.
 * @param {pg.Pool|pg.PoolClient} [client=pool]
 * @returns {Promise<{users: object[], total: number}>}
 *
 * @example
 *   const { users, total } = await getAllUsers({ limit: 10, offset: 20 });
 */
async function getAllUsers(
  { limit = DEFAULT_LIMIT, offset = 0, sortBy = 'id', sortDir = 'ASC' } = {},
  client = pool,
) {
  // --- Input validation ---------------------------------------------------
  const safeLimit  = Math.min(Math.max(parseInt(limit,  10) || DEFAULT_LIMIT, 1), MAX_LIMIT);
  const safeOffset = Math.max(parseInt(offset, 10) || 0, 0);

  assertNonNegativeInteger(safeLimit,  'limit');
  assertNonNegativeInteger(safeOffset, 'offset');

  // Validate sortBy against allow-list — never interpolate raw user input.
  const safeSortBy = ALLOWED_SORT_COLUMNS.has(sortBy) ? sortBy : 'id';

  // Force sortDir to one of exactly two known-safe string literals.
  const safeSortDir = sortDir?.toString().toUpperCase() === 'DESC' ? 'DESC' : 'ASC';

  // --- Queries (data + count run in parallel for efficiency) --------------
  const dataSql = `
    SELECT   ${USER_COLUMNS}
    FROM     users
    ORDER BY ${safeSortBy} ${safeSortDir}
    LIMIT    $1
    OFFSET   $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM   users
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('getAllUsers:data',  client, dataSql,  [safeLimit, safeOffset]),
    timedQuery('getAllUsers:count', client, countSql, []),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * searchUsers
 *
 * Full-text prefix search across name and email using PostgreSQL's ILIKE
 * operator with parameterised wildcards.
 *
 * SQL injection prevention
 *   The search term is passed entirely as a parameter value ($1).  The
 *   wildcard characters (%) are added by the application *outside* the SQL
 *   string, so they form part of the parameter value rather than part of the
 *   query structure.  Any SQL metacharacters in the user's input are therefore
 *   treated as literal data by the PostgreSQL server.
 *
 *   Additionally, LIKE-specific metacharacters (%, _, \) inside the user's
 *   search term are escaped so that they match literally rather than acting
 *   as wildcards within the ILIKE pattern.
 *
 * @param {string} query   - The search term (trimmed; max 200 chars).
 * @param {object} [options={}]
 * @param {number} [options.limit=DEFAULT_LIMIT]  - Maximum rows to return.
 * @param {number} [options.offset=0]             - Zero-based row offset.
 * @param {pg.Pool|pg.PoolClient} [client=pool]
 * @returns {Promise<{users: object[], total: number}>}
 *
 * @example
 *   const { users } = await searchUsers('ali', { limit: 5 });
 */
async function searchUsers(
  query,
  { limit = DEFAULT_LIMIT, offset = 0 } = {},
  client = pool,
) {
  // --- Input validation ---------------------------------------------------
  if (typeof query !== 'string') {
    throw new TypeError(`query must be a string, got: ${typeof query}`);
  }

  const trimmed = query.trim();

  if (trimmed.length === 0) {
    throw new TypeError('query must not be empty');
  }

  if (trimmed.length > 200) {
    throw new TypeError('query must not exceed 200 characters');
  }

  const safeLimit  = Math.min(Math.max(parseInt(limit,  10) || DEFAULT_LIMIT, 1), MAX_LIMIT);
  const safeOffset = Math.max(parseInt(offset, 10) || 0, 0);

  // --- Escape LIKE metacharacters in the search term ----------------------
  // This prevents a search for "100%" from being interpreted as "100
  // followed by any characters".  The backslash escape is standard SQL.
  const escapedQuery = trimmed
    .replace(/\\/g, '\\\\') // must be first
    .replace(/%/g,  '\\%')
    .replace(/_/g,  '\\_');

  // Wrap with wildcards to perform a contains-style search.
  const likePattern = `%${escapedQuery}%`;

  // --- Queries (data + count run in parallel) -----------------------------
  const dataSql = `
    SELECT   ${USER_COLUMNS}
    FROM     users
    WHERE    name  ILIKE $1
          OR email ILIKE $1
    ORDER BY name ASC
    LIMIT    $2
    OFFSET   $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM   users
    WHERE  name  ILIKE $1
        OR email ILIKE $1
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('searchUsers:data',  client, dataSql,  [likePattern, safeLimit, safeOffset]),
    timedQuery('searchUsers:count', client, countSql, [likePattern]),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
    query:  trimmed,
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,

  // Expose constants so callers (and tests) can reference them.
  MAX_LIMIT,
  DEFAULT_LIMIT,
  ALLOWED_SORT_COLUMNS,
};

/**
 * app.js
 *
 * Express application entry point.
 *
 * The /users endpoint now delegates all data access to the query functions in
 * db/queries.js.  Three sub-routes are wired up:
 *
 *   GET /users            → getAllUsers  (supports ?limit, ?offset, ?sortBy, ?sortDir)
 *   GET /users/search     → searchUsers (requires ?q; supports ?limit, ?offset)
 *   GET /users/:id        → getUserById
 *
 * Request-level timing is recorded by a lightweight middleware so every
 * response carries an X-Response-Time header and a structured log entry.
 */

'use strict';

// Load environment variables from .env (ignored in production where real env
// vars are expected to be injected by the platform).
require('dotenv').config();

const express = require('express');
const logger  = require('./logger');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  MAX_LIMIT,
  DEFAULT_LIMIT,
} = require('./db/queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Request timing middleware
// ---------------------------------------------------------------------------
// Attaches a high-resolution start time to every request, adds the
// X-Response-Time header to every response, and emits a structured access-log
// entry when the response finishes.

app.use((req, _res, next) => {
  req._startTime = process.hrtime.bigint();
  next();
});

app.use((req, res, next) => {
  res.on('finish', () => {
    const durationMs = Number(process.hrtime.bigint() - req._startTime) / 1_000_000;

    logger.info('http request', {
      method:     req.method,
      path:       req.path,
      status:     res.statusCode,
      durationMs: +durationMs.toFixed(3),
      ip:         req.ip,
      userAgent:  req.headers['user-agent'],
    });
  });

  res.setHeader('X-Response-Time', ''); // placeholder; will be overwritten
  const originalEnd = res.end.bind(res);
  res.end = function (...args) {
    const durationMs = Number(process.hrtime.bigint() - req._startTime) / 1_000_000;
    res.setHeader('X-Response-Time', `${durationMs.toFixed(3)}ms`);
    return originalEnd(...args);
  };

  next();
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * sendError — Sends a consistent JSON error envelope and logs at the
 * appropriate level.
 *
 * @param {import('express').Response} res
 * @param {number}  status  - HTTP status code.
 * @param {string}  message - Human-readable message sent to the client.
 * @param {Error}   [err]   - Original error (logged internally, NOT sent to client).
 */
function sendError(res, status, message, err) {
  if (err) {
    // 5xx errors are unexpected — log the full stack trace.
    const logFn = status >= 500 ? 'error' : 'warn';
    logger[logFn]('request error', { status, message, error: err.message, stack: err.stack });
  }
  res.status(status).json({ error: message });
}

/**
 * parsePagination — Extracts and coerces ?limit and ?offset from a query
 * string, returning safe integer values with sensible defaults.
 *
 * @param {import('express').Request} req
 * @returns {{ limit: number, offset: number }}
 */
function parsePagination(req) {
  const limit  = Math.min(
    Math.max(parseInt(req.query.limit  ?? DEFAULT_LIMIT, 10) || DEFAULT_LIMIT, 1),
    MAX_LIMIT,
  );
  const offset = Math.max(parseInt(req.query.offset ?? 0, 10) || 0, 0);
  return { limit, offset };
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health check — kept above all authenticated/DB routes.
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── GET /users/search ────────────────────────────────────────────────────────
// Must be registered BEFORE /users/:id so Express does not treat "search" as
// an id parameter.
//
// Query parameters:
//   q        {string}  Required. The search term.
//   limit    {number}  Optional. Rows per page (1–100, default 20).
//   offset   {number}  Optional. Zero-based row offset (default 0).
//
// Example:
//   GET /users/search?q=alice&limit=5
app.get('/users/search', async (req, res) => {
  const { q } = req.query;

  if (!q || typeof q !== 'string' || q.trim().length === 0) {
    return sendError(res, 400, 'Query parameter "q" is required and must be a non-empty string');
  }

  const { limit, offset } = parsePagination(req);

  try {
    const result = await searchUsers(q, { limit, offset });

    res.json({
      data:  result.users,
      meta: {
        query:      result.query,
        total:      result.total,
        limit:      result.limit,
        offset:     result.offset,
        returned:   result.users.length,
        totalPages: Math.ceil(result.total / result.limit),
        page:       Math.floor(result.offset / result.limit) + 1,
      },
    });
  } catch (err) {
    if (err instanceof TypeError) {
      // Validation errors from the query layer are client mistakes (400).
      return sendError(res, 400, err.message);
    }
    sendError(res, 500, 'An unexpected error occurred while searching users', err);
  }
});

// ── GET /users ───────────────────────────────────────────────────────────────
//
// Query parameters:
//   limit    {number}  Optional. Rows per page (1–100, default 20).
//   offset   {number}  Optional. Zero-based row offset (default 0).
//   sortBy   {string}  Optional. Column: id | name | email | created_at
//   sortDir  {string}  Optional. ASC (default) | DESC
//
// Example:
//   GET /users?limit=10&offset=0&sortBy=name&sortDir=ASC
app.get('/users', async (req, res) => {
  const { limit, offset } = parsePagination(req);
  const sortBy  = req.query.sortBy  ?? 'id';
  const sortDir = req.query.sortDir ?? 'ASC';

  try {
    const result = await getAllUsers({ limit, offset, sortBy, sortDir });

    res.json({
      data: result.users,
      meta: {
        total:      result.total,
        limit:      result.limit,
        offset:     result.offset,
        returned:   result.users.length,
        totalPages: Math.ceil(result.total / result.limit),
        page:       Math.floor(result.offset / result.limit) + 1,
      },
    });
  } catch (err) {
    if (err instanceof TypeError) {
      return sendError(res, 400, err.message);
    }
    sendError(res, 500, 'An unexpected error occurred while fetching users', err);
  }
});

// ── GET /users/:id ───────────────────────────────────────────────────────────
//
// Path parameter:
//   :id  {positive integer}  Required.
//
// Example:
//   GET /users/42
app.get('/users/:id', async (req, res) => {
  const rawId = req.params.id;

  // Reject obviously non-numeric ids before they reach the query layer.
  if (!/^\d+$/.test(rawId)) {
    return sendError(res, 400, 'User id must be a positive integer');
  }

  try {
    const user = await getUserById(rawId);

    if (!user) {
      return sendError(res, 404, `User with id ${rawId} not found`);
    }

    res.json({ data: user });
  } catch (err) {
    if (err instanceof TypeError) {
      return sendError(res, 400, err.message);
    }
    sendError(res, 500, 'An unexpected error occurred while fetching the user', err);
  }
});

// ---------------------------------------------------------------------------
// 404 catch-all
// ---------------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: `Route ${req.method} ${req.path} not found` });
});

// ---------------------------------------------------------------------------
// Global error handler
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  sendError(res, 500, 'Internal server error', err);
});

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = parseInt(process.env.PORT || '3000', 10);
  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT}`, { env: process.env.NODE_ENV || 'development' });
  });
}

module.exports = app;

/**
 * db/queries.test.js
 *
 * Unit tests for db/queries.js.
 *
 * The pg pool is mocked so these tests run without a real database.
 * Each test stubs pool.query to return controlled fixtures and then asserts
 * on the SQL sent to the driver, verifying:
 *   - correct parameterisation (no interpolated user input in SQL text)
 *   - input validation / clamping
 *   - error propagation
 *   - pagination maths
 *
 * Run with:  npm test
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the pg pool BEFORE requiring queries.js so the module picks up the
// mock when it does  require('./pool').
// ---------------------------------------------------------------------------
const mockQuery = jest.fn();

jest.mock('./pool', () => ({
  query:        mockQuery,
  on:           jest.fn(),
  totalCount:   0,
  idleCount:    0,
  waitingCount: 0,
}));

// Also suppress winston output during tests.
jest.mock('../logger', () => ({
  debug: jest.fn(),
  info:  jest.fn(),
  warn:  jest.fn(),
  error: jest.fn(),
}));

const {
  getUserById,
  getAllUsers,
  searchUsers,
  MAX_LIMIT,
  DEFAULT_LIMIT,
  ALLOWED_SORT_COLUMNS,
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Sets up mockQuery to respond to sequential calls with the provided arrays
 * of { rows, rowCount } objects.
 */
function mockQuerySequence(...results) {
  results.forEach((r) => {
    mockQuery.mockResolvedValueOnce({
      rows:     r.rows     ?? [],
      rowCount: r.rowCount ?? r.rows?.length ?? 0,
    });
  });
}

// Re-usable user fixture.
const ALICE = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date('2024-01-01') };
const BOB   = { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date('2024-01-02') };

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------

describe('getUserById', () => {
  beforeEach(() => mockQuery.mockReset());

  test('returns user row when found', async () => {
    mockQuerySequence({ rows: [ALICE] });

    const user = await getUserById(1);

    expect(user).toEqual(ALICE);
  });

  test('returns null when user is not found', async () => {
    mockQuerySequence({ rows: [] });

    const user = await getUserById(999);

    expect(user).toBeNull();
  });

  test('passes id as positional parameter — not interpolated in SQL', async () => {
    mockQuerySequence({ rows: [ALICE] });

    await getUserById(1);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([1]);
    // The SQL text must contain $1 and must NOT contain the literal "1" in
    // a position that looks like interpolation (i.e. WHERE id = 1).
    expect(sql).toContain('$1');
    expect(sql).not.toMatch(/WHERE\s+id\s*=\s*1/i);
  });

  test('accepts string "42" and coerces it to integer', async () => {
    mockQuerySequence({ rows: [ALICE] });

    await getUserById('42');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe(42);
    expect(typeof params[0]).toBe('number');
  });

  test('throws TypeError for id = 0', async () => {
    await expect(getUserById(0)).rejects.toThrow(TypeError);
  });

  test('throws TypeError for negative id', async () => {
    await expect(getUserById(-1)).rejects.toThrow(TypeError);
  });

  test('throws TypeError for non-numeric id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(TypeError);
  });

  test('throws TypeError for SQL-injection attempt in id', async () => {
    // Classic tautology injection — must be rejected, not passed to DB.
    await expect(getUserById("1 OR 1=1")).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('propagates database errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('connection refused'));

    await expect(getUserById(1)).rejects.toThrow('connection refused');
  });

  test('uses provided client instead of pool', async () => {
    const fakeClient = { query: jest.fn().mockResolvedValue({ rows: [ALICE], rowCount: 1 }) };

    const user = await getUserById(1, fakeClient);

    expect(user).toEqual(ALICE);
    expect(fakeClient.query).toHaveBeenCalled();
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

// ---------------------------------------------------------------------------
// getAllUsers
// ---------------------------------------------------------------------------

describe('getAllUsers', () => {
  beforeEach(() => mockQuery.mockReset());

  test('returns users array and total count', async () => {
    mockQuerySequence(
      { rows: [ALICE, BOB] },   // data query
      { rows: [{ total: '2' }] }, // count query
    );

    const result = await getAllUsers();

    expect(result.users).toEqual([ALICE, BOB]);
    expect(result.total).toBe(2);
  });

  test('uses default limit and offset when omitted', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    const result = await getAllUsers();

    expect(result.limit).toBe(DEFAULT_LIMIT);
    expect(result.offset).toBe(0);
  });

  test('respects supplied limit and offset', async () => {
    mockQuerySequence({ rows: [BOB] }, { rows: [{ total: '5' }] });

    const result = await getAllUsers({ limit: 1, offset: 1 });

    expect(result.limit).toBe(1);
    expect(result.offset).toBe(1);

    // Verify positional params
    const dataSqlCall = mockQuery.mock.calls.find(([sql]) => sql.includes('LIMIT'));
    expect(dataSqlCall[1]).toEqual([1, 1]);
  });

  test('clamps limit to MAX_LIMIT', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    const result = await getAllUsers({ limit: 99999 });

    expect(result.limit).toBe(MAX_LIMIT);
    const dataSqlCall = mockQuery.mock.calls.find(([sql]) => sql.includes('LIMIT'));
    expect(dataSqlCall[1][0]).toBe(MAX_LIMIT);
  });

  test('clamps limit minimum to 1', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    const result = await getAllUsers({ limit: -5 });

    expect(result.limit).toBe(1);
  });

  test('clamps offset to 0 when negative', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    const result = await getAllUsers({ offset: -10 });

    expect(result.offset).toBe(0);
  });

  test('uses "id" when sortBy is not in allow-list', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await getAllUsers({ sortBy: 'password_hash' }); // not in allow-list

    const dataSqlCall = mockQuery.mock.calls.find(([sql]) => sql.includes('ORDER BY'));
    expect(dataSqlCall[0]).toContain('ORDER BY id');
  });

  test.each([...ALLOWED_SORT_COLUMNS])('allows sortBy = %s', async (col) => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await getAllUsers({ sortBy: col });

    const dataSqlCall = mockQuery.mock.calls.find(([sql]) => sql.includes('ORDER BY'));
    expect(dataSqlCall[0]).toContain(`ORDER BY ${col}`);
  });

  test('defaults sortDir to ASC for unknown values', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await getAllUsers({ sortDir: 'SIDEWAYS' });

    const dataSqlCall = mockQuery.mock.calls.find(([sql]) => sql.includes('ORDER BY'));
    expect(dataSqlCall[0]).toContain('ASC');
  });

  test('accepts sortDir DESC (case-insensitive)', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await getAllUsers({ sortDir: 'desc' });

    const dataSqlCall = mockQuery.mock.calls.find(([sql]) => sql.includes('ORDER BY'));
    expect(dataSqlCall[0]).toContain('DESC');
  });

  test('SQL injection attempt in sortBy falls back to "id"', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await getAllUsers({ sortBy: "id; DROP TABLE users; --" });

    const dataSqlCall = mockQuery.mock.calls.find(([sql]) => sql.includes('ORDER BY'));
    expect(dataSqlCall[0]).toContain('ORDER BY id');
    expect(dataSqlCall[0]).not.toContain('DROP');
  });

  test('limit and offset are always parameterised, never interpolated', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await getAllUsers({ limit: 5, offset: 10 });

    const dataSqlCall = mockQuery.mock.calls.find(([sql]) => sql.includes('LIMIT'));
    const [sql, params] = dataSqlCall;
    expect(sql).toContain('$1');
    expect(sql).toContain('$2');
    expect(params).toEqual([5, 10]);
    // Must not appear as literals in the SQL text.
    expect(sql).not.toMatch(/LIMIT\s+5/);
    expect(sql).not.toMatch(/OFFSET\s+10/);
  });

  test('runs data and count queries in parallel (both calls recorded)', async () => {
    mockQuerySequence({ rows: [ALICE] }, { rows: [{ total: '1' }] });

    await getAllUsers();

    expect(mockQuery).toHaveBeenCalledTimes(2);
  });
});

// ---------------------------------------------------------------------------
// searchUsers
// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  beforeEach(() => mockQuery.mockReset());

  test('returns matching users and total', async () => {
    mockQuerySequence(
      { rows: [ALICE] },
      { rows: [{ total: '1' }] },
    );

    const result = await searchUsers('alice');

    expect(result.users).toEqual([ALICE]);
    expect(result.total).toBe(1);
    expect(result.query).toBe('alice');
  });

  test('wraps search term with % wildcards as a parameter value', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await searchUsers('ali');

    // Both queries receive the pattern as $1.
    mockQuery.mock.calls.forEach(([, params]) => {
      expect(params[0]).toBe('%ali%');
    });
  });

  test('user input is passed entirely as a parameter — not embedded in SQL', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await searchUsers('test');

    mockQuery.mock.calls.forEach(([sql]) => {
      // The raw search term must not appear in the SQL text itself.
      expect(sql).not.toContain('test');
      expect(sql).toContain('$1');
    });
  });

  test('escapes LIKE metacharacter % in search term', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await searchUsers('100%');

    mockQuery.mock.calls.forEach(([, params]) => {
      // % in the search term should be escaped; wrapper % should remain.
      expect(params[0]).toBe('%100\\%%');
    });
  });

  test('escapes LIKE metacharacter _ in search term', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await searchUsers('a_b');

    mockQuery.mock.calls.forEach(([, params]) => {
      expect(params[0]).toBe('%a\\_b%');
    });
  });

  test('escapes backslash in search term', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await searchUsers('C:\\Users');

    mockQuery.mock.calls.forEach(([, params]) => {
      expect(params[0]).toBe('%C:\\\\Users%');
    });
  });

  test('SQL injection attempt via search term is safely parameterised', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    // Classic UNION-based injection attempt.
    const injection = "' UNION SELECT * FROM secrets --";
    await searchUsers(injection);

    mockQuery.mock.calls.forEach(([sql, params]) => {
      // Injection string must not appear anywhere in the SQL text.
      expect(sql).not.toContain('UNION');
      expect(sql).not.toContain('secrets');
      // It must appear only as a parameter value (with wildcards prepended/appended).
      expect(params[0]).toContain(injection.replace(/\\/g, '\\\\'));
    });
  });

  test('throws TypeError when query is not a string', async () => {
    await expect(searchUsers(null)).rejects.toThrow(TypeError);
    await expect(searchUsers(42)).rejects.toThrow(TypeError);
  });

  test('throws TypeError when query is empty after trimming', async () => {
    await expect(searchUsers('   ')).rejects.toThrow(TypeError);
  });

  test('throws TypeError when query exceeds 200 characters', async () => {
    await expect(searchUsers('a'.repeat(201))).rejects.toThrow(TypeError);
  });

  test('trims whitespace from query before use', async () => {
    mockQuerySequence({ rows: [ALICE] }, { rows: [{ total: '1' }] });

    const result = await searchUsers('  alice  ');

    expect(result.query).toBe('alice');
    mockQuery.mock.calls.forEach(([, params]) => {
      expect(params[0]).toBe('%alice%');
    });
  });

  test('clamps limit to MAX_LIMIT', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    const result = await searchUsers('x', { limit: 9999 });

    expect(result.limit).toBe(MAX_LIMIT);
  });

  test('runs data and count queries in parallel', async () => {
    mockQuerySequence({ rows: [] }, { rows: [{ total: '0' }] });

    await searchUsers('bob');

    expect(mockQuery).toHaveBeenCalledTimes(2);
  });

  test('uses provided client', async () => {
    const fakeClient = {
      query: jest.fn()
        .mockResolvedValueOnce({ rows: [BOB],             rowCount: 1 })
        .mockResolvedValueOnce({ rows: [{ total: '1' }], rowCount: 1 }),
    };

    const result = await searchUsers('bob', {}, fakeClient);

    expect(result.users).toEqual([BOB]);
    expect(fakeClient.query).toHaveBeenCalledTimes(2);
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

-- db/schema.sql
--
-- Reference schema for the `users` table.
-- Apply with:  psql "$DATABASE_URL" -f db/schema.sql
--
-- This file is provided for documentation and local setup.
-- In production, use a proper migration tool (e.g. Flyway, golang-migrate).

BEGIN;

CREATE TABLE IF NOT EXISTS users (
    id         BIGSERIAL    PRIMARY KEY,
    name       VARCHAR(255) NOT NULL,
    email      VARCHAR(255) NOT NULL UNIQUE,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- Index that makes ILIKE prefix/contains searches faster via pg_trgm.
-- Enable the extension first:  CREATE EXTENSION IF NOT EXISTS pg_trgm;
-- CREATE INDEX IF NOT EXISTS idx_users_name_trgm  ON users USING GIN (name  gin_trgm_ops);
-- CREATE INDEX IF NOT EXISTS idx_users_email_trgm ON users USING GIN (email gin_trgm_ops);

-- Standard B-tree indexes used by ORDER BY and equality lookups.
CREATE INDEX IF NOT EXISTS idx_users_name       ON users (name);
CREATE INDEX IF NOT EXISTS idx_users_email      ON users (email);
CREATE INDEX IF NOT EXISTS idx_users_created_at ON users (created_at);

-- Seed data for local development / smoke tests.
INSERT INTO users (name, email) VALUES
    ('Alice',   'alice@example.com'),
    ('Bob',     'bob@example.com'),
    ('Charlie', 'charlie@example.com')
ON CONFLICT (email) DO NOTHING;

COMMIT;

{
  "name": "app",
  "version": "1.0.0",
  "description": "Express app with a parameterised PostgreSQL query layer",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "node --watch app.js",
    "test": "jest --runInBand --forceExit",
    "test:coverage": "jest --runInBand --forceExit --coverage",
    "db:schema": "psql \"$DATABASE_URL\" -f db/schema.sql"
  },
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "pg": "^8.12.0",
    "winston": "^3.13.0"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  },
  "jest": {
    "testEnvironment": "node",
    "testMatch": [
      "**/*.test.js"
    ],
    "collectCoverageFrom": [
      "db/queries.js",
      "db/pool.js",
      "app.js",
      "logger.js"
    ]
  }
}

