    );
  });

  test('rejects SQL injection via sortBy', async () => {
    await assert.rejects(
      () => getAllUsers(10, 0, { sortBy: '1; DROP TABLE users--' }),
      (err) => {
        assert.ok(err instanceof TypeError);
        return true;
      }
    );
  });

  test('rejects an invalid sortOrder value', async () => {
    await assert.rejects(
      () => getAllUsers(10, 0, { sortOrder: 'SIDEWAYS' }),
      (err) => {
        assert.ok(err instanceof TypeError);
        assert.match(err.message, /sortOrder/);
        return true;
      }
    );
  });

  test('uppercases sortOrder before interpolation', async () => {
    const restore = silenceConsole();
    let capturedSql;
    mockQueryFn = (sql) => {
      capturedSql = sql;
      return Promise.resolve(fakeResult([]));
    };

    await getAllUsers(10, 0, { sortOrder: 'desc' });
    restore();

    assert.match(capturedSql, /DESC/);
  });

  test('uses default sort of id ASC', async () => {
    const restore = silenceConsole();
    let capturedSql;
    mockQueryFn = (sql) => {
      capturedSql = sql;
      return Promise.resolve(fakeResult([]));
    };

    await getAllUsers(10, 0);
    restore();

    assert.match(capturedSql, /ORDER BY id ASC/i);
  });
});

// ---------------------------------------------------------------------------
// searchUsers
// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  test('passes the search term as a single bound parameter', async () => {
    const restore = silenceConsole();
    let capturedSql, capturedParams;

    mockQueryFn = (sql, params) => {
      capturedSql    = sql;
      capturedParams = params;
      return Promise.resolve(fakeResult([]));
    };

    await searchUsers('alice', { limit: 10, offset: 0 });
    restore();

    // First bound param must be the ILIKE pattern.
    assert.equal(capturedParams[0], '%alice%');
    assert.equal(capturedParams[1], 10);
    assert.equal(capturedParams[2], 0);
  });

  test('wraps the search term with % wildcards', async () => {
    const restore = silenceConsole();
    let capturedParams;
    mockQueryFn = (_sql, params) => {
      capturedParams = params;
      return Promise.resolve(fakeResult([]));
    };

    await searchUsers('bob');
    restore();

    assert.equal(capturedParams[0], '%bob%');
  });

  test('trims whitespace from the search term', async () => {
    const restore = silenceConsole();
    let capturedParams;
    mockQueryFn = (_sql, params) => {
      capturedParams = params;
      return Promise.resolve(fakeResult([]));
    };

    await searchUsers('  alice  ');
    restore();

    assert.equal(capturedParams[0], '%alice%');
  });

  test('returns users array and total', async () => {
    const restore = silenceConsole();
    const rows = [
      { id: 1, name: 'Alice', email: 'alice@example.com', total_count: '1' },
    ];
    mockQueryFn = () => Promise.resolve(fakeResult(rows));

    const { users, total } = await searchUsers('alice');
    restore();

    assert.equal(total, 1);
    assert.equal(users.length, 1);
    assert.ok(!('total_count' in users[0]));
  });

  test('rejects a non-string search term', async () => {
    await assert.rejects(
      () => searchUsers(123),
      (err) => {
        assert.ok(err instanceof TypeError);
        assert.match(err.message, /expected a string/);
        return true;
      }
    );
  });

  test('rejects an empty string search term', async () => {
    await assert.rejects(
      () => searchUsers('   '),
      (err) => {
        assert.ok(err instanceof RangeError);
        assert.match(err.message, /empty/);
        return true;
      }
    );
  });

  test('rejects a search term exceeding 200 characters', async () => {
    await assert.rejects(
      () => searchUsers('a'.repeat(201)),
      (err) => {
        assert.ok(err instanceof RangeError);
        assert.match(err.message, /200/);
        return true;
      }
    );
  });

  test('SQL metacharacters in search term are bound as data, not SQL', async () => {
    // "' OR '1'='1" is a classic ILIKE injection attempt.
    // It must be passed as the *value* of $1, not spliced into the SQL.
    const restore = silenceConsole();
    let capturedSql, capturedParams;

    mockQueryFn = (sql, params) => {
      capturedSql    = sql;
      capturedParams = params;
      return Promise.resolve(fakeResult([]));
    };

    await searchUsers("' OR '1'='1");
    restore();

    // The parameter value is the raw (trimmed) user string wrapped in %.
    assert.equal(capturedParams[0], `%' OR '1'='1%`);

    // The SQL template must use the placeholder — never the raw string.
    assert.match(capturedSql, /ILIKE \$1/i);

    // The SQL template must NOT contain the injection string.
    assert.ok(
      !capturedSql.includes("'1'='1"),
      'Injection string must not appear in the SQL template'
    );
  });

  test('rejects SQL injection via sortBy in searchUsers', async () => {
    await assert.rejects(
      () => searchUsers('alice', { sortBy: '1; DROP TABLE users--' }),
      (err) => {
        assert.ok(err instanceof TypeError);
        return true;
      }
    );
  });

  test('emits a timing log on success', async () => {
    const logLines = [];
    const origLog  = console.log;
    const origWarn = console.warn;
    console.log  = (line) => logLines.push(line);
    console.warn = (line) => logLines.push(line);

    mockQueryFn = () => Promise.resolve(fakeResult([]));
    await searchUsers('test');

    console.log  = origLog;
    console.warn = origWarn;

    assert.ok(logLines.length > 0);
    const entry = JSON.parse(logLines[0]);
    assert.equal(entry.fn, 'searchUsers');
    assert.equal(entry.success, true);
    assert.equal(entry.layer, 'db/query');
  });
});

// ---------------------------------------------------------------------------
// Slow-query promotion
// ---------------------------------------------------------------------------

describe('slow query promotion', () => {
  test('emits a WARN-level log when query exceeds threshold', async () => {
    const warnLines = [];
    const origWarn  = console.warn;
    const origLog   = console.log;
    console.warn = (line) => warnLines.push(line);
    console.log  = () => {};

    // Simulate a slow query by resolving after a short delay.
    mockQueryFn = () =>
      new Promise((resolve) =>
        setTimeout(() => resolve(fakeResult([])), 5)
      );

    // Lower the threshold to 0 ms so any query appears slow.
    const origThreshold = process.env.SLOW_QUERY_THRESHOLD_MS;
    process.env.SLOW_QUERY_THRESHOLD_MS = '0';

    // Re-require with cleared cache so the new env var is picked up.
    delete require.cache[require.resolve('./queries')];
    const { getUserById: getUserByIdFresh } = require('./queries');

    await getUserByIdFresh(1);

    process.env.SLOW_QUERY_THRESHOLD_MS = origThreshold;
    console.warn = origWarn;
    console.log  = origLog;

    assert.ok(warnLines.length > 0, 'Expected a WARN log for slow query');
    const entry = JSON.parse(warnLines[0]);
    assert.equal(entry.level, 'WARN');
  });
});

