/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single shared Pool instance so every module in the application
 * re-uses the same set of connections rather than opening a new connection
 * per request.
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials ever appear in source code.
 *
 * Required env vars (set in .env for local dev, injected by your platform in
 * production):
 *   DATABASE_URL          – full connection string, OR the individual vars below
 *   PGHOST / DB_HOST      – database hostname
 *   PGPORT / DB_PORT      – database port          (default 5432)
 *   PGDATABASE / DB_NAME  – database name
 *   PGUSER / DB_USER      – database user
 *   PGPASSWORD / DB_PASS  – database password
 *
 * Optional pool-tuning env vars:
 *   DB_POOL_MAX           – maximum pool size      (default 10)
 *   DB_POOL_IDLE_TIMEOUT  – ms before idle clients are released (default 30000)
 *   DB_CONNECT_TIMEOUT    – ms before a connection attempt fails (default 5000)
 *   NODE_ENV              – when "test" the pool is created but stays idle
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------

const poolConfig = {
  // pg respects standard PG* env vars automatically when connectionString is
  // absent, but we also accept the DB_* aliases used by many hosting providers.
  connectionString: process.env.DATABASE_URL || undefined,

  host:     process.env.PGHOST     || process.env.DB_HOST,
  port:     parseInt(process.env.PGPORT     || process.env.DB_PORT     || '5432', 10),
  database: process.env.PGDATABASE || process.env.DB_NAME,
  user:     process.env.PGUSER     || process.env.DB_USER,
  password: process.env.PGPASSWORD || process.env.DB_PASS,

  // Pool sizing
  max:             parseInt(process.env.DB_POOL_MAX          || '10',    10),
  idleTimeoutMillis:  parseInt(process.env.DB_POOL_IDLE_TIMEOUT || '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECT_TIMEOUT  || '5000',  10),

  // Enforce SSL in production unless explicitly disabled
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event handlers
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  console.log(
    `[db] New client connected — pool size: ${pool.totalCount} ` +
    `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
  );

  // Lock down the session: prevent SET ROLE / SET SESSION AUTHORIZATION
  // escalation attacks that could bypass row-level security.
  client.query("SET lock_timeout = '5s'").catch((err) => {
    console.error('[db] Failed to set session lock_timeout:', err.message);
  });
});

pool.on('error', (err) => {
  // A client has encountered an error while sitting idle in the pool.
  // Log and continue — pg will remove the broken client automatically.
  console.error('[db] Unexpected error on idle client:', err.message);
});

pool.on('remove', () => {
  console.log(
    `[db] Client removed — pool size: ${pool.totalCount} ` +
    `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
  );
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool and close all connections.
 * Call this in your SIGTERM / SIGINT handler.
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] Connection pool closed.');
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users resource
 *
 * Security model
 * ──────────────
 * Every user-supplied value is passed as a positional parameter ($1, $2, …)
 * so that pg sends the value out-of-band from the SQL text.  The database
 * driver handles all escaping; no string interpolation of user data is ever
 * performed.  This makes classic SQL injection impossible at the driver level,
 * independent of any application-layer validation.
 *
 * Input validation is performed in addition to parameterisation: types are
 * checked and values are range-clamped before being handed to the driver so
 * that malformed input is rejected early with a clear error rather than
 * reaching the database at all.
 *
 * Query timing
 * ────────────
 * Every exported function wraps its query in a timer that emits a structured
 * log line:
 *
 *   [query] getUserById | params: [42] | rows: 1 | 3.21 ms
 *   [query] getAllUsers  | params: [20,0] | rows: 20 | 5.84 ms
 *   [query] searchUsers | params: ["%alice%",20,0] | rows: 3 | 4.12 ms
 *   [query] ERROR getUserById | params: [abc] | 1.05 ms | <message>
 *
 * The actual parameter values are included in logs only in non-production
 * environments to avoid leaking PII in production log streams.
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Wraps a pool query with timing and structured logging.
 *
 * @param {string} fnName   - Human-readable label used in log output.
 * @param {string} sql      - Parameterised SQL string.
 * @param {Array}  params   - Positional parameter values.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(fnName, sql, params) {
  const start = process.hrtime.bigint();

  // In production we omit param values from logs to protect PII.
  const logParams =
    process.env.NODE_ENV === 'production' ? '[redacted]' : JSON.stringify(params);

  try {
    const result = await pool.query(sql, params);
    const elapsed = formatElapsed(start);

    console.log(
      `[query] ${fnName} | params: ${logParams} | rows: ${result.rowCount} | ${elapsed}`
    );

    return result;
  } catch (err) {
    const elapsed = formatElapsed(start);
    console.error(
      `[query] ERROR ${fnName} | params: ${logParams} | ${elapsed} | ${err.message}`
    );
    // Re-throw so callers / the route handler can decide on the HTTP response.
    throw err;
  }
}

/**
 * Returns a human-readable elapsed time string ("3.21 ms") from a BigInt
 * nanosecond start value produced by process.hrtime.bigint().
 *
 * @param {bigint} startNs
 * @returns {string}
 */
function formatElapsed(startNs) {
  const ns = process.hrtime.bigint() - startNs;
  return `${(Number(ns) / 1_000_000).toFixed(2)} ms`;
}

// ---------------------------------------------------------------------------
// Input validators
// ---------------------------------------------------------------------------

/**
 * Validates and coerces a raw value to a positive integer.
 * Throws a TypeError with a caller-visible message on failure.
 *
 * @param {*}      value  - Raw input (string from query-string, number, etc.)
 * @param {string} name   - Parameter name used in the error message.
 * @param {object} [opts]
 * @param {number} [opts.min=1]       - Inclusive lower bound.
 * @param {number} [opts.max=Infinity] - Inclusive upper bound.
 * @returns {number} Validated integer.
 */
function toPositiveInt(value, name, { min = 1, max = Infinity } = {}) {
  const n = Number(value);

  if (!Number.isInteger(n)) {
    throw new TypeError(`"${name}" must be an integer, got: ${JSON.stringify(value)}`);
  }
  if (n < min || n > max) {
    throw new TypeError(`"${name}" must be between ${min} and ${max}, got: ${n}`);
  }

  return n;
}

/**
 * Validates a search query string.
 * - Must be a non-empty string after trimming.
 * - Capped to MAX_SEARCH_LENGTH characters to prevent oversized LIKE patterns.
 * - Special LIKE wildcard characters (%, _) and the escape character (\) are
 *   escaped so the caller's term is always treated as a literal substring, not
 *   a LIKE pattern.
 *
 * @param {*}      value - Raw input.
 * @param {string} name  - Parameter name used in the error message.
 * @returns {string} Validated, wildcard-escaped, %-wrapped search string.
 */
const MAX_SEARCH_LENGTH = 100;

function toSearchPattern(value, name) {
  if (typeof value !== 'string') {
    throw new TypeError(`"${name}" must be a string, got: ${typeof value}`);
  }

  const trimmed = value.trim();

  if (trimmed.length === 0) {
    throw new TypeError(`"${name}" must not be empty`);
  }
  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new TypeError(
      `"${name}" must be at most ${MAX_SEARCH_LENGTH} characters, ` +
      `got: ${trimmed.length}`
    );
  }

  // Escape LIKE metacharacters so user input is never interpreted as a pattern.
  // We use '\' as the ESCAPE character (declared in the SQL via ESCAPE '\').
  const escaped = trimmed
    .replace(/\\/g, '\\\\') // must be first to avoid double-escaping
    .replace(/%/g,  '\\%')
    .replace(/_/g,  '\\_');

  return `%${escaped}%`;
}

// ---------------------------------------------------------------------------
// Column allow-list for ORDER BY (prevents order-by injection)
// ---------------------------------------------------------------------------

const ALLOWED_ORDER_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);
const ALLOWED_ORDER_DIRS    = new Set(['ASC', 'DESC']);

/**
 * Validates an ORDER BY column name against a hard-coded allow-list.
 *
 * @param {string} col - Column name from the caller.
 * @returns {string} Verified column name, safe to interpolate into SQL.
 */
function toOrderColumn(col) {
  const normalised = (col || 'id').toLowerCase();
  if (!ALLOWED_ORDER_COLUMNS.has(normalised)) {
    throw new TypeError(
      `Invalid order column "${col}". Allowed: ${[...ALLOWED_ORDER_COLUMNS].join(', ')}`
    );
  }
  return normalised;
}

/**
 * Validates an ORDER BY direction against a hard-coded allow-list.
 *
 * @param {string} dir - Direction from the caller ("asc" / "desc").
 * @returns {string} Uppercase direction string, safe to interpolate into SQL.
 */
function toOrderDir(dir) {
  const normalised = (dir || 'ASC').toUpperCase();
  if (!ALLOWED_ORDER_DIRS.has(normalised)) {
    throw new TypeError(`Invalid order direction "${dir}". Allowed: ASC, DESC`);
  }
  return normalised;
}

// ---------------------------------------------------------------------------
// Exported query functions
// ---------------------------------------------------------------------------

/**
 * Retrieves a single user by their primary-key ID.
 *
 * @param {number|string} id - The user's integer ID.
 * @returns {Promise<object|null>} The user row, or null if not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function getUserById(id) {
  // Validate: must be a positive integer; IDs < 1 can never exist.
  const safeId = toPositiveInt(id, 'id', { min: 1 });

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
}

/**
 * Retrieves a paginated list of all users, ordered by a validated column.
 *
 * @param {number|string} limit      - Maximum rows to return (1–100).
 * @param {number|string} offset     - Number of rows to skip (≥ 0).
 * @param {string}        [orderBy]  - Column to sort by (default: "id").
 * @param {string}        [orderDir] - Sort direction: "ASC" or "DESC" (default: "ASC").
 * @returns {Promise<{ rows: object[], total: number }>}
 *          rows  – The page of user records.
 *          total – Total row count for the unfiltered table (for pagination UI).
 *
 * @example
 *   const { rows, total } = await getAllUsers(20, 0, 'name', 'ASC');
 */
async function getAllUsers(limit, offset, orderBy = 'id', orderDir = 'ASC') {
  const safeLimit  = toPositiveInt(limit,  'limit',  { min: 1, max: 100 });
  const safeOffset = toPositiveInt(offset, 'offset', { min: 0 });

  // ORDER BY column and direction come from an allow-list, never from raw user
  // input, so they are safe to interpolate as SQL identifiers.
  const safeCol = toOrderColumn(orderBy);
  const safeDir = toOrderDir(orderDir);

  // Run the paginated data query and total-count query in one round-trip using
  // a CTE window function so we avoid a separate COUNT(*) query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY ${safeCol} ${safeDir}
    LIMIT  $1
    OFFSET $2
  `;

  const result = await timedQuery('getAllUsers', sql, [safeLimit, safeOffset]);

  return {
    rows:  result.rows.map(({ total_count, ...user }) => user),
    total: result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0,
  };
}

/**
 * Searches users whose name or email contains the given substring.
 * The search is case-insensitive (ILIKE) and uses server-side parameterisation,
 * so no part of the query string is ever interpolated into SQL text.
 *
 * LIKE metacharacters (%, _) and the escape character (\) in the caller's term
 * are escaped before the pattern is passed as a parameter, so they are always
 * treated as literal characters rather than wildcards.
 *
 * @param {string}        query      - Search term (1–100 characters).
 * @param {number|string} [limit]    - Maximum rows to return (1–100, default 20).
 * @param {number|string} [offset]   - Number of rows to skip  (≥ 0,  default 0).
 * @returns {Promise<{ rows: object[], total: number }>}
 *
 * @example
 *   const { rows, total } = await searchUsers('alice', 10, 0);
 */
async function searchUsers(query, limit = 20, offset = 0) {
  // Validate and escape the search term; wrap in % wildcards for ILIKE.
  const safePattern = toSearchPattern(query, 'query');
  const safeLimit   = toPositiveInt(limit,  'limit',  { min: 1, max: 100 });
  const safeOffset  = toPositiveInt(offset, 'offset', { min: 0 });

  // ESCAPE '\' tells PostgreSQL which character we used to escape metacharacters.
  // The pattern itself is still passed as a parameter ($1) — the ESCAPE clause
  // only affects how pg interprets the pattern value, not the value itself.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1 ESCAPE '\\'
      OR email ILIKE $1 ESCAPE '\\'
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const result = await timedQuery('searchUsers', sql, [safePattern, safeLimit, safeOffset]);

  return {
    rows:  result.rows.map(({ total_count, ...user }) => user),
    total: result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0,
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export helpers for unit testing
  _internal: {
    toPositiveInt,
    toSearchPattern,
    toOrderColumn,
    toOrderDir,
    timedQuery,
  },
};

/**
 * app.js — Express application
 *
 * /users routes now delegate all database access to queries.js.
 * The route handlers are responsible only for:
 *   1. Parsing / coercing HTTP parameters.
 *   2. Calling the appropriate query function.
 *   3. Mapping the result (or a validation error) to an HTTP response.
 *
 * They never construct SQL or touch the pool directly.
 */

'use strict';

require('dotenv').config(); // Load .env into process.env before anything else

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');
const { closePool } = require('./db');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler and forwards any unhandled rejection to the
 * Express error-handling middleware via next(err).
 *
 * @param {Function} fn - Async (req, res, next) handler.
 * @returns {Function}
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users
// Query-string params:
//   search  – substring search across name and email
//   limit   – page size  (1–100, default 20)
//   offset  – page start (≥ 0,   default 0)
//   orderBy – column to sort by (id | name | email | created_at, default id)
//   order   – sort direction    (asc | desc, default asc)
// ---------------------------------------------------------------------------
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    const { search, limit = 20, offset = 0, orderBy = 'id', order = 'asc' } = req.query;

    let data;
    if (search !== undefined) {
      // Delegate to searchUsers; validation happens inside queries.js.
      data = await searchUsers(search, limit, offset);
    } else {
      data = await getAllUsers(limit, offset, orderBy, order);
    }

    res.json({
      data:   data.rows,
      total:  data.total,
      limit:  Number(limit),
      offset: Number(offset),
    });
  })
);

// ---------------------------------------------------------------------------
// GET /users/:id
// ---------------------------------------------------------------------------
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ data: user });
  })
);

// ---------------------------------------------------------------------------
// Centralised error handler
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Input validation errors (TypeError thrown by query helpers)
  if (err instanceof TypeError) {
    return res.status(400).json({ error: err.message });
  }

  // Database / unexpected errors — do not leak internal details in production
  const message =
    process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message;

  console.error('[app] Unhandled error:', err);
  res.status(500).json({ error: message });
});

// ---------------------------------------------------------------------------
// Server startup / graceful shutdown
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT || '3000', 10);

// Only bind the port when this file is run directly (not when required by
// tests, which import the app without starting a real HTTP server).
let server;
if (require.main === module) {
  server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });

  // Graceful shutdown: finish in-flight requests, then drain the DB pool.
  const shutdown = async (signal) => {
    console.log(`[app] ${signal} received — shutting down gracefully…`);
    server.close(async () => {
      await closePool();
      console.log('[app] Clean shutdown complete.');
      process.exit(0);
    });
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT',  () => shutdown('SIGINT'));
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * The pg pool is mocked so these tests run without a real database.
 * Every branch of input validation, query construction, timing logs,
 * and error handling is exercised.
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the pool before requiring queries.js so it picks up the mock
// ---------------------------------------------------------------------------

// We keep a mutable reference so individual tests can change query behaviour.
const mockQuery = jest.fn();

jest.mock('./db', () => ({
  pool: { query: mockQuery },
  closePool: jest.fn(),
}));

const {
  getUserById,
  getAllUsers,
  searchUsers,
  _internal: { toPositiveInt, toSearchPattern, toOrderColumn, toOrderDir },
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Builds a mock pg QueryResult with the given rows. */
function mockResult(rows) {
  return { rows, rowCount: rows.length };
}

/** Attaches total_count to each row as the window function would. */
function withTotalCount(rows, total) {
  return rows.map((r) => ({ ...r, total_count: String(total) }));
}

// ---------------------------------------------------------------------------
// toPositiveInt
// ---------------------------------------------------------------------------

describe('toPositiveInt', () => {
  test('accepts a valid integer string', () => {
    expect(toPositiveInt('5', 'x')).toBe(5);
  });

  test('accepts a number', () => {
    expect(toPositiveInt(42, 'x')).toBe(42);
  });

  test('accepts the minimum boundary value', () => {
    expect(toPositiveInt(0, 'x', { min: 0 })).toBe(0);
  });

  test('accepts the maximum boundary value', () => {
    expect(toPositiveInt(100, 'x', { min: 1, max: 100 })).toBe(100);
  });

  test('throws on a non-integer string', () => {
    expect(() => toPositiveInt('abc', 'myParam')).toThrow(/"myParam" must be an integer/);
  });

  test('throws on a float', () => {
    expect(() => toPositiveInt(3.14, 'myParam')).toThrow(/"myParam" must be an integer/);
  });

  test('throws when value is below min', () => {
    expect(() => toPositiveInt(0, 'id', { min: 1 })).toThrow(/between 1/);
  });

  test('throws when value exceeds max', () => {
    expect(() => toPositiveInt(101, 'limit', { min: 1, max: 100 })).toThrow(/between 1 and 100/);
  });
});

// ---------------------------------------------------------------------------
// toSearchPattern
// ---------------------------------------------------------------------------

describe('toSearchPattern', () => {
  test('wraps a plain term in % wildcards', () => {
    expect(toSearchPattern('alice', 'q')).toBe('%alice%');
  });

  test('trims surrounding whitespace', () => {
    expect(toSearchPattern('  bob  ', 'q')).toBe('%bob%');
  });

  test('escapes SQL LIKE % metacharacter', () => {
    expect(toSearchPattern('100%', 'q')).toBe('%100\\%%');
  });

  test('escapes SQL LIKE _ metacharacter', () => {
    expect(toSearchPattern('a_b', 'q')).toBe('%a\\_b%');
  });

  test('escapes backslash escape character first to prevent double-escaping', () => {
    expect(toSearchPattern('a\\%b', 'q')).toBe('%a\\\\\\%b%');
  });

  test('throws when value is not a string', () => {
    expect(() => toSearchPattern(42, 'q')).toThrow(/"q" must be a string/);
  });

  test('throws on empty string', () => {
    expect(() => toSearchPattern('   ', 'q')).toThrow(/"q" must not be empty/);
  });

  test('throws when term exceeds 100 characters', () => {
    expect(() => toSearchPattern('x'.repeat(101), 'q')).toThrow(/at most 100 characters/);
  });

  test('accepts exactly 100 characters', () => {
    const term = 'a'.repeat(100);
    expect(toSearchPattern(term, 'q')).toBe(`%${term}%`);
  });
});

// ---------------------------------------------------------------------------
// toOrderColumn / toOrderDir
// ---------------------------------------------------------------------------

describe('toOrderColumn', () => {
  test.each(['id', 'name', 'email', 'created_at'])('accepts "%s"', (col) => {
    expect(toOrderColumn(col)).toBe(col);
  });

  test('is case-insensitive', () => {
    expect(toOrderColumn('NAME')).toBe('name');
  });

  test('defaults to "id" when falsy', () => {
    expect(toOrderColumn('')).toBe('id');
    expect(toOrderColumn(null)).toBe('id');
    expect(toOrderColumn(undefined)).toBe('id');
  });

  test('throws on an unknown column', () => {
    expect(() => toOrderColumn('password')).toThrow(/Invalid order column/);
  });

  test('rejects SQL injection attempt', () => {
    expect(() => toOrderColumn('id; DROP TABLE users')).toThrow(/Invalid order column/);
  });
});

describe('toOrderDir', () => {
  test.each(['ASC', 'DESC', 'asc', 'desc'])('accepts "%s"', (dir) => {
    expect(['ASC', 'DESC']).toContain(toOrderDir(dir));
  });

  test('throws on an unknown direction', () => {
    expect(() => toOrderDir('SIDEWAYS')).toThrow(/Invalid order direction/);
  });
});

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------

describe('getUserById', () => {
  afterEach(() => mockQuery.mockReset());

  test('returns the user row when found', async () => {
    const row = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() };
    mockQuery.mockResolvedValue(mockResult([row]));

    const user = await getUserById(1);

    expect(user).toEqual(row);
  });

  test('passes the ID as a parameter ($1)', async () => {
    mockQuery.mockResolvedValue(mockResult([]));

    await getUserById(7);

    expect(mockQuery).toHaveBeenCalledWith(
      expect.stringContaining('$1'),
      [7]
    );
  });

  test('returns null when user is not found', async () => {
    mockQuery.mockResolvedValue(mockResult([]));

    const user = await getUserById(999);

    expect(user).toBeNull();
  });

  test('rejects non-integer id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(/"id" must be an integer/);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects id < 1', async () => {
    await expect(getUserById(0)).rejects.toThrow(/between 1/);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('accepts a numeric string id', async () => {
    mockQuery.mockResolvedValue(mockResult([]));
    await expect(getUserById('42')).resolves.toBeNull();
    expect(mockQuery).toHaveBeenCalledWith(expect.any(String), [42]);
  });

  test('re-throws database errors', async () => {
    mockQuery.mockRejectedValue(new Error('connection refused'));
    await expect(getUserById(1)).rejects.toThrow('connection refused');
  });
});

// ---------------------------------------------------------------------------
// getAllUsers
// ---------------------------------------------------------------------------

describe('getAllUsers', () => {
  afterEach(() => mockQuery.mockReset());

  const baseRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date() },
  ];

  test('returns rows and total count', async () => {
    mockQuery.mockResolvedValue(mockResult(withTotalCount(baseRows, 2)));

    const result = await getAllUsers(20, 0);

    expect(result.rows).toHaveLength(2);
    expect(result.total).toBe(2);
  });

  test('strips total_count from individual row objects', async () => {
    mockQuery.mockResolvedValue(mockResult(withTotalCount(baseRows, 2)));

    const { rows } = await getAllUsers(20, 0);

    rows.forEach((r) => expect(r).not.toHaveProperty('total_count'));
  });

  test('passes limit and offset as parameters', async () => {
    mockQuery.mockResolvedValue(mockResult([]));

    await getAllUsers(10, 30);

    expect(mockQuery).toHaveBeenCalledWith(
      expect.stringContaining('$1'),
      [10, 30]
    );
  });

  test('interpolates the validated column (not user input) into ORDER BY', async () => {
    mockQuery.mockResolvedValue(mockResult([]));

    await getAllUsers(10, 0, 'name', 'DESC');

    const [sql] = mockQuery.mock.calls[0];
    expect(sql).toMatch(/ORDER BY name DESC/i);
  });

  test('returns total 0 when result set is empty', async () => {
    mockQuery.mockResolvedValue(mockResult([]));

    const result = await getAllUsers(10, 0);

    expect(result.total).toBe(0);
    expect(result.rows).toEqual([]);
  });

  test('rejects limit > 100', async () => {
    await expect(getAllUsers(101, 0)).rejects.toThrow(/between 1 and 100/);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects limit < 1', async () => {
    await expect(getAllUsers(0, 0)).rejects.toThrow(/between 1 and 100/);
  });

  test('rejects negative offset', async () => {
    await expect(getAllUsers(10, -1)).rejects.toThrow(/between 0/);
  });

  test('rejects invalid orderBy column', async () => {
    await expect(getAllUsers(10, 0, 'password')).rejects.toThrow(/Invalid order column/);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects SQL-injection attempt in orderBy', async () => {
    await expect(getAllUsers(10, 0, '1; DROP TABLE users--')).rejects.toThrow(/Invalid order column/);
  });

  test('rejects invalid order direction', async () => {
    await expect(getAllUsers(10, 0, 'id', 'SIDEWAYS')).rejects.toThrow(/Invalid order direction/);
  });

  test('re-throws database errors', async () => {
    mockQuery.mockRejectedValue(new Error('deadlock'));
    await expect(getAllUsers(10, 0)).rejects.toThrow('deadlock');
  });
});

// ---------------------------------------------------------------------------
// searchUsers
// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  afterEach(() => mockQuery.mockReset());

  const matchingRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() },
  ];

  test('returns matching rows and total', async () => {
    mockQuery.mockResolvedValue(mockResult(withTotalCount(matchingRows, 1)));

    const result = await searchUsers('alice');

    expect(result.rows).toHaveLength(1);
    expect(result.total).toBe(1);
  });

  test('strips total_count from individual row objects', async () => {
    mockQuery.mockResolvedValue(mockResult(withTotalCount(matchingRows, 1)));

    const { rows } = await searchUsers('alice');

    rows.forEach((r) => expect(r).not.toHaveProperty('total_count'));
  });

  test('wraps the search term in % wildcards', async () => {
    mockQuery.mockResolvedValue(mockResult([]));

    await searchUsers('ali', 10, 0);

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%ali%');
  });

  test('escapes % in search term', async () => {
    mockQuery.mockResolvedValue(mockResult([]));

    await searchUsers('100%', 10, 0);

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%100\\%%');
  });

  test('escapes _ in search term', async () => {
    mockQuery.mockResolvedValue(mockResult([]));

    await searchUsers('a_b', 10, 0);

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%a\\_b%');
  });

  test('passes limit and offset as $2 and $3', async () => {
    mockQuery.mockResolvedValue(mockResult([]));

    await searchUsers('bob', 15, 30);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(sql).toMatch(/\$2/);
    expect(sql).toMatch(/\$3/);
    expect(params[1]).toBe(15);
    expect(params[2]).toBe(30);
  });

