  const safeId = toPositiveInt(id, 'id', { min: 1 });

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
