/**
 * app.js — Express application
 *
 * /users routes now delegate all database access to queries.js.
 * The route handlers are responsible only for:
 *   1. Parsing / coercing HTTP parameters.
 *   2. Calling the appropriate query function.
 *   3. Mapping the result (or a validation error) to an HTTP response.
 *
 * They never construct SQL or touch the pool directly.
 */

'use strict';

require('dotenv').config(); // Load .env into process.env before anything else

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');
const { closePool } = require('./db');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler and forwards any unhandled rejection to the
 * Express error-handling middleware via next(err).
 *
 * @param {Function} fn - Async (req, res, next) handler.
 * @returns {Function}
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users
// Query-string params:
//   search  – substring search across name and email
//   limit   – page size  (1–100, default 20)
//   offset  – page start (≥ 0,   default 0)
//   orderBy – column to sort by (id | name | email | created_at, default id)
//   order   – sort direction    (asc | desc, default asc)
// ---------------------------------------------------------------------------
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    const { search, limit = 20, offset = 0, orderBy = 'id', order = 'asc' } = req.query;

    let data;
    if (search !== undefined) {
      // Delegate to searchUsers; validation happens inside queries.js.
      data = await searchUsers(search, limit, offset);
    } else {
      data = await getAllUsers(limit, offset, orderBy, order);
    }

    res.json({
      data:   data.rows,
      total:  data.total,
      limit:  Number(limit),
      offset: Number(offset),
    });
  })
);

// ---------------------------------------------------------------------------
// GET /users/:id
// ---------------------------------------------------------------------------
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ data: user });
  })
);

// ---------------------------------------------------------------------------
// Centralised error handler
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Input validation errors (TypeError thrown by query helpers)
  if (err instanceof TypeError) {
    return res.status(400).json({ error: err.message });
  }

  // Database / unexpected errors — do not leak internal details in production
  const message =
    process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message;

  console.error('[app] Unhandled error:', err);
  res.status(500).json({ error: message });
});

