// Server startup / graceful shutdown
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT || '3000', 10);

// Only bind the port when this file is run directly (not when required by
// tests, which import the app without starting a real HTTP server).
let server;
if (require.main === module) {
  server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });

  // Graceful shutdown: finish in-flight requests, then drain the DB pool.
  const shutdown = async (signal) => {
    console.log(`[app] ${signal} received — shutting down gracefully…`);
    server.close(async () => {
      await closePool();
      console.log('[app] Clean shutdown complete.');
      process.exit(0);
    });
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT',  () => shutdown('SIGINT'));
}

module.exports = app;

