/**
 * db.js — PostgreSQL connection pool (singleton)
 *
 * Exports a single `pg.Pool` instance that is shared across the entire
 * process.  All configuration is read from environment variables so that
 * no credentials ever live in source code.
 *
 * Required env vars (set in .env for local dev, real env in production):
 *   PGHOST, PGPORT, PGDATABASE, PGUSER, PGPASSWORD
 *   — OR —
 *   DATABASE_URL   (overrides the individual vars when present)
 *
 * Optional tuning env vars (sensible defaults shown):
 *   DB_POOL_MAX          default 10   – max simultaneous connections
 *   DB_POOL_IDLE_TIMEOUT default 30000 – ms before idle client is closed
 *   DB_POOL_CONN_TIMEOUT default 5000  – ms to wait for a free client
 *   DB_SSL               default false – set to "true" in production
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Build pool configuration from environment — zero hard-coded values
// ---------------------------------------------------------------------------
const isSSL = process.env.DB_SSL === 'true';

const poolConfig = {
  // If DATABASE_URL is provided it takes full precedence; otherwise the
  // standard PG* vars (PGHOST, PGPORT, etc.) are picked up automatically
  // by the `pg` library without us needing to read them explicitly here.
  ...(process.env.DATABASE_URL && { connectionString: process.env.DATABASE_URL }),

  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT ?? '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN_TIMEOUT ?? '5000', 10),

  // In production always require SSL; in test/dev allow plain connections.
  ssl: isSSL ? { rejectUnauthorized: true } : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event handlers — log unexpected errors so they are never silent
// ---------------------------------------------------------------------------
pool.on('connect', (client) => {
  // Enforce a statement timeout per connection so runaway queries cannot
  // block the pool indefinitely (10 s default, overridable via env var).
  const statementTimeout = process.env.DB_STATEMENT_TIMEOUT ?? '10000';
  client
    .query(`SET statement_timeout = ${parseInt(statementTimeout, 10)}`)
    .catch((err) =>
      console.error('[db] Failed to set statement_timeout:', err.message)
    );
});

pool.on('error', (err) => {
  // A client has errored while sitting idle in the pool.  Log it so we get
  // visibility without crashing the process.
  console.error('[db] Unexpected idle-client error:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown — drain the pool when the process is asked to stop
// ---------------------------------------------------------------------------
const shutdown = async (signal) => {
  console.log(`[db] Received ${signal} — draining connection pool…`);
  try {
    await pool.end();
    console.log('[db] Pool drained. Goodbye.');
  } catch (err) {
    console.error('[db] Error while draining pool:', err.message);
  }
};

process.once('SIGINT', () => shutdown('SIGINT'));
process.once('SIGTERM', () => shutdown('SIGTERM'));

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * ─────────────────
 * 1. SQL injection prevention
 *    Every piece of user-supplied data is passed as a *parameter* ($1, $2 …)
 *    and never interpolated into the SQL string.  `pg` sends parameters in a
 *    separate wire-protocol field so the database always treats them as data,
 *    not as SQL syntax — regardless of what characters the value contains.
 *
 * 2. Input validation before the query even reaches the database
 *    Parameters are validated (type-checked, range-checked, length-capped)
 *    and sanitised before being handed to `pg`.  This provides defence-in-
 *    depth: the parameterised query is the primary guard; validation is the
 *    secondary one.
 *
 * 3. Connection pooling
 *    All functions borrow a client from the shared pool in db.js rather than
 *    opening a new TCP connection for every request.
 *
 * 4. Query timing
 *    Every function measures wall-clock time from pool-checkout to result and
 *    emits a structured timing log on completion (and on error).
 *
 * 5. Predictable error surface
 *    Validation errors throw a `QueryValidationError` (HTTP-mappable to 400).
 *    Database errors bubble up as-is so callers can distinguish them from
 *    validation failures.
 */

'use strict';

const pool = require('./db');

// ─────────────────────────────────────────────────────────────────────────────
// Custom error type — lets route handlers return precise HTTP status codes
// ─────────────────────────────────────────────────────────────────────────────

class QueryValidationError extends Error {
  /**
   * @param {string} message  Human-readable reason.
   * @param {string} field    The parameter that failed validation.
   */
  constructor(message, field) {
    super(message);
    this.name = 'QueryValidationError';
    this.field = field;
    // Preserve a clean stack even when V8 optimises the constructor away
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, QueryValidationError);
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Internal helpers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * logTiming — emit a structured JSON timing line to stdout.
 *
 * Using a structured format (rather than free-form text) means the lines can
 * be ingested by log aggregators (Datadog, CloudWatch, etc.) without extra
 * parsing rules.
 *
 * @param {string}  fnName      Name of the query function.
 * @param {number}  startMs     `Date.now()` captured before the query ran.
 * @param {boolean} success     Whether the query completed without error.
 * @param {object}  [meta={}]   Optional extra context (rowCount, etc.).
 */
function logTiming(fnName, startMs, success, meta = {}) {
  const durationMs = Date.now() - startMs;
  const entry = {
    level: success ? 'info' : 'error',
    type: 'db_query',
    fn: fnName,
    durationMs,
    success,
    ...meta,
    ts: new Date().toISOString(),
  };
  // Use the appropriate console method so log-level filters work correctly
  if (success) {
    console.log(JSON.stringify(entry));
  } else {
    console.error(JSON.stringify(entry));
  }
}

/**
 * runQuery — thin wrapper around pool.query that handles timing and logging.
 *
 * Accepts the same arguments as `pool.query(text, values)` and adds:
 *   - Wall-clock timing from the moment the call is made (includes the time
 *     spent waiting for a free pool connection).
 *   - A structured timing log on both success and failure.
 *
 * @param {string}   fnName   Caller name (used in logs).
 * @param {string}   text     Parameterised SQL string.
 * @param {any[]}    values   Bound parameter values.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function runQuery(fnName, text, values) {
  const startMs = Date.now();
  try {
    const result = await pool.query(text, values);
    logTiming(fnName, startMs, true, { rowCount: result.rowCount });
    return result;
  } catch (err) {
    logTiming(fnName, startMs, false, { error: err.message });
    throw err; // re-throw so the caller can handle / convert to HTTP error
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Input validation helpers — applied before every query
// ─────────────────────────────────────────────────────────────────────────────

/**
 * validateId — ensure `id` is a positive integer.
 * @param {*} id
 * @throws {QueryValidationError}
 */
function validateId(id) {
  const parsed = Number(id);
  if (!Number.isInteger(parsed) || parsed < 1) {
    throw new QueryValidationError(
      `id must be a positive integer, received: ${JSON.stringify(id)}`,
      'id'
    );
  }
  return parsed; // return the coerced numeric value
}

/**
 * validatePagination — ensure limit/offset are non-negative integers and
 * that limit does not exceed a configurable cap (default 100).
 * @param {*} limit
 * @param {*} offset
 * @throws {QueryValidationError}
 */
function validatePagination(limit, offset) {
  const maxLimit = parseInt(process.env.QUERY_MAX_LIMIT ?? '100', 10);

  const parsedLimit = Number(limit);
  if (!Number.isInteger(parsedLimit) || parsedLimit < 1) {
    throw new QueryValidationError(
      `limit must be a positive integer, received: ${JSON.stringify(limit)}`,
      'limit'
    );
  }
  if (parsedLimit > maxLimit) {
    throw new QueryValidationError(
      `limit must not exceed ${maxLimit}, received: ${parsedLimit}`,
      'limit'
    );
  }

  const parsedOffset = Number(offset);
  if (!Number.isInteger(parsedOffset) || parsedOffset < 0) {
    throw new QueryValidationError(
      `offset must be a non-negative integer, received: ${JSON.stringify(offset)}`,
      'offset'
    );
  }

  return { limit: parsedLimit, offset: parsedOffset };
}

/**
 * validateSearchQuery — ensure the search string is a non-empty string within
 * a safe length.  We do *not* strip or escape special characters because `pg`
 * handles that — but we do reject empty strings and over-long values early.
 * @param {*} query
 * @throws {QueryValidationError}
 */
function validateSearchQuery(query) {
  if (typeof query !== 'string') {
    throw new QueryValidationError(
      `query must be a string, received: ${typeof query}`,
      'query'
    );
  }
  const trimmed = query.trim();
  if (trimmed.length === 0) {
    throw new QueryValidationError(
      'query must not be empty or whitespace-only',
      'query'
    );
  }
  // Cap length to prevent extremely large LIKE patterns from doing
  // unnecessary work at the database level.
  const maxLen = parseInt(process.env.QUERY_SEARCH_MAX_LEN ?? '200', 10);
  if (trimmed.length > maxLen) {
    throw new QueryValidationError(
      `query must not exceed ${maxLen} characters`,
      'query'
    );
  }
  return trimmed;
}

// ─────────────────────────────────────────────────────────────────────────────
// Public query functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * getUserById — fetch a single user row by primary key.
 *
 * SQL injection prevention
 * ────────────────────────
 * The `id` is passed as `$1` (a bound parameter), never concatenated into the
 * query string.  Additionally, `validateId()` guarantees it is a positive
 * integer before it even reaches the database driver.
 *
 * @param {number|string} id  The user's primary key.
 * @returns {Promise<object|null>}  The user row, or null if not found.
 * @throws {QueryValidationError}   If `id` is not a positive integer.
 */
async function getUserById(id) {
  const safeId = validateId(id);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await runQuery('getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
}

/**
 * getAllUsers — fetch a page of users ordered by primary key.
 *
 * SQL injection prevention
 * ────────────────────────
 * Both `limit` and `offset` are passed as bound parameters (`$1`, `$2`).
 * `validatePagination()` additionally enforces that both are non-negative
 * integers and that `limit` does not exceed the configured maximum.
 *
 * @param {number} limit   Maximum rows to return (1 – QUERY_MAX_LIMIT).
 * @param {number} offset  Number of rows to skip (for pagination).
 * @returns {Promise<{ users: object[], total: number }>}
 * @throws {QueryValidationError}  If limit or offset are invalid.
 */
async function getAllUsers(limit, offset) {
  const { limit: safeLimit, offset: safeOffset } = validatePagination(
    limit,
    offset
  );

  // Fetch the page and the total count in a single round-trip using a
  // window function so callers can build pagination metadata without an
  // extra query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const result = await runQuery('getAllUsers', sql, [safeLimit, safeOffset]);

  // Parse total_count (pg returns it as a string) only once
  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  // Strip the internal total_count column before returning to callers
  const users = result.rows.map(({ total_count, ...user }) => user);

  return { users, total };
}

/**
 * searchUsers — full-text LIKE search across `name` and `email`.
 *
 * SQL injection prevention
 * ────────────────────────
 * The search term is passed as the bound parameter `$1`.  LIKE special
 * characters (`%`, `_`, `\`) inside the term are *escaped* before binding so
 * that a user cannot craft a pattern that matches unintended rows or causes
 * an excessively expensive scan (e.g. passing `%` alone to dump every row).
 *
 * Because the wildcards are added by *our* code (not by the caller) the
 * search behaves as a simple substring match, which is the intent.
 *
 * Pagination is also parameterised (`$2`, `$3`).
 *
 * @param {string} query   Substring to search for in name / email.
 * @param {number} [limit=20]   Max rows to return.
 * @param {number} [offset=0]   Rows to skip.
 * @returns {Promise<{ users: object[], total: number }>}
 * @throws {QueryValidationError}  If query, limit, or offset are invalid.
 */
async function searchUsers(query, limit = 20, offset = 0) {
  const safeQuery = validateSearchQuery(query);
  const { limit: safeLimit, offset: safeOffset } = validatePagination(
    limit,
    offset
  );

  // Escape LIKE metacharacters so that user input is treated as a literal
  // substring, not as a pattern.  This is a second line of defence on top
  // of parameterised queries — it prevents unexpected wildcard expansion.
  const escapedQuery = safeQuery
    .replace(/\\/g, '\\\\') // escape backslash first (must be first)
    .replace(/%/g, '\\%')   // escape percent
    .replace(/_/g, '\\_');  // escape underscore

  // Wrap in SQL wildcards *here*, not in user input
  const likePattern = `%${escapedQuery}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1
      OR
      email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const result = await runQuery('searchUsers', sql, [
    likePattern,
    safeLimit,
    safeOffset,
  ]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  const users = result.rows.map(({ total_count, ...user }) => user);

  return { users, total };
}

// ─────────────────────────────────────────────────────────────────────────────
// Exports
// ─────────────────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError, // exported so route handlers can instanceof-check it
};

// app.js — Express application wired to the PostgreSQL query layer
//
// The /users endpoint now supports three query modes:
//   GET /users              → getAllUsers   (paginated list)
//   GET /users?search=bob   → searchUsers   (substring match on name / email)
//   GET /users/:id          → getUserById   (single user by primary key)
//
// All database interaction goes through queries.js which enforces:
//   - Parameterised SQL (primary SQL-injection guard)
//   - Input validation  (secondary guard + clear 400 responses)
//   - Connection pooling via a shared pg.Pool
//   - Per-query wall-clock timing logs

'use strict';

const express = require('express');

// Load .env file in development/test; no-op if the file is absent (production
// environments inject vars through the process environment directly).
require('dotenv').config();

const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
} = require('./queries');

const app = express();
app.use(express.json());

// ─────────────────────────────────────────────────────────────────────────────
// Helper — convert a QueryValidationError or unexpected Error into a response
// ─────────────────────────────────────────────────────────────────────────────

/**
 * handleQueryError — send a structured error response.
 *
 * - QueryValidationError  → 400 Bad Request  (safe to expose to the client)
 * - Everything else       → 500 Internal Server Error (message hidden from
 *   the client to avoid leaking implementation details or stack traces)
 *
 * @param {Error}   err  The error to handle.
 * @param {object}  res  Express response object.
 * @param {string}  ctx  Short description of what was being attempted (logs).
 */
function handleQueryError(err, res, ctx) {
  if (err instanceof QueryValidationError) {
    return res.status(400).json({
      error: 'Bad Request',
      message: err.message,
      field: err.field,
    });
  }

  // Log the real error server-side but never expose it to the client
  console.error(`[app] Unexpected error in ${ctx}:`, err);
  return res.status(500).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred. Please try again later.',
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// GET /health
// ─────────────────────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /users — list or search users (paginated)
//
// Query parameters
//   search  {string}  Substring to match against name or email.
//   limit   {number}  Max rows per page (default: 20, max: 100).
//   offset  {number}  Rows to skip      (default: 0).
//
// Examples
//   GET /users
//   GET /users?limit=10&offset=20
//   GET /users?search=alice&limit=5
// ─────────────────────────────────────────────────────────────────────────────

app.get('/users', async (req, res) => {
  const { search, limit = '20', offset = '0' } = req.query;

  try {
    let result;

    if (search !== undefined) {
      // searchUsers: substring match against name and email
      result = await searchUsers(search, limit, offset);
    } else {
      // getAllUsers: full paginated listing
      result = await getAllUsers(limit, offset);
    }

    return res.json({
      data: result.users,
      pagination: {
        total: result.total,
        limit: Number(limit),
        offset: Number(offset),
      },
    });
  } catch (err) {
    return handleQueryError(err, res, 'GET /users');
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /users/:id — retrieve a single user by primary key
//
// Examples
//   GET /users/1
//   GET /users/42
// ─────────────────────────────────────────────────────────────────────────────

app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (user === null) {
      return res.status(404).json({
        error: 'Not Found',
        message: `No user found with id ${req.params.id}`,
      });
    }

    return res.json({ data: user });
  } catch (err) {
    return handleQueryError(err, res, 'GET /users/:id');
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// Start server (skipped when the module is require()'d by tests)
// ─────────────────────────────────────────────────────────────────────────────

if (require.main === module) {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * The database pool (db.js / pg) is mocked so these tests are fully
 * self-contained and run without a live Postgres instance.
 *
 * Coverage:
 *   getUserById   – happy path, not-found, invalid id variants
 *   getAllUsers   – happy path with pagination metadata, validation errors
 *   searchUsers   – happy path, LIKE metachar escaping, empty/long query
 *   SQL injection – confirms user input always lands in the values array,
 *                   never in the SQL string
 */

'use strict';

// ─── Mock pg pool ────────────────────────────────────────────────────────────
// We intercept require('pg') before queries.js loads so that no real
// database connection is ever attempted.

const mockQuery = jest.fn();
const mockPoolOn = jest.fn();
const mockPoolEnd = jest.fn().mockResolvedValue();

jest.mock('pg', () => {
  return {
    Pool: jest.fn().mockImplementation(() => ({
      query: mockQuery,
      on: mockPoolOn,
      end: mockPoolEnd,
    })),
  };
});

// Also mock db.js so we fully control the pool handed to queries.js
jest.mock('./db', () => ({
  query: mockQuery,
  on: mockPoolOn,
  end: mockPoolEnd,
}));

const {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,
} = require('./queries');

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Build a fake pg QueryResult */
function makeResult(rows = [], rowCount = rows.length) {
  return { rows, rowCount };
}

/** Build a fake user row (includes the total_count window column) */
function fakeUser(overrides = {}, totalCount = 2) {
  return {
    id: 1,
    name: 'Alice',
    email: 'alice@example.com',
    created_at: new Date('2024-01-01'),
    updated_at: new Date('2024-06-01'),
    total_count: String(totalCount),
    ...overrides,
  };
}

beforeEach(() => {
  jest.clearAllMocks();
});

// ─────────────────────────────────────────────────────────────────────────────
// getUserById
// ─────────────────────────────────────────────────────────────────────────────

describe('getUserById', () => {
  test('returns the user row when found', async () => {
    const row = { id: 1, name: 'Alice', email: 'alice@example.com',
                  created_at: new Date(), updated_at: new Date() };
    mockQuery.mockResolvedValueOnce(makeResult([row]));

    const result = await getUserById(1);
    expect(result).toEqual(row);
  });

  test('returns null when no row is found', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    const result = await getUserById(999);
    expect(result).toBeNull();
  });

  test('passes id as a bound parameter, not in the SQL string', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    await getUserById(42);

    const [sql, values] = mockQuery.mock.calls[0];
    // The SQL text must NOT contain the literal id value
    expect(sql).not.toContain('42');
    // The value must appear in the parameters array
    expect(values).toContain(42);
    // The SQL placeholder must be present
    expect(sql).toContain('$1');
  });

  // ── Validation ──────────────────────────────────────────────────────────

  test.each([
    ['a string', 'abc'],
    ['zero',      0],
    ['negative',  -5],
    ['float',     1.5],
    ['null',      null],
    ['undefined', undefined],
    ['object',    {}],
    ['SQL fragment', "1; DROP TABLE users--"],
  ])('throws QueryValidationError for invalid id: %s', async (_, badId) => {
    await expect(getUserById(badId)).rejects.toThrow(QueryValidationError);
    // Must not reach the database
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('accepts a numeric string that coerces to a valid integer', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    await expect(getUserById('7')).resolves.toBeNull();
    expect(mockQuery).toHaveBeenCalledTimes(1);
    expect(mockQuery.mock.calls[0][1]).toContain(7);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// getAllUsers
// ─────────────────────────────────────────────────────────────────────────────

describe('getAllUsers', () => {
  test('returns users array and correct total', async () => {
    const rows = [fakeUser({ id: 1 }, 2), fakeUser({ id: 2, name: 'Bob' }, 2)];
    mockQuery.mockResolvedValueOnce(makeResult(rows));

    const { users, total } = await getAllUsers(20, 0);
    expect(total).toBe(2);
    expect(users).toHaveLength(2);
    // total_count must be stripped from each row
    users.forEach((u) => expect(u).not.toHaveProperty('total_count'));
  });

  test('returns empty array and total 0 when no rows', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    const { users, total } = await getAllUsers(20, 0);
    expect(users).toEqual([]);
    expect(total).toBe(0);
  });

  test('passes limit and offset as bound parameters', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    await getAllUsers(10, 30);

    const [sql, values] = mockQuery.mock.calls[0];
    expect(sql).toContain('$1');
    expect(sql).toContain('$2');
    expect(values).toEqual([10, 30]);
    // Literal numbers must not be interpolated into the SQL string
    expect(sql).not.toMatch(/LIMIT\s+10/);
    expect(sql).not.toMatch(/OFFSET\s+30/);
  });

  // ── Validation ──────────────────────────────────────────────────────────

  test('throws QueryValidationError for limit = 0', async () => {
    await expect(getAllUsers(0, 0)).rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryValidationError when limit exceeds maximum', async () => {
    await expect(getAllUsers(101, 0)).rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryValidationError for negative offset', async () => {
    await expect(getAllUsers(10, -1)).rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryValidationError for non-numeric limit', async () => {
    await expect(getAllUsers('many', 0)).rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryValidationError for float limit', async () => {
    await expect(getAllUsers(10.5, 0)).rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// searchUsers
// ─────────────────────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  test('returns matching users and total', async () => {
    const rows = [fakeUser({ name: 'Alice' }, 1)];
    mockQuery.mockResolvedValueOnce(makeResult(rows));

    const { users, total } = await searchUsers('alice');
    expect(total).toBe(1);
    expect(users[0].name).toBe('Alice');
    users.forEach((u) => expect(u).not.toHaveProperty('total_count'));
  });

  test('passes search term as a bound parameter, not in SQL string', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    await searchUsers('alice');

    const [sql, values] = mockQuery.mock.calls[0];
    // The raw search term (or the wrapped pattern) must be in values
    expect(values[0]).toContain('alice');
    // It must NOT be hard-coded into the SQL text
    expect(sql).not.toContain('alice');
    expect(sql).toContain('$1');
  });

  test('wraps the search term in % wildcards', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    await searchUsers('bob');

    const [, values] = mockQuery.mock.calls[0];
    expect(values[0]).toBe('%bob%');
  });

  // ── LIKE metacharacter escaping ─────────────────────────────────────────

  test('escapes % in search term to prevent wildcard injection', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    await searchUsers('%admin%');

    const [, values] = mockQuery.mock.calls[0];
    // % characters in user input must be escaped; our own wrapping % must remain
    expect(values[0]).toBe('%\\%admin\\%%');
  });

  test('escapes _ in search term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    await searchUsers('user_name');

    const [, values] = mockQuery.mock.calls[0];
    expect(values[0]).toBe('%user\\_name%');
  });

  test('escapes backslash in search term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    await searchUsers('C:\\path');

    const [, values] = mockQuery.mock.calls[0];
    expect(values[0]).toBe('%C:\\\\path%');
  });

  test('trims leading/trailing whitespace from search term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    await searchUsers('  alice  ');

    const [, values] = mockQuery.mock.calls[0];
    expect(values[0]).toBe('%alice%');
  });

  // ── Validation ──────────────────────────────────────────────────────────

  test('throws QueryValidationError for empty string', async () => {
    await expect(searchUsers('')).rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryValidationError for whitespace-only string', async () => {
    await expect(searchUsers('   ')).rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryValidationError for non-string input', async () => {
    await expect(searchUsers(42)).rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws QueryValidationError for excessively long query', async () => {
    const longQuery = 'a'.repeat(201);
    await expect(searchUsers(longQuery)).rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('inherits pagination validation from validatePagination', async () => {
    await expect(searchUsers('alice', -1, 0)).rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// SQL-injection probe suite
// Tests that injection strings in *any* parameter never contaminate the SQL.
// ─────────────────────────────────────────────────────────────────────────────

describe('SQL injection prevention', () => {
  const injectionStrings = [
    "'; DROP TABLE users; --",
    "1 OR 1=1",
    "1; SELECT * FROM pg_tables; --",
    "' UNION SELECT password FROM admins --",
    "\\' OR \\'1\\'=\\'1",
    "%'; DELETE FROM users WHERE 't' = 't",
  ];

  test.each(injectionStrings)(
    'searchUsers: injection attempt "%s" stays in values, not SQL',
    async (injection) => {
      mockQuery.mockResolvedValueOnce(makeResult([]));
      // searchUsers validates the string; only strings without special
      // pg validation concerns will reach the query.  We care that whatever
      // reaches the DB driver lands in values[], not the SQL string.
      try {
        await searchUsers(injection);
        const [sql, values] = mockQuery.mock.calls[0];
        expect(sql).not.toContain(injection.trim());
        expect(values[0]).toContain(injection.trim().replace(/\\/g, '\\\\')
                                               .replace(/%/g, '\\%')
                                               .replace(/_/g, '\\_'));
      } catch (e) {
        // If validation rejects it that is also acceptable — the DB was not hit
        expect(e).toBeInstanceOf(QueryValidationError);
        expect(mockQuery).not.toHaveBeenCalled();
      }
    }
  );

  test('getUserById: SQL fragment in id is rejected before reaching DB', async () => {
    await expect(getUserById("1; DROP TABLE users--"))
      .rejects.toThrow(QueryValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// QueryValidationError shape
// ─────────────────────────────────────────────────────────────────────────────

describe('QueryValidationError', () => {
  test('has correct name, message and field properties', () => {
    const err = new QueryValidationError('bad input', 'id');
    expect(err).toBeInstanceOf(Error);
    expect(err).toBeInstanceOf(QueryValidationError);
    expect(err.name).toBe('QueryValidationError');
    expect(err.message).toBe('bad input');
    expect(err.field).toBe('id');
  });
});

