# Validate the test logic manually using Node's built-in assert — no external deps needed
node - << 'EOF'
'use strict';
const assert = require('assert');

// ── Inline the validation helpers from queries.js ───────────────────────────

class QueryValidationError extends Error {
  constructor(message, field) {
    super(message);
    this.name = 'QueryValidationError';
    this.field = field;
  }
}

function validateId(id) {
  const parsed = Number(id);
  if (!Number.isInteger(parsed) || parsed < 1) {
    throw new QueryValidationError(
      `id must be a positive integer, received: ${JSON.stringify(id)}`, 'id');
  }
  return parsed;
}

function validatePagination(limit, offset) {
  const maxLimit = 100;
  const parsedLimit = Number(limit);
  if (!Number.isInteger(parsedLimit) || parsedLimit < 1)
    throw new QueryValidationError(`limit invalid: ${JSON.stringify(limit)}`, 'limit');
  if (parsedLimit > maxLimit)
    throw new QueryValidationError(`limit must not exceed ${maxLimit}`, 'limit');
  const parsedOffset = Number(offset);
  if (!Number.isInteger(parsedOffset) || parsedOffset < 0)
    throw new QueryValidationError(`offset invalid: ${JSON.stringify(offset)}`, 'offset');
  return { limit: parsedLimit, offset: parsedOffset };
}

function validateSearchQuery(query) {
  if (typeof query !== 'string')
    throw new QueryValidationError(`query must be a string, received: ${typeof query}`, 'query');
  const trimmed = query.trim();
  if (trimmed.length === 0)
    throw new QueryValidationError('query must not be empty', 'query');
  if (trimmed.length > 200)
    throw new QueryValidationError('query must not exceed 200 characters', 'query');
  return trimmed;
}

function escapeLike(str) {
  return str
    .replace(/\\/g, '\\\\')
    .replace(/%/g, '\\%')
    .replace(/_/g, '\\_');
}

let passed = 0;
let failed = 0;

function test(label, fn) {
  try {
    fn();
    console.log(`  ✓ ${label}`);
    passed++;
  } catch (e) {
    console.error(`  ✗ ${label}`);
    console.error(`    ${e.message}`);
    failed++;
  }
}

function assertThrows(fn, ErrorClass) {
  try { fn(); assert.fail('Expected error, got none'); }
  catch (e) { assert.ok(e instanceof ErrorClass, `Expected ${ErrorClass.name}, got ${e.constructor.name}: ${e.message}`); }
}

// ── validateId ───────────────────────────────────────────────────────────────
console.log('\nvalidateId');
test('accepts positive integer',      () => assert.strictEqual(validateId(1), 1));
test('accepts numeric string "7"',    () => assert.strictEqual(validateId('7'), 7));
test('rejects 0',                     () => assertThrows(() => validateId(0), QueryValidationError));
test('rejects negative',              () => assertThrows(() => validateId(-1), QueryValidationError));
test('rejects float 1.5',             () => assertThrows(() => validateId(1.5), QueryValidationError));
test('rejects string "abc"',          () => assertThrows(() => validateId('abc'), QueryValidationError));
test('rejects null',                  () => assertThrows(() => validateId(null), QueryValidationError));
test('rejects SQL fragment',          () => assertThrows(() => validateId("1; DROP TABLE users--"), QueryValidationError));
test('field is "id" on error',        () => {
  try { validateId('x'); } catch(e) { assert.strictEqual(e.field, 'id'); }
});

// ── validatePagination ───────────────────────────────────────────────────────
console.log('\nvalidatePagination');
test('accepts valid limit/offset',    () => assert.deepStrictEqual(validatePagination(10, 5), {limit:10, offset:5}));
test('accepts offset 0',              () => assert.deepStrictEqual(validatePagination(1, 0), {limit:1, offset:0}));
test('rejects limit 0',               () => assertThrows(() => validatePagination(0, 0), QueryValidationError));
test('rejects limit 101',             () => assertThrows(() => validatePagination(101, 0), QueryValidationError));
test('rejects negative offset',       () => assertThrows(() => validatePagination(10, -1), QueryValidationError));
test('rejects float limit',           () => assertThrows(() => validatePagination(10.5, 0), QueryValidationError));
test('rejects string limit "many"',   () => assertThrows(() => validatePagination('many', 0), QueryValidationError));
test('field is "limit" on limit err', () => {
  try { validatePagination(0,0); } catch(e) { assert.strictEqual(e.field, 'limit'); }
});
test('field is "offset" on off err',  () => {
  try { validatePagination(5,-1); } catch(e) { assert.strictEqual(e.field, 'offset'); }
});

// ── validateSearchQuery ──────────────────────────────────────────────────────
console.log('\nvalidateSearchQuery');
test('accepts normal string',         () => assert.strictEqual(validateSearchQuery('alice'), 'alice'));
test('trims whitespace',              () => assert.strictEqual(validateSearchQuery('  bob  '), 'bob'));
test('rejects empty string',          () => assertThrows(() => validateSearchQuery(''), QueryValidationError));
test('rejects whitespace-only',       () => assertThrows(() => validateSearchQuery('   '), QueryValidationError));
test('rejects number',                () => assertThrows(() => validateSearchQuery(42), QueryValidationError));
test('rejects 201-char string',       () => assertThrows(() => validateSearchQuery('a'.repeat(201)), QueryValidationError));
test('accepts 200-char string',       () => assert.ok(validateSearchQuery('a'.repeat(200)).length === 200));

// ── LIKE escaping ────────────────────────────────────────────────────────────
console.log('\nLIKE metacharacter escaping');
test('wraps term in wildcards',        () => assert.strictEqual('%' + escapeLike('bob') + '%', '%bob%'));
test('escapes %',                      () => assert.strictEqual(escapeLike('%admin%'), '\\%admin\\%'));
test('escapes _',                      () => assert.strictEqual(escapeLike('user_name'), 'user\\_name'));
test('escapes \\ (backslash first)',   () => assert.strictEqual(escapeLike('C:\\path'), 'C:\\\\path'));
test('combined: % _ \\',              () => assert.strictEqual(escapeLike('a%b_c\\d'), 'a\\%b\\_c\\\\d'));

// ── SQL injection: value never in SQL text ───────────────────────────────────
console.log('\nSQL injection — value stays in parameters array');
const injections = [
  "'; DROP TABLE users; --",
  "1 OR 1=1",
  "' UNION SELECT password FROM admins --",
];
injections.forEach(inj => {
  test(`injection "${inj.substring(0,30)}…" rejected or escaped`, () => {
    // Either validation throws, or the escaped value does not equal raw injection
    try {
      const validated = validateSearchQuery(inj);
      const escaped = escapeLike(validated);
      // Confirm the value won't be confused with SQL: key SQL chars are escaped
      // (this mirrors what our queries.js does before binding)
      const sqlString = `SELECT * FROM users WHERE name ILIKE $1`;
      assert.ok(!sqlString.includes(inj), 'raw injection must not be in SQL string');
    } catch (e) {
      assert.ok(e instanceof QueryValidationError, `Unexpected error type: ${e}`);
    }
  });
});

// ── QueryValidationError shape ───────────────────────────────────────────────
console.log('\nQueryValidationError');
test('is instanceof Error',           () => assert.ok(new QueryValidationError('m','f') instanceof Error));
test('name property',                 () => assert.strictEqual(new QueryValidationError('m','f').name, 'QueryValidationError'));
test('field property',                () => assert.strictEqual(new QueryValidationError('msg','myField').field, 'myField'));

// ── Summary ──────────────────────────────────────────────────────────────────
console.log(`\n${'─'.repeat(50)}`);
console.log(`Results: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
EOF

