{
  "name": "p15-test-ag0qyk",
  "version": "1.0.0",
  "description": "Express app with PostgreSQL query layer",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "jest --runInBand --forceExit"
  },
  "keywords": [],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "dotenv": "^16.0.0",
    "express": "^4.18.0",
    "pg": "^8.11.0"
  },
  "devDependencies": {
    "jest": "^29.0.0",
    "supertest": "^6.0.0"
  }
}

/**
 * db.js — PostgreSQL connection pool
 *
 * A single Pool instance is created once and re-used for every query.
 * All configuration is read from environment variables so that no
 * credentials ever appear in source code.
 *
 * Environment variables (set via .env / hosting secrets):
 *   DATABASE_URL               — full connection string (required)
 *   DB_POOL_MAX                — max simultaneous connections (default 10)
 *   DB_POOL_IDLE_TIMEOUT_MS    — ms before an idle client is released (default 30 000)
 *   DB_POOL_CONNECTION_TIMEOUT_MS — ms to wait for a free slot (default 2 000)
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Validate that a connection string is present before doing anything else.
// Failing loudly here is much easier to diagnose than a cryptic ECONNREFUSED
// that surfaces only when the first query fires.
// ---------------------------------------------------------------------------
if (!process.env.DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL environment variable is not set. ' +
      'Copy .env.example to .env and supply a real connection string.'
  );
}

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Keep connections alive with a lightweight keepalive so stale TCP
  // connections are detected and recycled before they cause query failures.
  keepAlive: true,

  // Pool sizing — sensible defaults that can be overridden per environment.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT_MS ?? '30000', 10),
  connectionTimeoutMillis: parseInt(
    process.env.DB_POOL_CONNECTION_TIMEOUT_MS ?? '2000',
    10
  ),
});

// ---------------------------------------------------------------------------
// Pool-level event listeners — surface infrastructure problems in the log
// without crashing the process.
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  // Runs once per new physical connection, not per query.
  console.info(
    `[db] New client connected — pool total: ${pool.totalCount}, ` +
      `idle: ${pool.idleCount}, waiting: ${pool.waitingCount}`
  );
  // Enforce a statement-level timeout on every connection as a last-resort
  // guard against runaway queries (value in milliseconds).
  client.query('SET statement_timeout = 30000').catch((err) => {
    console.error('[db] Failed to set statement_timeout:', err.message);
  });
});

pool.on('acquire', () => {
  // Fires each time a client is checked out from the pool; useful for
  // tracking pool pressure without adding overhead to each query helper.
});

pool.on('remove', () => {
  console.info(
    `[db] Client removed from pool — pool total: ${pool.totalCount}`
  );
});

pool.on('error', (err) => {
  // Unexpected errors on *idle* clients (e.g. the DB server restarted).
  // pg re-creates the client automatically; we just log the incident.
  console.error('[db] Idle client error:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown — drain the pool when the process exits so in-flight
// transactions are not left open.
// ---------------------------------------------------------------------------
const shutdown = async (signal) => {
  console.info(`[db] ${signal} received — draining connection pool…`);
  try {
    await pool.end();
    console.info('[db] Pool drained. Goodbye.');
  } catch (err) {
    console.error('[db] Error while draining pool:', err.message);
  }
};

process.once('SIGTERM', () => shutdown('SIGTERM'));
process.once('SIGINT', () => shutdown('SIGINT'));

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * ─────────────────
 * 1. SQL injection prevention
 *    Every variable piece of data is passed as a *query parameter* ($1, $2 …)
 *    and never interpolated into the SQL string.  The pg driver sends the
 *    values separately so the database server treats them as data, not code.
 *
 * 2. Input validation
 *    Parameters are validated and coerced *before* they reach the database.
 *    Validation errors are thrown as typed ValidationError instances so the
 *    route layer can distinguish them from database errors and return a 400
 *    rather than a 500.
 *
 * 3. Query timing
 *    Every query measures wall-clock time with process.hrtime.bigint() and
 *    emits a structured log line that includes the operation name, the time
 *    taken, and the row count returned.
 *
 * 4. Connection pooling
 *    All queries use the shared pool exported from db.js.  A dedicated
 *    poolQuery() wrapper centralises error handling and timing so individual
 *    query functions stay focused on SQL.
 *
 * 5. Allowlist for ORDER BY
 *    Because column names cannot be parameterised in PostgreSQL, any
 *    caller-supplied sort column is checked against an explicit allowlist
 *    before being interpolated — this is the standard safe pattern for
 *    dynamic ORDER BY clauses.
 */

'use strict';

const pool = require('./db');

// ---------------------------------------------------------------------------
// Typed error classes
// ---------------------------------------------------------------------------

/**
 * Thrown when a caller supplies a value that fails validation.
 * The route layer should map this to HTTP 400.
 */
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

/**
 * Thrown when a requested resource does not exist.
 * The route layer should map this to HTTP 404.
 */
class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'NotFoundError';
  }
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Columns the caller is allowed to sort by (ORDER BY allowlist). */
const SORTABLE_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);

/** Maximum rows that can be requested in a single paginated call. */
const MAX_LIMIT = 100;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Formats a BigInt nanosecond duration as a human-readable string.
 *
 * @param {bigint} ns
 * @returns {string}  e.g. "1.234 ms" or "0.042 ms"
 */
const formatNs = (ns) => `${(Number(ns) / 1_000_000).toFixed(3)} ms`;

/**
 * Central query runner.
 *
 * Checks out a client from the pool, runs the query, emits a structured
 * timing log, then releases the client back regardless of outcome.
 *
 * @param {string}   operation  Human-readable label used in log output.
 * @param {string}   sql        Parameterised SQL string.
 * @param {Array}    params     Positional parameter values ($1, $2 …).
 * @returns {Promise<import('pg').QueryResult>}
 */
const poolQuery = async (operation, sql, params = []) => {
  const client = await pool.connect();
  const start = process.hrtime.bigint();

  try {
    const result = await client.query(sql, params);
    const duration = process.hrtime.bigint() - start;

    console.info(
      `[query] operation=${operation} ` +
        `rows=${result.rowCount} ` +
        `duration=${formatNs(duration)} ` +
        `params_count=${params.length}`
    );

    return result;
  } catch (err) {
    const duration = process.hrtime.bigint() - start;

    console.error(
      `[query] operation=${operation} ` +
        `status=error ` +
        `duration=${formatNs(duration)} ` +
        `message=${err.message}`
    );

    throw err; // re-throw so the caller / route layer can handle it
  } finally {
    // Always release — prevents pool exhaustion on errors.
    client.release();
  }
};

/**
 * Validates and coerces `value` to a positive integer.
 *
 * @param {*}      value
 * @param {string} name   Field name used in error messages.
 * @returns {number}
 * @throws {ValidationError}
 */
const toPositiveInt = (value, name) => {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1) {
    throw new ValidationError(
      `"${name}" must be a positive integer, received: ${JSON.stringify(value)}`
    );
  }
  return n;
};

/**
 * Validates and coerces `value` to a non-negative integer.
 *
 * @param {*}      value
 * @param {string} name
 * @returns {number}
 * @throws {ValidationError}
 */
const toNonNegativeInt = (value, name) => {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw new ValidationError(
      `"${name}" must be a non-negative integer, received: ${JSON.stringify(value)}`
    );
  }
  return n;
};

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetches a single user by their primary-key ID.
 *
 * SQL injection prevention:
 *   The `id` value is passed as parameter $1 — it is *never* interpolated
 *   into the SQL string.
 *
 * @param {number|string} id  The user's numeric ID.
 * @returns {Promise<Object>} The user row.
 * @throws {ValidationError} If `id` is not a valid positive integer.
 * @throws {NotFoundError}   If no user with that ID exists.
 *
 * @example
 *   const user = await getUserById(42);
 */
const getUserById = async (id) => {
  // Validate before sending anything to the database.
  const safeId = toPositiveInt(id, 'id');

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
  `;

  const result = await poolQuery('getUserById', sql, [safeId]);

  if (result.rowCount === 0) {
    throw new NotFoundError(`User with id ${safeId} not found.`);
  }

  return result.rows[0];
};

/**
 * Returns a paginated list of all users, ordered by the specified column.
 *
 * SQL injection prevention:
 *   • `limit` and `offset` are parameterised ($1, $2).
 *   • `orderBy` is validated against an explicit allowlist *before* being
 *     interpolated into the SQL string — PostgreSQL does not support
 *     parameterising column names, so an allowlist is the correct approach.
 *   • `orderDir` is normalised to exactly 'ASC' or 'DESC'.
 *
 * @param {number|string} limit    Max rows to return (1–100, default 20).
 * @param {number|string} offset   Rows to skip for pagination (default 0).
 * @param {string}        orderBy  Column to sort by (default 'id').
 * @param {string}        orderDir Sort direction: 'ASC' or 'DESC' (default 'ASC').
 * @returns {Promise<{users: Object[], total: number, limit: number, offset: number}>}
 * @throws {ValidationError} If any parameter fails validation.
 *
 * @example
 *   const page = await getAllUsers(20, 40, 'name', 'ASC');
 */
const getAllUsers = async (limit = 20, offset = 0, orderBy = 'id', orderDir = 'ASC') => {
  // Validate numeric parameters.
  const safeLimit = Math.min(toPositiveInt(limit, 'limit'), MAX_LIMIT);
  const safeOffset = toNonNegativeInt(offset, 'offset');

  // Validate ORDER BY column against the explicit allowlist.
  const safeOrderBy = String(orderBy).toLowerCase();
  if (!SORTABLE_COLUMNS.has(safeOrderBy)) {
    throw new ValidationError(
      `"orderBy" must be one of [${[...SORTABLE_COLUMNS].join(', ')}], ` +
        `received: ${JSON.stringify(orderBy)}`
    );
  }

  // Normalise sort direction to exactly 'ASC' or 'DESC'.
  const safeOrderDir = String(orderDir).toUpperCase() === 'DESC' ? 'DESC' : 'ASC';

  // Count query — runs in the same transaction window as the data query so
  // the totals are consistent.  Uses a separate poolQuery call so both get
  // their own timing log lines.
  const countSql = `SELECT COUNT(*) AS total FROM users`;
  const countResult = await poolQuery('getAllUsers:count', countSql, []);
  const total = parseInt(countResult.rows[0].total, 10);

  // Data query — LIMIT and OFFSET are parameterised; ORDER BY column and
  // direction are allowlisted/normalised above, making interpolation safe.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    ORDER BY ${safeOrderBy} ${safeOrderDir}
    LIMIT $1 OFFSET $2
  `;

  const dataResult = await poolQuery('getAllUsers:data', dataSql, [
    safeLimit,
    safeOffset,
  ]);

  return {
    users: dataResult.rows,
    total,
    limit: safeLimit,
    offset: safeOffset,
  };
};

/**
 * Full-text search across user name and email fields.
 *
 * SQL injection prevention:
 *   The search term is passed as a parameterised value ($1).  The `ILIKE`
 *   pattern is constructed *inside the database* using the `$1` placeholder
 *   via the `CONCAT` expression — no user input is ever concatenated in JS
 *   before being sent to the server.
 *
 *   Additionally, ILIKE wildcard characters (%, _) and the escape character
 *   (\) that appear in the user's search term are escaped so that a search
 *   for "100%" matches the literal string rather than acting as a wildcard.
 *
 * @param {string}        query    Search term (1–200 characters).
 * @param {number|string} limit    Max rows to return (1–100, default 20).
 * @param {number|string} offset   Rows to skip for pagination (default 0).
 * @returns {Promise<{users: Object[], total: number, limit: number, offset: number, query: string}>}
 * @throws {ValidationError} If any parameter fails validation.
 *
 * @example
 *   const results = await searchUsers('alice', 10, 0);
 */
const searchUsers = async (query, limit = 20, offset = 0) => {
  // Validate the search string.
  if (typeof query !== 'string' || query.trim().length === 0) {
    throw new ValidationError('"query" must be a non-empty string.');
  }
  if (query.length > 200) {
    throw new ValidationError('"query" must be 200 characters or fewer.');
  }

  // Escape ILIKE special characters so the search term is treated literally.
  // The escape character itself must be escaped first to avoid double-escaping.
  const escapedQuery = query
    .replace(/\\/g, '\\\\') // escape the escape char
    .replace(/%/g, '\\%')   // escape wildcard %
    .replace(/_/g, '\\_');  // escape single-char wildcard _

  const safeLimit = Math.min(toPositiveInt(limit, 'limit'), MAX_LIMIT);
  const safeOffset = toNonNegativeInt(offset, 'offset');

  // Count how many rows match (for pagination metadata).
  // The pattern '%<term>%' is built inside the database using CONCAT so the
  // user value always travels as a parameter, never as SQL text.
  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
    WHERE
      name  ILIKE CONCAT('%', $1::text, '%') ESCAPE '\\'
      OR email ILIKE CONCAT('%', $1::text, '%') ESCAPE '\\'
  `;
  const countResult = await poolQuery('searchUsers:count', countSql, [escapedQuery]);
  const total = parseInt(countResult.rows[0].total, 10);

  // Data query — reuses the same parameterised pattern.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE
      name  ILIKE CONCAT('%', $1::text, '%') ESCAPE '\\'
      OR email ILIKE CONCAT('%', $1::text, '%') ESCAPE '\\'
    ORDER BY id ASC
    LIMIT $2 OFFSET $3
  `;

  const dataResult = await poolQuery('searchUsers:data', dataSql, [
    escapedQuery,
    safeLimit,
    safeOffset,
  ]);

  return {
    users: dataResult.rows,
    total,
    limit: safeLimit,
    offset: safeOffset,
    query,           // echo the *original* term back for the API consumer
  };
};

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export error classes so route handlers can use instanceof checks.
  ValidationError,
  NotFoundError,
  // Export the allowlist and cap so callers / tests can reference them.
  SORTABLE_COLUMNS,
  MAX_LIMIT,
};

/**
 * app.js — Express application
 *
 * The /users routes delegate all data access to queries.js, which uses a
 * shared pg connection pool and fully parameterised SQL.
 */

'use strict';

require('dotenv').config();
const express = require('express');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,
  NotFoundError,
} = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Request-level timing middleware
// ---------------------------------------------------------------------------

/**
 * Attaches a high-resolution start time to every request and emits a
 * structured access log line once the response is finished.
 */
app.use((req, res, next) => {
  const start = process.hrtime.bigint();

  res.on('finish', () => {
    const duration = process.hrtime.bigint() - start;
    const ms = (Number(duration) / 1_000_000).toFixed(3);
    console.info(
      `[http] ${req.method} ${req.originalUrl} → ${res.statusCode} (${ms} ms)`
    );
  });

  next();
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler so unhandled promise rejections are forwarded
 * to Express's error handler instead of crashing the process.
 *
 * @param {Function} fn  Async route handler.
 * @returns {Function}
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *
 * Returns a paginated list of all users.
 *
 * Query parameters:
 *   limit    {number}  Rows per page  (1–100, default 20)
 *   offset   {number}  Rows to skip   (≥ 0,   default 0)
 *   orderBy  {string}  Sort column    (id | name | email | created_at, default id)
 *   orderDir {string}  Sort direction (ASC | DESC, default ASC)
 *
 * Example:
 *   GET /users?limit=10&offset=20&orderBy=name&orderDir=ASC
 */
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    const { limit = 20, offset = 0, orderBy = 'id', orderDir = 'ASC' } = req.query;

    const data = await getAllUsers(limit, offset, orderBy, orderDir);
    res.json(data);
  })
);

/**
 * GET /users/search
 *
 * Full-text (ILIKE) search across user name and email.
 * Must be declared *before* /users/:id so Express matches it first.
 *
 * Query parameters:
 *   q        {string}  Search term (required, 1–200 chars)
 *   limit    {number}  Rows per page  (1–100, default 20)
 *   offset   {number}  Rows to skip   (≥ 0,   default 0)
 *
 * Example:
 *   GET /users/search?q=alice&limit=5
 */
app.get(
  '/users/search',
  asyncHandler(async (req, res) => {
    const { q, limit = 20, offset = 0 } = req.query;

    if (!q || String(q).trim().length === 0) {
      return res
        .status(400)
        .json({ error: 'Missing required query parameter: q' });
    }

    const data = await searchUsers(q, limit, offset);
    res.json(data);
  })
);

/**
 * GET /users/:id
 *
 * Returns a single user by numeric ID.
 *
 * Example:
 *   GET /users/42
 */
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const user = await getUserById(req.params.id);
    res.json(user);
  })
);

// ---------------------------------------------------------------------------
// Centralised error handler
// ---------------------------------------------------------------------------

/**
 * Maps typed errors from queries.js to appropriate HTTP status codes.
 * Any error that reaches here is also logged with its stack trace.
 *
 * Express identifies a function as an error handler by its four-argument
 * signature (err, req, res, next).
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  if (err instanceof ValidationError) {
    console.warn(`[error] ValidationError on ${req.method} ${req.originalUrl}: ${err.message}`);
    return res.status(400).json({ error: err.message });
  }

  if (err instanceof NotFoundError) {
    console.warn(`[error] NotFoundError on ${req.method} ${req.originalUrl}: ${err.message}`);
    return res.status(404).json({ error: err.message });
  }

  // Unexpected error — log the full stack for diagnosis.
  console.error(`[error] Unhandled error on ${req.method} ${req.originalUrl}:`, err);
  res.status(500).json({ error: 'Internal server error' });
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = parseInt(process.env.PORT ?? '3000', 10);
  app.listen(PORT, () => {
    console.info(`[app] Server running on port ${PORT} (${process.env.NODE_ENV ?? 'development'})`);
  });
}

module.exports = app;

