/**
 * Creates a mock pg client whose query() function returns `rows` and
 * `rowCount` derived from the rows array.  Multiple successive calls can be
 * configured by passing an array of result arrays.
 *
 * @param {Array<Array>|Array} rows  Single result or array of results.
 */
const buildMockClient = (rows) => {
  // Normalise to an array-of-results so we can handle multi-query tests.
  const results = Array.isArray(rows[0]) ? rows : [rows];
  let callIndex = 0;

  return {
    query: jest.fn((_sql, _params) => {
      const currentRows = results[callIndex] ?? results[results.length - 1];
      callIndex++;
      return Promise.resolve({
        rows: currentRows,
        rowCount: currentRows.length,
      });
    }),
    release: jest.fn(),
  };
};

// Captured SQL & params from the mock — read after each test.
const lastCall = (client, callIndex = 0) => ({
  sql: client.query.mock.calls[callIndex][0],
  params: client.query.mock.calls[callIndex][1],
});

// ---------------------------------------------------------------------------
// getUserById
