describe('getUserById', () => {
  const mockUser = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() };

  test('returns the user row when found', async () => {
    mockClient = buildMockClient([mockUser]);
    const user = await getUserById(1);
    expect(user).toEqual(mockUser);
  });

  test('sends exactly one parameterised query', async () => {
    mockClient = buildMockClient([mockUser]);
    await getUserById(1);
    const { sql, params } = lastCall(mockClient);
    expect(params).toEqual([1]);
    expect(sql).toMatch(/WHERE\s+id\s*=\s*\$1/i);
  });

  test('accepts a string-coercible numeric id', async () => {
    mockClient = buildMockClient([mockUser]);
    await getUserById('42');
    const { params } = lastCall(mockClient);
    expect(params).toEqual([42]);
  });

  test('throws NotFoundError when no rows are returned', async () => {
    mockClient = buildMockClient([]);
    await expect(getUserById(999)).rejects.toThrow(NotFoundError);
    await expect(getUserById(999)).rejects.toThrow('999');
  });

  test.each([
    [0,        '"id" must be a positive integer'],
    [-1,       '"id" must be a positive integer'],
    ['abc',    '"id" must be a positive integer'],
    ['1; DROP TABLE users', '"id" must be a positive integer'],
    [null,     '"id" must be a positive integer'],
    [undefined,'"id" must be a positive integer'],
    [1.5,      '"id" must be a positive integer'],
    ['',       '"id" must be a positive integer'],
  ])('throws ValidationError for invalid id %p', async (bad, msg) => {
    await expect(getUserById(bad)).rejects.toThrow(ValidationError);
    await expect(getUserById(bad)).rejects.toThrow(msg);
  });

  test('releases the pool client even when the query throws', async () => {
    const client = {
      query: jest.fn().mockRejectedValueOnce(new Error('DB is down')),
      release: jest.fn(),
    };
    mockClient = client;
    await expect(getUserById(1)).rejects.toThrow('DB is down');
    expect(client.release).toHaveBeenCalledTimes(1);
  });
});

