describe('getAllUsers', () => {
  const mockUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date() },
  ];

  // getAllUsers fires TWO queries: count then data.
  const buildAllUsersClient = (users = mockUsers, total = 2) =>
    buildMockClient([[{ total: String(total) }], users]);

  test('returns users with pagination metadata', async () => {
    mockClient = buildAllUsersClient();
    const result = await getAllUsers(20, 0);
    expect(result).toMatchObject({
      users: mockUsers,
      total: 2,
      limit: 20,
      offset: 0,
    });
  });

  test('passes limit and offset as $1 and $2 parameters', async () => {
    mockClient = buildAllUsersClient();
    await getAllUsers(10, 5);
    const { params } = lastCall(mockClient, 1); // second call is the data query
    expect(params).toEqual([10, 5]);
  });

  test('caps limit at MAX_LIMIT', async () => {
    mockClient = buildAllUsersClient();
    await getAllUsers(MAX_LIMIT + 500, 0);
    const { params } = lastCall(mockClient, 1);
    expect(params[0]).toBe(MAX_LIMIT);
  });

  test.each(['id', 'name', 'email', 'created_at'])(
    'allows orderBy=%s (in allowlist)',
    async (col) => {
      mockClient = buildAllUsersClient();
      await expect(getAllUsers(10, 0, col)).resolves.not.toThrow();
    }
  );

  test('rejects orderBy values outside the allowlist', async () => {
    await expect(getAllUsers(10, 0, 'password')).rejects.toThrow(ValidationError);
    await expect(getAllUsers(10, 0, '1; DROP TABLE users')).rejects.toThrow(ValidationError);
    await expect(getAllUsers(10, 0, 'id; DROP TABLE users')).rejects.toThrow(ValidationError);
  });

  test('normalises orderDir to ASC when value is unrecognised', async () => {
    mockClient = buildAllUsersClient();
    await getAllUsers(10, 0, 'id', 'INVALID');
    const { sql } = lastCall(mockClient, 1);
    expect(sql).toMatch(/ORDER BY id ASC/i);
  });

  test('uses DESC when orderDir=DESC', async () => {
    mockClient = buildAllUsersClient();
    await getAllUsers(10, 0, 'id', 'DESC');
    const { sql } = lastCall(mockClient, 1);
    expect(sql).toMatch(/ORDER BY id DESC/i);
  });

  test.each([
    [0,    'limit',  '"limit" must be a positive integer'],
    [-5,   'limit',  '"limit" must be a positive integer'],
    ['x',  'limit',  '"limit" must be a positive integer'],
    [-1,   'offset', '"offset" must be a non-negative integer'],
    ['x',  'offset', '"offset" must be a non-negative integer'],
  ])('throws ValidationError for invalid %s=%p', async (val, field, msg) => {
    const args = field === 'limit' ? [val, 0] : [10, val];
    await expect(getAllUsers(...args)).rejects.toThrow(ValidationError);
    await expect(getAllUsers(...args)).rejects.toThrow(msg);
  });

  test('never interpolates user input directly into the ORDER BY clause', async () => {
    // A SQL injection attempt in orderBy must be caught before it reaches SQL.
    await expect(
      getAllUsers(10, 0, "id; DROP TABLE users; --")
    ).rejects.toThrow(ValidationError);
  });

  test('releases the pool client on data-query error', async () => {
    let callCount = 0;
    const client = {
      query: jest.fn(() => {
        callCount++;
        if (callCount === 1) {
          return Promise.resolve({ rows: [{ total: '2' }], rowCount: 1 });
        }
        return Promise.reject(new Error('timeout'));
      }),
      release: jest.fn(),
    };
    mockClient = client;
    await expect(getAllUsers(10, 0)).rejects.toThrow('timeout');
    expect(client.release).toHaveBeenCalled();
  });
});

