describe('searchUsers', () => {
  const mockResults = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date() },
  ];

  const buildSearchClient = (rows = mockResults, total = 1) =>
    buildMockClient([[{ total: String(total) }], rows]);

  test('returns matching users with pagination metadata and echoes query', async () => {
    mockClient = buildSearchClient();
    const result = await searchUsers('alice');
    expect(result).toMatchObject({
      users: mockResults,
      total: 1,
      limit: 20,
      offset: 0,
      query: 'alice',
    });
  });

  test('passes the search term as a single parameterised value', async () => {
    mockClient = buildSearchClient();
    await searchUsers('alice');
    // Both count and data queries should use $1 for the search term.
    const { params: countParams } = lastCall(mockClient, 0);
    const { params: dataParams }  = lastCall(mockClient, 1);
    expect(countParams[0]).toBe('alice');
    expect(dataParams[0]).toBe('alice');
  });

  test('builds the ILIKE pattern inside the database with CONCAT', async () => {
    mockClient = buildSearchClient();
    await searchUsers('test');
    const { sql } = lastCall(mockClient, 1);
    // The JS string must NOT contain a %-wrapped literal.
    expect(sql).not.toMatch(/%test%/);
    // The SQL must use CONCAT to build the pattern server-side.
    expect(sql).toMatch(/CONCAT\('%',\s*\$1/i);
  });

  test('escapes ILIKE wildcard % in the search term', async () => {
    mockClient = buildSearchClient([], 0);
    await searchUsers('100%');
    const { params } = lastCall(mockClient, 0);
    // The escaped value sent to the DB should have \% not %
    expect(params[0]).toBe('100\\%');
  });

  test('escapes ILIKE wildcard _ in the search term', async () => {
    mockClient = buildSearchClient([], 0);
    await searchUsers('user_name');
    const { params } = lastCall(mockClient, 0);
    expect(params[0]).toBe('user\\_name');
  });

  test('escapes backslash in the search term', async () => {
    mockClient = buildSearchClient([], 0);
    await searchUsers('C:\\path');
    const { params } = lastCall(mockClient, 0);
    expect(params[0]).toBe('C:\\\\path');
  });

  test('passes limit and offset as $2 and $3 in the data query', async () => {
    mockClient = buildSearchClient();
    await searchUsers('bob', 5, 10);
    const { params } = lastCall(mockClient, 1);
    expect(params[1]).toBe(5);
    expect(params[2]).toBe(10);
  });

  test('caps limit at MAX_LIMIT', async () => {
    mockClient = buildSearchClient();
    await searchUsers('x', MAX_LIMIT + 999, 0);
    const { params } = lastCall(mockClient, 1);
    expect(params[1]).toBe(MAX_LIMIT);
  });

  test.each([
    ['',     '"query" must be a non-empty string'],
    ['   ',  '"query" must be a non-empty string'],
    [null,   '"query" must be a non-empty string'],
    [123,    '"query" must be a non-empty string'],
    ['a'.repeat(201), '"query" must be 200 characters or fewer'],
  ])('throws ValidationError for invalid query %p', async (bad, msg) => {
    await expect(searchUsers(bad)).rejects.toThrow(ValidationError);
    await expect(searchUsers(bad)).rejects.toThrow(msg);
  });

  test('a SQL injection attempt in query is sent as a safe parameter, not as SQL', async () => {
    // "'; DROP TABLE users; --" is a classic injection payload.
    // It must travel as the $1 parameter value — never as SQL text.
    const payload = "'; DROP TABLE users; --";
    mockClient = buildSearchClient([], 0);
    // Should not throw a ValidationError — it is a valid string.
    await expect(searchUsers(payload)).resolves.not.toThrow();
    const { params } = lastCall(mockClient, 0);
    // The raw (escaped) payload is the parameter value, nothing more.
    expect(typeof params[0]).toBe('string');
    // The SQL text itself must not contain the injection payload.
    const { sql } = lastCall(mockClient, 0);
    expect(sql).not.toContain(payload);
  });

  test('releases the pool client on error', async () => {
    const client = {
      query: jest.fn().mockRejectedValueOnce(new Error('connection lost')),
      release: jest.fn(),
    };
    mockClient = client;
    await expect(searchUsers('alice')).rejects.toThrow('connection lost');
    expect(client.release).toHaveBeenCalledTimes(1);
  });
});

