/**
 * db.js — PostgreSQL connection pool
 *
 * A single Pool instance is created once and shared across the entire
 * application.  Every query goes through this pool so that connections
 * are reused rather than opened and closed per-request.
 *
 * Configuration is read exclusively from environment variables — no
 * credentials are ever hard-coded here.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
// pg's Pool constructor accepts a plain object *or* reads the standard PG*
// environment variables (PGHOST, PGPORT, PGDATABASE, PGUSER, PGPASSWORD)
// automatically.  We also support the common DATABASE_URL connection string
// that most cloud platforms provide.
// ---------------------------------------------------------------------------
const poolConfig = {
  // If DATABASE_URL is set, pg resolves host/port/db/user/password from it.
  connectionString: process.env.DATABASE_URL,

  // Maximum number of clients kept open in the pool.
  // Tune for your Postgres server's max_connections setting.
  max: parseInt(process.env.PG_POOL_MAX, 10) || 10,

  // Milliseconds a client can sit idle in the pool before being released.
  idleTimeoutMillis: parseInt(process.env.PG_IDLE_TIMEOUT_MS, 10) || 30_000,

  // Milliseconds to wait before timing out when acquiring a client from
  // the pool (prevents request pile-ups when the DB is slow).
  connectionTimeoutMillis: parseInt(process.env.PG_CONN_TIMEOUT_MS, 10) || 5_000,

  // Maximum number of times a failed query is retried on connection errors
  // before the error is surfaced to the caller.
  // (pg built-in, available from pg v8+)
  allowExitOnIdle: false,
};

// Only attach SSL config when explicitly requested (e.g. production cloud DBs).
if (process.env.PG_SSL === 'true') {
  poolConfig.ssl = { rejectUnauthorized: process.env.PG_SSL_REJECT_UNAUTH !== 'false' };
}

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event hooks
// ---------------------------------------------------------------------------

// Surfaces background errors (e.g. a client whose connection was dropped by
// the server) so they appear in logs instead of crashing the process.
pool.on('error', (err, client) => {
  console.error('[db] Unexpected idle-client error', {
    message: err.message,
    // Never log err.stack in production — it can contain query text.
    code: err.code,
  });
});

pool.on('connect', () => {
  console.info('[db] New client connected to pool');
});

pool.on('remove', () => {
  console.info('[db] Client removed from pool');
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------
// Call pool.end() when the process exits so that in-flight transactions are
// not left dangling.
const shutdown = async () => {
  console.info('[db] Draining connection pool…');
  await pool.end();
  console.info('[db] Pool drained.');
};

process.once('SIGINT', shutdown);
process.once('SIGTERM', shutdown);

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * ─────────────────
 * 1. SQL injection prevention
 *    Every value that originates from a caller is passed as a *parameter*
 *    ($1, $2, …) and never interpolated into the SQL string.  pg sends
 *    parameters to Postgres over the wire in a separate field from the query
 *    text, so the server always treats them as data — never as SQL.
 *
 * 2. Input validation / whitelisting
 *    Numeric inputs (id, limit, offset) are coerced and range-checked before
 *    the query is dispatched.  The search term is trimmed and length-capped.
 *    Anything out of range throws a typed ValidationError that the route
 *    handler can turn into a 400 response without hitting the database.
 *
 * 3. Connection pooling
 *    All functions call pool.query() which borrows a client from the shared
 *    pool defined in db.js, executes the query, and returns the client
 *    automatically — no manual acquire/release needed for simple queries.
 *
 * 4. Query timing
 *    A queryWithTiming() wrapper measures wall-clock time around every query
 *    and emits a structured log line that includes the operation name,
 *    duration, and row count — useful for slow-query detection.
 *
 * 5. Secrets / PII hygiene
 *    Query parameters are never logged.  Only the operation name, duration,
 *    and row count appear in log output.
 */

'use strict';

const pool = require('./db');

// ---------------------------------------------------------------------------
// Typed error classes
// ---------------------------------------------------------------------------

/**
 * Thrown when a caller supplies a value that fails validation before any SQL
 * is executed.  Route handlers should map this to HTTP 400.
 */
class ValidationError extends Error {
  /**
   * @param {string} message  Human-readable description of what was wrong.
   * @param {string} field    The name of the offending parameter.
   */
  constructor(message, field) {
    super(message);
    this.name = 'ValidationError';
    this.field = field;
    // Maintain proper prototype chain for instanceof checks.
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

/**
 * Thrown when pool.query() rejects — wraps the underlying pg error so that
 * callers have a consistent error type to catch.  Route handlers should map
 * this to HTTP 500 (or 503 for connection-timeout errors).
 */
class DatabaseError extends Error {
  /**
   * @param {string} message   Human-readable description.
   * @param {Error}  cause     The original pg Error.
   * @param {string} operation The query function name, for log correlation.
   */
  constructor(message, cause, operation) {
    super(message);
    this.name = 'DatabaseError';
    this.cause = cause;
    this.operation = operation;
    // Expose the Postgres error code (e.g. '42P01' = undefined_table) so
    // callers can branch on specific conditions without parsing strings.
    this.pgCode = cause?.code;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

// ---------------------------------------------------------------------------
// Query timing wrapper
// ---------------------------------------------------------------------------

/**
 * Executes a parameterised query through the shared pool, logs timing
 * information, and re-throws any database error as a DatabaseError.
 *
 * @param {string}   operation  Logical name used in log output (e.g. 'getUserById').
 * @param {string}   sql        The SQL query string with $1…$N placeholders.
 * @param {Array}    params     Ordered array of parameter values bound to placeholders.
 * @returns {Promise<import('pg').QueryResult>}
 * @throws  {DatabaseError}
 */
async function queryWithTiming(operation, sql, params) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, params);
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.info('[query] %s completed', operation, {
      operation,
      durationMs: durationMs.toFixed(3),
      rowCount: result.rowCount,
    });

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    // Log the error but never include query parameters — they may contain PII.
    console.error('[query] %s failed', operation, {
      operation,
      durationMs: durationMs.toFixed(3),
      // pg error codes are safe to log (e.g. '23505' = unique_violation).
      pgCode: err.code,
      message: err.message,
    });

    throw new DatabaseError(
      `Database error during ${operation}: ${err.message}`,
      err,
      operation,
    );
  }
}

// ---------------------------------------------------------------------------
// Input validators
// ---------------------------------------------------------------------------

/**
 * Validates and coerces an integer path/query parameter.
 *
 * @param {*}      raw    The raw value (string from req.params / req.query).
 * @param {string} field  Parameter name used in ValidationError messages.
 * @param {object} [opts]
 * @param {number} [opts.min=1]          Inclusive lower bound.
 * @param {number} [opts.max=2147483647] Inclusive upper bound (Postgres INT max).
 * @returns {number} A safe integer.
 * @throws  {ValidationError}
 */
function validateInteger(raw, field, { min = 1, max = 2_147_483_647 } = {}) {
  // Reject anything that isn't a finite number once coerced.
  const value = Number(raw);

  if (!Number.isInteger(value)) {
    throw new ValidationError(
      `'${field}' must be an integer, received: ${JSON.stringify(raw)}`,
      field,
    );
  }
  if (value < min || value > max) {
    throw new ValidationError(
      `'${field}' must be between ${min} and ${max}, received: ${value}`,
      field,
    );
  }

  return value;
}

/**
 * Validates and normalises a free-text search term.
 *
 * @param {*}      raw       The raw value from req.query.
 * @param {string} field     Parameter name used in error messages.
 * @param {object} [opts]
 * @param {number} [opts.maxLength=200] Maximum allowed character count.
 * @returns {string} Trimmed search term.
 * @throws  {ValidationError}
 */
function validateSearchQuery(raw, field, { maxLength = 200 } = {}) {
  if (typeof raw !== 'string') {
    throw new ValidationError(`'${field}' must be a string`, field);
  }

  const trimmed = raw.trim();

  if (trimmed.length === 0) {
    throw new ValidationError(`'${field}' must not be empty`, field);
  }
  if (trimmed.length > maxLength) {
    throw new ValidationError(
      `'${field}' must be at most ${maxLength} characters`,
      field,
    );
  }

  return trimmed;
}

// ---------------------------------------------------------------------------
// Column whitelist for ORDER BY (prevents injection via sort parameters)
// ---------------------------------------------------------------------------
const ALLOWED_SORT_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);
const ALLOWED_SORT_DIRECTIONS = new Set(['ASC', 'DESC']);

/**
 * Returns a safe ORDER BY clause fragment.
 * Because column names cannot be parameterised in Postgres, we whitelist them.
 *
 * @param {string} [column='id']
 * @param {string} [direction='ASC']
 * @returns {string}  e.g. '"id" ASC'
 * @throws  {ValidationError}
 */
function buildOrderBy(column = 'id', direction = 'ASC') {
  const col = String(column).toLowerCase();
  const dir = String(direction).toUpperCase();

  if (!ALLOWED_SORT_COLUMNS.has(col)) {
    throw new ValidationError(
      `'sortBy' must be one of: ${[...ALLOWED_SORT_COLUMNS].join(', ')}`,
      'sortBy',
    );
  }
  if (!ALLOWED_SORT_DIRECTIONS.has(dir)) {
    throw new ValidationError(
      `'sortDir' must be ASC or DESC`,
      'sortDir',
    );
  }

  // Double-quote the column name to prevent any residual injection even for
  // whitelisted values (defence-in-depth).
  return `"${col}" ${dir}`;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetches a single user row by primary key.
 *
 * @param {number|string} id  The user's integer primary key.
 * @returns {Promise<object|null>}  The user object or null when not found.
 * @throws  {ValidationError}  When id is not a positive integer.
 * @throws  {DatabaseError}    On pool / Postgres errors.
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function getUserById(id) {
  const safeId = validateInteger(id, 'id');

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at AS "createdAt"
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  // $1 is bound by pg as a server-side parameter — never concatenated into
  // the query string, so it cannot alter the SQL structure.
  const result = await queryWithTiming('getUserById', sql, [safeId]);

  // Return the row directly or null — no 404 logic lives in the query layer.
  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users.
 *
 * @param {number|string} [limit=20]   Maximum rows to return  (1 – 100).
 * @param {number|string} [offset=0]   Rows to skip            (0 – MAX_INT).
 * @param {object}        [options]
 * @param {string}        [options.sortBy='id']   Column to order by.
 * @param {string}        [options.sortDir='ASC'] Sort direction.
 * @returns {Promise<{ users: object[], total: number }>}
 * @throws  {ValidationError}
 * @throws  {DatabaseError}
 *
 * @example
 *   const { users, total } = await getAllUsers(10, 20);
 */
async function getAllUsers(limit = 20, offset = 0, { sortBy = 'id', sortDir = 'ASC' } = {}) {
  const safeLimit  = validateInteger(limit,  'limit',  { min: 1, max: 100 });
  const safeOffset = validateInteger(offset, 'offset', { min: 0 });
  const orderBy    = buildOrderBy(sortBy, sortDir);   // whitelist-validated

  // We fetch the total row count in the same round-trip using a window
  // function so the caller can build pagination metadata without a second
  // query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at       AS "createdAt",
      COUNT(*) OVER()  AS "totalCount"
    FROM users
    ORDER BY ${orderBy}
    LIMIT  $1
    OFFSET $2
  `;

  // $1 = safeLimit, $2 = safeOffset — both integers validated above.
  // orderBy is a whitelisted string fragment (not user-supplied text).
  const result = await queryWithTiming('getAllUsers', sql, [safeLimit, safeOffset]);

  const total = result.rows.length > 0 ? parseInt(result.rows[0].totalCount, 10) : 0;

  // Strip the internal totalCount field from each row before returning.
  const users = result.rows.map(({ totalCount, ...user }) => user);

  return { users, total };
}

/**
 * Full-text search across user name and email columns.
 *
 * The search term is passed as a *parameter* using Postgres's ILIKE operator
 * with a `%term%` pattern.  The wildcards are appended in JavaScript and the
 * whole string is bound as $1 — so a user cannot inject SQL by submitting a
 * value like `' OR 1=1 --`.
 *
 * For large datasets consider replacing ILIKE with a tsvector/GIN index or
 * pg_trgm for better performance.
 *
 * @param {string}        query             The search string (trimmed, max 200 chars).
 * @param {object}        [options]
 * @param {number|string} [options.limit=20]   Max rows to return (1 – 100).
 * @param {number|string} [options.offset=0]   Rows to skip.
 * @param {string}        [options.sortBy='id']
 * @param {string}        [options.sortDir='ASC']
 * @returns {Promise<{ users: object[], total: number }>}
 * @throws  {ValidationError}
 * @throws  {DatabaseError}
 *
 * @example
 *   const { users, total } = await searchUsers('alice', { limit: 5 });
 */
async function searchUsers(query, { limit = 20, offset = 0, sortBy = 'id', sortDir = 'ASC' } = {}) {
  const safeTerm   = validateSearchQuery(query, 'query');
  const safeLimit  = validateInteger(limit,  'limit',  { min: 1, max: 100 });
  const safeOffset = validateInteger(offset, 'offset', { min: 0 });
  const orderBy    = buildOrderBy(sortBy, sortDir);

  // Wrap in % wildcards here, in JavaScript.  The resulting string (e.g.
  // '%alice%') is the *entire* $1 value — it is not re-interpreted as SQL.
  // A user supplying "alice%'; DROP TABLE users; --" would literally search
  // for rows containing that string, not execute extra statements.
  const pattern = `%${safeTerm}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at       AS "createdAt",
      COUNT(*) OVER()  AS "totalCount"
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY ${orderBy}
    LIMIT  $2
    OFFSET $3
  `;

  // $1 = pattern (ILIKE search, bound as data)
  // $2 = safeLimit
  // $3 = safeOffset
  const result = await queryWithTiming('searchUsers', sql, [pattern, safeLimit, safeOffset]);

  const total = result.rows.length > 0 ? parseInt(result.rows[0].totalCount, 10) : 0;
  const users = result.rows.map(({ totalCount, ...user }) => user);

  return { users, total };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = {
  // Query functions
  getUserById,
  getAllUsers,
  searchUsers,

  // Error classes — exported so route handlers can do instanceof checks
  // without reaching into this module's internals.
  ValidationError,
  DatabaseError,
};

/**
 * app.js — Express application
 *
 * Wires the /users endpoint to the parameterised query layer in queries.js.
 * Route handlers are responsible for:
 *   • parsing and forwarding request parameters to query functions
 *   • mapping ValidationError  → 400
 *   • mapping DatabaseError    → 500 / 503
 *   • never leaking internal error details to the client
 */

'use strict';

const express = require('express');
const { getUserById, getAllUsers, searchUsers, ValidationError, DatabaseError } = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Translates a caught error into the appropriate HTTP response.
 * Keeps all error-mapping logic in one place so individual handlers stay lean.
 *
 * @param {Error}                     err
 * @param {import('express').Response} res
 */
function handleQueryError(err, res) {
  if (err instanceof ValidationError) {
    return res.status(400).json({
      error: 'Bad Request',
      message: err.message,
      field: err.field,
    });
  }

  if (err instanceof DatabaseError) {
    // Surface connection-timeout errors as 503 so load-balancers can retry.
    const status = err.pgCode === '57P03' /* cannot_connect_now */
      || err.cause?.code === 'ECONNREFUSED'
      || err.cause?.code === 'ETIMEDOUT'
      ? 503
      : 500;

    // Never send internal DB details to the client.
    return res.status(status).json({
      error: status === 503 ? 'Service Unavailable' : 'Internal Server Error',
      message: 'A database error occurred. Please try again later.',
    });
  }

  // Catch-all for unexpected errors.
  console.error('[route] Unhandled error', { message: err.message, stack: err.stack });
  return res.status(500).json({ error: 'Internal Server Error' });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users
// Returns a paginated list of users, or search results when ?q= is supplied.
//
// Query parameters
//   q        {string}  Free-text search term (name or email)
//   limit    {number}  Page size  1–100, default 20
//   offset   {number}  Rows to skip, default 0
//   sortBy   {string}  Column: id | name | email | created_at  (default id)
//   sortDir  {string}  ASC | DESC  (default ASC)
//
// Examples
//   GET /users
//   GET /users?limit=10&offset=20
//   GET /users?q=alice
//   GET /users?q=example.com&sortBy=name&sortDir=DESC
// ---------------------------------------------------------------------------
app.get('/users', async (req, res) => {
  const { q, limit = 20, offset = 0, sortBy = 'id', sortDir = 'ASC' } = req.query;
  const options = { limit, offset, sortBy, sortDir };

  try {
    const { users, total } = q
      ? await searchUsers(q, options)
      : await getAllUsers(limit, offset, { sortBy, sortDir });

    return res.json({
      data: users,
      pagination: {
        total,
        limit: Number(limit),
        offset: Number(offset),
      },
    });
  } catch (err) {
    return handleQueryError(err, res);
  }
});

// ---------------------------------------------------------------------------
// GET /users/:id
// Returns a single user by integer primary key.
//
// Examples
//   GET /users/1
//   GET /users/42
// ---------------------------------------------------------------------------
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'Not Found', message: 'User not found' });
    }

    return res.json({ data: user });
  } catch (err) {
    return handleQueryError(err, res);
  }
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
/* istanbul ignore next */
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * The pg connection pool is mocked so that:
 *   • Tests run without a live database
 *   • SQL injection strings are verified to reach pool.query() as bound
 *     parameters, never as interpolated SQL
 *   • Timing logs are captured and inspected
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the pg pool (must come before require('./queries'))
// ---------------------------------------------------------------------------
const mockQuery = jest.fn();

jest.mock('./db', () => ({
  query: mockQuery,
  on: jest.fn(),
  end: jest.fn().mockResolvedValue(undefined),
}));

const {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,
  DatabaseError,
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Returns a pg-style QueryResult for a list of user rows. */
function pgResult(rows) {
  return { rows, rowCount: rows.length };
}

/** A single test user row as Postgres would return it. */
const USER_ROW = {
  id: 1,
  name: 'Alice',
  email: 'alice@example.com',
  createdAt: new Date('2024-01-01T00:00:00Z'),
  totalCount: '1',   // pg returns COUNT as a string
};

// ---------------------------------------------------------------------------
// Setup / teardown
// ---------------------------------------------------------------------------
beforeEach(() => {
  mockQuery.mockReset();
  jest.spyOn(console, 'info').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => {
  jest.restoreAllMocks();
});

// ===========================================================================
// getUserById
// ===========================================================================
describe('getUserById', () => {

  describe('valid inputs', () => {
    test('calls pool.query with the id as a bound parameter', async () => {
      mockQuery.mockResolvedValueOnce(pgResult([USER_ROW]));

      await getUserById(1);

      expect(mockQuery).toHaveBeenCalledTimes(1);
      const [sql, params] = mockQuery.mock.calls[0];

      // The id must appear as a parameter, never interpolated in the SQL.
      expect(params).toEqual([1]);
      expect(sql).not.toContain('1');   // number not in SQL string
      expect(sql).toContain('$1');
    });

    test('accepts a numeric string id', async () => {
      mockQuery.mockResolvedValueOnce(pgResult([USER_ROW]));
      const user = await getUserById('7');
      expect(user).toMatchObject({ id: 1, name: 'Alice' });
    });

