/**
 * run_tests.js — Self-contained test runner (no external dependencies)
 *
 * Mirrors every assertion in queries.test.js using only Node built-ins.
 * Mocks the pg pool exactly as Jest would via jest.mock('./db').
 */

'use strict';

// ---------------------------------------------------------------------------
// Minimal test framework
// ---------------------------------------------------------------------------
let passed = 0;
let failed = 0;
const failures = [];

function assert(condition, label) {
  if (condition) {
    passed++;
    process.stdout.write(`  ✓ ${label}\n`);
  } else {
    failed++;
    failures.push(label);
    process.stdout.write(`  ✗ ${label}\n`);
  }
}

async function assertThrows(fn, ErrorClass, label) {
  try {
    await fn();
    failed++;
    failures.push(label);
    process.stdout.write(`  ✗ ${label} (did not throw)\n`);
  } catch (err) {
    if (err instanceof ErrorClass) {
      passed++;
      process.stdout.write(`  ✓ ${label}\n`);
    } else {
      failed++;
      failures.push(label);
      process.stdout.write(`  ✗ ${label} (threw ${err.constructor.name}: ${err.message})\n`);
    }
  }
}

function describe(name, fn) {
  process.stdout.write(`\n${name}\n`);
  fn();
}

// ---------------------------------------------------------------------------
// Mock the pg pool BEFORE requiring queries.js
// ---------------------------------------------------------------------------
let mockQueryFn = null;

// Stub out require() for './db' by pre-populating the module cache.
const Module = require('module');
const path = require('path');
const dbModulePath = path.resolve(__dirname, 'db.js');

require.cache[dbModulePath] = {
  id: dbModulePath,
  filename: dbModulePath,
  loaded: true,
  exports: {
    query: (...args) => mockQueryFn(...args),
    on: () => {},
    end: () => Promise.resolve(),
  },
};

const {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,
  DatabaseError,
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function pgResult(rows) {
  return { rows, rowCount: rows.length };
}

const USER_ROW = {
  id: 1,
  name: 'Alice',
  email: 'alice@example.com',
  createdAt: new Date('2024-01-01T00:00:00Z'),
  totalCount: '1',
};

// Silence console output from the module under test
const origInfo  = console.info;
const origError = console.error;

function silenceLogs()  { console.info = () => {}; console.error = () => {}; }
function restoreLogs()  { console.info = origInfo;  console.error = origError; }

// Captured log calls
let infoCalls  = [];
let errorCalls = [];
function captureLogs() {
  infoCalls  = [];
  errorCalls = [];
  console.info  = (...a) => infoCalls.push(a);
  console.error = (...a) => errorCalls.push(a);
}

// ===========================================================================
// getUserById
// ===========================================================================
describe('getUserById — valid inputs', () => {
  const run = async () => {
    silenceLogs();

    // calls pool.query with id as a bound parameter
    mockQueryFn = async (sql, params) => pgResult([USER_ROW]);
    let capturedSql, capturedParams;
    mockQueryFn = async (sql, params) => { capturedSql = sql; capturedParams = params; return pgResult([USER_ROW]); };
    await getUserById(1);
    assert(Array.isArray(capturedParams) && capturedParams[0] === 1,
      'passes id as bound parameter $1');
    assert(capturedSql.includes('$1'),
      'SQL contains $1 placeholder');
    assert(!capturedSql.includes(' 1 ') && !capturedSql.includes(' 1\n'),
      'raw integer not interpolated in SQL string');

    // returns null when not found
    mockQueryFn = async () => pgResult([]);
    const nullResult = await getUserById(999);
    assert(nullResult === null, 'returns null when no row found');

    // returns the row when found
    mockQueryFn = async () => pgResult([USER_ROW]);
    const user = await getUserById(1);
    assert(user.id === 1 && user.name === 'Alice', 'returns the matching user row');

    // timing log emitted on success
    captureLogs();
    mockQueryFn = async () => pgResult([USER_ROW]);
    await getUserById(1);
    assert(infoCalls.some(a => a[0].includes('[query]') && a[1].includes('getUserById')),
      'emits [query] timing log on success');

    restoreLogs();
  };
  run();
});

describe('getUserById — input validation (no DB call)', () => {
  silenceLogs();

  const badIds = [0, -1, 'abc', 1.5, '', null, undefined,
                  "1; DROP TABLE users; --", "1 OR 1=1", "' OR '1'='1", "1 UNION SELECT"];

  for (const id of badIds) {
    const label = `ValidationError thrown for id=${JSON.stringify(id)}`;
    // We call assertThrows but it's async so we collect promises
    assertThrows(() => getUserById(id), ValidationError, label);
  }

  restoreLogs();
});

describe('getUserById — DatabaseError wrapping', () => {
  const run = async () => {
    silenceLogs();

    const pgErr = Object.assign(new Error('connection refused'), { code: 'ECONNREFUSED' });
    mockQueryFn = async () => { throw pgErr; };
    await assertThrows(() => getUserById(1), DatabaseError,
      'wraps pg errors in DatabaseError');

    captureLogs();
    mockQueryFn = async () => { throw new Error('timeout'); };
    try { await getUserById(1); } catch (_) {}
    assert(errorCalls.some(a => a[0].includes('[query]') && a[1].includes('getUserById')),
      'emits [query] error timing log on failure');

    restoreLogs();
  };
  run();
});

// ===========================================================================
// getAllUsers
// ===========================================================================
const ROWS = [
  { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: new Date(), totalCount: '2' },
  { id: 2, name: 'Bob',   email: 'bob@example.com',   createdAt: new Date(), totalCount: '2' },
];

describe('getAllUsers — valid inputs', () => {
  const run = async () => {
    silenceLogs();

    // default limit/offset
    let capturedParams;
    mockQueryFn = async (sql, params) => { capturedParams = params; return pgResult(ROWS); };
    await getAllUsers();
    assert(capturedParams[0] === 20 && capturedParams[1] === 0,
      'default limit=20, offset=0');

    // explicit limit/offset
    mockQueryFn = async (sql, params) => { capturedParams = params; return pgResult(ROWS); };
    await getAllUsers(10, 30);
    assert(capturedParams[0] === 10 && capturedParams[1] === 30,
      'explicit limit=10, offset=30 passed as params');

    // string coercion (from req.query)
    mockQueryFn = async (sql, params) => { capturedParams = params; return pgResult(ROWS); };
    await getAllUsers('5', '10');
    assert(capturedParams[0] === 5 && capturedParams[1] === 10,
      'string limit/offset coerced to integers');

    // totalCount stripped
    mockQueryFn = async () => pgResult(ROWS);
    const { users } = await getAllUsers();
    assert(!Object.prototype.hasOwnProperty.call(users[0], 'totalCount'),
      'totalCount stripped from returned rows');

    // total value
    mockQueryFn = async () => pgResult(ROWS);
    const { total } = await getAllUsers();
    assert(total === 2, 'total parsed from window function value');

    // empty result
    mockQueryFn = async () => pgResult([]);
    const r = await getAllUsers();
    assert(r.total === 0 && r.users.length === 0, 'empty result → total=0, users=[]');

    restoreLogs();
  };
  run();
});

describe('getAllUsers — sort whitelisting', () => {
  const run = async () => {
    silenceLogs();

    // Allowed combos
    for (const [col, dir] of [['name','ASC'],['email','DESC'],['created_at','ASC'],['id','DESC']]) {
      let capturedSql;
      mockQueryFn = async (sql) => { capturedSql = sql; return pgResult([]); };
      await getAllUsers(20, 0, { sortBy: col, sortDir: dir });
      assert(capturedSql.includes(`"${col}" ${dir}`),
        `allows sortBy=${col} sortDir=${dir} in SQL ORDER BY`);
    }

    // Injection attempts via sort params
    const badSorts = [
      ['id; DROP TABLE users', 'ASC'],
      ['id', 'INVALID'],
      ['(SELECT 1)', 'ASC'],
      ['name', 'ASC OR 1=1'],
    ];
    for (const [col, dir] of badSorts) {
      await assertThrows(
        () => getAllUsers(20, 0, { sortBy: col, sortDir: dir }),
        ValidationError,
        `sortBy="${col}" sortDir="${dir}" → ValidationError`
      );
    }

    restoreLogs();
  };
  run();
});

describe('getAllUsers — limit/offset validation', () => {
  silenceLogs();
  const cases = [[0,20,'limit'],[101,20,'limit'],[20,-1,'offset'],['x',0,'limit'],[20,'y','offset']];
  for (const [limit, offset, field] of cases) {
    assertThrows(() => getAllUsers(limit, offset), ValidationError,
      `limit=${limit} offset=${offset} → ValidationError (field=${field})`);
  }
  restoreLogs();
});

// ===========================================================================
// searchUsers
// ===========================================================================
describe('searchUsers — valid inputs', () => {
  const run = async () => {
    silenceLogs();

    const SEARCH_ROW = { id: 1, name: 'Alice', email: 'alice@example.com',
                         createdAt: new Date(), totalCount: '1' };

    // $1 is wrapped in wildcards, not interpolated into SQL
    let capturedSql, capturedParams;
    mockQueryFn = async (sql, params) => { capturedSql = sql; capturedParams = params; return pgResult([SEARCH_ROW]); };
    await searchUsers('alice');
    assert(capturedParams[0] === '%alice%', '$1 param is %alice%');
    assert(capturedSql.includes('$1'), 'SQL contains $1');
    assert(!capturedSql.includes('alice'), 'raw term not in SQL string');

    // default limit/offset
    assert(capturedParams[1] === 20 && capturedParams[2] === 0, 'default limit=20, offset=0');

    // trim
    mockQueryFn = async (sql, params) => { capturedParams = params; return pgResult([SEARCH_ROW]); };
    await searchUsers('  alice  ');
    assert(capturedParams[0] === '%alice%', 'trims whitespace from search term');

    // totalCount stripped
    mockQueryFn = async () => pgResult([SEARCH_ROW]);
    const { users } = await searchUsers('alice');
    assert(!Object.prototype.hasOwnProperty.call(users[0], 'totalCount'),
      'totalCount stripped');

    restoreLogs();
  };
  run();
});

describe('searchUsers — SQL injection via search term', () => {
  const run = async () => {
    silenceLogs();

    const injections = [
      "' OR '1'='1",
      "alice' --",
      "%; DROP TABLE users; --",
      "alice' UNION SELECT password FROM admins --",
      "%admin%",
      "\\",
    ];

    for (const injection of injections) {
      let capturedSql, capturedParams;
      mockQueryFn = async (sql, params) => { capturedSql = sql; capturedParams = params; return pgResult([]); };
      await searchUsers(injection);
      const trimmed = injection.trim();
      assert(capturedParams[0].includes(trimmed),
        `injection "${trimmed}" is inside params[0], not SQL`);
      assert(!capturedSql.includes(trimmed),
        `injection "${trimmed}" does NOT appear in the SQL string`);
    }

    restoreLogs();
  };
  run();
});

describe('searchUsers — input validation', () => {
  silenceLogs();

  const badInputs = ['', '   ', 123, null, undefined, 'a'.repeat(201)];
  for (const input of badInputs) {
    assertThrows(() => searchUsers(input), ValidationError,
      `query=${JSON.stringify(input)} → ValidationError`);
  }

  assertThrows(() => searchUsers('alice', { limit: 0 }),  ValidationError, 'limit=0 → ValidationError');
  assertThrows(() => searchUsers('alice', { offset: -5 }), ValidationError, 'offset=-5 → ValidationError');

  restoreLogs();
});

describe('searchUsers — 200-char boundary', () => {
  const run = async () => {
    silenceLogs();
    mockQueryFn = async () => pgResult([]);
    let threw = false;
    try { await searchUsers('a'.repeat(200)); } catch (_) { threw = true; }
    assert(!threw, 'exactly 200-char query is accepted');
    restoreLogs();
  };
  run();
});

// ===========================================================================
// Error class contracts
// ===========================================================================
describe('ValidationError', () => {
  const err = new ValidationError('bad input', 'id');
  assert(err.name === 'ValidationError', 'name is ValidationError');
  assert(err.field === 'id', 'field is set');
  assert(err instanceof Error, 'is instanceof Error');
  assert(err instanceof ValidationError, 'is instanceof ValidationError');
});

describe('DatabaseError', () => {
  const cause = Object.assign(new Error('fail'), { code: '42P01' });
  const err = new DatabaseError('db error', cause, 'getUserById');
  assert(err.name === 'DatabaseError', 'name is DatabaseError');
  assert(err.operation === 'getUserById', 'operation is set');
  assert(err.cause === cause, 'cause is the original error');
  assert(err.pgCode === '42P01', 'pgCode extracted from cause');
  assert(err instanceof Error, 'is instanceof Error');
  assert(err instanceof DatabaseError, 'is instanceof DatabaseError');
});

// ===========================================================================
// Summary (printed after all async tests settle)
// ===========================================================================
setImmediate(() => {
  process.stdout.write(`\n${'─'.repeat(60)}\n`);
  if (failures.length) {
    process.stdout.write(`FAILED tests:\n`);
    failures.forEach(f => process.stdout.write(`  ✗ ${f}\n`));
    process.stdout.write(`\n`);
  }
  process.stdout.write(`Results: ${passed} passed, ${failed} failed\n`);
  process.exitCode = failed > 0 ? 1 : 0;
