/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single shared pg.Pool instance so every module in the
 * application re-uses the same set of persistent connections instead
 * of opening a new TCP connection on every query.
 *
 * Configuration is read exclusively from environment variables so that
 * no credentials ever appear in source code.  In development, populate
 * a .env file (never committed to version control) and load it with
 * `dotenv` before this module is first imported.
 *
 * Required env vars
 * -----------------
 *   PGHOST      – database server hostname
 *   PGPORT      – server port (default 5432)
 *   PGDATABASE  – database name
 *   PGUSER      – role / username
 *   PGPASSWORD  – password
 *
 *   Alternatively set DATABASE_URL to a full connection string:
 *   postgres://<user>:<password>@<host>:<port>/<database>
 *
 * Pool tuning env vars (all optional, sensible defaults provided)
 * ---------------------------------------------------------------
 *   DB_POOL_MAX          – maximum simultaneous clients  (default 10)
 *   DB_POOL_IDLE_TIMEOUT – ms before idle client released (default 30000)
 *   DB_POOL_CONN_TIMEOUT – ms to wait for a free client  (default 5000)
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
const poolConfig = {
  // When DATABASE_URL is set, pg parses it automatically and the individual
  // PG* variables are ignored — both forms are therefore fully supported.
  connectionString: process.env.DATABASE_URL || undefined,

  // Individual host/port/db/user/password fields (used when DATABASE_URL is
  // absent; pg ignores them when connectionString is provided).
  host:     process.env.PGHOST,
  port:     parseInt(process.env.PGPORT || '5432', 10),
  database: process.env.PGDATABASE,
  user:     process.env.PGUSER,
  password: process.env.PGPASSWORD,

  // ---------------------------------------------------------------------------
  // Pool sizing
  // A pool that is too large wastes database connections; one that is too small
  // creates queuing under load.  10 is a reasonable default for a small service.
  // ---------------------------------------------------------------------------
  max: parseInt(process.env.DB_POOL_MAX || '10', 10),

  // Release a client back to the pool after it has been idle for this many ms.
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT || '30000', 10),

  // Throw an error if a client cannot be acquired within this many ms.
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN_TIMEOUT || '5000', 10),

  // Keep connections alive across network firewalls / load-balancers.
  keepAlive: true,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event hooks
// ---------------------------------------------------------------------------

// Fired once per new physical TCP connection — useful for auditing growth.
pool.on('connect', (client) => {
  console.info(
    `[db] New client connected — pool size now ${pool.totalCount} ` +
    `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
  );
  // Enforce a statement timeout per connection so runaway queries cannot block
  // the pool indefinitely.  The env var is in milliseconds.
  const statementTimeout = parseInt(process.env.DB_STATEMENT_TIMEOUT || '10000', 10);
  client.query(`SET statement_timeout = ${statementTimeout}`).catch((err) => {
    console.error('[db] Failed to set statement_timeout:', err.message);
  });
});

// Surfaces background errors (e.g. the server closed the connection) so they
// appear in logs rather than crashing the process with an unhandled rejection.
pool.on('error', (err) => {
  console.error('[db] Unexpected client error:', err.message);
});

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

/**
 * Run a single parameterised query on a pool-managed client.
 *
 * @param {string}  text   – The SQL string with $1, $2 … placeholders.
 * @param {Array}   params – Positional parameter values (never interpolated).
 * @returns {Promise<import('pg').QueryResult>}
 */
pool.query; // re-exported as-is through the Pool instance

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Every function in this module:
 *
 *  1. Uses PostgreSQL's native $1 / $2 … parameterised queries so that user-
 *     supplied values are NEVER interpolated into the SQL string.  This is the
 *     primary, non-negotiable defence against SQL injection.
 *
 *  2. Validates and sanitises its own arguments before the query is even
 *     dispatched to the pool (defence-in-depth).
 *
 *  3. Records a query timing log so slow queries are immediately visible in
 *     production logs without needing an external APM tool.
 *
 *  4. Releases connections back to the pool automatically (via pool.query).
 *
 * SQL injection prevention strategy
 * ----------------------------------
 *  • All variable data travels through the `values` array, never via string
 *    concatenation or template literals inside the SQL text.
 *  • The `pg` driver serialises the values array into the PostgreSQL extended
 *    query protocol, which keeps SQL structure and data in separate wire frames.
 *  • Column names and sort directions used in ORDER BY clauses are validated
 *    against a strict allow-list (no user string ever reaches the SQL text).
 *  • Integer parameters (id, limit, offset) are coerced with parseInt and
 *    range-checked before use, so a payload like "1; DROP TABLE users" is
 *    rejected at the validation layer before a database round-trip is made.
 *  • The ILIKE search pattern is built server-side with a single user token;
 *    the wildcard characters themselves are in the SQL text, not in user input.
 *    Any literal % or _ in the user's search string are escaped so they cannot
 *    act as SQL wildcards themselves.
 */

'use strict';

const pool = require('./db');

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Allowed column names for ORDER BY clauses.
 * Keeping this as a Set makes O(1) look-ups and makes the allow-list explicit.
 * @type {Set<string>}
 */
const ALLOWED_ORDER_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);

/** Allowed sort directions. */
const ALLOWED_DIRECTIONS = new Set(['ASC', 'DESC']);

/**
 * Escape PostgreSQL LIKE / ILIKE special characters inside a user-supplied
 * search string so that % and _ are treated as literals, not wildcards.
 *
 * @param {string} raw
 * @returns {string}
 */
function escapeLikePattern(raw) {
  // Escape the backslash first (it is the escape character itself), then % and _.
  return raw
    .replace(/\\/g, '\\\\')
    .replace(/%/g, '\\%')
    .replace(/_/g, '\\_');
}

/**
 * Measure wall-clock time for a query and emit a structured timing log.
 *
 * @param {string} queryName   – Logical name used in the log line.
 * @param {string} sql         – The SQL text (for the log, never executed here).
 * @param {Array}  params      – Bound parameter values.
 * @param {Function} executor  – Async function that actually runs the query.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(queryName, sql, params, executor) {
  const start = process.hrtime.bigint();
  let rowCount = 0;
  let error = null;

  try {
    const result = await executor();
    rowCount = result.rowCount ?? result.rows?.length ?? 0;
    return result;
  } catch (err) {
    error = err;
    throw err;
  } finally {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    // Structured log line — easy to parse by log aggregators (Datadog, Loki …)
    const logEntry = {
      event:      'db_query',
      query:      queryName,
      durationMs: parseFloat(durationMs.toFixed(3)),
      rowCount,
      params:     params.map(() => '[REDACTED]'), // lengths visible, values hidden
      status:     error ? 'error' : 'ok',
      ...(error && { errorMessage: error.message }),
    };

    if (error || durationMs > (parseInt(process.env.SLOW_QUERY_THRESHOLD_MS || '200', 10))) {
      // Slow queries and errors are logged at warn / error level.
      const level = error ? 'error' : 'warn';
      console[level](`[db:query] ${JSON.stringify(logEntry)}`);
    } else {
      console.info(`[db:query] ${JSON.stringify(logEntry)}`);
    }
  }
}

/**
 * Validate that a value is a safe positive integer (or zero).
 * Throws a TypeError with a caller-visible message on failure so the HTTP
 * handler can convert it to a 400 response without exposing database details.
 *
 * @param {*}      value – The raw value to validate.
 * @param {string} name  – Parameter name, used in the error message.
 * @param {object} [opts]
 * @param {number} [opts.min=0]       – Inclusive lower bound.
 * @param {number} [opts.max=Infinity]– Inclusive upper bound.
 * @returns {number} The coerced integer.
 */
function validateInteger(value, name, { min = 0, max = Infinity } = {}) {
  const n = parseInt(value, 10);
  if (!Number.isFinite(n)) {
    throw new TypeError(`"${name}" must be an integer, got: ${String(value)}`);
  }
  if (n < min || n > max) {
    throw new RangeError(`"${name}" must be between ${min} and ${max}, got: ${n}`);
  }
  return n;
}

/**
 * Validate a free-text search term.
 * Rejects empty strings, strings that are too long, and strings composed
 * entirely of wildcard/special characters that would produce a useless query.
 *
 * @param {*}      value – The raw value.
 * @param {string} name  – Parameter name for the error message.
 * @returns {string} The trimmed string.
 */
function validateSearchQuery(value, name) {
  if (typeof value !== 'string') {
    throw new TypeError(`"${name}" must be a string`);
  }
  const trimmed = value.trim();
  if (trimmed.length === 0) {
    throw new TypeError(`"${name}" must not be empty or whitespace-only`);
  }
  if (trimmed.length > 200) {
    throw new RangeError(`"${name}" must be 200 characters or fewer`);
  }
  return trimmed;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user row by its primary key.
 *
 * Parameterised query:  the id value is bound as $1 — it is never spliced
 * into the SQL string — so a payload such as "1 OR 1=1" is harmless because
 * pg will try to CAST it to INTEGER and fail before the query reaches the
 * planner.  Our own parseInt check catches it even earlier.
 *
 * @param {number|string} id – The user's integer primary key.
 * @returns {Promise<object|null>} The user row, or null if not found.
 */
async function getUserById(id) {
  // Validate: must be a positive integer.
  const safeId = validateInteger(id, 'id', { min: 1, max: 2_147_483_647 });

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;
  const params = [safeId];

  return timedQuery('getUserById', sql, params, async () => {
    const result = await pool.query(sql, params);
    // Return the row directly (or null) so callers don't unpack result.rows.
    return { ...result, row: result.rows[0] ?? null };
  }).then((result) => result.row);
}

/**
 * Return a paginated list of all users.
 *
 * Pagination is implemented with LIMIT / OFFSET rather than cursor-based
 * pagination for simplicity.  For very large tables, cursor pagination is
 * preferred; this can be swapped in without changing the public API.
 *
 * Both `limit` and `offset` are bound as $1 / $2 — PostgreSQL accepts
 * integer-typed parameters in LIMIT / OFFSET positions.
 *
 * @param {number} [limit=20]  – Maximum rows to return (1–100).
 * @param {number} [offset=0]  – Number of rows to skip.
 * @param {string} [orderBy='id']  – Column to sort by (allow-listed).
 * @param {string} [direction='ASC'] – Sort direction: 'ASC' or 'DESC'.
 * @returns {Promise<{users: object[], total: number}>}
 */
async function getAllUsers(
  limit = 20,
  offset = 0,
  orderBy = 'id',
  direction = 'ASC'
) {
  // --- Validate numeric arguments ---
  const safeLimit  = validateInteger(limit,  'limit',  { min: 1, max: 100 });
  const safeOffset = validateInteger(offset, 'offset', { min: 0 });

  // --- Allow-list the ORDER BY column and direction ---
  // CRITICAL: identifiers cannot be bound as parameterised values in
  // PostgreSQL — only data values can be.  We therefore validate against a
  // strict allow-list and use the validated literal directly in the SQL text.
  // No user-supplied string ever reaches the SQL text.
  const safeColumn = ALLOWED_ORDER_COLUMNS.has(orderBy) ? orderBy : 'id';
  const safeDir    = ALLOWED_DIRECTIONS.has(direction?.toUpperCase())
    ? direction.toUpperCase()
    : 'ASC';

  // COUNT(*) uses a separate query so we can return the total without an
  // extra application-side loop.  Both queries share the same connection
  // from the pool (acquired once via pool.connect()) to avoid two round-trips
  // through the pool queue under high concurrency.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM  users
    ORDER BY ${safeColumn} ${safeDir}
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `SELECT COUNT(*) AS total FROM users`;

  const params = [safeLimit, safeOffset];

  return timedQuery('getAllUsers', dataSql, params, async () => {
    // Acquire one client for both queries so they run in the same session.
    const client = await pool.connect();
    try {
      const [dataResult, countResult] = await Promise.all([
        client.query(dataSql, params),
        client.query(countSql),
      ]);

      return {
        rows:     dataResult.rows,
        rowCount: dataResult.rowCount,
        total:    parseInt(countResult.rows[0].total, 10),
      };
    } finally {
      // ALWAYS release the client — even if one of the queries throws.
      client.release();
    }
  }).then((result) => ({
    users: result.rows,
    total: result.total,
    limit: safeLimit,
    offset: safeOffset,
  }));
}

/**
 * Full-text search across the name and email columns.
 *
 * The search pattern is built *server-side* using an escaped version of the
 * user's input, then bound as a single parameter ($1).  The ILIKE operator
 * performs a case-insensitive substring match.
 *
 * SQL-injection is prevented at two layers:
 *  1. The pg driver transmits the pattern as a typed parameter, never as part
 *     of the SQL text.
 *  2. escapeLikePattern() removes the ability for the user to supply
 *     unintended LIKE wildcards (% and _) — they are escaped to literals.
 *
 * @param {string} query       – Search term (trimmed, max 200 chars).
 * @param {number} [limit=20]  – Maximum rows to return (1–100).
 * @param {number} [offset=0]  – Number of rows to skip.
 * @returns {Promise<{users: object[], total: number}>}
 */
async function searchUsers(query, limit = 20, offset = 0) {
  // --- Validate arguments ---
  const safeTerm   = validateSearchQuery(query, 'query');
  const safeLimit  = validateInteger(limit,  'limit',  { min: 1, max: 100 });
  const safeOffset = validateInteger(offset, 'offset', { min: 0 });

  // Build the ILIKE pattern server-side.
  // The wildcards % are in the SQL text; the user's token is the bound value.
  const pattern = `%${escapeLikePattern(safeTerm)}%`;

  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM  users
    WHERE name  ILIKE $1
       OR email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM   users
    WHERE  name  ILIKE $1
        OR email ILIKE $1
  `;

  const dataParams  = [pattern, safeLimit, safeOffset];
  const countParams = [pattern];

  return timedQuery('searchUsers', dataSql, dataParams, async () => {
    const client = await pool.connect();
    try {
      const [dataResult, countResult] = await Promise.all([
        client.query(dataSql, dataParams),
        client.query(countSql, countParams),
      ]);

      return {
        rows:     dataResult.rows,
        rowCount: dataResult.rowCount,
        total:    parseInt(countResult.rows[0].total, 10),
      };
    } finally {
      client.release();
    }
  }).then((result) => ({
    users:  result.rows,
    total:  result.total,
    limit:  safeLimit,
    offset: safeOffset,
    query:  safeTerm,
  }));
}

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
};

/**
 * app.js — Express application
 *
 * Wires the database query layer (queries.js / db.js) into the HTTP routes.
 * The /users endpoint now supports:
 *
 *   GET /users                       → paginated list of all users
 *   GET /users?limit=5&offset=10     → pagination controls
 *   GET /users?orderBy=name&dir=DESC → server-side sort (allow-listed)
 *   GET /users?search=alice          → ILIKE search across name + email
 *   GET /users/:id                   → single user by primary key
 *
 * All query parameters are validated and bound as parameterised values before
 * they reach PostgreSQL — see queries.js for the full security commentary.
 */

'use strict';

// Load environment variables from .env before any other module is imported.
// In production these are injected by the runtime (e.g. Docker / k8s secrets);
// dotenv is a no-op when the variables are already set.
require('dotenv').config();

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Normalise a validation/range error thrown by queries.js into a structured
 * 400 response so the caller receives a useful message without any internal
 * database detail leaking out.
 *
 * Any other (unexpected) error becomes a 500 with a generic message —
 * the full error is only written to the server log.
 *
 * @param {Error} err
 * @param {import('express').Response} res
 */
function handleQueryError(err, res) {
  if (err instanceof TypeError || err instanceof RangeError) {
    return res.status(400).json({ error: err.message });
  }
  // Unexpected database or pool error — log the detail but hide it from the client.
  console.error('[app] Unhandled query error:', err);
  return res.status(500).json({ error: 'Internal server error' });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 *
 * Query parameters (all optional):
 *   search  {string}  – Search term; triggers searchUsers() when present.
 *   limit   {number}  – Page size, 1–100 (default 20).
 *   offset  {number}  – Page offset, ≥ 0   (default 0).
 *   orderBy {string}  – Sort column: id | name | email | created_at (default id).
 *   dir     {string}  – Sort direction: ASC | DESC (default ASC).
 *
 * Response shape:
 *   { users: [...], total: number, limit: number, offset: number }
 */
app.get('/users', async (req, res) => {
  const { search, limit, offset, orderBy, dir } = req.query;

  try {
    // Branch: full-text search vs. plain listing.
    const payload = search !== undefined
      ? await searchUsers(search, limit, offset)
      : await getAllUsers(limit, offset, orderBy, dir);

    res.json(payload);
  } catch (err) {
    handleQueryError(err, res);
  }
});

/**
 * GET /users/:id
 *
 * Path parameter:
 *   id {number} – Integer primary key (≥ 1).
 *
 * Responses:
 *   200  { id, name, email, created_at }
 *   400  { error: "..." }  – id is not a valid integer
 *   404  { error: "User not found" }
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  } catch (err) {
    handleQueryError(err, res);
  }
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

const PORT = parseInt(process.env.PORT || '3000', 10);

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

