  const safeLimit  = validateInteger(limit,  'limit',  { min: 1, max: 200 });
  const safeOffset = validateInteger(offset, 'offset', { min: 0 });

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const result = await executeQuery('getAllUsers', sql, [safeLimit, safeOffset]);
  return result.rows;
}

/**
 * Searches users whose name or email contains the supplied query string
 * (case-insensitive).
 *
 * SQL injection prevention
 * ─────────────────────────
 * The search term is:
 *  1. Validated as a non-empty string of ≤ 200 characters.
 *  2. Passed through `buildLikePattern`, which escapes the LIKE
 *     metacharacters (%, _, \) so they are treated as literals.
 *  3. Passed as the parameterised value $1 – it is never concatenated into
 *     the SQL text.
 *
 * @param {string} query  The search term to look for in name and email fields.
 * @returns {Promise<object[]>}  Array of matching user rows (may be empty).
 *
 * @example
 *   const results = await searchUsers('alice');
 *   // [{ id: 1, name: 'Alice', email: 'alice@example.com', created_at: … }]
 */
async function searchUsers(query) {
  const safeQuery  = validateSearchQuery(query);
  const likePattern = buildLikePattern(safeQuery);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY id ASC
    LIMIT 100
  `;

  const result = await executeQuery('searchUsers', sql, [likePattern]);
  return result.rows;
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Expose internal helpers so unit tests can exercise them directly without
  // needing a real database connection.
  _internal: {
    validateInteger,
    validateSearchQuery,
    buildLikePattern,
    executeQuery,
  },
};

'use strict';

/**
 * app.js – Express application
 *
 * /health         – liveness probe (no DB dependency)
 * /users          – list all users with optional pagination
 * /users/search   – search users by name or email
 * /users/:id      – fetch a single user by primary key
 *
 * All database access goes through queries.js; this file contains only HTTP
 * concerns (parsing, validation of HTTP-level inputs, response shaping,
 * and error handling).
 */

require('dotenv').config();
const express = require('express');
const {
  getUserById,
  getAllUsers,
  searchUsers,
} = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parses an optional query-string integer parameter.
 *
 * Returns `defaultValue` when the parameter is absent.
 * Returns NaN when the parameter is present but not a valid integer so that
 * the route handler can return 400.
 *
 * @param {string|undefined} raw           Raw string from req.query.
 * @param {number}           defaultValue  Value to use when the param is absent.
 * @returns {number}
 */
function parseQueryInt(raw, defaultValue) {
  if (raw === undefined) return defaultValue;
  const n = Number(raw);
  return Number.isInteger(n) ? n : NaN;
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// GET /health ──────────────────────────────────────────────────────────────
// Simple liveness probe; does not touch the database so it stays fast and
// independent of DB availability.
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users/search?q=<term> ───────────────────────────────────────────────
// Must be registered BEFORE /users/:id so Express does not treat "search"
// as an :id value.
//
// Query parameters:
//   q  (required) – search term; matched case-insensitively against name & email
//
// Response: 200 { users: [...] }
//           400 { error: "..." }   – missing or invalid q
//           500 { error: "..." }   – database error
app.get('/users/search', async (req, res) => {
  const { q } = req.query;

  if (!q || typeof q !== 'string' || q.trim().length === 0) {
    return res.status(400).json({
      error: 'Query parameter "q" is required and must be a non-empty string.',
    });
  }

  try {
    const users = await searchUsers(q);
    return res.json({ users });
  } catch (err) {
    // TypeError from validation inside queries.js means the caller passed bad
    // data; respond with 400.  All other errors are 500.
    if (err instanceof TypeError) {
      return res.status(400).json({ error: err.message });
    }
    console.error('[app] searchUsers error:', err);
    return res.status(500).json({ error: 'Internal server error.' });
  }
});

// GET /users?limit=<n>&offset=<n> ──────────────────────────────────────────
// Returns a paginated list of all users.
//
// Query parameters:
//   limit   (optional, default 20, max 200) – rows per page
//   offset  (optional, default 0)           – rows to skip
//
// Response: 200 { users: [...], pagination: { limit, offset } }
//           400 { error: "..." }   – non-integer or out-of-range parameters
//           500 { error: "..." }   – database error
app.get('/users', async (req, res) => {
  const limit  = parseQueryInt(req.query.limit,  20);
  const offset = parseQueryInt(req.query.offset, 0);

  if (isNaN(limit) || isNaN(offset)) {
    return res.status(400).json({
      error: '"limit" and "offset" must be integers.',
    });
  }

  try {
    const users = await getAllUsers(limit, offset);
    return res.json({
      users,
      pagination: { limit, offset },
    });
  } catch (err) {
    if (err instanceof TypeError) {
      return res.status(400).json({ error: err.message });
    }
    console.error('[app] getAllUsers error:', err);
    return res.status(500).json({ error: 'Internal server error.' });
  }
});

// GET /users/:id ───────────────────────────────────────────────────────────
// Returns a single user by numeric ID.
//
// Path parameters:
//   id  (required) – positive integer
//
// Response: 200 { user: {...} }
//           400 { error: "..." }   – id is not a positive integer
//           404 { error: "..." }   – no user with that id
//           500 { error: "..." }   – database error
app.get('/users/:id', async (req, res) => {
  const rawId = req.params.id;
  const id    = Number(rawId);

  if (!Number.isInteger(id) || id < 1) {
    return res.status(400).json({
      error: `"id" must be a positive integer, got: ${rawId}`,
    });
  }

  try {
    const user = await getUserById(id);
    if (!user) {
      return res.status(404).json({ error: `User with id ${id} not found.` });
    }
    return res.json({ user });
  } catch (err) {
    if (err instanceof TypeError) {
      return res.status(400).json({ error: err.message });
    }
    console.error('[app] getUserById error:', err);
    return res.status(500).json({ error: 'Internal server error.' });
  }
});

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT ?? '3000', 10);
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

'use strict';

/**
 * queries.test.js
 *
 * Unit tests for queries.js.
 *
 * The PostgreSQL pool (db.js) is mocked at the module level so no real
 * database connection is required.  Tests exercise:
 *
 *  - Happy-path query execution for each public function.
 *  - Input validation (TypeErrors) for every argument.
 *  - LIKE-pattern escaping / SQL injection prevention.
 *  - Timing log output.
 *  - Pool client acquisition and release (including on errors).
 */

// ---------------------------------------------------------------------------
// Mock db.js BEFORE requiring queries.js so the module resolver picks up the
// mock when queries.js calls require('./db').
// ---------------------------------------------------------------------------
jest.mock('./db', () => {
  const mockClient = {
    query:   jest.fn(),
    release: jest.fn(),
  };
  const mockPool = {
    connect: jest.fn().mockResolvedValue(mockClient),
    end:     jest.fn().mockResolvedValue(undefined),
    on:      jest.fn(),
  };
  // Expose the mock client so individual tests can configure return values.
  mockPool.__mockClient = mockClient;
  return mockPool;
});

const pool    = require('./db');
const queries = require('./queries');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  _internal: { validateInteger, validateSearchQuery, buildLikePattern },
} = queries;

// Convenience alias
const mockClient = pool.__mockClient;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Builds a fake pg QueryResult with the supplied rows. */
function fakeResult(rows) {
  return { rows, rowCount: rows.length };
}

beforeEach(() => {
  jest.clearAllMocks();
  // Default: connect succeeds and query returns an empty result set.
  pool.connect.mockResolvedValue(mockClient);
  mockClient.query.mockResolvedValue(fakeResult([]));
});

// ============================================================================
// validateInteger
// ============================================================================
describe('validateInteger', () => {
  test('accepts a positive integer', () => {
    expect(validateInteger(5, 'x')).toBe(5);
  });

  test('accepts a numeric string', () => {
    expect(validateInteger('42', 'x')).toBe(42);
  });

  test('accepts 0 when min is 0', () => {
    expect(validateInteger(0, 'offset', { min: 0 })).toBe(0);
  });

  test('throws on a float', () => {
    expect(() => validateInteger(3.7, 'x')).toThrow(TypeError);
    expect(() => validateInteger(3.7, 'x')).toThrow('must be an integer');
  });

  test('throws on a string that is not a number', () => {
    expect(() => validateInteger('abc', 'x')).toThrow(TypeError);
  });

  test('throws when value is below min', () => {
    expect(() => validateInteger(0, 'id', { min: 1 })).toThrow(TypeError);
    expect(() => validateInteger(0, 'id', { min: 1 })).toThrow('>= 1');
  });

  test('throws when value exceeds max', () => {
    expect(() => validateInteger(300, 'limit', { min: 1, max: 200 })).toThrow(TypeError);
    expect(() => validateInteger(300, 'limit', { min: 1, max: 200 })).toThrow('<= 200');
  });

  test('accepts value at exact max boundary', () => {
    expect(validateInteger(200, 'limit', { min: 1, max: 200 })).toBe(200);
  });

  test('throws on NaN', () => {
    expect(() => validateInteger(NaN, 'x')).toThrow(TypeError);
  });
});

// ============================================================================
// validateSearchQuery
// ============================================================================
describe('validateSearchQuery', () => {
  test('returns trimmed string', () => {
    expect(validateSearchQuery('  alice  ')).toBe('alice');
  });

  test('throws on non-string input', () => {
    expect(() => validateSearchQuery(123)).toThrow(TypeError);
    expect(() => validateSearchQuery(123)).toThrow('must be a string');
  });

  test('throws on empty string', () => {
    expect(() => validateSearchQuery('')).toThrow(TypeError);
    expect(() => validateSearchQuery('')).toThrow('must not be empty');
  });

  test('throws on whitespace-only string', () => {
    expect(() => validateSearchQuery('   ')).toThrow(TypeError);
  });

  test('throws when string exceeds 200 chars', () => {
    const long = 'a'.repeat(201);
    expect(() => validateSearchQuery(long)).toThrow(TypeError);
    expect(() => validateSearchQuery(long)).toThrow('200 characters');
  });

  test('accepts a string of exactly 200 chars', () => {
    const exact = 'a'.repeat(200);
    expect(validateSearchQuery(exact)).toBe(exact);
  });
});

// ============================================================================
// buildLikePattern  (SQL injection / wildcard escaping)
// ============================================================================
describe('buildLikePattern', () => {
  test('wraps term in % wildcards', () => {
    expect(buildLikePattern('alice')).toBe('%alice%');
  });

  test('escapes % so it is treated as a literal', () => {
    expect(buildLikePattern('100%')).toBe('%100\\%%');
  });

  test('escapes _ so it is treated as a literal', () => {
    expect(buildLikePattern('a_b')).toBe('%a\\_b%');
  });

  test('escapes backslash before other metacharacters', () => {
    expect(buildLikePattern('a\\b')).toBe('%a\\\\b%');
  });

  test('escapes a string containing all three metacharacters', () => {
    // Input: 50% off_sale\deal
    // Expected pattern: %50\% off\_sale\\deal%
    expect(buildLikePattern('50% off_sale\\deal')).toBe('%50\\% off\\_sale\\\\deal%');
  });

  test('handles a classic SQL injection attempt', () => {
    // The attacker tries to break out of the LIKE pattern.
    // After escaping, the literal characters are preserved.
    const evil = "' OR '1'='1";
    const pattern = buildLikePattern(evil);
    // No raw single-quotes or equals signs are added – the value is safe to
    // pass as a parameterised argument.
    expect(pattern).toBe("%' OR '1'='1%");
    // Crucially it must NOT contain an unescaped % that wasn't in the input.
    expect(pattern.match(/%/g)).toHaveLength(2); // only the two wrapping %
  });
});

// ============================================================================
// getUserById
// ============================================================================
describe('getUserById', () => {
  const mockUser = {
    id: 1,
    name: 'Alice',
    email: 'alice@example.com',
    created_at: new Date('2024-01-01'),
  };

  test('returns the user row when found', async () => {
