    mockClient.query.mockResolvedValueOnce(fakeResult([]));
    const result = await getUserById(999);
    expect(result).toBeNull();
  });

  test('passes id as a parameterised value, not in SQL text', async () => {
    mockClient.query.mockResolvedValueOnce(fakeResult([mockUser]));
    await getUserById(42);

    const [sqlText, params] = mockClient.query.mock.calls[0];
    expect(sqlText).not.toContain('42');   // id must NOT be in the query text
    expect(params).toEqual([42]);          // id must be in the params array
    expect(sqlText).toContain('$1');       // placeholder must be present
  });

  test('releases the pool client after a successful query', async () => {
    mockClient.query.mockResolvedValueOnce(fakeResult([mockUser]));
    await getUserById(1);
    expect(mockClient.release).toHaveBeenCalledTimes(1);
  });

  test('releases the pool client even when the query throws', async () => {
    mockClient.query.mockRejectedValueOnce(new Error('DB error'));
    await expect(getUserById(1)).rejects.toThrow('DB error');
    expect(mockClient.release).toHaveBeenCalledTimes(1);
  });

  test('throws TypeError for a non-integer id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(TypeError);
  });

  test('throws TypeError for id < 1', async () => {
    await expect(getUserById(0)).rejects.toThrow(TypeError);
  });

  test('throws TypeError for a negative id', async () => {
