  });

  test('logs timing information', async () => {
    const spy = jest.spyOn(console, 'log').mockImplementation(() => {});
    mockClient.query.mockResolvedValueOnce(fakeResult([mockUser]));
    await getUserById(1);
    const logCalls = spy.mock.calls.map((c) => c.join(' '));
    const timingLog = logCalls.find((l) => l.includes('getUserById'));
